INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did you manage conversation history, session handling, and database schema for a chatbot system?', '{"key_points":[{"id":"KP1","description":"Delineates a dual-tier storage strategy separating active ephemeral session state from persistent conversational history.","required":true,"acceptable_evidence":["Technical keywords: Redis session cache, PostgreSQL conversation_history, TTL expiration, hot-cold storage, session_id partition.","Explains storing active multi-turn working state in Redis with sub-millisecond latency while persisting full dialogue transcripts to PostgreSQL.","Details how session expiration (e.g., 24-hour TTL) prevents memory bloat while preserving historical compliance and analytics in relational storage."]},{"id":"KP2","description":"Defines a concrete relational database schema for conversation history with appropriate keys, columns, and constraints.","required":true,"acceptable_evidence":["Technical keywords: conversation_history table, session_id UUID, user_id, role enum (user/assistant/system), content TEXT, timestamp TIMESTAMPTZ, metadata JSONB, foreign key constraints.","Outlines schema definition with explicit columns: message_id, session_id, user_id, message_role, message_content, created_at, and optional token_count.","Specifies relational integrity using foreign keys to users and sessions tables, along with B-tree composite indexing on (session_id, created_at)."]},{"id":"KP3","description":"Articulates session handling mechanics, caching patterns, and state lifecycle management.","required":true,"acceptable_evidence":["Technical keywords: Cache-aside pattern, Redis SETEX, JSON serialization, Pydantic model serialization, connection pooling asyncpg.","Explains the cache-aside pattern where session context is fetched from Redis on turn start and lazily hydrated from PostgreSQL if cache misses occur.","Details serialization of conversational turns as JSON strings or Redis hashes with automatic TTL extension upon user activity."]},{"id":"KP4","description":"Details context window management, sliding window buffers, and token budget enforcement for the LLM prompt.","required":true,"acceptable_evidence":["Technical keywords: Sliding window buffer, token budget, LangGraph checkpointer, tiktoken count, conversation summarization, truncation.","Describes selecting the most recent k-turns (e.g., last 5-10 messages) combined with an incremental rolling summary to respect model token limits.","Explains how LangGraph checkpointing or custom memory managers prune message history before passing the combined context payload to the LLM."]},{"id":"KP5","description":"Addresses long-term memory retrieval, semantic persistence, and privacy/data isolation controls.","required":false,"acceptable_evidence":["Technical keywords: Milvus vector store, Neo4j GraphRAG, tenant_id isolation, PII masking, data retention policy.","Explains indexing synthesized user preferences or cross-session facts into Milvus vector collections or Neo4j knowledge graphs for semantic recall.","Details multi-tenant isolation where queries strictly filter by user_id and tenant_id, preventing cross-user data leakage."]}],"critical_failures":["Confuses Redis ephemeral session state with PostgreSQL persistent relational history or relies entirely on in-memory process dictionaries.","Fails to specify concrete schema columns or table structures for tracking multi-turn conversation messages.","Ignores LLM context window limits and fails to describe sliding window truncation, token budgets, or summarization."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you model entities and relationships in Neo4j, and how were they queried?', '{"key_points":[{"id":"KP1","description":"Defines the property graph data model including node labels, properties, and directed relationship types.","required":true,"acceptable_evidence":["Technical keywords: Labeled Property Graph (LPG), Node labels (:User, :Document, :Entity, :Tool, :Topic), Relationship types ([:MENTIONS], [:RESOLVED_BY], [:HAS_TOPIC], [:CALLS]), properties.","Describes schema design where entities like Users, Entities, and Concepts are represented as nodes with unique IDs and properties.","Explains directed relationship semantics that capture semantic dependencies and hierarchies (e.g., `(:User)-[:REPORTED]->(:Incident)`)."]},{"id":"KP2","description":"Demonstrates Cypher declarative querying syntax for pattern matching, traversal, and entity resolution.","required":true,"acceptable_evidence":["Technical keywords: Cypher query language, MATCH, MERGE, WHERE, RETURN, OPTIONAL MATCH, variable length paths (*1..2).","Provides concrete Cypher examples such as `MATCH (u:User {id: $user_id})-[:HAS_ACCESS]->(d:Document) RETURN d`.","Explains the use of MERGE for idempotent node/relationship creation during ingestion to prevent duplicate graph entities."]},{"id":"KP3","description":"Covers graph query optimization, constraint definitions, and index strategies.","required":true,"acceptable_evidence":["Technical keywords: Node key constraints, unique constraints, point-lookup B-tree/range indexes, PROFILE and EXPLAIN, memory heap configuration.","Explains creating unique constraints on entity keys (e.g., `CREATE CONSTRAINT FOR (e:Entity) REQUIRE e.id IS UNIQUE`).","Discusses analyzing execution plans using PROFILE/EXPLAIN to avoid expensive Cartesian products or excessive graph traversals."]},{"id":"KP4","description":"Integrates Neo4j graph traversal with hybrid GraphRAG retrieval pipelines for AI reasoning.","required":false,"acceptable_evidence":["Technical keywords: GraphRAG, 1-hop / 2-hop neighborhood expansion, Milvus vector hybrid search, LangChain Neo4jGraph, context enrichment.","Explains how vector search in Milvus identifies seed entities, which are then expanded via 1-2 hop Cypher traversals in Neo4j to retrieve connected relational context.","Describes formatting retrieved graph subgraphs into structured context prompts for LLM response generation."]}],"critical_failures":["Treats Neo4j as a relational table or purely vector store without understanding nodes, relationships, and property graph mechanics.","Fails to provide or explain Cypher syntax (e.g., MATCH, MERGE, RETURN) or relies on generic SQL syntax for graph operations.","Omits indexing or unique constraints, failing to address graph traversal performance or duplicate node creation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did your full-stack experience contribute to building AI applications, especially in integrating frontend and backend components?', '{"key_points":[{"id":"KP1","description":"Explains real-time streaming protocol integration between backend inference services and frontend user interfaces.","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events (SSE), StreamingResponse, FastAPI async generator, EventSource API, fetch ReadableStream, chunked transfer encoding.","Explains utilizing FastAPI StreamingResponse to stream token deltas from LLM providers directly to React frontend components.","Details frontend stream processing using Web API `ReadableStream` or `EventSource` to render progressive markdown responses without UI freezing."]},{"id":"KP2","description":"Details end-to-end data contract definition, schema synchronization, and typed validation across the stack.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModels, OpenAPI specification, TypeScript interfaces, automated type generation, payload validation.","Explains using Pydantic schemas in FastAPI to define strict input/output structures that auto-generate OpenAPI specs.","Describes synchronizing backend schemas with TypeScript interfaces in React to guarantee type safety across API boundaries."]},{"id":"KP3","description":"Covers asynchronous state management, latency handling, and responsive user feedback mechanisms.","required":true,"acceptable_evidence":["Technical keywords: React hooks (useState, useEffect, useReducer), AbortController, optimistic UI updates, loading skeletons, error boundaries.","Explains handling multi-second AI inference latencies using loading indicators, progress skeletons, and optimistic message rendering in chat lists.","Details implementing AbortController in frontend fetch requests to allow users to cancel in-flight LLM generations and free backend worker resources."]},{"id":"KP4","description":"Addresses end-to-end security, session propagation, and authorization across UI and backend layers.","required":false,"acceptable_evidence":["Technical keywords: JWT Bearer token, OAuth2PasswordBearer, HTTP Authorization header, CORS middleware, session_id propagation.","Explains securely injecting JWT bearer tokens into frontend Axios/fetch interceptors and validating them in FastAPI dependency injectors.","Describes propagating session_id and user_id from frontend requests through backend middleware down to Redis and PostgreSQL stores."]}],"critical_failures":["Advocates blocking synchronous HTTP request/response polling for AI text generation instead of streaming protocols (SSE/WebSockets).","Ignores API contracts, TypeScript/Pydantic validation, or error handling between frontend and backend layers."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did your system interact with databases or external systems via tools or APIs?', '{"key_points":[{"id":"KP1","description":"Defines standardized tool calling interfaces and schema specifications for LLM agent integration.","required":true,"acceptable_evidence":["Technical keywords: LangGraph tool nodes, LangChain @tool decorator, Pydantic schema validation, Model Context Protocol (MCP), function calling JSON schema.","Explains structuring tools with explicit Pydantic BaseModels defining parameter names, types, descriptions, and required constraints.","Details how the LLM produces structured JSON tool call arguments which are validated before invoking underlying Python functions."]},{"id":"KP2","description":"Implements safe, sandboxed database querying mechanisms and injection defense.","required":true,"acceptable_evidence":["Technical keywords: Parameterized SQL queries, read-only replica, SQLAlchemy / asyncpg, SQL injection prevention, schema exposure limiting.","Explains restricting automated database tools to read-only database connections and whitelisted tables/views to prevent catastrophic mutations.","Details executing parameterized queries rather than concatenating raw unvalidated LLM output strings into SQL interpreters."]},{"id":"KP3","description":"Details asynchronous HTTP client execution, retries, and failure resilience for third-party APIs.","required":true,"acceptable_evidence":["Technical keywords: httpx.AsyncClient, aiohttp, exponential backoff, tenacity, circuit breaker, timeout configuration.","Explains performing non-blocking external API requests using async HTTP clients to avoid blocking the FastAPI/LangGraph event loop.","Describes implementing exponential backoff retries with jitter for rate-limited (HTTP 429) or transient 5xx external upstream responses."]},{"id":"KP4","description":"Covers Human-in-the-Loop (HITL) checkpoints and security boundary governance for side-effect operations.","required":false,"acceptable_evidence":["Technical keywords: Human-in-the-Loop (HITL), LangGraph interrupt(), state checkpointing, authorization verification, audit logging.","Explains pausing execution via LangGraph interrupt checkpoints when an agent requests destructive actions (e.g., database writes, payment processing, sending emails).","Details waiting for human reviewer approval before persisting the state and resuming tool execution."]}],"critical_failures":["Allows arbitrary, unvalidated LLM text output to execute directly as raw SQL queries against production database connections.","Omits parameter validation or fails to define explicit Pydantic/JSON schemas for LLM tool calling interfaces."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach building AI systems that can be rapidly customized for different clients or use cases?', '{"key_points":[{"id":"KP1","description":"Designs a modular, configuration-driven architecture decoupling core agent logic from client-specific implementations.","required":true,"acceptable_evidence":["Technical keywords: LangGraph state graphs, pluggable architecture, dependency injection, YAML/JSON configuration, prompt templates.","Explains abstracting retrieval pipelines, model selection, and tool execution into pluggable modules configured via client configuration files.","Details using factory patterns or dependency injection to instantiate customized agent workflows per tenant without altering core engine code."]},{"id":"KP2","description":"Enforces robust multi-tenant data isolation and client-scoped vector and database partitioning.","required":true,"acceptable_evidence":["Technical keywords: Milvus partition keys / collections, PostgreSQL tenant_id filtering, metadata-based filtering, Row Level Security (RLS).","Explains isolating client knowledge bases using dedicated Milvus collections or partition keys with strict tenant_id pre-filtering.","Details enforcing relational database separation via tenant_id column constraints or PostgreSQL Row Level Security to prevent cross-tenant data leaks."]},{"id":"KP3","description":"Implements dynamic prompt templating, domain ontology alignment, and customized guardrail policies.","required":true,"acceptable_evidence":["Technical keywords: Jinja2 prompt templating, NeMo Guardrails, custom Pydantic schemas, client system prompts, domain taxonomy.","Describes dynamically loading client-specific system instructions, tone guidelines, and allowed toolsets based on authenticated tenant context.","Details configuring customizable guardrail rules to enforce compliance with specific client policies or regulatory requirements."]},{"id":"KP4","description":"Establishes automated ingestion workflows and standardized evaluation pipelines for rapid client onboarding.","required":false,"acceptable_evidence":["Technical keywords: Prefect/Airflow ETL pipelines, Docling document chunking, RAGAS automated evaluation (faithfulness, context_precision), LangSmith benchmarking.","Explains automating client document ingestion, embedding generation, and indexing via scheduled Prefect or Airflow workflows.","Details running automated RAGAS evaluation suites on newly ingested client corpora to establish baseline retrieval accuracy before production deployment."]}],"critical_failures":["Hardcodes prompts, models, vector store names, or client business rules directly inside application code instead of modular configuration.","Fails to establish multi-tenant data isolation, allowing potential cross-client data leakage in vector retrieval or database queries."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach building end-to-end AI systems that require both backend and UI integration?', '{"key_points":[{"id":"KP1","description":"Establishes an asynchronous, non-blocking backend service layer optimized for high-concurrency AI workloads.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async def, Uvicorn ASGI, asyncio event loop, APIRouter, background tasks, non-blocking I/O.","Explains building backend API gateways using FastAPI with asynchronous endpoints to prevent blocking on external LLM and vector DB calls.","Details leveraging uvicorn worker processes and async connection pooling to sustain concurrent chat sessions efficiently."]},{"id":"KP2","description":"Architects low-latency streaming pipelines connecting backend LLM generation directly to responsive frontend interfaces.","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events (SSE), StreamingResponse, fetch ReadableStream, chunked transfer encoding, React state updates.","Describes streaming raw LLM tokens via FastAPI StreamingResponse using SSE format (`data: {chunk}\\n\\n`).","Explains consuming streaming chunks in React via `ReadableStream` reader, appending tokens to local state for smooth progressive rendering."]},{"id":"KP3","description":"Implements distributed session state management and durable conversation persistence across client and server.","required":true,"acceptable_evidence":["Technical keywords: Redis session cache, PostgreSQL conversation_history, session_id header, token budget management, sliding window.","Explains tracking in-flight dialogue context in Redis with 24-hour TTL while persistently logging user interactions to PostgreSQL.","Details passing session identifiers between UI and backend to ensure continuity across browser refreshes and multi-turn exchanges."]},{"id":"KP4","description":"Integrates end-to-end telemetry, distributed tracing, and user feedback capture across UI and backend components.","required":false,"acceptable_evidence":["Technical keywords: LangSmith tracing, Prometheus metrics, run_id correlation, user feedback thumbs-up/down endpoint, OpenTelemetry.","Explains attaching unique trace/run IDs to backend generation requests and propagating them to the frontend UI.","Details collecting user feedback (thumbs up/down) mapped back to specific LangSmith trace IDs for continuous prompt and retrieval fine-tuning."]}],"critical_failures":["Designs synchronous blocking HTTP request-response loops for LLM responses, freezing client UIs during generation.","Omits distributed session handling or relies on client-side browser memory alone for conversational state persistence."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach building solutions that bridge rapid prototyping and production systems?', '{"key_points":[{"id":"KP1","description":"Applies an evolutionary architecture strategy transitioning from lightweight prototypes to modular production microservices.","required":true,"acceptable_evidence":["Technical keywords: LangGraph state machines, FastAPI microservices, Pydantic domain models, interface abstractions, clean architecture.","Explains structuring prototype code using interface abstractions (e.g., BaseRetriever, BaseLLM) so underlying implementations can be swapped without rewriting business logic.","Details refactoring exploratory notebook prototypes into modular FastAPI services with strict Pydantic validation schemas and test coverage."]},{"id":"KP2","description":"Upgrades ephemeral prototype storage and indexing to horizontally scalable, enterprise-grade data stores.","required":true,"acceptable_evidence":["Technical keywords: In-memory Chroma/FAISS to Milvus cluster (HNSW), SQLite to PostgreSQL connection pooling (asyncpg/HikariCP), Redis session caching.","Describes migrating initial in-memory vector stores to distributed Milvus clusters supporting billions of vectors and HNSW index tuning.","Explains replacing prototype SQLite databases with managed PostgreSQL clusters utilizing connection pooling, read replicas, and write-ahead logging."]},{"id":"KP3","description":"Institutes quantitative evaluation benchmarks and regression testing to measure prototype enhancements objectively.","required":true,"acceptable_evidence":["Technical keywords: RAGAS metrics (faithfulness, context_precision, answer_relevancy), golden evaluation dataset, LangSmith datasets, CI/CD regression gating.","Explains establishing curated ground-truth test sets to benchmark accuracy before promoting prototype prompt or pipeline modifications to production.","Details running automated RAGAS scoring in CI/CD pipelines to prevent quality regressions during iterative refactoring."]},{"id":"KP4","description":"Hardens production operations through containerization, autoscaling, rate limiting, and observability.","required":false,"acceptable_evidence":["Technical keywords: Docker multi-stage builds, Kubernetes/EKS HPA, API Gateway rate limiting, Prometheus/Grafana monitoring, circuit breakers.","Explains packaging services in minimal multi-stage Docker containers deployed to EKS with Horizontal Pod Autoscaling based on CPU/concurrency metrics.","Details implementing API Gateway rate limits and circuit breakers to protect downstream LLMs and vector databases from traffic spikes."]}],"critical_failures":["Recommends deploying exploratory Jupyter notebooks or raw prototype scripts directly into production environments without hardening.","Promotes architectural changes to production based on anecdotal testing without quantitative benchmark evaluation (e.g., RAGAS)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach rapid prototyping and iteration in fast-paced engineering environments?', '{"key_points":[{"id":"KP1","description":"Leverages modular frameworks and pre-built components to accelerate MVP delivery without accumulating irreversible technical debt.","required":true,"acceptable_evidence":["Technical keywords: LangGraph pre-built nodes, LangChain components, FastAPI scaffolding, Pydantic models, mock tools.","Explains using LangGraph state graph templates and reusable tool wrappers to assemble end-to-end conversational flows in days.","Details mocking external downstream dependencies and databases using typed stubs to validate AI workflow logic quickly."]},{"id":"KP2","description":"Employs an evaluation-driven iteration cycle based on empirical test sets rather than subjective inspection.","required":true,"acceptable_evidence":["Technical keywords: Golden dataset, LangSmith evaluation runs, RAGAS automated scoring, prompt versioning, iterative error analysis.","Explains curating a compact, high-quality benchmark dataset of representative user queries and ground-truth answers.","Details executing automated evaluation sweeps after each prompt or retrieval tweak to objectively quantify accuracy and latency deltas."]},{"id":"KP3","description":"Maintains decoupled configuration and environmental switches to test alternative models and techniques rapidly.","required":true,"acceptable_evidence":["Technical keywords: Environment variables, feature flags, interchangeable embedding models (BGE vs MiniLM), hybrid search weights (BM25 vs semantic).","Describes externalizing hyperparameters (chunk size, chunk overlap, k-neighbors, model temperature) into environment configs.","Explains using feature toggles or configuration parameters to seamlessly compare different model providers or embedding algorithms."]}],"critical_failures":["Iterates blindly without establishing benchmark evaluation metrics, relying solely on subjective spot-checking of individual outputs.","Reinvents foundational framework scaffolding from scratch during initial prototyping phases, stalling delivery."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you balance speed and simplicity versus scalability and robustness when building initial solutions?', '{"key_points":[{"id":"KP1","description":"Defines clear abstraction boundaries and clean interfaces that enable rapid initial delivery while preserving future extensibility.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, Repository pattern, interface abstraction, loose coupling, modular monolith.","Explains defining clear service contracts and domain models using Pydantic so storage backends or external APIs can be swapped without touching core logic.","Details starting with a modular monolithic architecture instead of microservices to minimize initial deployment and orchestration overhead."]},{"id":"KP2","description":"Selects pragmatic, production-viable foundational technologies rather than disposable toy libraries.","required":true,"acceptable_evidence":["Technical keywords: FastAPI over Flask, PostgreSQL over SQLite, Redis session caching, managed Milvus vector database.","Explains adopting FastAPI and PostgreSQL from day one to gain async performance and schema safety without sacrificing developer velocity.","Discusses choosing enterprise-grade tools that can easily scale out horizontally rather than starting with ephemeral tools requiring complete rewrites."]},{"id":"KP3","description":"Designs services to be stateless at the application tier to facilitate horizontal scaling when traffic expands.","required":true,"acceptable_evidence":["Technical keywords: Stateless FastAPI workers, externalized state in Redis/PostgreSQL, Horizontal Pod Autoscaling (HPA), load balancer.","Explains ensuring backend service containers hold no local in-memory session state, delegating all state to Redis and PostgreSQL.","Details how this stateless design enables straightforward horizontal replication behind load balancers without architectural refactoring."]},{"id":"KP4","description":"Embeds basic observability and defensive limits early without overcomplicating initial architecture.","required":false,"acceptable_evidence":["Technical keywords: Token limits, timeout handling, basic rate limiting, structured logging, LangSmith tracing.","Explains incorporating basic API timeouts, input validation bounds, and error logging from the outset to isolate failure modes.","Describes tracking LLM token consumption and latency metrics from early phases to identify scaling bottlenecks before they cause outages."]}],"critical_failures":["Prematurely over-engineers initial solutions with complex distributed microservices and multi-region messaging before validating core value.","Couples business logic directly to ephemeral in-memory state or ad-hoc scripts, creating insurmountable technical debt for production migration."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you balance your work across AI engineering, backend development, and frontend development?', '{"key_points":[{"id":"KP1","description":"Adopts a contract-first engineering methodology establishing shared schemas before cross-stack implementation.","required":true,"acceptable_evidence":["Technical keywords: OpenAPI specification, Pydantic schemas, TypeScript interfaces, contract-first design, mock endpoints.","Explains defining backend Pydantic models and generating OpenAPI contracts first so frontend and AI pipelines can develop in parallel against mock responses.","Details how strict data contracts prevent integration drift and cross-team communication bottlenecks."]},{"id":"KP2","description":"Prioritizes development efforts based on critical path bottlenecks across model quality, API throughput, and user experience.","required":true,"acceptable_evidence":["Technical keywords: Time to First Token (TTFT), RAGAS evaluation, Redis cache-aside, SSE streaming, end-to-end latency profiling.","Explains allocating effort to AI engineering when retrieval precision or model hallucination is the gating issue, backend when latency or concurrency bounds appear, and frontend when UI responsiveness lags.","Details optimizing end-to-end latency across the stack: BGE embedding speed (AI), async Redis caching (Backend), and smooth token chunk rendering (Frontend)."]},{"id":"KP3","description":"Maintains a cohesive developer workflow leveraging automated tooling, unified testing, and observability.","required":true,"acceptable_evidence":["Technical keywords: Docker Compose, pytest, LangSmith tracing, GitHub Actions CI/CD, full-stack observability.","Explains utilizing Docker Compose environments to run local PostgreSQL, Redis, Milvus, and FastAPI instances alongside React dev servers.","Details managing cross-cutting concerns like telemetry and error tracing end-to-end from browser events through backend API logs."]}],"critical_failures":["Treats AI engineering, backend, and frontend as completely isolated silos without maintaining synchronized data contracts or shared schemas.","Focuses exclusively on one tier (e.g. prompt tuning or visual styling) while ignoring backend concurrency limits, latency budgets, or data integrity."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you decide between monolithic, microservices, or hybrid architectures for a given problem?', '{"key_points":[{"id":"KP1","description":"Evaluates organizational boundaries, domain complexity, and independent deployment cadences using Domain-Driven Design.","required":true,"acceptable_evidence":["Technical keywords: Domain-Driven Design (DDD), bounded contexts, Conway\'s Law, independent deployability, team topology.","Explains analyzing whether domain models have strong transactional coupling (favoring monoliths) or clean independent business boundaries (favoring microservices).","Discusses how team size and release independence dictate architecture, where smaller teams benefit from unified monolith repos."]},{"id":"KP2","description":"Analyzes heterogeneous compute requirements and scaling characteristics specific to AI/ML workloads.","required":true,"acceptable_evidence":["Technical keywords: GPU vs CPU workloads, memory-intensive vector search (Milvus), lightweight I/O-bound CRUD (FastAPI), compute heterogeneity.","Explains isolating resource-heavy AI inference, document parsing (Docling), or vector search into dedicated services that scale independently from user-facing CRUD APIs.","Details preventing GPU/memory contention by decoupling batch data ingestion pipelines from latency-sensitive transactional endpoints."]},{"id":"KP3","description":"Weighs data consistency, transactional guarantees, and distributed complexity trade-offs.","required":true,"acceptable_evidence":["Technical keywords: ACID transactions, dual-write problem, CQRS, SQS/Kafka event-driven choreography, eventual consistency.","Explains how monolithic databases offer single-database ACID guarantees, whereas microservices introduce eventual consistency and complex distributed sagas.","Discusses implementing CQRS to separate transactional write systems (PostgreSQL) from optimized read/search systems (Milvus vector index)."]},{"id":"KP4","description":"Accounts for network latency, serialization overhead, and distributed observability costs.","required":true,"acceptable_evidence":["Technical keywords: Inter-process communication (IPC) vs in-memory method calls, network hops, OpenTelemetry, distributed tracing, LangSmith.","Explains the latency penalty of multiple internal HTTP/gRPC hops across microservices in real-time user-facing AI chat applications.","Details the operational overhead required for microservices: service discovery, distributed tracing, central logging, and Kubernetes cluster maintenance."]},{"id":"KP5","description":"Formulates a pragmatic hybrid architectural pattern combining modular monoliths with specialized AI services.","required":false,"acceptable_evidence":["Technical keywords: Modular monolith, specialized AI microservice, asynchronous queuing (Amazon SQS), BFF (Backend-For-Frontend).","Describes maintaining core business logic, user auth, and transactional entities within a robust modular FastAPI monolith.","Details spinning off specialized microservices solely for computationally intensive tasks like vector indexing, heavy model inference, or asynchronous document parsing."]}],"critical_failures":["Dogmatically mandates microservices for every scenario without justifying the operational complexity, network overhead, and distributed consistency challenges.","Fails to account for compute heterogeneity, co-locating heavy ML model batch execution inside synchronous transactional web servers."]}', 1),
('TECHNICAL', 'Software Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'How do you determine the final predicted class in KNN after identifying the nearest neighbors?', '{"key_points":[{"id":"KP1","description":"Explains the standard majority voting mechanism across identified nearest neighbors.","required":true,"acceptable_evidence":["Technical keywords: Majority voting, mode of class labels, unweighted count, k nearest neighbors, non-parametric classification.","Explains tallying the categorical class labels of the top k neighbors and assigning the class that has the highest count.","Details how unweighted majority voting treats all k neighbors with equal importance regardless of their relative distance to the query instance."]},{"id":"KP2","description":"Explains distance-weighted voting techniques and their mathematical formulations.","required":true,"acceptable_evidence":["Technical keywords: Distance-weighted voting, inverse Euclidean distance (1/d), Gaussian kernel weights, softmax weighting.","Explains assigning weights to neighbors inversely proportional to their distance (e.g., $w_i = 1 / d(x, x_i)$) so closer neighbors exert greater voting influence.","Details how distance weighting mitigates the risk of selecting a suboptimal class when neighbors are distributed unevenly across boundaries."]},{"id":"KP3","description":"Details tie-breaking strategies and hyperparameter tuning considerations.","required":true,"acceptable_evidence":["Technical keywords: Tie-breaking, odd k for binary classification, reducing k by 1, nearest neighbor fallback, cross-validation.","Explains selecting an odd value for k in binary classification tasks to prevent equal-vote deadlocks.","Describes tie-breaking heuristics when equal votes occur: falling back to 1-NN (the single closest neighbor), decreasing k, or comparing sum of distances."]}],"critical_failures":["Claims KNN learns parametric weights or coefficients during an offline training phase rather than being an instance-based lazy learner.","Fails to explain majority voting or cannot describe any tie-breaking or distance-weighting mechanism."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How do you integrate structured (SQL) and unstructured (document-based) data in AI systems to support real-time and contextual responses?', '{"key_points":[{"id":"KP1","description":"Architects dual retrieval pipelines optimized separately for relational structured tables and unstructured semantic documents.","required":true,"acceptable_evidence":["Technical keywords: Text-to-SQL / SQL execution engine, Milvus HNSW vector database, hybrid retrieval, Docling document parsing, embedding models.","Explains using PostgreSQL for precise relational filtering, numerical aggregations, and transactional records alongside Milvus for semantic text search.","Details parsing unstructured PDFs/documents into dense embeddings stored in Milvus while retaining relational references to SQL primary keys."]},{"id":"KP2","description":"Implements intelligent query routing and intent classification to direct user queries to the appropriate data pipeline.","required":true,"acceptable_evidence":["Technical keywords: LangGraph agent router, intent classification, LLM tool dispatch, structured vs unstructured intent.","Explains using a classifier or LangGraph routing node to analyze the prompt: routing quantitative/analytical questions to SQL tools and conceptual questions to vector search.","Describes multi-hop reasoning where queries requiring both domains invoke structured SQL lookups first, followed by contextual vector retrieval."]},{"id":"KP3","description":"Applies metadata filtering and relational cross-linking between vector embeddings and SQL database entities.","required":true,"acceptable_evidence":["Technical keywords: Metadata pre-filtering, foreign key alignment, Milvus boolean expression filtering, entity linking, Neo4j GraphRAG.","Explains tagging vector document chunks with SQL foreign keys (e.g., `customer_id`, `product_id`, `contract_date`) at ingestion time.","Details executing vector searches with scalar metadata pre-filters (e.g., `status == \'ACTIVE\' and org_id == 123`) to ensure strict relational consistency."]},{"id":"KP4","description":"Synthesizes structured tabular records and unstructured context passages into a unified, validated prompt payload.","required":true,"acceptable_evidence":["Technical keywords: Context fusion, Pydantic schema validation, prompt serialization, Markdown tabular representation, token budget.","Explains formatting SQL result sets as structured Markdown/JSON tables and combining them with retrieved text chunks in the LLM system prompt.","Details enforcing Pydantic schema validation on the combined payload to ensure downstream generation adheres to verified facts."]},{"id":"KP5","description":"Ensures query safety, concurrency, and real-time latency optimization across both data stores.","required":false,"acceptable_evidence":["Technical keywords: Read-only DB connection, SQL parameterization / query validation, Redis caching, async execution (asyncio.gather).","Explains executing structured SQL and unstructured Milvus vector queries concurrently via Python `asyncio.gather` to minimize latency.","Details enforcing strict read-only database connections and query validation to prevent malicious or accidental SQL mutations during agent execution."]}],"critical_failures":["Attempts to dump entire structured relational database tables into vector embeddings without utilizing relational query engines or schema-aware SQL tools.","Allows arbitrary, unvalidated LLM-generated SQL queries to execute directly against writable production databases."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you minimize downtime during database credential rotation in production systems?', '{"key_points":[{"id":"KP1","description":"Implements an overlapping dual-user credential rotation strategy to guarantee valid credentials throughout rotation.","required":true,"acceptable_evidence":["Technical keywords: Dual-user strategy, overlapping credentials, User A / User B rotation, zero-downtime rotation, active/standby credentials.","Explains provisioning two distinct database users with identical permissions where one user is active while the other is updated with new credentials.","Details verifying that newly rotated credentials authenticate successfully before revoking or retiring the previous credential set."]},{"id":"KP2","description":"Automates secret lifecycle management using centralized secret stores and event-driven rotation workflows.","required":true,"acceptable_evidence":["Technical keywords: AWS Secrets Manager, HashiCorp Vault, IAM authentication, rotation Lambda / cron job, secret versioning (AWSCURRENT / AWSPENDING).","Explains using AWS Secrets Manager or Vault to handle automated 30/90-day password generation and database role updates.","Details tracking secret staging labels (e.g., AWSPREVIOUS, AWSCURRENT, AWSPENDING) during the multi-step rotation lifecycle."]},{"id":"KP3","description":"Manages application-tier database connection pool refreshing without restarting running instances.","required":true,"acceptable_evidence":["Technical keywords: Dynamic connection pool refresh, SQLAlchemy / asyncpg pool recreation, graceful connection draining, PgBouncer reload.","Explains configuring the application or PgBouncer to dynamically reload credentials upon authentication failures or via background polling.","Details graceful draining of existing pooled connections so active in-flight queries complete before replacing the pool with new credentials."]},{"id":"KP4","description":"Establishes automated health probes, retry policies, and rollback mechanisms.","required":false,"acceptable_evidence":["Technical keywords: FastAPI /health probe, transient authentication retries, circuit breaker, exponential backoff, rollback triggers.","Explains implementing retry policies with exponential backoff for transient authentication handshakes during the brief rotation window.","Details automated rollback where rotation failure triggers immediate fallback to previous credentials, preserving application uptime."]}],"critical_failures":["Revokes old database credentials immediately before new credentials have been deployed and verified across all application instances.","Requires manual application downtime, full server restarts, or hardcoding credentials inside deployed environment images."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you restrict the number of transactions to avoid an outage for microservices?', '{"key_points":[{"id":"KP1","description":"Deploys distributed rate limiting algorithms at ingress API gateways and service layers.","required":true,"acceptable_evidence":["Technical keywords: Token Bucket algorithm, Leaky Bucket, Sliding Window Counter, Redis distributed rate limiter, Kong / AWS API Gateway.","Explains enforcing rate limits based on client IP, user ID, or API key using Redis sorted sets or atomic counters.","Details comparing Token Bucket (allowing controlled bursts) with Leaky Bucket (enforcing smooth constant processing rates)."]},{"id":"KP2","description":"Implements concurrency throttling and resource-bounded connection pooling at the application tier.","required":true,"acceptable_evidence":["Technical keywords: asyncio.Semaphore, max concurrent requests, Uvicorn worker limits, connection pool max_size, thread pool bounds.","Explains using `asyncio.Semaphore` in FastAPI to cap concurrent downstream requests to LLMs or vector databases.","Details sizing database connection pools (e.g., asyncpg max_size=20) to prevent saturating database backend process limits during traffic spikes."]},{"id":"KP3","description":"Employs circuit breakers and progressive load-shedding mechanisms during system degradation.","required":true,"acceptable_evidence":["Technical keywords: Circuit breaker pattern (Closed, Open, Half-Open), load shedding, fast failure, Resilience4j / pybreaker.","Explains tripping circuit breakers when downstream error rates or latencies exceed defined thresholds, instantly rejecting incoming transactions.","Details shedding non-critical transactions (e.g., background indexing, non-essential analytics) to preserve core transactional paths."]},{"id":"KP4","description":"Decouples bursty transaction ingestion from execution using asynchronous queues and backpressure buffering.","required":true,"acceptable_evidence":["Technical keywords: Amazon SQS, Apache Kafka, backpressure, consumer throttling, Dead Letter Queue (DLQ).","Explains buffering incoming requests in persistent queues (SQS) so worker services consume transactions at a sustainable, controlled rate.","Describes routing poison-pill or repeatedly failing transactions to a Dead Letter Queue to prevent pipeline stalls."]},{"id":"KP5","description":"Enforces client-facing contract standards and graceful degradation responses.","required":false,"acceptable_evidence":["Technical keywords: HTTP 429 Too Many Requests, Retry-After header, degraded fallback responses, client exponential backoff.","Explains returning HTTP 429 responses containing explicit `Retry-After` headers to instruct clients on backoff durations.","Details serving cached or degraded responses rather than throwing unhandled 500 server errors during overload."]}],"critical_failures":["Allows unbounded in-memory request buffering on web instances without backpressure, leading to fatal Out-Of-Memory (OOM) crashes.","Fails to return standard HTTP 429 status codes or lacks circuit breaker / shedding mechanisms when downstream microservices fail."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you secure backend applications, including authentication, authorization, rate limiting, and protection against common vulnerabilities?', '{"key_points":[{"id":"KP1","description":"Implements stateless, cryptographically signed authentication using industry-standard protocols.","required":true,"acceptable_evidence":["Technical keywords: OAuth2 with Password Bearer, JSON Web Tokens (JWT), asymmetric signing (RS256 / HS256), token expiration, refresh tokens.","Explains verifying signed JWTs in FastAPI dependencies using OAuth2PasswordBearer to validate issuer, audience, and expiry.","Details managing short-lived access tokens (e.g., 15 minutes) paired with secure, revocable refresh tokens stored in Redis."]},{"id":"KP2","description":"Enforces fine-grained authorization and Role-Based Access Control (RBAC) at the route and resource levels.","required":true,"acceptable_evidence":["Technical keywords: Role-Based Access Control (RBAC), FastAPI Depends() dependency injection, scopes, tenant isolation, claim validation.","Explains inspecting user roles and permissions within FastAPI route dependencies to restrict endpoint access (e.g., admin vs standard user).","Details validating resource ownership (e.g., verifying `user_id == resource.owner_id`) to prevent Insecure Direct Object Reference (IDOR) attacks."]},{"id":"KP3","description":"Deploys distributed rate limiting and abuse prevention mechanisms.","required":true,"acceptable_evidence":["Technical keywords: Redis sliding window, slowapi, token bucket, IP and user-based throttling, HTTP 429 Too Many Requests.","Explains tracking request frequencies in Redis using sliding window algorithms to throttle abusive clients per minute/hour.","Details enforcing stricter rate limits on sensitive endpoints (e.g., `/auth/login`, LLM generation) to thwart brute-force and DDoS attacks."]},{"id":"KP4","description":"Guards against injection, deserialization, and cross-origin security vulnerabilities.","required":true,"acceptable_evidence":["Technical keywords: Parameterized SQL queries, Pydantic input sanitization, CORS middleware, XSS prevention, Content-Security-Policy (CSP).","Explains using parameterized queries via ORMs (SQLAlchemy) to completely eliminate SQL injection risks.","Details configuring FastAPI CORSMiddleware with strict allowed origins and methods rather than permissive wildcard `*` settings."]},{"id":"KP5","description":"Enforces transport layer security, secret governance, and data-at-rest encryption.","required":false,"acceptable_evidence":["Technical keywords: TLS 1.3 / HTTPS termination, AWS Secrets Manager / HashiCorp Vault, environment variable protection, bcrypt / Argon2 hashing.","Explains hashing stored passwords with salted bcrypt or Argon2 algorithms and never logging plaintext secrets or API tokens.","Details sourcing sensitive credentials from secure secret stores into environment variables rather than committing them to version control."]}],"critical_failures":["Suggests storing plaintext passwords or API keys in databases or client-accessible storage without one-way cryptographic hashing.","Omits parameterized SQL queries, accepting concatenated raw user input strings directly into database query execution engines."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you select appropriate tools and technologies when integrating data across different systems such as SaaS platforms or databases?', '{"key_points":[{"id":"KP1","description":"Evaluates data velocity, latency tolerance, and ingestion volume requirements.","required":true,"acceptable_evidence":["Technical keywords: Real-time event streaming vs batch ETL/ELT, Change Data Capture (CDC), Kafka/SQS vs scheduled Airflow/Prefect, throughput.","Explains choosing event-driven streaming (Webhooks, Kafka, Debezium CDC) when downstream AI workflows require sub-second fresh context.","Details choosing batch ETL pipelines (Airflow, Spark) for high-volume historical analytics where hourly or daily latency is acceptable."]},{"id":"KP2","description":"Analyzes protocol standards, rate limitations, and schema capabilities of source external systems.","required":true,"acceptable_evidence":["Technical keywords: REST API pagination, GraphQL, webhook payloads, rate limit quotas, OpenAPI, SDK availability.","Explains evaluating SaaS API constraints including rate limit headers, cursor-based pagination, and payload compression.","Details choosing direct database connectors or CDC over REST polling when SaaS API quotas would otherwise bottleneck ingestion."]},{"id":"KP3","description":"Assesses pipeline orchestration, transformation tooling, and schema evolution support.","required":true,"acceptable_evidence":["Technical keywords: Prefect / Apache Airflow DAGs, dbt transformations, Pydantic / Avro schema validation, data lineage.","Explains selecting orchestration engines like Prefect for dynamic task retries, dependency graphs, and clear observability.","Details using Pydantic or Avro schemas to detect breaking schema changes from external SaaS platforms before data enters warehouse stores."]},{"id":"KP4","description":"Incorporates operational resiliency, idempotency, and error recovery architectures.","required":false,"acceptable_evidence":["Technical keywords: Idempotent upserts (ON CONFLICT DO UPDATE), Dead Letter Queues (DLQ), deduplication keys, circuit breakers.","Explains designing pipeline transformations with idempotent upserts in PostgreSQL and Milvus to safely allow pipeline re-runs.","Details isolating malformed records into Dead Letter Queues to prevent individual ingestion failures from halting entire sync jobs."]}],"critical_failures":["Selects heavyweight distributed streaming infrastructure (e.g. multi-node Kafka) for low-volume, daily batch transfers without considering operational overhead.","Overlooks data idempotency, schema validation, and rate-limit quotas, risking data corruption or blocked API access."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you stay up to date with rapidly evolving AI technologies, and how do you apply new learnings to your work?', '{"key_points":[{"id":"KP1","description":"Maintains a structured regimen of technical literature, open-source repositories, and research publications.","required":true,"acceptable_evidence":["Technical keywords: arXiv preprints, Hugging Face Papers / Models, GitHub release notes (LangGraph, vLLM, Milvus), conference proceedings (NeurIPS, ICML).","Explains following primary research papers on arXiv and GitHub release changelogs for foundational frameworks rather than relying on social media summaries.","Details tracking architectural advances in agentic planning, vector indexing algorithms (HNSW vs ScaNN), and inference optimizations."]},{"id":"KP2","description":"Executes empirical proof-of-concept benchmarks in isolated sandbox environments to evaluate claims.","required":true,"acceptable_evidence":["Technical keywords: Sandbox prototyping, ablation testing, baseline comparisons, local GPU benchmarking, latency vs accuracy profiling.","Describes setting up controlled test harnesses to evaluate new models, embedding architectures, or agent frameworks against existing baselines.","Details measuring real system impacts: Time to First Token (TTFT), token memory footprint, and retrieval recall before considering adoption."]},{"id":"KP3","description":"Applies a rigorous, evaluation-gated promotion process before deploying new technologies to production.","required":true,"acceptable_evidence":["Technical keywords: RAGAS evaluation (faithfulness, context_precision), LangSmith regression suites, A/B testing, gradual canary rollout.","Explains benchmarking candidate techniques against standardized golden datasets using automated RAGAS metrics to prove quantitative gains.","Details utilizing canary deployments or A/B testing to measure real-world user metrics and stability prior to full production cutover."]}],"critical_failures":["Adopts unvetted AI frameworks or models directly into production based purely on social media hype without empirical benchmark validation.","Lacks any disciplined evaluation criteria (e.g., RAGAS, golden test suites) to quantify whether new techniques outperform existing systems."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How does GROUP BY work in SQL, and when would you use it?', '{"key_points":[{"id":"KP1","description":"Explains the underlying execution mechanics of row partitioning based on grouping attributes.","required":true,"acceptable_evidence":["Technical keywords: Row partitioning, grouping attributes, hash aggregation, sort aggregation, temporary buckets.","Explains that the database engine scans table rows and collates them into distinct groups sharing identical values across the GROUP BY columns.","Details internal execution strategies such as Hash Aggregate (building in-memory hash tables) or Group Aggregate (sorting on group keys)."]},{"id":"KP2","description":"Describes the application of aggregate functions over grouped partitions and standard use cases.","required":true,"acceptable_evidence":["Technical keywords: Aggregate functions (COUNT, SUM, AVG, MIN, MAX), dimensional summarization, reporting metrics, cardinality reduction.","Explains calculating summary metrics per category, such as total revenue per user (`SUM(amount)` GROUP BY `user_id`) or call frequency per topic.","Emphasizes that non-aggregated columns in the SELECT clause must appear in the GROUP BY clause under standard SQL."]},{"id":"KP3","description":"Distinguishes pre-aggregation row filtering (WHERE) from post-aggregation group filtering (HAVING).","required":true,"acceptable_evidence":["Technical keywords: WHERE vs HAVING, logical query execution order, row-level predicate vs group-level predicate, EXPLAIN ANALYZE.","Explains that WHERE filters individual candidate rows before grouping occurs, while HAVING evaluates conditions on aggregated results after groups are formed.","Provides examples showing `WHERE status = \'COMPLETED\'` pruning rows followed by `HAVING COUNT(*) > 5` filtering aggregated groups."]}],"critical_failures":["Confuses WHERE and HAVING clauses, incorrectly claiming WHERE filters aggregated values or HAVING filters individual rows before grouping.","Includes arbitrary unaggregated columns in the SELECT clause without including them in the GROUP BY expression (violating SQL standards)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How does Redis differ from traditional relational databases?', '{"key_points":[{"id":"KP1","description":"Contrasts in-memory storage architectures and latency profiles against disk-backed relational storage engines.","required":true,"acceptable_evidence":["Technical keywords: In-memory primary storage, sub-millisecond latency, disk-backed B-tree/LSM storage, page cache, I/O bottlenecks.","Explains that Redis serves operations directly from RAM achieving sub-millisecond response times, whereas relational databases read from and write to disk with page caches.","Details how memory-bound operations in Redis avoid disk seek and I/O wait times typical of high-concurrency relational workloads."]},{"id":"KP2","description":"Differentiates native rich data structures from relational tabular schemas and SQL join operations.","required":true,"acceptable_evidence":["Technical keywords: Key-value store, native data structures (Strings, Hashes, Lists, Sets, Sorted Sets), relational schema, SQL JOINs, normalization.","Contrasts Redis\'s specialized data structures (e.g., ZSET for leaderboards, HSET for user sessions) with relational schemas organized into normalized tables.","Explains that Redis lacks declarative multi-table JOIN capabilities, requiring application-level assembly or denormalized models."]},{"id":"KP3","description":"Compares persistence mechanisms, durability guarantees, and transactional models.","required":true,"acceptable_evidence":["Technical keywords: Redis persistence (RDB snapshots, AOF append-only file), ACID compliance, Write-Ahead Logging (WAL), fsync, eventual durability.","Explains that relational databases offer strict ACID transactions via WAL with synchronous fsync, whereas Redis defaults to asynchronous persistence (RDB/AOF) with potential minor data loss on crash.","Details Redis single-threaded event loop atomic command execution versus relational multi-threaded multi-version concurrency control (MVCC)."]},{"id":"KP4","description":"Identifies complementary architectural coexistence patterns within production systems.","required":false,"acceptable_evidence":["Technical keywords: Cache-aside pattern, session store, rate limiting, system of record, hybrid coexistence.","Explains using Redis as a high-speed caching tier, distributed lock manager, and session store, while relying on PostgreSQL as the durable, auditable system of record.","Details preventing cache stampedes and managing TTL freshness to ensure Redis data remains synchronized with relational state."]}],"critical_failures":["Claims Redis cannot persist data to disk or claims Redis is a full relational database replacement with native SQL JOIN support.","Fails to articulate differences in storage medium (RAM vs disk) or fundamental data structures (key-value data structures vs normalized tables)."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How does the Vault platform architecture support multiple applications like R&D;, quality, safety, and compliance on a shared data foundation?', '{"key_points":[{"id":"KP1","description":"Multi-tenant unified core metadata architecture and domain entity models.","required":true,"acceptable_evidence":["Technical keywords: unified data foundation, multi-tenant architecture, shared metadata model, domain entity abstraction, schema inheritance.","Explains how a shared core schema models core master entities (products, clinical trials, regulatory documents, safety events) while allowing application-specific extensions.","Details metadata-driven configuration enabling R&D, Quality, Safety, and Compliance modules to consume identical underlying records without data duplication."]},{"id":"KP2","description":"Strict regulatory compliance, auditability, and data integrity enforcement.","required":true,"acceptable_evidence":["Technical keywords: 21 CFR Part 11, GxP compliance, immutable audit trail, versioning, electronic signatures, data integrity.","Details automated generation of tamper-evident audit trails recording user, timestamp, previous value, and rationale for every mutation.","Explains electronic signature capture and strict validation workflows required across clinical safety and quality operations."]},{"id":"KP3","description":"Role-based access control (RBAC), tenant isolation, and cross-application security boundaries.","required":true,"acceptable_evidence":["Technical keywords: RBAC, granular permissioning, object-level security, field-level security, tenant data isolation.","Describes how strict security policies enforce departmental boundaries (e.g., blinding clinical data from commercial users) on the same database foundation.","Details tenant isolation mechanisms preventing cross-client data leakage in cloud deployments."]},{"id":"KP4","description":"Cross-application workflow orchestration and event-driven data synchronization.","required":false,"acceptable_evidence":["Technical keywords: event-driven architecture, webhook events, lifecycle states, asynchronous message queues, cross-domain workflows.","Explains how events in one application (e.g., a safety adverse event) trigger automated actions in compliance and quality without point-to-point hardcoding."]}],"critical_failures":["Suggests duplicating entire databases for each application instead of leveraging a shared multi-tenant metadata core.","Fails to address regulatory compliance requirements such as immutable audit trails (21 CFR Part 11 / GxP).","Ignores granular object-level and field-level security isolation across functional business units."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How have you applied your software engineering background to building scalable AI/ML systems in production environments?', '{"key_points":[{"id":"KP1","description":"Applies distributed systems principles, service decoupling, and containerized deployment patterns.","required":true,"acceptable_evidence":["Technical keywords: FastAPI microservices, Docker multi-stage builds, Kubernetes/EKS orchestration, Horizontal Pod Autoscaler (HPA), API Gateway.","Explains architecting modular microservices separating API routing from asynchronous model inference and data ingestion workers.","Details containerizing AI microservices with Docker and deploying them on Kubernetes with autoscaling policies driven by CPU and request queues."]},{"id":"KP2","description":"Implements asynchronous queuing and non-blocking I/O to isolate computationally heavy AI inference.","required":true,"acceptable_evidence":["Technical keywords: Amazon SQS, Celery / background workers, asyncio event loop, backpressure management, decoupling.","Explains offloading document parsing (Docling) and bulk vector indexing to asynchronous worker queues (SQS) to prevent blocking user-facing APIs.","Details using non-blocking async handlers in FastAPI to ensure high request throughput while awaiting external LLM provider responses."]},{"id":"KP3","description":"Designs high-performance, tiered caching and persistent state management architectures.","required":true,"acceptable_evidence":["Technical keywords: Redis cache-aside, semantic embedding caching, PostgreSQL conversation history, Milvus HNSW vector store, connection pooling.","Explains caching frequent query embeddings and responses in Redis with TTLs to reduce redundant LLM API costs and lower latency.","Details managing transactional session persistence in PostgreSQL with connection pooling (asyncpg) alongside Milvus vector search."]},{"id":"KP4","description":"Establishes disciplined MLOps practices for data versioning, model governance, and drift monitoring.","required":true,"acceptable_evidence":["Technical keywords: DVC data versioning, MLflow model registry, Evidently drift detection, CI/CD automated retraining, feature store.","Explains tracking training datasets and pipeline artifacts using DVC to ensure complete experiment reproducibility.","Details monitoring data and prediction drift in production using Evidently, triggering automated alerts or retraining runs."]},{"id":"KP5","description":"Institutes comprehensive observability, distributed tracing, and quantitative evaluation frameworks.","required":false,"acceptable_evidence":["Technical keywords: LangSmith LLM tracing, Prometheus metrics, Grafana dashboards, RAGAS evaluation, OpenTelemetry.","Explains instrumenting services with Prometheus metrics (TTFT, request latency, token consumption) visualized in Grafana.","Details tracing multi-agent LLM reasoning graphs with LangSmith and running automated RAGAS evaluation pipelines."]}],"critical_failures":["Treats AI/ML as an isolated data science activity confined to Jupyter notebooks without software engineering practices (APIs, tests, CI/CD, deployment).","Executes heavy model inference or document processing synchronously within user-facing API request threads, causing blocking and server crashes under load."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How have you built and exposed APIs for AI systems using frameworks like FastAPI?', '{"key_points":[{"id":"KP1","description":"Architects asynchronous API endpoints leveraging non-blocking event loops for high-concurrency inference.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async def, Uvicorn ASGI server, asyncio event loop, non-blocking I/O, httpx.AsyncClient.","Explains writing `async def` route handlers in FastAPI to allow the single-threaded event loop to handle thousands of concurrent connections while awaiting upstream LLMs.","Details avoiding blocking CPU calls inside async handlers by utilizing `run_in_threadpool` or background tasks."]},{"id":"KP2","description":"Enforces strict input validation and response serialization using typed Pydantic models.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModels, Field validation, automated OpenAPI docs, schema constraints, HTTP 422 Unprocessable Entity.","Explains defining strongly typed request models (e.g., query strings, temperature, session_id) with Field constraints that reject invalid payloads automatically.","Details using response models to serialize LLM outputs cleanly, ensuring predictable schema contracts and auto-generated Swagger documentation."]},{"id":"KP3","description":"Implements real-time token streaming endpoints via Server-Sent Events (SSE).","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, Server-Sent Events (SSE), async generators, text/event-stream, Time to First Token (TTFT).","Explains creating streaming endpoints using FastAPI\'s `StreamingResponse(generator(), media_type=\'text/event-stream\')`.","Details yielding chunked token deltas as they arrive from LLM providers to minimize Time to First Token (TTFT) for clients."]},{"id":"KP4","description":"Utilizes dependency injection for authentication, rate limiting, and database session management.","required":false,"acceptable_evidence":["Technical keywords: Depends() dependency injection, OAuth2PasswordBearer, Redis session dependency, centralized exception handlers.","Explains using FastAPI `Depends()` to inject authenticated user contexts, database sessions, and Redis clients into route handlers.","Details implementing global exception handlers to catch LLM timeouts or rate limits and return standardized error payloads."]}],"critical_failures":["Executes blocking synchronous operations (e.g. `requests.get` or time.sleep) directly inside FastAPI `async def` endpoints, stalling the ASGI event loop.","Omits Pydantic schema validation or relies on unvalidated raw dictionary inputs, risking runtime type errors and security vulnerabilities."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How have you integrated backend APIs using frameworks like FastAPI into AI-driven systems, and how did you collaborate with frontend teams?', '{"key_points":[{"id":"KP1","description":"Drives contract-first API development using automated OpenAPI generation and typed schema sharing.","required":true,"acceptable_evidence":["Technical keywords: OpenAPI / Swagger UI (/docs), Pydantic schemas, TypeScript interfaces, contract-first design, openapi-typescript-codegen.","Explains exposing FastAPI\'s auto-generated OpenAPI documentation to frontend teams to agree upon request/response payloads before coding.","Details converting backend Pydantic models into TypeScript interfaces so frontend client components remain strictly synchronized with API contracts."]},{"id":"KP2","description":"Collaborates on streaming protocols and real-time token rendering implementations.","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events (SSE), StreamingResponse, fetch ReadableStream reader, chunk delimiter, handling stream cancellation.","Explains agreeing upon payload chunk formatting (e.g., JSON SSE events: `data: {\\"chunk\\": \\"...\\", \\"finish_reason\\": null}\\n\\n`).","Details coordinating with frontend engineers on parsing chunk streams in React and handling AbortController signals to cancel server generation."]},{"id":"KP3","description":"Standardizes HTTP status codes, error schemas, and loading/retry boundaries.","required":true,"acceptable_evidence":["Technical keywords: HTTP 422 validation error, HTTP 429 rate limit with Retry-After, HTTP 504 gateway timeout, standardized error payload format.","Explains establishing standard JSON error structures (`{\\"detail\\": \\"...\\", \\"code\\": \\"ERR_...\\"}`) to ensure frontend error boundaries render meaningful messages.","Details coordinating retry policies with exponential backoff for rate-limited (HTTP 429) requests."]},{"id":"KP4","description":"Establishes collaborative staging environments, mock servers, and integration testing workflows.","required":false,"acceptable_evidence":["Technical keywords: Postman / Insomnia collections, mock endpoints, Dockerized local staging, CORS middleware, integration testing.","Explains setting up FastAPI mock endpoints that return realistic mocked AI responses so frontend developers can build UI features without incurring LLM costs.","Details configuring CORS middleware properly across development and staging domains to ensure smooth cross-origin API integration."]}],"critical_failures":["Fails to provide OpenAPI documentation or clear contracts, leading to broken data contracts and misaligned frontend-backend schemas.","Forces frontend to wait for complete multi-second AI generation without supporting streaming protocols or coordinating chunk format standards."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How have you used Java and frameworks like Spring Boot to build microservices?', '{"key_points":[{"id":"KP1","description":"Architects microservices using core Spring Boot annotations, Dependency Injection, and layered architecture.","required":true,"acceptable_evidence":["Technical keywords: @RestController, @Service, @Repository, Inversion of Control (IoC), Dependency Injection (@Autowired / constructor injection), ApplicationContext.","Explains structuring enterprise services into controllers, business services, and data repositories using constructor injection for testability.","Details configuring Spring Boot starter dependencies (`spring-boot-starter-web`, `spring-boot-starter-data-jpa`) to minimize boilerplate configuration."]},{"id":"KP2","description":"Implements data persistence and object-relational mapping using Spring Data JPA and Hibernate.","required":true,"acceptable_evidence":["Technical keywords: Spring Data JPA, Hibernate, JpaRepository, @Entity, @Table, HikariCP connection pooling, @Transactional.","Explains creating entity models with JPA annotations and writing repository interfaces extending `JpaRepository` for automated CRUD and custom JPQL queries.","Details tuning HikariCP connection pool settings and managing database transaction boundaries using declarative `@Transactional` annotations."]},{"id":"KP3","description":"Secures microservice APIs and enforces validation using Spring Security and Bean Validation.","required":true,"acceptable_evidence":["Technical keywords: Spring Security, SecurityFilterChain, JWT authentication filter, @Valid, BindingResult, Method Security (@PreAuthorize).","Explains configuring stateless JWT authentication by inserting a custom `OncePerRequestFilter` into the Spring Security filter chain.","Details enforcing request payload constraints using Bean Validation annotations (`@NotNull`, `@Size`, `@Pattern`) with global `@ControllerAdvice` exception handlers."]},{"id":"KP4","description":"Enables inter-service communication, fault tolerance, and configuration management.","required":true,"acceptable_evidence":["Technical keywords: OpenFeign client, RestClient / WebClient, Resilience4j circuit breaker, Spring Cloud Config, Eureka service discovery.","Explains building declarative REST clients using OpenFeign or non-blocking WebClient for inter-microservice communication.","Details integrating Resilience4j circuit breakers and rate limiters to prevent cascading microservice failures during upstream outages."]},{"id":"KP5","description":"Incorporates microservice operational monitoring, containerization, and production deployment.","required":false,"acceptable_evidence":["Technical keywords: Spring Boot Actuator (/actuator/health, /metrics), Micrometer, Prometheus, Docker multi-stage build, Kubernetes pod deployment.","Explains exposing health and operational metrics via Spring Boot Actuator for Kubernetes liveness/readiness probes and Prometheus scraping.","Details packaging microservices as minimal Docker containers using multi-stage builds and deploying to Kubernetes clusters."]}],"critical_failures":["Confuses Spring Boot architecture with Python or Node.js frameworks, showing lack of understanding of Java enterprise patterns (IoC, JPA, annotations).","Omits transaction management (@Transactional), connection pooling, or security filter chains in production microservices."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How have your past experiences with full-stack development (React, FastAPI, MongoDB) supported your work in building end-to-end AI systems?', '{"key_points":[{"id":"KP1","description":"Orchestrates end-to-end data flow seamlessly from user interactions down through backend inference and persistence.","required":true,"acceptable_evidence":["Technical keywords: React frontend, FastAPI async backend, MongoDB document store, end-to-end data pipeline, RESTful/SSE communication.","Explains integrating user prompts from React UI into FastAPI async endpoints, dispatching AI reasoning, and persisting dialogue turns into MongoDB.","Details understanding the full lifecycle of an AI request, enabling rapid debugging of issues across client, server, or database layers."]},{"id":"KP2","description":"Translates full-stack frontend expertise into responsive, real-time AI user interfaces.","required":true,"acceptable_evidence":["Technical keywords: React hooks, SSE streaming consumption, markdown rendering, token-by-token display, loading states, optimistic updates.","Explains parsing streaming SSE tokens in React to provide instant visual feedback rather than freezing the screen during multi-second LLM calls.","Details rendering structured markdown, code blocks with syntax highlighting, and interactive feedback buttons (thumbs up/down) in the chat UI."]},{"id":"KP3","description":"Leverages MongoDB\'s flexible document schema for dynamic agent traces, memory logs, and heterogeneous metadata.","required":true,"acceptable_evidence":["Technical keywords: MongoDB BSON documents, dynamic schema, JSON logging, agent execution trace, tool call metadata, indexing on session_id.","Explains storing polymorphic AI agent execution traces, tool call parameters, and intermediate thoughts without rigid relational migrations.","Details indexing MongoDB collections on `session_id` and `timestamp` for sub-second dialogue retrieval and historical session analysis."]},{"id":"KP4","description":"Applies end-to-end performance profiling and latency optimization across all application tiers.","required":false,"acceptable_evidence":["Technical keywords: Time to First Token (TTFT), network latency, database query profiling, async concurrency, connection pooling.","Explains diagnosing end-to-end latency bottlenecks: optimizing browser bundle sizes, using non-blocking FastAPI async handlers, and indexing MongoDB queries.","Details tuning the system to minimize user-perceived latency across the complete interactive journey."]}],"critical_failures":["Describes the stack as disconnected tools without explaining how full-stack knowledge directly improves AI streaming latency, UX, or data flow.","Demonstrates inability to explain how MongoDB document storage handles semi-structured agent outputs and metadata."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How is session state maintained across multi-turn conversations, and what role do Postgres and Redis play?', '{"key_points":[{"id":"KP1","description":"Defines a tiered session storage architecture segregating hot ephemeral context from cold durable persistence.","required":true,"acceptable_evidence":["Technical keywords: Redis hot working memory, PostgreSQL cold storage / durable persistence, dual-tier architecture, cache-aside pattern, session lifecycle.","Explains using Redis for high-throughput, low-latency access to recent conversational turns during active user sessions.","Details persisting complete, auditable dialogue history in PostgreSQL to guarantee durability beyond Redis cache evictions."]},{"id":"KP2","description":"Details Redis session caching mechanics, key naming conventions, and TTL expiration policies.","required":true,"acceptable_evidence":["Technical keywords: `session:{session_id}` key schema, TTL (e.g. 24 hours), SETEX / EXPIRE, JSON serialization, cache eviction.","Explains storing active conversation buffers in Redis using keys like `session:{session_id}` with an automatic 24-hour TTL refreshed on each user turn.","Describes serializing message arrays into JSON strings or Redis Lists for sub-millisecond retrieval during prompt construction."]},{"id":"KP3","description":"Specifies the PostgreSQL relational schema for durable conversation history tracking.","required":true,"acceptable_evidence":["Technical keywords: conversation_history table (id, session_id, user_id, role, content, timestamp, token_count), B-tree index on (session_id, timestamp).","Outlines the relational schema storing every message turn with explicit columns: message ID, session foreign key, user ID, role (user/assistant), message body, and created timestamp.","Explains indexing on `(session_id, timestamp)` to ensure historical session lookups and analytical queries execute efficiently."]},{"id":"KP4","description":"Implements context window management, sliding window buffers, and LangGraph state checkpointing.","required":true,"acceptable_evidence":["Technical keywords: Sliding window buffer, token budget truncation, LangGraph checkpointer (PostgresSaver / RedisSaver), conversation summary buffer.","Explains maintaining a sliding window of the last k-turns (e.g., 6-10 messages) to prevent exceeding LLM context token limits.","Details how LangGraph checkpointers persist agent state graphs between turns, reloading active node states upon resuming conversations."]},{"id":"KP5","description":"Articulates write-through or cache-aside synchronization and failure recovery mechanics between Redis and PostgreSQL.","required":false,"acceptable_evidence":["Technical keywords: Write-through cache, cache-aside hydration, asynchronous persistence (background tasks), fallback query.","Explains writing each new conversation turn to PostgreSQL for durability and simultaneously updating the active Redis cache.","Details the cache-miss recovery flow: if a Redis key expires or evicts, the application queries PostgreSQL for recent messages to rehydrate the Redis session."]}],"critical_failures":["Confuses Redis ephemeral cache with permanent storage, relying solely on Redis without durable database persistence (risking complete history loss on eviction).","Fails to implement sliding window or token budget truncation, leading to LLM context window overflow errors during extended conversations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How is user context (such as user ID) passed across different components from UI to backend systems?', '{"key_points":[{"id":"KP1","description":"Transports user identity securely from frontend clients to backend APIs using standard cryptographic tokens.","required":true,"acceptable_evidence":["Technical keywords: HTTP Authorization header, Bearer token, JSON Web Token (JWT), claims (`sub`, `user_id`, `tenant_id`), Axios / fetch interceptors.","Explains injecting the JWT into the HTTP `Authorization: Bearer <token>` header on all frontend API requests via client interceptors.","Emphasizes that user ID is encoded within the cryptographically signed JWT payload rather than passed as an unverified, easily spoofed query parameter."]},{"id":"KP2","description":"Decodes, validates, and extracts user identity within backend gateway and middleware layers.","required":true,"acceptable_evidence":["Technical keywords: FastAPI OAuth2PasswordBearer, PyJWT / python-jose, cryptographic signature verification (RS256 / HS256), token expiration check.","Explains using FastAPI dependency injection (`Depends(get_current_user)`) to intercept requests, verify JWT signatures, and extract the authenticated `user_id`.","Details rejecting expired or tampered tokens immediately at the API gateway layer with HTTP 401 Unauthorized errors."]},{"id":"KP3","description":"Propagates user context across asynchronous internal Python execution threads and service calls.","required":true,"acceptable_evidence":["Technical keywords: Python contextvars, request.state, thread-local storage, correlation ID, dependency injection.","Explains storing extracted user context in `request.state.user_id` or Python `contextvars` to make user context accessible to deep internal service methods without parameter drilling.","Details propagating user context into asynchronous background tasks and LangGraph agent execution states."]},{"id":"KP4","description":"Enforces user context down to downstream storage, multi-tenant databases, and external service calls.","required":false,"acceptable_evidence":["Technical keywords: Multi-tenant filtering, Row Level Security (RLS), Milvus partition/scalar filter (`user_id == ...`), inter-service HTTP headers.","Explains appending user and tenant filters to all SQL database queries and Milvus vector searches to guarantee data isolation.","Details forwarding user identity and trace IDs in downstream inter-service HTTP headers or SQS message metadata."]}],"critical_failures":["Passes unauthenticated, easily spoofable user IDs directly in plaintext URL parameters or request bodies without token cryptographic verification.","Fails to validate or enforce user ID isolation at database query boundaries, allowing potential cross-tenant or cross-user data leakage."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How is your experience in terms of the databases understanding the queries SQL queries etc. How what has been your experience in that?', '{"key_points":[{"id":"KP1","description":"Demonstrates advanced SQL query fluency and analytical data manipulation techniques.","required":true,"acceptable_evidence":["Technical keywords: Complex JOINs (INNER, LEFT, FULL OUTER), Common Table Expressions (CTEs), Window functions (ROW_NUMBER, RANK, LAG/LEAD), subqueries, aggregations.","Explains writing complex analytical queries using CTEs (`WITH ... AS (...)`) for clean modular query organization.","Details applying SQL window functions for pagination, ranking, and running totals over partitioned datasets."]},{"id":"KP2","description":"Utilizes query execution plans and performance profiling tools to diagnose database bottlenecks.","required":true,"acceptable_evidence":["Technical keywords: EXPLAIN / EXPLAIN ANALYZE, Sequential Scan (Seq Scan) vs Index Scan, Index Only Scan, Hash Join, Nested Loop, cost estimation.","Explains analyzing PostgreSQL execution plans using `EXPLAIN (ANALYZE, BUFFERS)` to detect costly full-table sequential scans and suboptimal join algorithms.","Details interpreting planner cost estimates, buffer cache hits, and actual execution times to guide query restructuring."]},{"id":"KP3","description":"Designs strategic database indexes aligned with specific query access patterns.","required":true,"acceptable_evidence":["Technical keywords: B-tree indexes, GIN indexes (JSONB / full-text), BRIN indexes (time-series), composite indexes (multi-column), partial indexes.","Explains creating composite B-tree indexes ordered by equality columns first followed by range columns (e.g., `(user_id, created_at)`).","Details using GIN indexes for fast searching over JSONB payloads or document text attributes in PostgreSQL."]},{"id":"KP4","description":"Addresses transaction isolation, concurrency control, and connection pooling in high-load systems.","required":false,"acceptable_evidence":["Technical keywords: ACID transactions, transaction isolation levels (Read Committed, Serializable), Multi-Version Concurrency Control (MVCC), PgBouncer connection pooling, deadlocks.","Explains handling concurrent transactions and avoiding race conditions or deadlocks using appropriate isolation levels and explicit row locking (`SELECT ... FOR UPDATE`).","Details configuring PgBouncer or asyncpg connection pooling to prevent connection exhaustion under heavy concurrent query spikes."]}],"critical_failures":["Exhibits superficial SQL knowledge limited to basic SELECT * queries without understanding query plans (EXPLAIN), joins, or aggregation.","Unaware of the performance consequences of missing indexes or cannot distinguish between a sequential scan and an index scan."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Startups are usually made to family and not super stable · what gets you interested in joining a startup there?', '{"key_points":[{"id":"KP1","description":"Values high autonomy, technical ownership, and direct influence over foundational architectural decisions.","required":true,"acceptable_evidence":["Technical keywords: High technical agency, zero-to-one engineering, architectural ownership, end-to-end responsibility, rapid decision-making.","Explains being motivated by the opportunity to architect core systems (e.g., choosing FastAPI, Milvus, Redis, LangGraph) from scratch without bureaucratic inertia.","Details thriving in environments where personal code contributions directly shape production system performance and product success."]},{"id":"KP2","description":"Thrives on rapid iteration cycles, wearing multiple hats, and cross-functional technical breadth.","required":true,"acceptable_evidence":["Technical keywords: Fast feedback loops, cross-stack breadth (frontend, backend, AI, MLOps, DevOps), fast-paced shipping, adaptive engineering.","Explains enthusiasm for working across the complete stack: writing React frontends, FastAPI microservices, Milvus retrieval pipelines, and Kubernetes deployment scripts.","Describes an agile mindset that embraces shifting priorities and treats technical ambiguity as an opportunity for innovative problem solving."]},{"id":"KP3","description":"Connects engineering efforts directly to tangible customer value and measurable business growth.","required":true,"acceptable_evidence":["Technical keywords: Customer impact, product-market fit, business value creation, tangible user feedback, mission-driven alignment.","Explains enjoying the immediate visibility of customer impact, seeing user feedback directly inform product improvements.","Details finding deep fulfillment in solving mission-critical client problems that directly determine the startup\'s market traction."]}],"critical_failures":["Expresses a strong preference for rigid enterprise structure, siloed specialized roles, or reluctance to operate outside defined job boundaries.","Views startup environments purely through financial speculation (equity) without expressing genuine passion for high-ownership technical challenges."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Talk me through how I would normalize the data coming in when dealing with external APIs and multiple systems.', '{"key_points":[{"id":"KP1","description":"Ingests, validates, and parses heterogeneous external payloads into strongly typed intermediate models.","required":true,"acceptable_evidence":["Technical keywords: Pydantic Data Transfer Objects (DTOs), JSON Schema validation, strict type casting, schema parsing, field validators.","Explains defining source-specific Pydantic schemas that validate incoming raw payloads, reject malformed records, and parse raw strings into structured data types.","Details handling heterogeneous null representations (e.g., `\\"\\"`, `null`, `\\"N/A\\"`) using custom Pydantic `@field_validator` functions."]},{"id":"KP2","description":"Maps disparate external representations into a unified canonical enterprise domain model.","required":true,"acceptable_evidence":["Technical keywords: Canonical data model (CDM), field mapping layer, semantic translation, domain entity, structural normalization.","Explains creating a standardized internal domain model that decouples internal microservices from third-party API naming conventions and structural variations.","Details mapping diverse external field variations (e.g., `client_num`, `cust_id`, `accountNumber`) to a unified `customer_id` attribute."]},{"id":"KP3","description":"Cleanses, standardizes, and unifies data formats across temporal, categorical, and geographical attributes.","required":true,"acceptable_evidence":["Technical keywords: ISO 8601 UTC timestamps, E.164 phone normalization, enum standardization, currency normalization, unicode normalization (NFC).","Explains parsing diverse timestamp formats into standard UTC ISO 8601 strings to prevent timezone discrepancies across systems.","Details normalizing categorical status values into standard internal Enum constants (e.g., mapping `\\"active\\"`, `\\"1\\"`, `\\"ENABLED\\"` to `Status.ACTIVE`)."]},{"id":"KP4","description":"Performs entity resolution, deduplication, and idempotent database upserts.","required":true,"acceptable_evidence":["Technical keywords: Deduplication, entity resolution, PostgreSQL ON CONFLICT DO UPDATE, Neo4j MERGE, idempotent write, unique business keys.","Explains matching records across systems using composite unique keys or fuzzy matching algorithms to prevent duplicate entity creation.","Details executing idempotent upserts in PostgreSQL (`INSERT ... ON CONFLICT (...) DO UPDATE`) to ensure replayable, resilient pipeline processing."]},{"id":"KP5","description":"Institutes dead-letter routing, schema versioning, and observability for unparseable data.","required":false,"acceptable_evidence":["Technical keywords: Dead Letter Queue (DLQ), Amazon SQS, schema versioning, unhandled payload quarantine, alerting on validation failure spikes.","Explains routing unparseable or breaking third-party payloads to a Dead Letter Queue for engineering review without crashing ingestion pipelines.","Details monitoring validation error rates in Prometheus to rapidly detect silent upstream API schema updates."]}],"critical_failures":["Persists raw, unvalidated external API responses directly into core database tables without normalization or schema validation.","Fails to handle temporal, categorical, or null-value formatting differences, leading to corrupted records and downstream query failures."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Walk me through each step of the architecture so I can visualize what that structure looks like.', '{"key_points":[{"id":"KP1","description":"Details the client and ingress tier managing authentication, rate limiting, and traffic routing.","required":true,"acceptable_evidence":["Technical keywords: React UI client, API Gateway / ALB, TLS termination, OAuth2 / JWT authentication, rate limiting (Token Bucket), CORS.","Explains user interaction via a React single-page application communicating over HTTPS with an API Gateway.","Details gateway responsibilities: terminating TLS, verifying JWT authorization headers, and throttling requests via rate limiting algorithms before forwarding to backend services."]},{"id":"KP2","description":"Explains the backend application and agent orchestration layer managing business workflows.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async microservices, Uvicorn ASGI, LangGraph multi-agent orchestration, Pydantic schemas, dependency injection.","Explains FastAPI async handlers receiving validated requests and handing them to LangGraph state machine agents.","Details LangGraph coordinating multi-step reasoning, dynamic tool selection, and Human-in-the-Loop checkpoints across agent nodes."]},{"id":"KP3","description":"Describes the dual-tier session state and persistent storage layer.","required":true,"acceptable_evidence":["Technical keywords: Redis session cache (TTL 24h), PostgreSQL relational database, conversation_history table, connection pooling (asyncpg).","Explains fetching active conversational context from Redis for sub-millisecond turn updates.","Details simultaneously persisting all conversation turns, users, and audit logs into PostgreSQL tables for durability and compliance."]},{"id":"KP4","description":"Details the hybrid retrieval and knowledge intelligence layer.","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW vector database, dense BGE embeddings, BM25 sparse keyword search, cross-encoder reranking, Neo4j GraphRAG.","Explains executing hybrid search in Milvus combining dense vector embeddings with BM25 keyword matching, refined via a cross-encoder reranker.","Details querying Neo4j knowledge graphs via Cypher to retrieve connected entity relationships and enrich context for the LLM prompt."]},{"id":"KP5","description":"Covers asynchronous background pipelines, observability, and MLOps infrastructure.","required":false,"acceptable_evidence":["Technical keywords: Amazon SQS, Docling document parser, Prefect ETL, LangSmith tracing, Prometheus / Grafana metrics, Evidently drift detection.","Explains decoupling document uploads via Amazon SQS workers that run Docling PDF parsing and vector indexing in the background.","Details tracking system health with Prometheus/Grafana and tracing LLM execution graphs end-to-end via LangSmith."]}],"critical_failures":["Presents an oversimplified single-box architecture that fails to separate client, application, storage, and AI retrieval tiers.","Omits caching, database persistence, or asynchronous processing mechanisms, demonstrating an incomplete view of production architecture."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What APIs did you build using FastAPI, and what operations did they support?', '{"key_points":[{"id":"KP1","description":"Exposes real-time conversational streaming and query execution endpoints.","required":true,"acceptable_evidence":["Technical keywords: POST `/api/v1/chat`, StreamingResponse, Server-Sent Events (SSE), async generator, session_id parameter, query payload.","Explains building a POST `/api/v1/chat` endpoint accepting user messages and returning real-time LLM token streams using `StreamingResponse`.","Details handling client parameters including session_id, model configuration, and streaming control flags."]},{"id":"KP2","description":"Provides session and conversation history lifecycle management endpoints.","required":true,"acceptable_evidence":["Technical keywords: GET/DELETE `/api/v1/sessions`, GET `/api/v1/sessions/{session_id}/history`, Redis cache, PostgreSQL conversation_history, pagination.","Explains endpoints for fetching historical conversations (`GET /api/v1/sessions/{id}/history`) with pagination (limit/offset) from PostgreSQL.","Details session deletion and reset endpoints that invalidate keys in Redis and archive conversation records in the database."]},{"id":"KP3","description":"Implements document ingestion and knowledge base indexing endpoints.","required":true,"acceptable_evidence":["Technical keywords: POST `/api/v1/documents/upload`, UploadFile / multipart/form-data, background tasks / SQS trigger, Docling chunking, Milvus indexing.","Explains building multipart file upload endpoints (`POST /api/v1/documents/upload`) that accept PDFs/docs for knowledge ingestion.","Details returning immediate job IDs (HTTP 202 Accepted) while delegating document chunking and embedding generation to background workers."]},{"id":"KP4","description":"Supports administrative, health monitoring, and evaluation trigger endpoints.","required":false,"acceptable_evidence":["Technical keywords: GET `/health` (liveness/readiness), GET `/metrics` (Prometheus), POST `/api/v1/evaluate` (RAGAS evaluation trigger).","Explains implementing health check endpoints validating database and Redis connectivity for Kubernetes liveness/readiness probes.","Details administrative endpoints to trigger offline RAGAS evaluation benchmark runs or clear internal cache state."]}],"critical_failures":["Describes only generic CRUD endpoints without mentioning any AI, streaming, document ingestion, or vector retrieval API capabilities.","Fails to specify concrete HTTP methods (POST, GET), route paths, or asynchronous request handling patterns."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are the core fundamentals or skills that provide a long-term, flexible career path in the rapidly evolving field of AI/ML?', '{"key_points":[{"id":"KP1","description":"Emphasizes foundational computer science, software engineering, and systems architecture principles.","required":true,"acceptable_evidence":["Technical keywords: Data structures and algorithms, distributed systems, API design, database internals, concurrency (asyncio), networking.","Explains that high-performance engineering fundamentals—such as designing scalable APIs, memory management, and distributed caching—endure across changing AI frameworks.","Details how deep software engineering skills enable engineers to transition effortlessly between new AI libraries and production runtimes."]},{"id":"KP2","description":"Highlights mathematical underpinnings and core machine learning fundamentals over fleeting wrapper libraries.","required":true,"acceptable_evidence":["Technical keywords: Linear algebra, probability and statistics, optimization (gradient descent), loss functions, transformer architecture internals, attention mechanism.","Explains understanding the mathematical mechanisms behind vector embeddings, attention matrices, and loss formulations rather than just calling high-level APIs.","Details how mathematical grounding allows engineers to diagnose model failures, fine-tuning instabilities, and embedding degradation."]},{"id":"KP3","description":"Prioritizes disciplined MLOps, empirical evaluation methodology, and production reliability.","required":true,"acceptable_evidence":["Technical keywords: Automated evaluation (RAGAS), MLOps, data versioning (DVC), drift monitoring (Evidently), continuous benchmarking, observability.","Explains that rigorous evaluation methodologies—establishing golden datasets and measuring statistical significance—are essential regardless of model type.","Details the long-term value of mastering deployment pipelines, telemetry, and system observability for production AI platforms."]}],"critical_failures":["Focuses exclusively on transient high-level wrapper tools or superficial prompt tweaking without mastering underlying engineering, mathematical, or systems fundamentals.","Dismisses software engineering, scalability, and evaluation rigor in favor of purely theoretical or toy implementations."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are the key cultural strengths and challenges of working in a rapidly growing company like Veeva?', '{"key_points":[{"id":"KP1","description":"Recognizes the cultural strength of deep industry domain specialization and customer-centric software stability.","required":true,"acceptable_evidence":["Technical keywords: Customer success culture, life sciences domain expertise, high architectural stability, Public Benefit Corporation (PBC), long-term product vision.","Explains that Veeva\'s focus on life sciences and healthcare drives a mission-oriented culture emphasizing software correctness and long-term customer partnerships.","Details the benefit of well-defined enterprise customer requirements and clear business models compared to speculative consumer apps."]},{"id":"KP2","description":"Addresses the operational challenges of strict regulatory compliance, data validation, and enterprise governance.","required":true,"acceptable_evidence":["Technical keywords: Regulatory compliance (21 CFR Part 11, GxP, HIPAA), strict data validation, audit trails, rigorous release qualification.","Explains the necessity for comprehensive audit trails, data integrity verification, and rigorous testing required in life sciences software.","Details navigating slower, formal deployment qualification cycles to ensure patient safety and regulatory adherence."]},{"id":"KP3","description":"Balances rapid architectural innovation with enterprise reliability and scaling organizational complexity.","required":true,"acceptable_evidence":["Technical keywords: Scaling engineering teams, adopting modern AI/cloud stacks, enterprise backward compatibility, technical debt management.","Explains the challenge of modernizing legacy systems and introducing generative AI while maintaining absolute backward compatibility.","Details managing cross-team coordination, standardizing development practices, and maintaining agile execution as engineering headcount expands."]}],"critical_failures":["Fails to acknowledge the enterprise regulatory, compliance, or life sciences context that defines Veeva\'s product ecosystem.","Advocates reckless \'move fast and break things\' startup methodologies without respecting mission-critical software reliability and audit requirements."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are the key responsibilities you take on when building and maintaining full-stack applications, including frontend, backend, APIs, and databases?', '{"key_points":[{"id":"KP1","description":"Engineers responsive, performant user interfaces and client-side state architectures.","required":true,"acceptable_evidence":["Technical keywords: React component architecture, TypeScript typing, client state management, real-time SSE streaming consumption, responsive UI/UX.","Explains building modular frontend components, managing global application state, and implementing streaming token renderers for interactive AI chat.","Details handling optimistic updates, loading states, and client-side error boundaries to deliver an intuitive user experience."]},{"id":"KP2","description":"Architects high-concurrency backend services and typed API contracts.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async def, Uvicorn ASGI, Pydantic data validation, APIRouter modularization, REST / SSE endpoints.","Explains designing modular backend routes with FastAPI, validating input payloads via Pydantic, and managing non-blocking asynchronous workflows.","Details structuring clean architectural layers separating API controllers from business services and external integrations."]},{"id":"KP3","description":"Designs database schemas, ensures data persistence, and tunes query performance.","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL relational schema design, Alembic database migrations, B-tree / GIN indexing, Redis caching, connection pooling.","Explains designing normalized database schemas, authoring version-controlled migrations with Alembic, and creating indexes based on query profiles.","Details implementing Redis caching patterns to reduce database load and maintain sub-millisecond session access."]},{"id":"KP4","description":"Owns deployment pipelines, containerization, security enforcement, and operational telemetry.","required":false,"acceptable_evidence":["Technical keywords: Docker containerization, CI/CD pipelines (GitHub Actions), JWT authentication, Prometheus / Grafana observability, logging.","Explains packaging applications into Docker containers, configuring automated CI/CD build and test pipelines, and enforcing JWT authorization.","Details setting up health check endpoints, central logging, and Prometheus metrics to monitor system availability in production."]}],"critical_failures":["Limits responsibilities exclusively to one siloed layer (e.g. only frontend design or only database queries) without demonstrating full-stack lifecycle ownership.","Omits operational concerns such as database migrations, security, API contracts, or system observability."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What are your goals in working on scalable AI platforms, and how do you plan to contribute to building end-to-end AI-driven products?', '{"key_points":[{"id":"KP1","description":"Articulates a clear technical vision for enterprise-grade, low-latency, and horizontally scalable AI platform architecture.","required":true,"acceptable_evidence":["Technical keywords: Sub-second Time to First Token (TTFT), horizontally scalable AI gateway, multi-tenant vector indexing, asynchronous agent orchestration.","Explains driving platform performance by optimizing vector retrieval pipelines, caching common semantic queries in Redis, and minimizing streaming latencies.","Details building resilient agentic infrastructure capable of handling high concurrent user workloads without degradation."]},{"id":"KP2","description":"Contributes to robust data pipelines, knowledge indexing systems, and vector store infrastructure.","required":true,"acceptable_evidence":["Technical keywords: Milvus distributed cluster (HNSW), hybrid search (BM25 + dense BGE), Docling document chunking, Prefect / Airflow pipelines.","Explains architecting high-throughput ingestion pipelines that parse and index massive document corpora into Milvus with fine-tuned HNSW indexing.","Details implementing hybrid search and cross-encoder rerankers to maximize retrieval context precision for downstream LLMs."]},{"id":"KP3","description":"Establishes automated evaluation pipelines, model governance, and continuous MLOps rigor.","required":true,"acceptable_evidence":["Technical keywords: RAGAS evaluation (faithfulness, answer_relevancy), LangSmith tracing, MLflow model registry, Evidently drift monitoring.","Explains implementing automated evaluation suites in CI/CD pipelines to benchmark model output quality objectively before production releases.","Details setting up production drift detection and distributed tracing to monitor model behavior and detect hallucinations."]},{"id":"KP4","description":"Bridges complex AI capabilities into intuitive, reliable, and secure end-user applications.","required":false,"acceptable_evidence":["Technical keywords: Human-in-the-Loop (HITL), NeMo Guardrails, React streaming UX, Pydantic schema validation, enterprise security.","Explains translating enterprise business needs into deterministic agent workflows guarded by strict Pydantic schemas and guardrails.","Details collaborating across product and design to ensure AI-driven products provide transparent, responsive, and verifiable outputs."]}],"critical_failures":["Expresses goals divorced from scalable systems engineering, treating AI platforms as purely theoretical or exploratory research.","Fails to articulate concrete contributions to scalability, latency optimization, data engineering, or production reliability."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are your interests outside of work?', '{"key_points":[{"id":"KP1","description":"Demonstrates authentic intellectual curiosity and passion for continuous technical exploration.","required":true,"acceptable_evidence":["Technical keywords: Open-source contributions, building personal software projects, experimenting with new LLMs/frameworks, reading technical papers.","Explains engaging with technical hobbies such as contributing to open-source tools, building home automation systems, or exploring new AI capabilities.","Details how self-directed technical exploration fuels creative problem-solving and keeps skills sharp."]},{"id":"KP2","description":"Pursues disciplined physical wellness, sports, or outdoor activities that build stamina and mental resilience.","required":true,"acceptable_evidence":["Technical keywords: Fitness training, running, hiking, competitive sports, cycling, discipline, cognitive balance.","Explains participating in structured physical activities that foster mental discipline, stress management, and physical health.","Details how physical pursuits provide a healthy counterbalance to intense engineering and problem-solving work."]},{"id":"KP3","description":"Engages in creative, collaborative, or community-oriented pursuits reflecting well-rounded personal growth.","required":true,"acceptable_evidence":["Technical keywords: Music, strategy games, reading, community volunteering, mentoring, collaborative hobbies.","Explains participating in creative or strategic hobbies (such as playing chess, music, or reading diverse non-fiction) that broaden perspective.","Demonstrates effective communication and interpersonal interests that support positive team collaboration."]}],"critical_failures":["Displays a disingenuous or entirely fabricated response devoid of authentic personal interests or healthy work-life balance.","Demonstrates an unhealthy attitude toward work or complete absence of curiosity and personal development."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What backend and frontend technologies did you use, and what was your level of involvement in each?', '{"key_points":[{"id":"KP1","description":"Articulates core backend technologies utilized and specific architectural contributions.","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Python asyncio, Uvicorn, Pydantic, LangGraph, APIRouter, StreamingResponse, dependency injection.","Explains actively developing FastAPI async microservices, implementing Pydantic data contracts, and architecting LangGraph multi-agent workflows.","Details personally designing real-time SSE streaming endpoints and managing asynchronous background tasks for document indexing."]},{"id":"KP2","description":"Details frontend technologies used and ownership of user interface components.","required":true,"acceptable_evidence":["Technical keywords: React, TypeScript, Tailwind CSS, EventSource / fetch ReadableStream, client state management, UI component library.","Explains building interactive user interfaces in React with TypeScript, managing client state, and implementing streaming token display components.","Details constructing chat interfaces with real-time markdown parsing, citation popovers, and feedback controls."]},{"id":"KP3","description":"Specifies database, caching, and retrieval infrastructure technologies and direct management responsibilities.","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, Redis (TTL caching), Milvus (HNSW vector indexing), Neo4j (GraphRAG), Alembic migrations.","Explains modeling relational tables in PostgreSQL, configuring Redis session caching with 24-hour TTL, and setting up Milvus HNSW vector collections.","Details writing Cypher queries for Neo4j knowledge graphs and implementing hybrid vector-graph retrieval pipelines."]},{"id":"KP4","description":"Outlines deployment, containerization, and observability tooling used in day-to-end development.","required":false,"acceptable_evidence":["Technical keywords: Docker multi-stage builds, Kubernetes / EKS, Prometheus, Grafana, LangSmith, GitHub Actions CI/CD.","Explains containerizing backend and frontend services using Docker, deploying to Kubernetes clusters, and setting up CI/CD automation.","Details instrumenting distributed tracing with LangSmith and monitoring platform metrics in Grafana dashboards."]}],"critical_failures":["Lists buzzwords generically without articulating specific personal involvement, architecture decisions, or implementation details.","Cannot explain how frontend and backend components communicated or refuses ownership of either tier."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What challenges have you faced when working with rapidly evolving AI technologies, and how do you adapt to new advancements?', '{"key_points":[{"id":"KP1","description":"Navigates framework instability, breaking API updates, and deprecation churn across AI libraries.","required":true,"acceptable_evidence":["Technical keywords: Framework churn (LangChain / LangGraph breaking changes), dependency pinning, API deprecations, abstraction layers.","Explains insulating core application logic by wrapping third-party libraries (e.g., LangChain/LangGraph) behind custom interface abstractions.","Details using strict dependency pinning in `pyproject.toml` / `requirements.txt` and maintaining comprehensive integration test suites to catch breaking upstream updates."]},{"id":"KP2","description":"Mitigates model non-determinism, hallucinations, and unpredictable output schemas.","required":true,"acceptable_evidence":["Technical keywords: Hallucination mitigation, Pydantic structured outputs, NeMo Guardrails, temperature 0, cross-encoder reranking, ground-truth anchoring.","Explains enforcing deterministic tool calling and structured outputs using Pydantic JSON schemas to prevent unparseable LLM output formats.","Details reducing hallucinations through hybrid retrieval (BM25 + dense BGE embeddings) and cross-encoder rerankers to supply strictly relevant context."]},{"id":"KP3","description":"Institutes quantitative evaluation benchmarks to validate new advancements before production adoption.","required":true,"acceptable_evidence":["Technical keywords: RAGAS evaluation (faithfulness, context_precision, answer_relevancy), golden evaluation datasets, LangSmith regression suites, A/B testing.","Explains establishing automated evaluation pipelines with RAGAS to objectively benchmark new models or embedding techniques against established baselines.","Details running A/B tests and canary deployments to measure real-world performance, latency, and cost before completing upgrades."]},{"id":"KP4","description":"Manages inference latency, token economics, and rate limit quotas at scale.","required":false,"acceptable_evidence":["Technical keywords: Time to First Token (TTFT), token budget management, Redis semantic caching, sliding window truncation, provider failover.","Explains caching frequent query responses in Redis to reduce redundant LLM calls and avoid costly API rate limits.","Details implementing automatic failover across alternative LLM providers when primary endpoints experience latency spikes or downtime."]}],"critical_failures":["Denies or downplays major generative AI challenges such as hallucinations, latency, breaking updates, or non-deterministic outputs.","Adopts new AI models or frameworks into production without automated evaluation benchmarks or regression testing."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What checks would you perform to validate HTTP methods, response status codes, headers, and data formats for an API?', '{"key_points":[{"id":"KP1","description":"Validates correct semantic usage and safety properties of standard HTTP methods.","required":true,"acceptable_evidence":["Technical keywords: HTTP method semantics (GET, POST, PUT, PATCH, DELETE), idempotency, safe methods, 405 Method Not Allowed.","Explains verifying that GET operations are read-only and idempotent without mutating server state.","Details validating that POST is used for resource creation, PUT for complete replacement, PATCH for partial updates, and DELETE for removal, returning HTTP 405 for disallowed verbs."]},{"id":"KP2","description":"Enforces strict alignment and accuracy of HTTP response status codes based on operational outcomes.","required":true,"acceptable_evidence":["Technical keywords: Status codes (200 OK, 201 Created, 204 No Content, 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 422 Unprocessable Entity, 429 Too Many Requests, 500 Internal Server Error).","Explains verifying that successful operations return appropriate 2xx codes (201 for POST creation, 200 for retrieval, 204 for deletion).","Details validating precise error codes: 401 for missing/invalid tokens, 403 for permission denial, 422 for schema validation failures, and 429 for rate limit exhaustion."]},{"id":"KP3","description":"Checks critical HTTP request and response headers for security, content typing, and streaming protocols.","required":true,"acceptable_evidence":["Technical keywords: Content-Type (`application/json`, `text/event-stream`), Authorization (`Bearer <token>`), CORS headers (Access-Control-Allow-Origin), Cache-Control, Retry-After.","Explains asserting `Content-Type: application/json` for REST responses and `text/event-stream` with `Cache-Control: no-cache` for SSE streams.","Details verifying security headers including CORS permissions, HSTS, and inspecting `Retry-After` on HTTP 429 responses."]},{"id":"KP4","description":"Validates payload data contracts, schema compliance, and boundary constraints.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModels, JSON Schema validation, required fields, data type constraints, null handling, automated OpenAPI validation.","Explains verifying that request and response bodies match Pydantic schemas, checking field types, nested objects, and mandatory attributes.","Details testing edge-case boundary inputs (e.g., empty strings, oversized payloads, unexpected fields) to ensure proper rejection with HTTP 422."]},{"id":"KP5","description":"Implements automated API testing suites and contract verification tools in CI/CD pipelines.","required":false,"acceptable_evidence":["Technical keywords: pytest, httpx TestClient, Schemathesis / Dredd, Postman / Newman collections, automated contract testing.","Explains writing automated test suites using `pytest` and `httpx.AsyncClient` to validate status codes, headers, and schemas on every build.","Details using property-based or schema testing tools (e.g., Schemathesis) to automatically fuzz endpoints against the OpenAPI specification."]}],"critical_failures":["Advocates returning HTTP 200 OK for error responses with error details nested in JSON, violating standard REST principles.","Allows state-mutating actions over GET requests or ignores payload schema validation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What did the architecture look like end to end?', '{"key_points":[{"id":"KP1","description":"Maps the client and ingress gateway architecture handling authentication and traffic security.","required":true,"acceptable_evidence":["Technical keywords: React UI, API Gateway, TLS termination, OAuth2 / JWT authentication, rate limiting (Redis sliding window), CORS middleware.","Explains client interactions through a React interface communicating securely via HTTPS to an API Gateway.","Details validating JWT bearer tokens, enforcing distributed rate limits, and routing requests to backend microservices."]},{"id":"KP2","description":"Details the application execution and agentic reasoning layer.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async def, Uvicorn ASGI, LangGraph multi-agent workflow, Pydantic validation, StreamingResponse (SSE).","Explains FastAPI async microservices orchestrating agentic reasoning flows using LangGraph state graphs.","Details streaming generated tokens back to the client via Server-Sent Events (SSE) while enforcing Pydantic schema validation on all inputs and outputs."]},{"id":"KP3","description":"Specifies the dual-tier session state and persistent storage layer.","required":true,"acceptable_evidence":["Technical keywords: Redis session cache (24h TTL), PostgreSQL conversation_history, connection pooling (asyncpg), sliding window buffer.","Explains maintaining active multi-turn working state in Redis for sub-millisecond turn lookups.","Details persisting all dialogue history, user accounts, and audit logs durably in PostgreSQL with composite indexing on `(session_id, created_at)`."]},{"id":"KP4","description":"Architects the knowledge indexing, hybrid search, and graph retrieval pipelines.","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW vector database, dense BGE embeddings, BM25 sparse search, cross-encoder reranker, Neo4j GraphRAG.","Explains hybrid retrieval in Milvus combining dense vector search and BM25 sparse keyword matching, reranked via a cross-encoder model.","Details traversing entity relationships in Neo4j via Cypher queries to inject structured graph context into the prompt."]},{"id":"KP5","description":"Details asynchronous ingestion pipelines, operational telemetry, and MLOps infrastructure.","required":false,"acceptable_evidence":["Technical keywords: Amazon SQS, Docling document parser, Prefect orchestration, LangSmith tracing, Prometheus / Grafana metrics, Evidently drift detection.","Explains offloading document parsing and chunking to asynchronous SQS workers running Docling and embedding pipelines.","Details monitoring platform health via Prometheus/Grafana and tracing LLM execution graphs end-to-end with LangSmith."]}],"critical_failures":["Presents an oversimplified or disconnected architecture omitting data persistence, vector retrieval, or caching tiers.","Fails to articulate the sequential data and control flow from client request through AI generation to response delivery."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What excites you most about building scalable, production-ready AI systems rather than experimental prototypes?', '{"key_points":[{"id":"KP1","description":"Solves demanding real-world performance, concurrency, and latency optimization challenges.","required":true,"acceptable_evidence":["Technical keywords: Time to First Token (TTFT), high concurrency, horizontal autoscaling (HPA), vector index optimization (HNSW), streaming throughput.","Explains the engineering thrill of taking multi-second AI prototypes and optimizing them for sub-second production performance under concurrent load.","Details tuning Milvus vector indexes, Redis caching tiers, and async streaming pipelines to sustain thousands of simultaneous user queries."]},{"id":"KP2","description":"Engineers deterministic safety, rigorous reliability, and operational robustness into stochastic AI systems.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schema validation, NeMo Guardrails, Human-in-the-Loop (HITL), circuit breakers, failover handling.","Explains the intellectual satisfaction of turning unpredictable LLM outputs into dependable enterprise software using strict schema contracts and guardrails.","Details designing resilient fallback mechanisms, retry policies, and automated safeguards that ensure continuous platform availability."]},{"id":"KP3","description":"Delivers tangible, measurable business impact and authentic user value at scale.","required":true,"acceptable_evidence":["Technical keywords: Real-world user impact, business ROI, production feedback loops, product-market validation, SLA adherence.","Explains that prototypes only demonstrate potential, whereas production systems solve real user pain points, automate critical workflows, and deliver measurable ROI.","Details learning from real production telemetry and user interaction patterns to drive continuous product refinement."]},{"id":"KP4","description":"Applies mature software engineering, evaluation benchmarks, and MLOps rigor.","required":false,"acceptable_evidence":["Technical keywords: RAGAS automated evaluation, LangSmith tracing, Evidently drift detection, CI/CD automated deployment, DVC versioning.","Explains moving beyond anecdotal subjective prompt testing to disciplined quantitative evaluation suites (RAGAS) and automated regression gating.","Details establishing comprehensive observability with distributed tracing (LangSmith) and telemetry dashboards (Prometheus/Grafana)."]}],"critical_failures":["Dismisses production engineering challenges (latency, security, concurrency, reliability) as uninteresting compared to toy prototyping.","Demonstrates lack of appreciation for quantitative evaluation benchmarks, data contracts, or production operational excellence."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'What experience do you have with Python web frameworks like FastAPI, and how do you use them to build APIs?', '{"key_points":[{"id":"KP1","description":"Leverages Python asynchronous programming and the ASGI concurrency model for high-throughput APIs.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async def, Uvicorn ASGI server, asyncio event loop, non-blocking I/O, httpx.AsyncClient.","Explains building `async def` endpoints that efficiently yield control during I/O-bound operations (database queries, LLM calls) to sustain high concurrency.","Details running multi-worker Uvicorn configurations behind reverse proxies to maximize CPU utilization across multi-core servers."]},{"id":"KP2","description":"Implements robust data validation, schema enforcement, and serialization using Pydantic.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModels, Field constraints, automatic OpenAPI / Swagger generation, type hints, HTTP 422 validation errors.","Explains defining strictly typed request and response schemas using Pydantic BaseModels with Field validators.","Details how FastAPI leverages Python type annotations to validate payloads automatically, reject malformed requests with HTTP 422, and generate interactive Swagger docs."]},{"id":"KP3","description":"Utilizes FastAPI\'s dependency injection system for modular, reusable service architecture.","required":true,"acceptable_evidence":["Technical keywords: Depends() dependency injection, OAuth2PasswordBearer, database session management (asyncpg / SQLAlchemy), scoped dependencies.","Explains using `Depends()` to inject authenticated user contexts, database sessions, and Redis connection pools into route handlers cleanly.","Details writing composable dependency hierarchies to enforce role-based access control (RBAC) and rate limiting across API routes."]},{"id":"KP4","description":"Implements advanced response streaming and modular application routing.","required":false,"acceptable_evidence":["Technical keywords: StreamingResponse, Server-Sent Events (SSE), APIRouter, background tasks, global exception handlers.","Explains implementing `StreamingResponse` to stream token deltas directly to clients with `media_type=\'text/event-stream\'`.","Details structuring complex microservice projects using `APIRouter` to modularize endpoints into logical domain modules."]}],"critical_failures":["Confuses FastAPI\'s asynchronous ASGI architecture with synchronous frameworks like Flask, failing to explain `async def` or the event loop.","Ignores Pydantic models, parsing incoming request data manually from untyped dictionaries."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What experience do you have with building scalable backend systems using Python, FastAPI, and integrating them with frontend frameworks like React?', '{"key_points":[{"id":"KP1","description":"Architects high-concurrency, asynchronous backend services in Python and FastAPI.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async def, Uvicorn ASGI workers, asyncio non-blocking I/O, Pydantic schemas, connection pooling (asyncpg).","Explains developing asynchronous FastAPI microservices that handle concurrent client requests without blocking during external I/O waits.","Details configuring Uvicorn workers and async connection pools to sustain high request throughput and minimal memory overhead."]},{"id":"KP2","description":"Implements real-time token streaming pipelines connecting FastAPI backends to React frontends.","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events (SSE), StreamingResponse, fetch ReadableStream, chunk parsing, React state updates, EventSource.","Explains creating FastAPI `StreamingResponse` endpoints emitting chunked SSE streams consumed in React via `ReadableStream` reader.","Details updating React state progressively as tokens arrive to render real-time responses without UI stutter."]},{"id":"KP3","description":"Maintains distributed session state and durable persistence across backend and database tiers.","required":true,"acceptable_evidence":["Technical keywords: Redis session cache (24h TTL), PostgreSQL conversation_history, JWT authentication, sliding window context buffer.","Explains maintaining active conversation context in Redis for sub-millisecond retrieval during chat turns.","Details durably logging full conversation histories in PostgreSQL while propagating user identities via cryptographically signed JWT tokens."]},{"id":"KP4","description":"Manages frontend responsiveness, stream cancellation, and graceful error handling.","required":true,"acceptable_evidence":["Technical keywords: AbortController, React hooks (useState, useEffect), optimistic updates, error boundaries, HTTP 429 retry backoff.","Explains implementing `AbortController` in React fetch calls to cancel in-flight generation requests and free backend worker resources.","Details designing optimistic UI updates, loading skeletons, and standardized error banners for transient API failures."]},{"id":"KP5","description":"Deploys scalable infrastructure using containerization, autoscaling, and API gateway protection.","required":false,"acceptable_evidence":["Technical keywords: Docker containerization, Kubernetes / EKS Horizontal Pod Autoscaler (HPA), API Gateway rate limiting, CORS configuration.","Explains packaging FastAPI and React applications into optimized Docker containers deployed on Kubernetes clusters.","Details configuring Horizontal Pod Autoscaling (HPA) and API Gateway rate limits to protect backend services from traffic spikes."]}],"critical_failures":["Uses blocking synchronous operations inside FastAPI async def route handlers, stalling concurrent frontend user requests.","Fails to implement streaming communication (SSE/WebSockets), proposing blocking full-response polling that freezes React user interfaces."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is Pydantic, and how is it used within FastAPI?', '{"key_points":[{"id":"KP1","description":"Explains Pydantic\'s core role in data validation, type enforcement, and settings management via BaseModel and standard Python type annotations.","required":true,"acceptable_evidence":["Technical keywords: Pydantic, BaseModel, Field, type hinting, runtime validation, ValidationError.","Explains how Pydantic parses and enforces type safety on incoming JSON payloads at runtime.","Mentions how BaseModel subclasses define expected schemas with required and optional attributes."]},{"id":"KP2","description":"Details how FastAPI integrates Pydantic for automated request body parsing, input sanitization, and 422 Unprocessable Entity error generation.","required":true,"acceptable_evidence":["Technical keywords: request body validation, 422 Unprocessable Entity, dependency injection, automatic error response, FastAPI integration.","Explains that FastAPI automatically validates request payloads against Pydantic models before route handlers execute.","Describes how invalid inputs trigger detailed 422 HTTP responses pinpointing field-level validation errors."]},{"id":"KP3","description":"Covers response modeling, output serialization, and schema filtering using response_model and .model_dump().","required":true,"acceptable_evidence":["Technical keywords: response_model, model_dump(), model_validate(), serialization, response filtering, exclude_unset.","Explains how FastAPI uses response_model to sanitize outgoing data, strip internal fields, and ensure API contract consistency.","References Pydantic v2 methods like model_dump() or model_validate() for object transformation."]},{"id":"KP4","description":"Explains custom validation logic using Field constraints and validators, as well as automatic OpenAPI/Swagger documentation generation.","required":false,"acceptable_evidence":["Technical keywords: @field_validator, @model_validator, Field(ge=..., le=...), OpenAPI schema, Swagger UI, JSON Schema.","Describes using @field_validator or @model_validator to enforce business domain constraints.","Explains how Pydantic models automatically populate the interactive OpenAPI/Swagger documentation in FastAPI."]}],"critical_failures":["Confuses Pydantic with an ORM like SQLAlchemy or Tortoise.","Claims Pydantic only performs static compile-time type checks rather than runtime validation and coercion."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is Pydantic, and why is it important in enforcing schema validation in AI systems and APIs?', '{"key_points":[{"id":"KP1","description":"Defines Pydantic as a data parsing and validation library based on Python type hints that guarantees runtime type safety across system boundaries.","required":true,"acceptable_evidence":["Technical keywords: Pydantic, BaseModel, runtime validation, type coercion, ValidationError, data parsing.","Explains that Pydantic enforces data contracts at runtime rather than relying purely on static analysis.","Highlights how type coercion standardizes incoming types (e.g., parsing string numbers into integers safely)."]},{"id":"KP2","description":"Explains Pydantic\'s critical role in constraining non-deterministic LLM generations into deterministic structured outputs.","required":true,"acceptable_evidence":["Technical keywords: structured outputs, JsonOutputParser, function calling, tool schemas, Instructor, LangChain.","Explains how Pydantic schemas are passed to LLMs via tool/function calling definitions to force valid JSON output.","Describes parsing raw LLM string completions into verified Pydantic objects, triggering retry loops upon validation failure."]},{"id":"KP3","description":"Discusses defending API and agent workflows against malformed data, schema drift, and prompt injection payloads.","required":true,"acceptable_evidence":["Technical keywords: schema contract, prompt injection defense, API guardrails, input sanitization, 422 status.","Explains how strict schema validation acts as a first line of defense against malformed or hostile external payloads.","Details how custom validators (@field_validator, @model_validator) reject illegal agent parameters before tool execution."]},{"id":"KP4","description":"Details interoperability across modern AI architectures including LangGraph agent states, MCP tool definitions, and FastAPI microservices.","required":false,"acceptable_evidence":["Technical keywords: LangGraph state schema, MCP tools, FastAPI request/response, model_dump(), serialization.","Describes using Pydantic models to define state across LangGraph nodes and Model Context Protocol (MCP) tool interfaces.","Explains seamless serialization and deserialization between microservices and persistent datastores."]}],"critical_failures":["Claims LLM outputs can be reliably parsed and trusted in production using raw regex without schema validation.","Confuses Pydantic validation with static type checkers such as mypy or pyright."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is TTL in Redis, and how did you use it to manage cache freshness?', '{"key_points":[{"id":"KP1","description":"Explains Redis Time-To-Live (TTL) mechanics and core commands for setting and checking key expiration.","required":true,"acceptable_evidence":["Technical keywords: TTL, EXPIRE, SET key value EX seconds, PEXPIRE, PERSIST, passive and active expiration.","Explains that Redis automatically removes keys after the configured TTL duration expires.","Describes how Redis evicts expired keys via passive lookup checks and background active sampling routines."]},{"id":"KP2","description":"Details a multi-tier TTL strategy balancing short-lived LLM cache entries with longer-lived conversation session states.","required":true,"acceptable_evidence":["Technical keywords: session state TTL=86400, LLM response cache TTL=3600, sliding TTL, cache invalidation, cache freshness.","Describes setting a 1-hour (3600s) TTL on semantic/exact LLM query caches to prevent stale AI responses.","Details setting a 24-hour (86400s) sliding TTL on active session states renewed on each incoming interaction."]},{"id":"KP3","description":"Addresses cache stampede (thundering herd), TTL jitter, and handling stale data during cache expiration.","required":true,"acceptable_evidence":["Technical keywords: cache stampede, thundering herd, TTL jitter, distributed mutex lock, Redlock, probabilistic early expiration.","Explains adding random jitter to TTL values to prevent multiple cached items expiring simultaneously.","Discusses using Redis distributed locks or single-flight loaders to prevent concurrent duplicate backend LLM calls on expiration."]},{"id":"KP4","description":"Covers Redis memory management and eviction policies when memory limits are reached before TTL expiration.","required":false,"acceptable_evidence":["Technical keywords: maxmemory-policy, volatile-lru, volatile-ttl, allkeys-lru, out-of-memory mitigation.","Explains configuring volatile-lru or volatile-ttl so Redis evicts expiring keys first when memory thresholds are hit.","Discusses monitoring memory consumption to avoid unexpected key evictions before TTL expiry."]}],"critical_failures":["Suggests storing LLM responses or session states indefinitely in Redis without any TTL or expiration mechanism.","Confuses Redis automatic TTL expiration with requiring external cron jobs or manual polling to delete keys."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is pub/sub architecture, and how does it enable decoupling in distributed systems?', '{"key_points":[{"id":"KP1","description":"Explains the foundational architecture of Pub/Sub: publishers, subscribers, event topics/channels, and the message broker.","required":true,"acceptable_evidence":["Technical keywords: Pub/Sub, publisher, subscriber, broker, topic, channel, event-driven architecture.","Explains that publishers emit events to topics without knowing which or how many subscribers exist.","Details how the message broker handles routing and fanout delivery of messages to active subscribers."]},{"id":"KP2","description":"Details how Pub/Sub enables spatial, temporal, and operational decoupling between distributed microservices.","required":true,"acceptable_evidence":["Technical keywords: spatial decoupling, temporal decoupling, 1-to-many fanout, loose coupling, asynchronous communication.","Explains spatial decoupling where services do not need IP addresses, network locations, or knowledge of peers.","Explains temporal decoupling where producers and consumers can operate asynchronously at different rates."]},{"id":"KP3","description":"Describes concrete technology implementations (Redis Pub/Sub, Redis Streams, AWS SQS/SNS, Kafka) for distributed AI pipelines.","required":true,"acceptable_evidence":["Technical keywords: Redis PUBLISH/SUBSCRIBE, Redis Streams, AWS SQS/SNS, Kafka, Celery, consumer groups.","Provides concrete examples such as publishing document ingestion events to trigger downstream embedding workers.","Explains horizontal scaling by adding independent consumer instances to process heavy AI workloads."]},{"id":"KP4","description":"Covers reliability trade-offs, message persistence, delivery guarantees, and handling failure modes like dead-letter queues.","required":false,"acceptable_evidence":["Technical keywords: at-least-once delivery, fire-and-forget, Dead Letter Queue (DLQ), idempotency, backpressure.","Contrasts ephemeral fire-and-forget Redis Pub/Sub with persistent message brokers (SQS, Kafka, Redis Streams).","Discusses ensuring idempotent consumer handlers and routing repeatedly failing messages to a Dead Letter Queue."]}],"critical_failures":["Claims Pub/Sub is inherently synchronous and blocks the publisher until every subscriber finishes execution.","Fails to differentiate between fire-and-forget broadcast messaging and persistent queued delivery."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is the role of Redis in your system, and what type of data do you store in it?', '{"key_points":[{"id":"KP1","description":"Explains Redis\'s role as a sub-millisecond in-memory cache for LLM responses and frequent queries.","required":true,"acceptable_evidence":["Technical keywords: Redis, in-memory cache, semantic cache, response caching, TTL=3600, query hash.","Explains storing hash keys of user queries to return cached LLM responses, avoiding redundant inference cost and latency.","Mentions setting a 1-hour expiration (TTL=3600) on cached query results."]},{"id":"KP2","description":"Details storing ephemeral conversational session state and short-term agent memory in Redis.","required":true,"acceptable_evidence":["Technical keywords: session state, conversation history, TTL=86400, LangGraph Redis checkpointer, sliding expiration.","Explains storing recent turn dialogues, active thread context, and agent scratchpad variables in Redis.","References a 24-hour sliding TTL (86400s) to maintain active user session continuity while automatically freeing inactive memory."]},{"id":"KP3","description":"Covers rate limiting, throttling, and concurrency control using Redis data structures.","required":true,"acceptable_evidence":["Technical keywords: rate limiting, sliding window, token bucket, INCRBY, EXPIRE, API protection.","Describes using Redis atomic counters and expiration to enforce API quotas per user or IP address.","Explains throttling requests to safeguard downstream LLM APIs and prevent denial-of-service."]},{"id":"KP4","description":"Mentions Redis Pub/Sub or lightweight queueing for asynchronous communication between microservices.","required":false,"acceptable_evidence":["Technical keywords: Redis Pub/Sub, Redis Streams, LPUSH/RPOP, async notification, worker synchronization.","Describes using Redis channels or streams to broadcast state updates or trigger background worker tasks.","Mentions real-time token streaming synchronization or event fanout to connected web clients."]}],"critical_failures":["Claims Redis is used as the permanent primary relational database for critical financial audit logs.","Proposes using Redis without setting memory limits (maxmemory) or TTL expiration policies."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your approach to building scalable and maintainable AI systems that can be incrementally improved over time?', '{"key_points":[{"id":"KP1","description":"Architects modular, decoupled microservices and orchestration graphs (FastAPI, LangGraph) separating business logic, inference, and retrieval.","required":true,"acceptable_evidence":["Technical keywords: modular architecture, LangGraph, FastAPI, microservices, separation of concerns, DAG.","Explains organizing agent workflows into discrete, independently testable graph nodes and tool executors.","Highlights isolating LLM provider integrations behind abstract interfaces to swap models without rewriting business logic."]},{"id":"KP2","description":"Implements automated offline and online evaluation frameworks (RAGAS, LangSmith) to benchmark improvements and prevent regressions.","required":true,"acceptable_evidence":["Technical keywords: RAGAS, LangSmith, faithfulness, answer_relevancy, context_precision, golden evaluation dataset.","Describes evaluating prompt updates and retrieval changes against golden benchmark test sets in CI/CD pipelines.","Explains measuring quantitative metrics (e.g., faithfulness, context precision) prior to deploying agent upgrades."]},{"id":"KP3","description":"Establishes comprehensive observability, tracing, and metric collection across all system components.","required":true,"acceptable_evidence":["Technical keywords: OpenTelemetry, Prometheus, Grafana, LangSmith tracing, token usage, p99 latency.","Details tracking end-to-end trace spans for every LLM call, retrieval query, and tool execution.","Monitors system health, cost per query, latency spikes, and error rates using Prometheus and Grafana dashboards."]},{"id":"KP4","description":"Utilizes progressive deployment strategies including feature flags, canary rollouts, and shadow deployments for new models.","required":true,"acceptable_evidence":["Technical keywords: canary release, shadow deployment, A/B testing, feature flags, blue-green deployment.","Describes routing a small percentage of live production traffic to new prompts or models to validate behavior safely.","Explains shadow evaluation where production queries are duplicated to candidate models without impacting end users."]},{"id":"KP5","description":"Creates continuous feedback and data curation loops for ongoing dataset refinement and drift detection.","required":false,"acceptable_evidence":["Technical keywords: continuous feedback loop, user thumbs-up/down, Evidently, DVC, data drift, fine-tuning curation.","Explains logging user feedback and failed queries into curated datasets versioned with DVC.","Monitors data and concept drift using Evidently to trigger pipeline retraining or prompt updates."]}],"critical_failures":["Advocates pushing prompt or model changes directly into production without automated evaluation benchmarks.","Relies entirely on subjective manual testing without quantitative metrics or distributed tracing."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is your experience working with and relational databases such as PostgreSQL in AI systems?', '{"key_points":[{"id":"KP1","description":"Explains PostgreSQL\'s role as the durable ACID source of truth for user identities, conversation audit history, and billing records.","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, ACID compliance, conversation history, audit logging, relational schema, foreign keys.","Details storing long-term chat threads, user profiles, permissions, and token consumption logs in relational tables.","Explains enforcing relational integrity, constraints, and transactions across user and organization boundaries."]},{"id":"KP2","description":"Details query optimization, indexing strategies, parameterized queries, and asynchronous connection pooling via asyncpg/SQLAlchemy.","required":true,"acceptable_evidence":["Technical keywords: parameterized queries, asyncpg, connection pooling, EXPLAIN ANALYZE, B-tree indexes, SQLAlchemy.","Explains using parameterized queries (cursor.execute with parameters) to prevent SQL injection vulnerabilities.","Details tuning database performance with asyncpg connection pools and B-tree indexes analyzed via EXPLAIN ANALYZE."]},{"id":"KP3","description":"Covers vector extension integration (pgvector) for hybrid relational and similarity search within a unified database.","required":true,"acceptable_evidence":["Technical keywords: pgvector, vector embeddings, HNSW, IVFFlat, cosine distance, hybrid query, metadata filtering.","Explains using pgvector to store and index embeddings alongside relational metadata in PostgreSQL.","Describes executing unified queries combining SQL WHERE clauses with vector similarity distance thresholds."]},{"id":"KP4","description":"Discusses integrating PostgreSQL checkpointers for agent state persistence in frameworks like LangGraph.","required":false,"acceptable_evidence":["Technical keywords: LangGraph PostgresSaver, state checkpointing, thread_id, transactional state, HITL recovery.","Explains configuring Postgres checkpointers to persist multi-turn agent execution graphs durably.","Details resuming interrupted agent runs or supporting human-in-the-loop review from database checkpoints."]}],"critical_failures":["Recommends raw string interpolation/concatenation for building SQL queries, introducing SQL injection vulnerabilities.","Confuses persistent PostgreSQL relational storage with ephemeral in-memory caches like Redis."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What modifications or enhancements did you make to an existing UVM testbench to improve scalability and functionality?', '{"key_points":[{"id":"KP1","description":"Modularization and parameterization of UVM components and sequence items.","required":true,"acceptable_evidence":["Technical keywords: UVM (Universal Verification Methodology), uvm_sequence_item, uvm_driver, uvm_monitor, factory pattern, configuration database (uvm_config_db).","Explains refactoring monolithic testbench components into parameterized, reusable agents and sequence items using the UVM factory override mechanism.","Details replacing hardcoded transaction values with randomized constraints to scale stimulus coverage."]},{"id":"KP2","description":"Scoreboard optimization and automated transaction-level modeling (TLM).","required":true,"acceptable_evidence":["Technical keywords: TLM analysis ports, uvm_analysis_fifo, transaction matching, scoreboard, golden reference model.","Describes integrating non-blocking TLM analysis FIFOs to decouple monitors from scoreboards, preventing simulation stalls under high transaction volume.","Explains replacing slow cycle-accurate checking with transaction-level golden model comparisons."]},{"id":"KP3","description":"Functional coverage expansion and regression performance improvements.","required":true,"acceptable_evidence":["Technical keywords: covergroups, coverpoints, cross-coverage, regression runtime, constrained-random stimulus.","Details structuring hierarchical covergroups to systematically track cross-coverage holes across corner-case execution paths.","Explains reducing regression execution times by optimizing test seed generation and eliminating redundant sequence repetitions."]}],"critical_failures":["Confuses standard software unit testing frameworks with hardware verification Universal Verification Methodology (UVM).","Fails to explain UVM core mechanics such as TLM ports, sequence items, or the UVM factory mechanism.","Does not mention functional coverage or scoreboard transaction verification as key enhancement levers."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What motivated your interest in this role and how does it align with your current experience?', '{"key_points":[{"id":"KP1","description":"Articulates strong alignment with production AI engineering, agentic systems (LangGraph), and high-performance backend architecture (FastAPI).","required":true,"acceptable_evidence":["Technical keywords: LangGraph, FastAPI, production AI systems, agentic workflows, RAG architecture, microservices.","Connects personal background to designing and operating end-to-end LLM applications and agent graphs.","Highlights experience building robust API layers that interface reliably with non-deterministic models."]},{"id":"KP2","description":"Demonstrates hands-on experience solving real-world performance, latency, and data scalability challenges.","required":true,"acceptable_evidence":["Technical keywords: Milvus vector search, Redis caching, streaming responses, latency optimization, data pipelines.","References concrete optimizations like implementing Redis caching, hybrid search retrieval, and async streaming.","Discusses handling throughput, token cost constraints, and complex data ingestion at scale."]},{"id":"KP3","description":"Emphasizes focus on engineering rigors: automated evaluation (RAGAS), observability, and bridging research to production.","required":true,"acceptable_evidence":["Technical keywords: RAGAS, LangSmith, MLOps, CI/CD, production-grade, reliability, guardrails.","Emphasizes moving beyond proof-of-concept demos into robust, monitored, production-ready systems.","Highlights passion for systematic evaluation, hallucination suppression, and continuous deployment."]}],"critical_failures":["Provides generic career platitudes without citing any concrete AI engineering technologies or architectural challenges.","Shows unfamiliarity with the fundamental responsibilities of a senior AI/backend software engineer."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What motivates your interest in AI and problem solving, and how have you demonstrated this in your work?', '{"key_points":[{"id":"KP1","description":"Articulates motivation in transforming probabilistic, non-deterministic AI models into deterministic, enterprise-grade reliable systems.","required":true,"acceptable_evidence":["Technical keywords: non-deterministic LLMs, deterministic guardrails, Pydantic validation, LangGraph state machines, reliability.","Explains the intellectual challenge of engineering predictability and safety around probabilistic model outputs.","Discusses using structured schemas, state graphs, and strict validation to tame LLM variance."]},{"id":"KP2","description":"Demonstrates problem-solving through concrete technical remediation of production failure modes (hallucinations, latency, drift).","required":true,"acceptable_evidence":["Technical keywords: RAGAS evaluation, cross-encoder reranking, Evidently drift detection, Redis caching, hybrid search.","Provides specific examples such as diagnosing retrieval gaps and adding cross-encoder reranking to boost precision.","Details implementing semantic caching to cut latency from seconds to milliseconds for frequent queries."]},{"id":"KP3","description":"Highlights building automated evaluation, tracing, and monitoring pipelines that ensure long-term system health.","required":true,"acceptable_evidence":["Technical keywords: LangSmith tracing, automated evaluation, golden test sets, Prometheus telemetry, CI/CD.","Describes building systematic regression test suites to benchmark prompt and code changes automatically.","Shows passion for deep root-cause analysis using distributed trace telemetry."]}],"critical_failures":["Discusses AI solely from an end-user consumer perspective (prompting ChatGPT) without backend engineering depth.","Cannot provide a single concrete example of debugging a production system or algorithmic failure."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What motivates your interest in transitioning from large organizations to early-stage startups, and how do you adapt to less structured environments?', '{"key_points":[{"id":"KP1","description":"Articulates desire for end-to-end architectural ownership, rapid decision velocity, and direct business impact in early-stage startups.","required":true,"acceptable_evidence":["Technical keywords: end-to-end ownership, rapid prototyping, agile velocity, direct business impact, autonomy.","Contrasts slow corporate bureaucratic processes with high-velocity startup execution.","Expresses motivation to design systems from scratch across infrastructure, backend, and AI layers."]},{"id":"KP2","description":"Explains a disciplined approach to managing technical debt, balancing rapid MVP delivery with scalable foundation patterns.","required":true,"acceptable_evidence":["Technical keywords: technical debt, pragmatic architecture, MVP scoping, modular design, FastAPI, Docker.","Explains making conscious trade-offs between rapid shipping and clean, modular interfaces that prevent rewrites.","Advocates adopting managed cloud services (e.g., managed Redis, Milvus, RDS) to move fast without operational overhead."]},{"id":"KP3","description":"Describes thriving in ambiguous, unstructured environments by taking proactive initiative, establishing telemetry, and self-directing.","required":true,"acceptable_evidence":["Technical keywords: ambiguity management, proactive initiative, self-driven evaluation, LangSmith tracing, feedback loops.","Details setting up basic observability and CI tests early to enable confident, autonomous iteration.","Explains clarifying requirements directly with stakeholders rather than waiting for formal product specifications."]}],"critical_failures":["Expresses a preference for rigid, strictly defined top-down corporate instructions and siloed tasks.","Advocates cutting all architectural standards, tests, and security under the guise of startup speed."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What qualities do you think are important for building scalable, production-grade AI systems?', '{"key_points":[{"id":"KP1","description":"Highlights determinism, schema enforcement, and guardrails to ensure predictable outputs from non-deterministic models.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, NeMo Guardrails, structured outputs, input sanitization, error handling.","Explains using strict Pydantic models and guardrail layers to validate LLM inputs and outputs.","Emphasizes that production systems cannot accept raw unstructured text without contract validation."]},{"id":"KP2","description":"Emphasizes latency management, high-concurrency throughput, and asynchronous streaming.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async/await, StreamingResponse, Redis caching, connection pooling, asyncio.gather().","Discusses reducing perceived latency using real-time token streaming (SSE) and caching repeated queries in Redis.","Explains designing non-blocking async backends capable of serving thousands of concurrent users."]},{"id":"KP3","description":"Details high-performance retrieval and scalable vector/knowledge indexing (Milvus, HNSW, GraphRAG).","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW indexing, hybrid search, BM25, cross-encoder reranking, metadata filtering.","Explains scaling vector search to millions of embeddings using HNSW indexing and metadata partitioning.","Describes combining keyword and dense semantic search with reranking for top retrieval precision."]},{"id":"KP4","description":"Stresses comprehensive observability, tracing, and automated regression evaluation (LangSmith, RAGAS, Prometheus).","required":true,"acceptable_evidence":["Technical keywords: LangSmith tracing, RAGAS metrics, faithfulness, context_precision, Prometheus, Grafana.","Explains capturing distributed trace spans for every tool call, retrieval query, and LLM invocation.","Advocates automated CI evaluation pipelines to benchmark prompt and model iterations."]},{"id":"KP5","description":"Focuses on fault tolerance, graceful degradation, and resilience against third-party API outages.","required":false,"acceptable_evidence":["Technical keywords: circuit breaker, exponential backoff, fallback models, dead-letter queues, HITL checkpointing.","Describes implementing circuit breakers and automatic fallbacks to secondary LLM providers during rate limits.","Details human-in-the-loop checkpointing to recover gracefully from agent exceptions."]}],"critical_failures":["Treats AI system design as merely invoking an LLM API endpoint without considering latency, failure modes, or validation.","Completely omits observability and evaluation, assuming standard application logging is sufficient."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What role did business requirements play in shaping your evaluation strategy and system improvements?', '{"key_points":[{"id":"KP1","description":"Translates core business KPIs (cost reduction, resolution rate, p99 latency SLA) into quantifiable engineering evaluation metrics.","required":true,"acceptable_evidence":["Technical keywords: business KPIs, RAGAS faithfulness, context_precision, token cost per query, p99 latency SLA.","Explains aligning business tolerance for latency and cost with technical metric targets (e.g., <2s TTFT, <$0.01/call).","Describes mapping business accuracy requirements directly to RAGAS faithfulness and answer relevancy thresholds."]},{"id":"KP2","description":"Curates custom domain-specific evaluation datasets mirroring real customer edge cases rather than generic academic benchmarks.","required":true,"acceptable_evidence":["Technical keywords: domain ground-truth dataset, synthetic edge cases, gold standard, human-annotated test set.","Explains building evaluation sets based on actual high-friction user queries and historical customer support tickets.","Details incorporating hard domain edge cases (e.g., ambiguous policy clauses, multi-document cross-references)."]},{"id":"KP3","description":"Implements strict compliance, hallucination suppression, and guardrail policies mandated by enterprise risk requirements.","required":true,"acceptable_evidence":["Technical keywords: hallucination mitigation, Pydantic schemas, PII redaction, NeMo Guardrails, compliance audit.","Explains how business liability constraints required 0% tolerance for ungrounded claims, necessitating strict RAGAS faithfulness gates.","Details enforcing PII filtering and regulatory compliance rules before returning LLM responses to users."]},{"id":"KP4","description":"Drives engineering architecture improvements based on metric feedback (e.g., adding cross-encoder reranking to fix retrieval drops).","required":false,"acceptable_evidence":["Technical keywords: iterative ablation, cross-encoder reranking, Milvus hybrid search tuning, ROI-driven model selection.","Describes identifying a business drop in query resolution, diagnosing retrieval precision loss, and introducing cross-encoder reranking.","Explains selecting smaller, cost-effective models (e.g., GPT-4o-mini) where evaluation proved quality met business thresholds."]}],"critical_failures":["Evaluates AI models purely on generic public benchmarks (like MMLU) without aligning with domain business metrics.","Ignores operational business constraints such as budget ceilings, compliance standards, and latency SLAs."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What scalability considerations arise when handling increasing volumes of pull requests across large engineering teams?', '{"key_points":[{"id":"KP1","description":"Addresses CI/CD runner bottlenecking through parallel test execution, containerized runners, and matrix test sharding.","required":true,"acceptable_evidence":["Technical keywords: CI/CD pipeline, parallel test execution, containerized runners, matrix builds, test sharding.","Explains distributing unit and integration tests across ephemeral auto-scaling runners (e.g., GitHub Actions, Kubernetes runners).","Details sharding large test suites to reduce total CI execution turnaround time per pull request."]},{"id":"KP2","description":"Optimizes build and test efficiency via selective test execution, build artifact caching, and flaky test isolation.","required":true,"acceptable_evidence":["Technical keywords: test impact analysis, build cache, selective test execution, flaky test quarantine, Docker layer caching.","Explains running only test suites impacted by changed files or dependencies rather than the entire test suite on every commit.","Details utilizing Docker layer caching and dependency caches to eliminate redundant compilation and downloads."]},{"id":"KP3","description":"Manages branch contention and merge serialization using automated merge queues and speculative execution.","required":true,"acceptable_evidence":["Technical keywords: merge queue, speculative execution, branch protection, rebase conflicts, trunk-based development.","Explains how merge queues validate PRs against the latest target branch tip, preventing broken main branches.","Describes batching and speculative testing of multiple PRs simultaneously to maintain high merge throughput."]},{"id":"KP4","description":"Enforces automated pre-merge gating for code quality, schema contracts (Pydantic), and security scanning.","required":false,"acceptable_evidence":["Technical keywords: pre-commit hooks, static analysis, Pydantic schema validation, SonarQube, security SAST/DAST.","Explains running automated schema compatibility checks to prevent breaking API changes across microservices.","Details automated linting, type-checking (mypy), and dependency vulnerability scans prior to human code review."]}],"critical_failures":["Advocates running slow monolithic linear CI pipelines for every PR without any caching or parallelization.","Ignores merge contention and race conditions on the main branch, allowing broken builds to merge under heavy team volume."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What technologies do you use for frontend and backend development, and how do they integrate within your AI systems?', '{"key_points":[{"id":"KP1","description":"Details backend development stack: FastAPI, Python asyncio, Pydantic schemas, and Uvicorn ASGI server.","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Python asyncio, Pydantic, Uvicorn, REST endpoints, dependency injection.","Explains structuring high-performance backend microservices exposing async endpoints for AI inference.","Highlights Pydantic BaseModel validation for enforcing strict request and response schemas."]},{"id":"KP2","description":"Details frontend development stack: React, Next.js, TypeScript, and modern component state management.","required":true,"acceptable_evidence":["Technical keywords: React, Next.js, TypeScript, TailwindCSS, state management, component lifecycle.","Explains building responsive user interfaces with TypeScript for end-to-end type safety matching backend schemas.","Describes managing UI state, chat thread histories, and optimistic rendering during AI interactions."]},{"id":"KP3","description":"Covers real-time streaming integration between frontend and backend using Server-Sent Events (SSE) or WebSockets.","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, Server-Sent Events (SSE), EventSource, token streaming, chunks rendering.","Explains streaming generated LLM tokens incrementally from FastAPI\'s StreamingResponse to the React frontend.","Details parsing event stream chunks on the client to render responses in real time, minimizing perceived latency."]},{"id":"KP4","description":"Explains integration with data and agent orchestration tiers (Redis, PostgreSQL, Milvus, LangGraph).","required":false,"acceptable_evidence":["Technical keywords: LangGraph, Milvus, Redis session store, PostgreSQL, background workers.","Details how the FastAPI backend queries Milvus for RAG context and coordinates LangGraph state nodes.","Explains caching session state in Redis and persisting completed conversation logs into PostgreSQL."]}],"critical_failures":["Fails to explain how real-time LLM streaming is delivered from backend to frontend (SSE or WebSockets).","Suggests frontend should call external LLM APIs (OpenAI) directly without a secure backend API layer."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What testing frameworks have you used for backend and frontend development?', '{"key_points":[{"id":"KP1","description":"Details backend testing frameworks: pytest, pytest-asyncio, httpx.AsyncClient, and mock fixtures.","required":true,"acceptable_evidence":["Technical keywords: pytest, pytest-asyncio, httpx.AsyncClient, unittest.mock, fixtures, coverage.","Explains writing unit and integration tests for asynchronous FastAPI route handlers using pytest-asyncio.","Describes mocking external I/O, database sessions, and third-party API dependencies using pytest fixtures."]},{"id":"KP2","description":"Covers testing FastAPI dependency overrides and schema contract validation.","required":true,"acceptable_evidence":["Technical keywords: app.dependency_overrides, TestClient, status code assertions, Pydantic schema validation tests.","Explains overriding authentication and database dependencies in FastAPI tests using app.dependency_overrides.","Details asserting HTTP status codes (200, 422, 401) and validating Pydantic response models against expected fixtures."]},{"id":"KP3","description":"Details frontend testing frameworks: Jest, React Testing Library, and Playwright/Cypress for end-to-end testing.","required":true,"acceptable_evidence":["Technical keywords: Jest, React Testing Library, Playwright, Cypress, component rendering, userEvent.","Explains unit testing React components and hooks with Jest and React Testing Library focusing on user interactions.","Describes writing end-to-end browser tests with Playwright to verify full user journeys and streaming chat UI."]},{"id":"KP4","description":"Mentions specialized testing for AI systems: deterministic LLM mocking and RAGAS automated evaluation test suites.","required":false,"acceptable_evidence":["Technical keywords: RAGAS, deterministic LLM mocks, golden dataset regression tests, LangSmith test runner.","Explains mocking LLM completion responses in CI to test application logic deterministically and without API costs.","Describes running automated RAGAS evaluation suites on PR merges to catch retrieval or faithfulness regressions."]}],"critical_failures":["Claims unit tests in CI pipelines should always call live paid external LLM APIs without mocking.","Suggests manual user testing in a browser is sufficient without automated test suites."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'What types of data do you store in relational databases like MySQL for conversational AI systems, and why?', '{"key_points":[{"id":"KP1","description":"Stores user identities, authentication credentials, organization multi-tenancy, and role-based permissions.","required":true,"acceptable_evidence":["Technical keywords: user authentication, OAuth2/JWT metadata, RBAC, tenant isolation, foreign keys, users table.","Explains storing user accounts, organization hierarchies, and role permissions requiring strict ACID relational consistency.","Details enforcing referential integrity across tenants, users, and assigned workspace permissions."]},{"id":"KP2","description":"Stores durable conversation metadata, session threads, and auditable message logs.","required":true,"acceptable_evidence":["Technical keywords: conversation threads, message timestamps, audit trails, user feedback scores, ACID compliance.","Details persisting historical chat turns, sender roles (user/assistant), timestamps, and feedback ratings.","Explains that relational storage provides durable, long-term auditability required for enterprise compliance."]},{"id":"KP3","description":"Stores token consumption, API latency metrics, billing records, and operational quotas.","required":true,"acceptable_evidence":["Technical keywords: token counts, prompt/completion tokens, billing records, API latency logs, aggregations.","Explains recording exact token usage per request to calculate customer billing and track API costs.","Describes running analytical SQL aggregations (GROUP BY, SUM) over usage tables for reporting."]},{"id":"KP4","description":"Articulates why relational databases are chosen over vector or in-memory stores for this data: ACID guarantees, relational indexing, and structured schema integrity.","required":false,"acceptable_evidence":["Technical keywords: relational integrity, ACID transactions, B-tree indexes, foreign keys, vs Redis ephemeral state.","Contrasts durable relational tables with ephemeral in-memory caches (Redis) and unstructured vector stores (Milvus).","Explains leveraging B-tree indexes and primary keys for fast point lookups and transactional consistency."]}],"critical_failures":["Recommends storing millions of high-dimensional vector embeddings directly in basic relational tables without vector extensions.","Confuses durable relational audit history with ephemeral session state that should reside in Redis."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What types of projects are you most interested in working on, and how do they align with your past experience?', '{"key_points":[{"id":"KP1","description":"Expresses passion for stateful multi-agent systems and dynamic workflow orchestration (LangGraph, MCP tools).","required":true,"acceptable_evidence":["Technical keywords: LangGraph, multi-agent orchestration, MCP tools, stateful DAGs, human-in-the-loop (HITL).","Aligns interest with designing complex agent architectures capable of planning, reflection, and autonomous tool use.","References past experience building stateful agent workflows with LangGraph and checkpointing."]},{"id":"KP2","description":"Highlights interest in advanced enterprise RAG systems featuring hybrid retrieval, reranking, and knowledge graphs (Milvus, Neo4j, RAGAS).","required":true,"acceptable_evidence":["Technical keywords: Milvus vector search, BM25 hybrid search, cross-encoder reranking, Neo4j GraphRAG, RAGAS.","Expresses enthusiasm for solving difficult hallucination and domain retrieval challenges in mission-critical industries.","Connects interest to hands-on experience tuning vector indexes and measuring evaluation metrics."]},{"id":"KP3","description":"Emphasizes scalable, production-grade distributed backend architecture and MLOps platforms (FastAPI, Redis, Kubernetes).","required":true,"acceptable_evidence":["Technical keywords: FastAPI async streaming, Redis TTL caching, EKS Kubernetes, Prometheus observability, MLOps.","Focuses on taking AI prototypes into high-throughput, low-latency, resilient production deployments.","Highlights dedication to building robust microservice infrastructure with continuous evaluation and monitoring."]}],"critical_failures":["Discusses interest only in generic prompt writing without architectural depth or engineering grounding.","Cannot articulate how past engineering projects relate to enterprise AI and distributed backend challenges."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What was your approach to modernizing legacy systems into event-driven architectures?', '{"key_points":[{"id":"KP1","description":"Applies the Strangler Fig pattern to incrementally extract services from the legacy monolith into decoupled microservices.","required":true,"acceptable_evidence":["Technical keywords: Strangler Fig pattern, microservices extraction, legacy monolith, domain-driven boundaries, API gateway routing.","Explains routing new feature requests and targeted workflows through an API gateway to new services while legacy runs.","Describes gradually deprecating legacy monolithic modules without risky all-at-once migrations."]},{"id":"KP2","description":"Selects a resilient event backbone and establishes standardized message schema contracts (SQS, Kafka, Redis Streams, Pydantic).","required":true,"acceptable_evidence":["Technical keywords: SQS, Kafka, Redis Streams, event broker, Pydantic schemas, Avro/Protobuf, event schema registry.","Explains introducing a reliable message broker to publish domain events (e.g., document uploaded, task completed).","Details defining strict Pydantic or protobuf schemas for event payloads to ensure producer-consumer contract stability."]},{"id":"KP3","description":"Implements asynchronous consumer workers with idempotent processing and Dead Letter Queues (DLQ).","required":true,"acceptable_evidence":["Technical keywords: async worker consumers, Celery/Prefect, DLQ (Dead Letter Queue), idempotency keys, at-least-once delivery.","Explains designing consumer workers that process long-running AI tasks asynchronously without blocking web servers.","Details using idempotency keys and dead-letter queues to prevent duplicate processing and isolate poison messages."]},{"id":"KP4","description":"Ensures dual-write safety and data consistency using the Transactional Outbox pattern or Change Data Capture (CDC).","required":false,"acceptable_evidence":["Technical keywords: Transactional Outbox pattern, Change Data Capture (CDC), Debezium, dual-write mitigation.","Explains writing domain events into an outbox table within the same database transaction to prevent dual-write inconsistencies.","Describes streaming events from the database log via CDC to reliably populate downstream queues."]}],"critical_failures":["Advocates a risky big-bang rewrite that attempts to replace an entire legacy system overnight.","Ignores message idempotency and duplicate handling in distributed event-driven consumers."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What were the key considerations behind choosing DynamoDB and Redis for session and memory management?', '{"key_points":[{"id":"KP1","description":"Leverages Redis as an ultra-fast, in-memory cache for active session state, short-term conversational context, and LangGraph checkpointers.","required":true,"acceptable_evidence":["Technical keywords: Redis, in-memory, sub-millisecond latency, TTL expiration, LangGraph checkpointer, active session.","Explains that Redis provides sub-millisecond read/write speeds critical for low-latency multi-turn agent turns.","Details using automatic Redis TTL (e.g., 24h) to expire transient user sessions without manual cleanup."]},{"id":"KP2","description":"Utilizes DynamoDB for highly scalable, durable, serverless persistence of long-term conversation history and audit records.","required":true,"acceptable_evidence":["Technical keywords: DynamoDB, partition key, sort key, serverless persistence, automatic scaling, durability, NoSQL.","Explains using DynamoDB\'s managed key-value storage for persistent chat history partitioned by user_id and session_id.","Highlights DynamoDB\'s high availability, automatic scaling, and durability without requiring database cluster management."]},{"id":"KP3","description":"Implements a tiered hot/cold storage architecture balancing performance, durability, and infrastructure costs.","required":true,"acceptable_evidence":["Technical keywords: tiered caching, cache-aside pattern, read-through cache, TTL synchronization, cost optimization.","Describes checking Redis for hot active sessions first and falling back to DynamoDB when hydrating past sessions.","Explains that keeping months of chat history in expensive Redis RAM is cost-prohibitive, while DynamoDB provides cheap cold storage."]},{"id":"KP4","description":"Evaluates operational overhead, memory limits, and failure isolation trade-offs between Redis and DynamoDB.","required":false,"acceptable_evidence":["Technical keywords: maxmemory-policy, eviction, on-demand capacity, managed service overhead, failure isolation.","Explains that Redis memory exhaustion is prevented by evicting cold sessions, knowing DynamoDB retains the durable copy.","Discusses DynamoDB\'s on-demand capacity mode handling unpredictable traffic spikes seamlessly."]}],"critical_failures":["Suggests storing all long-term historical conversational records permanently in expensive Redis RAM without cold storage.","Confuses Redis sub-millisecond RAM caching with serverless disk-backed persistent storage like DynamoDB."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What would you say if asked why you are specifically interested in a company automating insurance workflows or supply-chain operations?', '{"key_points":[{"id":"KP1","description":"Recognizes the immense economic ROI and operational efficiency gained by automating complex, unstructured document processing.","required":true,"acceptable_evidence":["Technical keywords: document processing, unstructured-to-structured, Docling PDF parsing, claims extraction, automation, operational ROI.","Explains that insurance and supply-chain domains are weighed down by manual review of unstructured claims, invoices, and forms.","Highlights the transformative value of converting unstructured documents into structured, validated data automatically."]},{"id":"KP2","description":"Enthusiastic about applying cutting-edge AI architectures (RAG, GraphRAG, LangGraph multi-agent systems) to complex domain data.","required":true,"acceptable_evidence":["Technical keywords: LangGraph, Neo4j GraphRAG, Milvus hybrid search, multi-agent validation, auditability.","Explains that standard LLMs fail on complex domain reasoning, requiring hybrid retrieval and knowledge graphs to succeed.","Highlights the excitement of building multi-agent workflows that cross-check policy rules against claim line items."]},{"id":"KP3","description":"Emphasizes engineering for zero-tolerance hallucination, strict regulatory compliance, and human-in-the-loop auditability.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, RAGAS faithfulness, compliance, PII redaction, human-in-the-loop (HITL), SLA.","Recognizes that insurance and supply chain have strict legal liabilities requiring 100% auditable and faithful outputs.","Expresses passion for engineering deterministic guardrails and human approval checkpoints into AI workflows."]}],"critical_failures":["Treats enterprise insurance or supply-chain automation as trivial chatbot prompting without considering data accuracy and regulations.","Fails to acknowledge the high cost and liability of AI hallucinations in legal, financial, or logistics domains."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Where do your core strengths lie between frontend, backend, and AI/ML engineering?', '{"key_points":[{"id":"KP1","description":"Articulates deep expertise in backend systems engineering: high-throughput async APIs, database design, and caching layers.","required":true,"acceptable_evidence":["Technical keywords: FastAPI, asyncio, PostgreSQL, Redis TTL, API Gateway, microservice architecture.","Demonstrates mastery in designing robust backend services with FastAPI, async/await, and connection pooling.","Details optimizing relational queries in PostgreSQL and implementing multi-tiered caching in Redis."]},{"id":"KP2","description":"Demonstrates strong AI/ML systems engineering skills: agent orchestration (LangGraph), RAG pipelines, and automated evaluation.","required":true,"acceptable_evidence":["Technical keywords: LangGraph, Milvus vector search, RAGAS, cross-encoder reranking, Pydantic schemas, MLflow.","Explains building production RAG systems with hybrid search, dense indexing (Milvus HNSW), and reranking.","Highlights experience with stateful agent graphs, structured output validation, and systematic RAGAS benchmarking."]},{"id":"KP3","description":"Shows competent full-stack frontend integration skills: real-time streaming interfaces (SSE) and responsive UI.","required":true,"acceptable_evidence":["Technical keywords: React, TypeScript, Server-Sent Events (SSE), token streaming, WebSocket, optimistic updates.","Explains building client interfaces in React/TypeScript that consume streaming LLM responses seamlessly.","Details managing frontend state, rendering partial markdown tokens, and handling network disconnections gracefully."]},{"id":"KP4","description":"Positions overall strength as a cohesive bridge engineer capable of owning end-to-end AI applications from infrastructure to user experience.","required":false,"acceptable_evidence":["Technical keywords: end-to-end ownership, LangSmith tracing, Docker/Kubernetes deployment, CI/CD pipelines.","Emphasizes the ability to diagnose issues across the entire stack, from frontend rendering to vector retrieval to model latency.","Highlights delivering complete, production-ready features rather than isolated siloed components."]}],"critical_failures":["Claims equal senior-level mastery across every layer without providing technical depth or concrete examples for any.","Fails to articulate how backend architecture and AI engineering must interface to deliver a reliable product."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Which Python frameworks are suitable for building APIs, and how is FastAPI used in backend development?', '{"key_points":[{"id":"KP1","description":"Compares prominent Python API frameworks (FastAPI, Flask, Django), contrasting synchronous WSGI with modern asynchronous ASGI.","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Flask, Django, Starlette, ASGI vs WSGI, asynchronous performance, Uvicorn.","Explains that Flask and Django traditionally use synchronous WSGI, whereas FastAPI is built natively on ASGI (Starlette).","Highlights FastAPI\'s superior concurrency and non-blocking I/O handling for I/O-bound AI services."]},{"id":"KP2","description":"Details FastAPI\'s native support for async def, standard Python type hints, and automatic OpenAPI/Swagger documentation.","required":true,"acceptable_evidence":["Technical keywords: async def, type hinting, OpenAPI docs, Swagger UI, Starlette routing, Uvicorn ASGI server.","Explains that FastAPI uses standard Python type annotations to generate interactive OpenAPI/Swagger docs automatically.","Describes using async def and await to handle high-concurrency requests without blocking worker threads."]},{"id":"KP3","description":"Explains FastAPI\'s tight integration with Pydantic for request validation, data serialization, and response modeling.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModel, Field, response_model, 422 Unprocessable Entity, model_dump().","Details how incoming JSON payloads are automatically validated against Pydantic models before route handlers run.","Explains using response_model to sanitize output data and enforce consistent API contracts."]},{"id":"KP4","description":"Covers FastAPI\'s dependency injection system, background tasks, and streaming response capabilities.","required":false,"acceptable_evidence":["Technical keywords: Depends(), dependency injection, StreamingResponse, BackgroundTasks, httpx.AsyncClient.","Explains using Depends() for shared authentication, database sessions, and configuration management.","Details using StreamingResponse with async generators to stream real-time LLM tokens directly to clients."]}],"critical_failures":["Claims Flask or Django natively provide asynchronous ASGI streaming and automated Pydantic schema validation out of the box.","Confuses FastAPI\'s asynchronous event loop with multi-threading without mentioning ASGI or Uvicorn."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Which programming languages have you primarily used, and how have you applied them across different components such as ML, backend, and frontend?', '{"key_points":[{"id":"KP1","description":"Applies Python for backend services, machine learning pipelines, and agent orchestration.","required":true,"acceptable_evidence":["Technical keywords: Python, FastAPI, LangGraph, PySpark, PyTorch, Pydantic, asyncio, scientific ecosystem.","Explains utilizing Python for backend microservices (FastAPI), agent graphs (LangGraph), and ML data processing (PySpark).","Highlights Python\'s rich ecosystem of AI libraries, vector clients, and asynchronous frameworks."]},{"id":"KP2","description":"Applies TypeScript / JavaScript for frontend web development, user interfaces, and client state management.","required":true,"acceptable_evidence":["Technical keywords: TypeScript, JavaScript, React, Next.js, type safety, Server-Sent Events client.","Explains building responsive web applications with React and Next.js utilizing TypeScript for type safety.","Details consuming backend streaming endpoints and managing UI state with typed interfaces."]},{"id":"KP3","description":"Applies SQL for relational data queries, complex analytical aggregations, and database schema migrations.","required":true,"acceptable_evidence":["Technical keywords: SQL, PostgreSQL, MySQL, CTEs, window functions, indexing, parameterized queries.","Explains writing parameterized SQL queries, window functions, and Common Table Expressions (CTEs) in PostgreSQL.","Details optimizing indexes and query execution plans for persistent application data."]},{"id":"KP4","description":"Articulates architectural rationale for polyglot language choices based on performance, ecosystem maturity, and team velocity.","required":false,"acceptable_evidence":["Technical keywords: polyglot architecture, static vs dynamic typing, performance trade-offs, serialization standards.","Explains why Python dominates the AI/ML backend while TypeScript provides type safety and reactive rendering on the frontend.","Discusses sharing data contracts across language boundaries using OpenAPI and JSON schema standards."]}],"critical_failures":["Advocates using Python for client-side frontend browser rendering without architectural justification.","Fails to explain why Python is the industry standard for AI orchestration and backend services."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why are you interested in joining startups focused on applying AI to traditional industries such as insurance, food supply chains, or claims processing?', '{"key_points":[{"id":"KP1","description":"Identifies massive economic value and untapped transformation opportunities in modernizing paper-heavy traditional industries.","required":true,"acceptable_evidence":["Technical keywords: legacy workflows, paperless automation, claims processing, operational efficiency, ROI, traditional industries.","Explains that sectors like insurance and food supply chains still rely on manual, fragmented document processing.","Highlights the immense business impact of applying generative AI to automate hours of repetitive manual data entry."]},{"id":"KP2","description":"Tackles hard technical challenges with complex multimodal enterprise documents, domain taxonomies, and high precision standards.","required":true,"acceptable_evidence":["Technical keywords: Docling PDF parsing, table extraction, multi-agent validation, Pydantic validation, RAGAS faithfulness.","Explains that real-world industry documents (invoices, policies, shipping manifests) contain messy tables and nested clauses.","Describes designing advanced document extraction (Docling) and multi-agent reasoning to solve complex domain extraction."]},{"id":"KP3","description":"Emphasizes the critical need for deterministic guardrails, regulatory auditability, and human-in-the-loop workflows in high-stakes operations.","required":true,"acceptable_evidence":["Technical keywords: human-in-the-loop (HITL), audit trails, compliance, LangGraph checkpointing, explainability.","Recognizes that mistakes in insurance or supply chain cause immediate financial and legal repercussions.","Highlights enthusiasm for building auditable AI systems featuring human oversight checkpoints and transparent citations."]}],"critical_failures":["Dismisses traditional industries as mundane or assumes basic off-the-shelf chatbots can solve complex claims processing.","Fails to recognize the strict requirement for accuracy, compliance, and auditability in regulated enterprise sectors."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Why is long-term memory necessary when structured data can be fetched directly from databases?', '{"key_points":[{"id":"KP1","description":"Differentiates entity state in relational databases from unstructured, evolving semantic context and user conversational preferences.","required":true,"acceptable_evidence":["Technical keywords: semantic context, user preferences, unstructured history, episodic memory vs entity relational tables.","Explains that SQL databases store static facts (names, balances), but lack the conversational context and behavioral nuances.","Highlights that user intents, communication tone, and past problem-solving interactions are unstructured and dynamic."]},{"id":"KP2","description":"Explains how long-term vector/graph memory enables semantic similarity search over historical interactions across multiple sessions.","required":true,"acceptable_evidence":["Technical keywords: Milvus vector search, embedding similarity, Neo4j GraphRAG, historical intent, episodic retrieval.","Details embedding past conversation summaries and retrieving semantically relevant past experiences using Milvus.","Explains connecting concepts across sessions via knowledge graphs (Neo4j) to recall cross-domain user context."]},{"id":"KP3","description":"Enables personalization, cross-session continuity, and agent self-reflection without bloating prompts.","required":true,"acceptable_evidence":["Technical keywords: implicit preferences, personalization, cross-session continuity, agent self-reflection.","Describes synthesizing user feedback and past mistakes into episodic memory so the agent improves over time.","Explains personalizing future answers without forcing the user to repeat past context in every session."]},{"id":"KP4","description":"Optimizes context window and token budget management by retrieving relevant memory snippets rather than querying entire databases.","required":false,"acceptable_evidence":["Technical keywords: token budget, context window optimization, memory summarization, metadata filtering.","Explains that dumping entire database schemas or raw message logs into prompts overflows context windows and spikes cost.","Details summarizing past conversations and injecting only top-k relevant memory chunks into the prompt."]}],"critical_failures":["Claims structured SQL tables can natively perform semantic similarity search over fuzzy conversational context without vector embeddings.","Suggests dumping entire multi-month raw message histories into the LLM prompt window on every request."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why would I wrap an API into a tool and specify that as a tool node for a particular node to call versus just calling the API directly?', '{"key_points":[{"id":"KP1","description":"Enforces structured parameter schemas via LLM function calling and Pydantic validation before API invocation.","required":true,"acceptable_evidence":["Technical keywords: tool node, LangGraph ToolNode, Pydantic tool schema, JSON schema, LLM function calling.","Explains that wrapping an API into a tool provides a strict Pydantic schema so the LLM outputs correctly formatted parameters.","Details automatic argument validation, ensuring invalid LLM parameters fail before reaching the external API."]},{"id":"KP2","description":"Encapsulates resilience, error handling, retries, and fallback logic within a modular graph node.","required":true,"acceptable_evidence":["Technical keywords: encapsulation, retry policy, exception handling, fallback tool, modular architecture.","Explains that a tool node catches API timeouts, rate limits, and errors, feeding clear error messages back to the LLM.","Allows the agent to self-correct its parameters and retry without crashing the overall application."]},{"id":"KP3","description":"Enables Human-In-The-Loop (HITL) checkpointing, permission gating, and security policy checks before executing sensitive actions.","required":true,"acceptable_evidence":["Technical keywords: HITL checkpointing, LangGraph interrupt, approval workflow, security guardrail, RBAC.","Explains that specifying a tool node allows the graph to pause execution via checkpointers for human approval.","Prevents destructive or sensitive API actions (e.g., transfers, deletions) from executing without explicit authorization."]},{"id":"KP4","description":"Provides granular observability, telemetry, and distributed tracing of tool invocations.","required":false,"acceptable_evidence":["Technical keywords: LangSmith tracing, tool call telemetry, execution latency, input/output inspection.","Details how dedicated tool nodes produce isolated trace spans in LangSmith, capturing exact inputs, outputs, and latency.","Enables independent monitoring and debugging of external API dependencies across agent runs."]}],"critical_failures":["Fails to explain that an LLM cannot autonomously invoke an external API without a structured tool schema definition.","Claims hardcoding raw API calls directly inside system prompts without validation or error handling is safer and more reliable."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe a project where you rapidly prototyped an algorithm for a data-intensive or high-performance application, and how you validated its effectiveness?', '{"key_points":[{"id":"KP1","description":"Defines the problem domain and initial algorithmic prototype (e.g., fraud anomaly detection, hybrid search reranker, or data pipeline optimization).","required":true,"acceptable_evidence":["Technical keywords: XGBoost, PySpark AQE, hybrid retrieval, BM25 + dense embedding, rapid prototyping.","Describes a concrete technical project solving a high-throughput or data-intensive challenge.","Explains developing an initial working prototype using Python scientific/ML libraries."]},{"id":"KP2","description":"Applies high-performance optimization techniques: vectorization, broadcast joins, or scalable indexing structures.","required":true,"acceptable_evidence":["Technical keywords: broadcast join, Milvus HNSW indexing, cross-encoder reranking, vectorized operations, numpy/pandas.","Details optimizing algorithmic execution using vectorized NumPy/pandas operations or PySpark broadcast hints.","Explains replacing brute-force scans with HNSW indexing or efficient tree structures to cut computational complexity."]},{"id":"KP3","description":"Establishes a rigorous quantitative validation methodology using holdout datasets and domain benchmark metrics.","required":true,"acceptable_evidence":["Technical keywords: ROC-AUC, PR-AUC, RAGAS context_precision, offline holdout dataset, cross-validation.","Explains evaluating the algorithm against a historical holdout test set using metrics like ROC-AUC or context precision.","Compares performance quantitatively against baseline algorithms to prove statistical significance."]},{"id":"KP4","description":"Profiles latency, memory footprint, and throughput scalability under simulated production load.","required":false,"acceptable_evidence":["Technical keywords: latency profiling, p99 latency, cProfile, Spark UI shuffle analysis, throughput (QPS).","Describes profiling code bottlenecks with cProfile or analyzing Spark stages in the Spark UI.","Demonstrates meeting production SLAs for latency (p99) and queries per second under stress testing."]}],"critical_failures":["Describes building an algorithm without citing any quantitative evaluation metrics or baseline comparison.","Fails to explain how algorithmic latency, memory, or scalability bottlenecks were profiled and resolved."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe an instance where you identified a gap between frontend and backend behavior and how you handled cross-team communication?', '{"key_points":[{"id":"KP1","description":"Identifies the technical contract mismatch (e.g., SSE streaming chunk formatting, error response schemas, or HTTP 422 validation mismatches).","required":true,"acceptable_evidence":["Technical keywords: schema mismatch, Server-Sent Events (SSE), Pydantic validation error, contract divergence, HTTP 422.","Details discovering that backend response payloads differed from frontend TypeScript interface expectations.","Provides concrete examples such as misaligned SSE event delimiters causing frontend stream parser drops."]},{"id":"KP2","description":"Conducts systematic root-cause investigation using network inspection tools, browser DevTools, and backend trace logs.","required":true,"acceptable_evidence":["Technical keywords: browser DevTools, Network tab, LangSmith traces, FastAPI request logs, curl reproduction.","Describes reproducing the issue using curl and inspecting raw payload bytes in the browser Network tab.","Correlates frontend error timestamps with backend FastAPI and LangSmith server traces."]},{"id":"KP3","description":"Drives cross-team alignment by establishing formalized API contracts using OpenAPI specifications and shared TypeScript types.","required":true,"acceptable_evidence":["Technical keywords: OpenAPI specification, shared TypeScript interfaces, Pydantic schema export, contract testing.","Explains convening a technical sync with frontend engineers to review the OpenAPI schema definition.","Describes auto-generating TypeScript interfaces directly from backend Pydantic models to ensure single-source truth."]},{"id":"KP4","description":"Implements preventative mechanisms including automated contract testing and CI schema validation checks.","required":false,"acceptable_evidence":["Technical keywords: contract tests, schema diff CI checks, Swagger documentation, post-mortem.","Explains adding CI pipeline checks that flag breaking schema changes between backend PRs and frontend builds.","Documents API contracts and error code conventions in shared living documentation."]}],"critical_failures":["Blames the counterpart team without investigating the boundary contract or payload divergence.","Resolves the issue with ad-hoc frontend hacks rather than fixing and formalizing the underlying API contract."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your experience building AI systems that go beyond model development and integrate with microservices and production infrastructure?', '{"key_points":[{"id":"KP1","description":"Exposes model capabilities through high-performance, asynchronous microservice APIs using FastAPI, Docker, and Uvicorn.","required":true,"acceptable_evidence":["Technical keywords: FastAPI, microservices, async workers, Celery, Docker containerization, Uvicorn.","Explains encapsulating model inference within modular FastAPI microservices packaged as Docker containers.","Details decoupling heavy generation tasks to asynchronous Celery/Prefect workers to keep APIs responsive."]},{"id":"KP2","description":"Integrates scalable vector retrieval and state persistence infrastructure (Milvus, Redis, PostgreSQL).","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW, Redis session cache, PostgreSQL conversation persistence, hybrid retrieval.","Details connecting APIs with Milvus for high-scale HNSW vector indexing and hybrid search.","Explains using Redis for active session caching and PostgreSQL for persistent relational data and audit trails."]},{"id":"KP3","description":"Manages Kubernetes deployment, resource orchestration, and horizontal auto-scaling (HPA).","required":true,"acceptable_evidence":["Technical keywords: Kubernetes (EKS), Horizontal Pod Autoscaler (HPA), resource limits, ingress controller.","Explains deploying containerized AI microservices to Kubernetes clusters with ingress routing.","Details configuring HPA based on CPU/memory and GPU utilization to handle variable production traffic."]},{"id":"KP4","description":"Implements distributed observability, tracing, and metric collection across microservices.","required":true,"acceptable_evidence":["Technical keywords: LangSmith, Prometheus, Grafana, OpenTelemetry, request tracing, latency metrics.","Details instrumenting distributed traces across API gateways, microservices, and LLM calls via OpenTelemetry.","Monitors system health, token usage, error rates, and p99 latency in Prometheus and Grafana dashboards."]},{"id":"KP5","description":"Establishes production CI/CD pipelines, automated evaluation gating (RAGAS), and model registry versioning (MLflow/DVC).","required":false,"acceptable_evidence":["Technical keywords: MLflow model registry, DVC, RAGAS evaluation pipeline, GitHub Actions CI/CD.","Explains tracking model artifacts and experiment versions in MLflow with DVC-managed data versioning.","Details automated CI gating where pull requests must meet RAGAS evaluation thresholds before deployment."]}],"critical_failures":["Treats AI deployment as merely running a local Jupyter notebook or writing a simple synchronous script.","Omits production infrastructure concerns such as containerization, auto-scaling, or distributed monitoring."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your experience working on camera performance optimization across software and hardware layers, including collaboration with hardware, firmware, and SoC teams?', '{"key_points":[{"id":"KP1","description":"Multi-layer camera pipeline architecture across application, HAL, firmware, and SoC ISP.","required":true,"acceptable_evidence":["Technical keywords: camera pipeline, Android Camera HAL (HAL3), ISP (Image Signal Processor), V4L2 kernel driver, sensor firmware, DMA buffers, ION/dmabuf.","Explains tracing frame data flow from camera image sensor through ISP hardware, kernel V4L2 driver, Camera HAL, to user-space application consumers.","Details zero-copy buffer sharing between hardware blocks and GPU/DSP using ION or dmabuf to prevent memory copying bottlenecks."]},{"id":"KP2","description":"Cross-functional profiling and performance bottleneck identification.","required":true,"acceptable_evidence":["Technical keywords: systrace, Perfetto, ftrace, ISP frame processing time, frame drop, FPS jitter, thermal throttling.","Describes using Perfetto/systrace with kernel ftrace tracepoints to measure exact time spent in sensor exposure, ISP processing, and HAL request pipelines.","Details identifying frame drops caused by ISP pipeline stalls or kernel buffer lock contention under thermal limits."]},{"id":"KP3","description":"Collaborative firmware and hardware tuning for latency and power optimization.","required":true,"acceptable_evidence":["Technical keywords: 3A algorithms (Auto-Exposure, Auto-Focus, Auto-White-Balance), ISP tuning, sensor clock frequencies, SoC power rails, firmware patch validation.","Explains partnering with firmware engineers to optimize 3A convergence loops to reduce camera launch-to-first-frame latency.","Details collaborating with hardware/SoC teams to balance clock frequencies and power consumption to avoid aggressive thermal throttling."]}],"critical_failures":["Treats camera optimization purely as high-level application UI code without understanding HAL, ISP, or firmware interactions.","Cannot explain how frame buffers are shared across hardware components without CPU copy overhead (dmabuf/zero-copy).","Fails to name hardware tracing or performance instrumentation tools (Perfetto, systrace, ftrace)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how it was built? What was the architecture and the technology behind it?', '{"key_points":[{"id":"KP1","description":"Outlines high-level tiered architecture: Client UI, API Gateway, Application API layer, AI Orchestration engine, and Data Tier.","required":true,"acceptable_evidence":["Technical keywords: API Gateway, FastAPI async backend, LangGraph state engine, microservice tiers, React frontend.","Presents a structured multi-tier system separating presentation, business logic, agent orchestration, and storage.","Explains how requests flow securely from client entry points through backend microservices to AI workers."]},{"id":"KP2","description":"Details AI retrieval and reasoning pipeline: document ingestion, embedding generation, vector search, and reranking.","required":true,"acceptable_evidence":["Technical keywords: Docling PDF parser, BGE/MiniLM embeddings, Milvus HNSW indexing, cross-encoder reranker, BM25.","Explains parsing complex enterprise PDFs with Docling into structured semantic chunks.","Details indexing embeddings in Milvus with HNSW and executing hybrid search followed by cross-encoder reranking."]},{"id":"KP3","description":"Explains multi-tier caching, state management, and conversational persistence (Redis, PostgreSQL, LangGraph).","required":true,"acceptable_evidence":["Technical keywords: Redis session cache (TTL=86400), PostgreSQL long-term audit store, LangGraph checkpointers.","Details caching active session states in Redis with a 24h TTL and persisting completed threads in PostgreSQL.","Explains using LangGraph checkpointers to preserve multi-turn agent state and support human-in-the-loop interventions."]},{"id":"KP4","description":"Implements real-time token streaming and asynchronous communication protocols (FastAPI StreamingResponse, SSE).","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, Server-Sent Events (SSE), React frontend, asynchronous generators, astream().","Explains streaming generated LLM tokens via FastAPI\'s StreamingResponse and SSE to the React frontend.","Highlights minimizing time-to-first-token (TTFT) and providing a fluid real-time chat user experience."]},{"id":"KP5","description":"Covers production containerization, security policies, and distributed observability.","required":false,"acceptable_evidence":["Technical keywords: Docker, Kubernetes, JWT/OAuth2 authentication, LangSmith tracing, Prometheus monitoring.","Details containerizing microservices with Docker for deployment on Kubernetes clusters with JWT auth guards.","Instruments full-stack tracing with LangSmith and monitors system metrics with Prometheus and Grafana."]}],"critical_failures":["Gives a vague high-level overview without naming concrete technologies and component interactions.","Fails to describe data storage separation between relational databases, vector search, and session caching."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain the different HTTP methods and their use cases in API design?', '{"key_points":[{"id":"KP1","description":"Explains GET and DELETE methods: semantics, resource retrieval, removal, idempotency, and safe method properties.","required":true,"acceptable_evidence":["Technical keywords: GET, DELETE, safe methods, idempotent, query parameters, path parameters, caching.","Explains that GET is safe and idempotent, used exclusively to retrieve resources without modifying state.","Explains that DELETE is idempotent, used to remove resources such that repeated calls yield the same system state."]},{"id":"KP2","description":"Compares POST, PUT, and PATCH: creation vs full resource replacement vs partial modification, including idempotency differences.","required":true,"acceptable_evidence":["Technical keywords: POST (non-idempotent creation), PUT (idempotent full update), PATCH (partial update), idempotency.","Explains that POST is non-idempotent, commonly used to create new resources or submit inference tasks.","Differentiates PUT (idempotent complete replacement) from PATCH (modifying specific attributes of an existing resource)."]},{"id":"KP3","description":"Associates HTTP methods with standard REST status codes and error responses.","required":true,"acceptable_evidence":["Technical keywords: 200 OK, 201 Created, 204 No Content, 400 Bad Request, 404 Not Found, 422 Unprocessable Entity.","Explains returning 201 Created upon successful POST creation and 200 OK or 204 No Content on PUT/PATCH/DELETE.","Details standard client error codes like 404 Not Found, 401 Unauthorized, and 422 for validation failures."]},{"id":"KP4","description":"Applies HTTP methods to AI/ML backend API patterns (e.g., POST for inference generation, GET for polling task status, SSE streaming).","required":false,"acceptable_evidence":["Technical keywords: POST /chat/completions, GET /tasks/{task_id}, StreamingResponse, RESTful AI endpoints.","Explains using POST for generation requests due to large prompt payload bodies exceeding URL parameter limits.","Describes using GET endpoints to poll asynchronous background job status or retrieve past chat sessions."]}],"critical_failures":["Confuses PUT with PATCH regarding idempotency and full resource replacement vs partial update.","Claims GET requests should be used to mutate database state or trigger heavy LLM generation."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Discuss your experience with Python, specifying which frameworks and libraries you utilize efficiently for backend and API services (e.g., FastAPI), and your proficiency in both functional and Object-Oriented Programming (OOP) concepts.', '{"key_points":[{"id":"KP1","description":"Details experience with backend and API frameworks: FastAPI, Uvicorn ASGI server, Starlette, and Python asyncio.","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Uvicorn, asyncio, async/await, httpx.AsyncClient, non-blocking I/O.","Explains leveraging FastAPI and asyncio to handle high-concurrency, I/O-bound AI requests efficiently.","Describes building asynchronous route handlers and using httpx.AsyncClient for non-blocking outbound requests."]},{"id":"KP2","description":"Covers data validation, serialization, and schema management using Pydantic BaseModel.","required":true,"acceptable_evidence":["Technical keywords: Pydantic, BaseModel, Field, validation, model_dump(), model_validate().","Details using Pydantic models for strict API request validation, response serialization, and structured LLM outputs.","Explains leveraging custom validators (@field_validator) and Field constraints to enforce data hygiene."]},{"id":"KP3","description":"Demonstrates proficiency in Object-Oriented Programming (OOP): class hierarchies, abstraction, custom exceptions, and design patterns.","required":true,"acceptable_evidence":["Technical keywords: OOP, inheritance, abstract base classes (ABC), custom exceptions, encapsulation, LangChain/LangGraph classes.","Explains building extensible service classes, custom exception hierarchies, and abstract model adapters.","Details encapsulating agent state and tool behaviors within structured classes and graph nodes."]},{"id":"KP4","description":"Demonstrates proficiency in functional programming concepts: generators, list/dict comprehensions, pure functions, and immutability.","required":true,"acceptable_evidence":["Technical keywords: functional programming, generators (yield), map/filter/reduce, lambdas, immutability, async generators.","Explains using Python generators (yield) and async generators to stream large files or token responses with low memory overhead.","Details writing pure data transformation functions and immutable state transitions in LangGraph state graphs."]},{"id":"KP5","description":"References broader Python ecosystem expertise: testing (pytest), data manipulation (PySpark, pandas), and static typing (mypy).","required":false,"acceptable_evidence":["Technical keywords: PySpark, pandas, NumPy, pytest fixtures, type annotations, mypy.","Mentions using PySpark or pandas for large-scale data ingestion and dataset preparation.","Highlights writing comprehensive pytest test suites and enforcing static typing with mypy."]}],"critical_failures":["Confuses asynchronous I/O event loops with multi-threaded multiprocessing or fails to explain when await is necessary.","Cannot articulate the distinction between OOP principles (encapsulation, polymorphism) and functional programming constructs in Python."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Have you worked on designing novel loss functions or custom model architectures for discriminative or generative tasks?', '{"key_points":[{"id":"KP1","description":"Formulation and mathematical justification of custom loss functions for specific data challenges.","required":true,"acceptable_evidence":["Technical keywords: custom loss function, Focal Loss, Contrastive Loss, Triplet Loss, Dice Loss, class imbalance, hard negative mining, gradient behavior.","Explains modifying standard cross-entropy or MSE to address extreme class imbalance or hard-to-distinguish samples using focusing parameters $\\\\gamma$.","Details contrastive or metric learning loss formulations: $\\\\mathcal{L} = \\\\max(0, d(a,p) - d(a,n) + \\\\alpha)$ to enforce embedding space separation."]},{"id":"KP2","description":"Custom neural architecture design, layer modification, and specialized head integration.","required":true,"acceptable_evidence":["Technical keywords: PyTorch nn.Module, custom attention mechanisms, multi-task learning heads, skip connections, feature fusion, bottleneck layers.","Describes building custom neural architectures in PyTorch by overriding `forward()` and integrating multi-scale feature pyramids or specialized pooling.","Explains designing multi-task architectures sharing a common backbone with task-specific projection heads and balanced loss weighting."]},{"id":"KP3","description":"Empirical validation, gradient stability, and training convergence monitoring.","required":true,"acceptable_evidence":["Technical keywords: gradient vanishing/exploding, gradient clipping, learning rate warmup, ablation studies, loss convergence, WandB/TensorBoard.","Explains verifying that custom loss functions maintain well-behaved gradients across extreme prediction ranges (e.g. log-sum-exp numerical stability).","Details conducting systematic ablation experiments comparing custom architectures against standard baselines on validation metrics."]}],"critical_failures":["Claims to design loss functions without articulating mathematical formulations or addressing gradient behavior.","Cannot explain the difference in objective functions between discriminative tasks (cross-entropy/focal) and generative tasks (adversarial/diffusion/KL-divergence).","Fails to describe how numerical stability and gradient scaling were evaluated during training."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you design a scalable framework that allows multiple teams to upload documents and use the AI assistant across domains?', '{"key_points":[{"id":"KP1","description":"Implements a multi-tenant ingestion architecture with strict document metadata tagging (tenant_id, domain, role_access).","required":true,"acceptable_evidence":["Technical keywords: multi-tenancy, tenant_id, metadata filtering, Docling parser, chunking strategies.","Explains tagging all document chunks with tenant and domain IDs during ingestion to ensure data isolation.","Details parsing heterogeneous documents (PDFs, docs) with Docling into normalized semantic chunks."]},{"id":"KP2","description":"Partitions vector storage in Milvus using collection namespaces, partition keys, and filtered HNSW indexing.","required":true,"acceptable_evidence":["Technical keywords: Milvus partitions, HNSW indexing, partition keys, namespace isolation, RBAC access control.","Explains leveraging Milvus partition keys to segment vector storage by team or domain for high query efficiency.","Details applying strict metadata filtering during search to guarantee teams cannot access unauthorized documents."]},{"id":"KP3","description":"Decouples document processing using asynchronous background task queues (SQS, Celery, BackgroundTasks).","required":true,"acceptable_evidence":["Technical keywords: SQS, Celery, BackgroundTasks, async worker pool, ingestion status tracking.","Explains accepting document uploads immediately with a 202 Accepted status and job ID, offloading OCR and embedding to workers.","Details tracking ingestion status and failures in a database so teams can monitor processing progress."]},{"id":"KP4","description":"Designs a dynamic domain router (LangGraph) that selects specialized retrieval collections, prompts, and tools per team.","required":true,"acceptable_evidence":["Technical keywords: LangGraph router node, domain classifiers, prompt templates per domain, dynamic tool selection.","Explains routing user queries through a classifier node that directs the query to the appropriate domain knowledge base.","Details configuring domain-specific system prompts, temperature settings, and specialized tool nodes dynamically."]},{"id":"KP5","description":"Enforces rate limiting, quota management, and compute resource isolation across different teams.","required":false,"acceptable_evidence":["Technical keywords: API Gateway rate limiting, per-team quotas, Redis token bucket, Prometheus metrics.","Explains implementing Redis-backed rate limiting per tenant to prevent one team from starving shared cluster resources.","Monitors token consumption and retrieval latency per tenant using Prometheus metrics."]}],"critical_failures":["Proposes a single shared vector index without tenant metadata filtering or partition isolation, risking cross-tenant data leaks.","Suggests processing heavy multi-page document parsing and embedding synchronously within the incoming HTTP request thread."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How did you design the system architecture, including backend services, APIs, and frontend integration?', '{"key_points":[{"id":"KP1","description":"Architects comprehensive multi-tier system: React/Next.js frontend, API Gateway, FastAPI backend microservices, and LangGraph AI orchestration.","required":true,"acceptable_evidence":["Technical keywords: API Gateway, FastAPI backend, React frontend, LangGraph engine, microservices architecture.","Presents a clean separation of concerns across client, gateway, backend business logic, and agent execution layers.","Explains the end-to-end request lifecycle from user interface through APIs to backend services."]},{"id":"KP2","description":"Designs real-time API communication protocols using FastAPI StreamingResponse and Server-Sent Events (SSE).","required":true,"acceptable_evidence":["Technical keywords: REST APIs, Server-Sent Events (SSE), StreamingResponse, OpenAPI contracts, WebSocket.","Explains streaming generated LLM tokens incrementally via SSE to provide instant feedback on the React frontend.","Details defining strict OpenAPI/Pydantic schemas to ensure frontend-backend contract stability."]},{"id":"KP3","description":"Decouples asynchronous tasks and compute-heavy workloads using background queues (Celery/SQS).","required":true,"acceptable_evidence":["Technical keywords: Celery, SQS, Redis queue, async task workers, event-driven architecture.","Explains offloading document parsing, model fine-tuning, and batch evaluation to asynchronous worker queues.","Ensures the core API server remains non-blocking and highly available during peak load."]},{"id":"KP4","description":"Implements clear data tier separation: relational storage (PostgreSQL), vector indexing (Milvus), and in-memory caching (Redis).","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL (ACID records), Milvus (HNSW vector search), Redis (ephemeral session state & TTL).","Details storing user accounts, audit trails, and billing in PostgreSQL with ACID guarantees.","Details indexing document embeddings in Milvus and caching active sessions and frequent queries in Redis."]},{"id":"KP5","description":"Incorporates production security, authentication, and full-stack observability.","required":false,"acceptable_evidence":["Technical keywords: JWT/OAuth2, CORS, rate limiting, LangSmith tracing, Prometheus, Grafana.","Explains securing endpoints with JWT authentication, role-based access control, and API Gateway rate limiting.","Details capturing distributed traces with LangSmith and monitoring system performance in Prometheus and Grafana."]}],"critical_failures":["Describes a monolithic synchronous design where the frontend blocks on a single long-running HTTP request without streaming.","Fails to define distinct data storage strategies for relational records, high-dimensional vectors, and session caching."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement API gateways, FastAPI services, and rate limiting for production traffic?', '{"key_points":[{"id":"KP1","description":"Configures API Gateway (Kong, Traefik, Nginx, or AWS API Gateway) for centralized SSL termination, reverse proxy routing, and JWT validation.","required":true,"acceptable_evidence":["Technical keywords: API Gateway, Nginx, Kong, Traefik, reverse proxy, SSL termination, JWT validation.","Explains using an API gateway as the single entry point to route external traffic to backend microservices.","Details offloading TLS termination and validating JWT bearer tokens at the gateway before hitting application code."]},{"id":"KP2","description":"Structures FastAPI services modularly using APIRouters, dependency injection, and Pydantic validation.","required":true,"acceptable_evidence":["Technical keywords: APIRouter, FastAPI Depends(), Pydantic BaseModel, error handlers, Uvicorn workers.","Explains organizing endpoints into domain-specific APIRouters with shared dependency injection (Depends).","Details validating request bodies via Pydantic and running multiple Uvicorn workers behind Gunicorn."]},{"id":"KP3","description":"Implements distributed rate limiting using Redis data structures and sliding window / token bucket algorithms.","required":true,"acceptable_evidence":["Technical keywords: Redis sliding window, token bucket algorithm, INCRBY, EXPIRE, HTTP 429 Too Many Requests.","Explains tracking request timestamps in Redis sorted sets or atomic counters to calculate rolling request rates.","Details returning HTTP 429 Too Many Requests when users or IP addresses exceed permitted thresholds."]},{"id":"KP4","description":"Defines multi-tiered rate limiting policies (per-user, per-IP, and per-API-key tiers) with standard headers.","required":true,"acceptable_evidence":["Technical keywords: user quotas, IP throttling, API key tiers, rate limit headers (X-RateLimit-Remaining).","Explains applying strict rate limits on anonymous IP addresses while granting higher quotas to authenticated API keys.","Details returning standard response headers (Retry-After, X-RateLimit-Limit, X-RateLimit-Remaining)."]},{"id":"KP5","description":"Integrates Prometheus metrics and circuit breakers to handle traffic spikes and protect downstream LLMs.","required":false,"acceptable_evidence":["Technical keywords: Prometheus metrics, Grafana dashboards, circuit breaker, exponential backoff.","Monitors rate limit breach rates and API latency via Prometheus metrics in Grafana.","Applies circuit breakers to shed load gracefully when downstream LLM APIs experience outages or throttling."]}],"critical_failures":["Recommends implementing in-memory Python dictionaries for rate limiting across multi-pod or multi-worker deployments.","Omits returning HTTP 429 status codes and standard rate limit headers when requests are rejected."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement asynchronous APIs and streaming responses in your system?', '{"key_points":[{"id":"KP1","description":"Designs asynchronous FastAPI endpoints using async def, await, and non-blocking I/O clients (httpx.AsyncClient).","required":true,"acceptable_evidence":["Technical keywords: async def, await, asyncio, httpx.AsyncClient, non-blocking I/O, event loop.","Explains using async def route handlers so worker threads are not blocked during slow external I/O operations.","Details using httpx.AsyncClient with await to query external services concurrently on the asyncio event loop."]},{"id":"KP2","description":"Implements real-time token streaming using FastAPI StreamingResponse and Python asynchronous generators.","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, async generator, yield, media_type=\'text/event-stream\', Server-Sent Events (SSE).","Explains creating an async generator that yields formatted data chunks (data: {token}\\\\n\\\\n) as they are produced.","Wraps the generator in FastAPI\'s StreamingResponse with media_type=\'text/event-stream\' to enable SSE streaming."]},{"id":"KP3","description":"Integrates LLM and LangGraph streaming events (astream, on_llm_new_token) into the generator pipeline.","required":true,"acceptable_evidence":["Technical keywords: astream(), LangChain/LangGraph streaming events, token chunking, on_llm_new_token.","Explains iterating over model.astream() or LangGraph\'s event stream to capture tokens in real time.","Details forwarding partial token deltas immediately through the async generator without buffering full responses."]},{"id":"KP4","description":"Handles client disconnects, cancellation signals, and connection error handling gracefully.","required":false,"acceptable_evidence":["Technical keywords: EventSource, fetch ReadableStream, client disconnect handling, cancellation cleanup.","Explains listening for client disconnect signals (request.is_disconnected()) to abort active LLM generation promptly.","Prevents orphaned background inference jobs and conserves costly token consumption when users cancel."]}],"critical_failures":["Uses synchronous blocking calls (requests.get, time.sleep) directly inside async def endpoints, freezing the event loop.","Buffers the entire LLM response in server memory before returning, completely negating the benefits of streaming."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement caching in your system, and what role did Redis play?', '{"key_points":[{"id":"KP1","description":"Implements a multi-layer caching strategy: exact query hashing, semantic LLM caching, and active session caching in Redis.","required":true,"acceptable_evidence":["Technical keywords: Redis, semantic cache, prompt caching, session cache, cache-aside pattern.","Explains using Redis to intercept identical or semantically equivalent user queries before invoking LLMs.","Details storing active conversation state in Redis to avoid re-reading database history on every turn."]},{"id":"KP2","description":"Details cache key generation mechanisms: cryptographic hashing (SHA256/MD5) for exact matches and vector similarity for semantic matches.","required":true,"acceptable_evidence":["Technical keywords: MD5/SHA256 query hash, vector similarity threshold, normalized prompt keys, cache lookup.","Explains normalizing and hashing query strings with SHA256 to serve as Redis lookup keys.","Describes comparing incoming query embeddings against cached questions in Redis using a cosine similarity threshold."]},{"id":"KP3","description":"Manages cache freshness and expiration policies using granular Redis TTL settings.","required":true,"acceptable_evidence":["Technical keywords: Redis TTL, EXPIRE, SET EX, TTL=3600 (LLM cache), TTL=86400 (session), cache invalidation.","Explains configuring a 1-hour TTL (3600s) on LLM response caches to balance freshness with cost savings.","Details setting a 24-hour sliding TTL (86400s) on user session states, renewed on each new interaction."]},{"id":"KP4","description":"Addresses cache operational resilience: eviction policies, cache stampede mitigation, and graceful fallback.","required":false,"acceptable_evidence":["Technical keywords: maxmemory-policy volatile-lru, mutex lock / single-flight, graceful fallback to LLM.","Configures Redis memory eviction (volatile-lru) to automatically purge expired items when RAM limits are reached.","Ensures the system falls back seamlessly to model inference if Redis encounters a cache miss or network timeout."]}],"critical_failures":["Implements caching without setting any TTL or invalidation policy, resulting in permanently stale or inaccurate responses.","Fails to handle cache misses gracefully, allowing Redis timeouts or missing keys to crash the application."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you structure and optimize FastAPI-based services to expose AI/ML capabilities in production?', '{"key_points":[{"id":"KP1","description":"Structures services with modular APIRouters and manages model lifecycle using FastAPI Lifespan context managers.","required":true,"acceptable_evidence":["Technical keywords: APIRouter, lifespan context manager, model warm-up, dependency injection, Uvicorn workers.","Explains loading models, tokenizers, and database pools during application startup via async lifespan managers.","Prevents reloading heavy model weights per request and ensures clean shutdown resource cleanup."]},{"id":"KP2","description":"Optimizes request/response serialization using Pydantic v2, response_model filtering, and high-performance JSON serializers (orjson).","required":true,"acceptable_evidence":["Technical keywords: Pydantic v2, orjson, model_dump(), serialization overhead, response_model.","Details adopting Pydantic v2 compiled core and orjson to drastically reduce JSON parsing and serialization latency.","Uses response_model to sanitize outgoing schemas without unnecessary deep object copies."]},{"id":"KP3","description":"Ensures non-blocking concurrency: asyncio.gather() for parallel I/O and thread pools for synchronous CPU-bound operations.","required":true,"acceptable_evidence":["Technical keywords: asyncio.gather(), run_in_threadpool, httpx.AsyncClient, non-blocking inference calls.","Explains using asyncio.gather() to execute vector searches and external API queries concurrently.","Details offloading synchronous ML inference or tokenization functions to thread pools via run_in_threadpool."]},{"id":"KP4","description":"Exposes real-time token streaming using StreamingResponse and asynchronous generators for low perceived latency.","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, text/event-stream, async generator, LangGraph astream().","Explains streaming generated tokens directly from LangGraph or LLMs to web clients via Server-Sent Events.","Minimizes time-to-first-token (TTFT) and delivers immediate interactive feedback to users."]},{"id":"KP5","description":"Implements production health checks, Prometheus telemetry middleware, and containerized deployment tuning.","required":false,"acceptable_evidence":["Technical keywords: /health endpoint, Prometheus middleware, LangSmith tracing, Gunicorn/Uvicorn worker sizing, EKS.","Details implementing liveness and readiness probe endpoints (/health, /ready) for Kubernetes orchestration.","Instruments request metrics, error counts, and token latency using Prometheus middleware and LangSmith tracing."]}],"critical_failures":["Loads heavy model weights on every incoming HTTP request inside the route handler instead of during application startup.","Executes heavy synchronous CPU-bound operations directly on the main event loop thread, blocking all concurrent API traffic."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How do shuffles impact Spark job performance, and what strategies can you use to minimize them?', '{"key_points":[{"id":"KP1","description":"Explains the Spark shuffle mechanism: wide transformations, disk serialization, network data transfer, and stage boundaries.","required":true,"acceptable_evidence":["Technical keywords: Spark shuffle, Wide transformations, stage boundary, disk spill, network I/O, serialization overhead.","Explains that shuffles occur during wide transformations (groupBy, join, distinct) requiring data repartitioning across executors.","Details the severe performance impact of disk I/O spills, network serialization, and executor garbage collection pauses."]},{"id":"KP2","description":"Leverages Adaptive Query Execution (AQE) to dynamically coalesce shuffle partitions and optimize query plans at runtime.","required":true,"acceptable_evidence":["Technical keywords: Adaptive Query Execution (AQE), spark.sql.adaptive.enabled, dynamic partition coalescing, runtime join conversion.","Explains enabling AQE to dynamically merge small shuffle partitions post-shuffle based on runtime stage statistics.","Details AQE dynamically converting slow SortMergeJoins into BroadcastHashJoins when partition sizes fall below thresholds."]},{"id":"KP3","description":"Utilizes Broadcast Hash Joins to eliminate shuffles entirely when joining large datasets with small lookup tables.","required":true,"acceptable_evidence":["Technical keywords: broadcast() hint, spark.sql.autoBroadcastJoinThreshold, BroadcastHashJoin, SortMergeJoin avoidance.","Explains using the broadcast() hint to send small dimension tables to all executors, avoiding expensive shuffle exchanges.","Mentions tuning spark.sql.autoBroadcastJoinThreshold (default 10MB) to optimize broadcast join eligibility."]},{"id":"KP4","description":"Optimizes partitioning strategies: distinguishes coalesce() from repartition() and tunes shuffle partition counts.","required":true,"acceptable_evidence":["Technical keywords: coalesce(n), repartition(n, col), spark.sql.shuffle.partitions, partition pruning.","Explains using coalesce(n) to reduce partition counts without triggering a shuffle, versus repartition() which forces a full shuffle.","Details tuning spark.sql.shuffle.partitions away from the default 200 to match data scale and cluster core count."]},{"id":"KP5","description":"Mitigates data skew bottlenecks using salting and AQE skew join optimization.","required":false,"acceptable_evidence":["Technical keywords: data skew, salting technique, random prefix, spark.sql.adaptive.skewJoin.enabled.","Explains appending random salt keys to skewed join keys to distribute hot-key data evenly across multiple shuffle partitions.","Details enabling AQE skew join optimization (spark.sql.adaptive.skewJoin.enabled) to automatically split skewed partitions."]}],"critical_failures":["Recommends using repartition() instead of coalesce() when reducing partition counts without needing a shuffle.","Confuses narrow transformations (map, filter) with wide transformations (groupBy, join) that trigger shuffles."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do techniques like lazy loading and memoization improve frontend performance, and when would you apply them?', '{"key_points":[{"id":"KP1","description":"Explains lazy loading concepts and implementation: code splitting, React.lazy, dynamic imports, and Suspense boundaries.","required":true,"acceptable_evidence":["Technical keywords: React.lazy, Suspense, dynamic import(), code splitting, bundle size reduction.","Explains deferring the loading of non-critical JavaScript bundles until the specific component is rendered.","Details using dynamic import() inside React.lazy with Suspense fallbacks to accelerate initial page load times."]},{"id":"KP2","description":"Explains memoization mechanisms in React: React.memo, useMemo, and useCallback for skipping redundant calculations and re-renders.","required":true,"acceptable_evidence":["Technical keywords: React.memo, useMemo, useCallback, referential equality, expensive computation caching.","Explains using React.memo to prevent component re-renders when parent props remain unchanged.","Details using useMemo to cache computationally expensive calculations and useCallback to maintain stable function references."]},{"id":"KP3","description":"Analyzes performance trade-offs: memory overhead and comparison costs of excessive memoization versus re-render expenses.","required":true,"acceptable_evidence":["Technical keywords: memory overhead, shallow comparison cost, unnecessary memoization, re-render profiling.","Explains that memoization consumes memory to store cached values and incurs prop comparison overhead on every render.","Emphasizes profiling rendering performance before applying memoization rather than memoizing trivial primitives."]},{"id":"KP4","description":"Applies lazy loading and memoization to AI/ML chat interfaces (e.g., lazy loading heavy syntax highlighters/math renderers and memoizing message lists).","required":false,"acceptable_evidence":["Technical keywords: streamed message list, syntax highlighter lazy loading, Virtualized lists (react-window).","Explains lazy loading heavy markdown libraries (e.g., Prism.js, KaTeX) only when code or math is present in LLM output.","Details memoizing completed historical message bubbles so that incoming streamed tokens only trigger re-renders on the active bubble."]}],"critical_failures":["Advocates wrapping every single component and primitive value in useMemo/useCallback indiscriminately without understanding overhead.","Confuses frontend client-side code-splitting with backend database query caching."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach designing scalable and user-focused AI product experiences?', '{"key_points":[{"id":"KP1","description":"Manages perceived latency through real-time token streaming, skeleton loaders, and optimistic UI updates.","required":true,"acceptable_evidence":["Technical keywords: token streaming, Server-Sent Events, skeleton loaders, perceived latency, time-to-first-token (TTFT).","Explains streaming generated tokens incrementally (SSE) to deliver immediate visual feedback instead of waiting on full answers.","Details displaying animated skeleton loaders and instant message bubbles to enhance perceived responsiveness."]},{"id":"KP2","description":"Addresses AI uncertainty and non-determinism via transparent citations, confidence indicators, and fallback states.","required":true,"acceptable_evidence":["Technical keywords: source citations, confidence scores, disclaimer guardrails, graceful degradation, fallback responses.","Explains displaying clickable source citations linking to original retrieved document chunks to build user trust.","Details presenting clear error states and graceful fallbacks when the AI is uncertain or retrieval finds no relevant context."]},{"id":"KP3","description":"Incorporates Human-In-The-Loop (HITL) interactions: user feedback controls, prompt editing, and approval workflows.","required":true,"acceptable_evidence":["Technical keywords: human-in-the-loop, LangGraph checkpointers, user edits, thumbs-up/thumbs-down feedback, rollback.","Explains allowing users to edit past prompts and regenerate responses from LangGraph execution checkpoints.","Details capturing granular feedback (thumbs up/down, edit text) to feed continuous evaluation and improvement loops."]},{"id":"KP4","description":"Designs scalable backend infrastructure capable of handling high-concurrency real-time interactions.","required":true,"acceptable_evidence":["Technical keywords: FastAPI async streaming, Redis session cache, connection pooling, horizontal auto-scaling.","Details structuring asynchronous backends with Redis session caching to handle thousands of simultaneous active chats.","Implements connection pooling and auto-scaling to prevent traffic spikes from degrading UI responsiveness."]},{"id":"KP5","description":"Monitors user experience telemetry, drop-off rates, and operational quality through distributed tracing and analytics.","required":false,"acceptable_evidence":["Technical keywords: user session analytics, drop-off rate, latency tracking, LangSmith traces, A/B testing.","Tracks user engagement, completion rates, and satisfaction scores alongside technical latency metrics.","Conducts A/B tests on prompt variants and UI interaction models to validate product improvements empirically."]}],"critical_failures":["Displays blank waiting screens for 15+ seconds instead of implementing real-time token streaming.","Treats AI generations as infallible truths without providing source attribution, confidence indicators, or error fallbacks."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach model selection decisions, considering factors like cost, context window, and performance?', '{"key_points":[{"id":"KP1","description":"Establishes a multi-dimensional evaluation rubric: token pricing, time-to-first-token (TTFT), context length, reasoning capability, and rate limits.","required":true,"acceptable_evidence":["Technical keywords: cost per 1k tokens, TTFT (time-to-first-token), context window length, benchmark accuracy, throughput.","Explains evaluating models across a structured trade-off matrix balancing financial cost against latency and accuracy.","Considers operational throughput constraints including API tier rate limits (TPM/RPM) and concurrency ceilings."]},{"id":"KP2","description":"Implements tiered model routing (cascading): assigning lightweight SLMs to simple tasks and reserving frontier LLMs for complex reasoning.","required":true,"acceptable_evidence":["Technical keywords: model cascading / routing, lightweight SLMs (e.g. GPT-4o-mini, Claude Haiku), frontier LLMs, intent classifier.","Explains using fast, inexpensive models for intent classification, query extraction, and basic summarization.","Routes multi-step reasoning, tool coordination, and complex policy synthesis to frontier models (e.g., GPT-4o, Claude 3.5 Sonnet)."]},{"id":"KP3","description":"Conducts empirical evaluation using domain-specific benchmarks and RAGAS metrics rather than relying on public leaderboards.","required":true,"acceptable_evidence":["Technical keywords: RAGAS evaluation, domain validation dataset, context_precision, faithfulness, ablation testing.","Explains running offline ablation tests across candidate models against a curated domain ground-truth dataset.","Measures quantitative RAGAS metrics (faithfulness, relevancy) to prove smaller models meet quality thresholds before adoption."]},{"id":"KP4","description":"Evaluates context window trade-offs: attention dilution (\'lost in the middle\') versus RAG hybrid retrieval.","required":true,"acceptable_evidence":["Technical keywords: lost-in-the-middle, attention dilution, RAG retrieval vs long-context brute force, prompt truncation.","Explains that massive context windows often suffer from attention degradation and significantly higher latency and cost.","Advocates hybrid RAG retrieval with precise context injection over stuffing entire unindexed document archives into prompts."]},{"id":"KP5","description":"Considers operational deployment factors: data privacy, open-weight self-hosting (vLLM) versus commercial managed APIs.","required":false,"acceptable_evidence":["Technical keywords: open-weight models (Llama, Mistral), vLLM deployment, data privacy compliance, fallback providers.","Evaluates self-hosting open-weight models on vLLM/Kubernetes for strict data residency or offline enterprise environments.","Plans multi-provider fallbacks to insulate against cloud vendor outages or aggressive rate limiting."]}],"critical_failures":["Always defaults to the largest and most expensive frontier LLM for every task without evaluating cost or latency trade-offs.","Relies entirely on generic public leaderboards (e.g., LMSYS, MMLU) rather than empirical benchmarking on domain-specific data."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach system design for AI platforms in fast-paced, ambiguous startup environments?', '{"key_points":[{"id":"KP1","description":"Designs modular, decoupled architectures (LangGraph, FastAPI) with pluggable model adapters to absorb rapid pivoting.","required":true,"acceptable_evidence":["Technical keywords: modular architecture, LangGraph DAGs, pluggable model adapters, abstraction layers, FastAPI.","Explains isolating AI model and retrieval integrations behind clean interfaces so models can be swapped effortlessly.","Uses stateful graph engines (LangGraph) allowing agent logic and tools to be reconfigured without major code rewrites."]},{"id":"KP2","description":"Prioritizes pragmatic MVP delivery by leveraging proven managed cloud services and open-source tools over premature custom infrastructure.","required":true,"acceptable_evidence":["Technical keywords: managed services, Docker, Redis, PostgreSQL, Milvus, avoiding premature over-engineering.","Explains choosing managed databases (e.g., managed Redis, RDS PostgreSQL, managed Milvus) to eliminate DevOps overhead.","Focuses engineering bandwidth on differentiating core product logic and user experience rather than reinventing infrastructure."]},{"id":"KP3","description":"Establishes early observability, tracing, and automated evaluation benchmarks to iterate safely amidst shifting requirements.","required":true,"acceptable_evidence":["Technical keywords: LangSmith tracing, RAGAS automated evaluation, centralized logging, rapid feedback loops.","Instruments distributed tracing (LangSmith) on day one to diagnose failures and inspect intermediate prompt steps.","Builds lightweight automated evaluation test sets to catch behavioral regressions during rapid iteration."]},{"id":"KP4","description":"Enforces strict Pydantic schema contracts to protect application boundaries against volatile LLM outputs and external APIs.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, strict API contracts, backward compatibility, versioned endpoints.","Uses Pydantic models to validate all incoming API payloads and structured LLM outputs strictly.","Ensures downstream UI components and database writers never receive malformed data during rapid prompt iterations."]},{"id":"KP5","description":"Architects for horizontal scalability by keeping API services stateless and externalizing session state.","required":false,"acceptable_evidence":["Technical keywords: stateless API tier, Redis session state, horizontal scaling, cloud auto-scaling, containerization.","Ensures backend web containers are completely stateless, storing all active session state in Redis.","Allows instant horizontal scaling via Docker containers on cloud services as user traffic surges."]}],"critical_failures":["Spends months over-engineering a complex distributed custom framework before validating product-market fit with users.","Deploys unmonitored, tightly-coupled prompt scripts with no schema validation, tracing, or automated evaluation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach system design for scalable, production-grade GenAI applications end-to-end?', '{"key_points":[{"id":"KP1","description":"Designs an asynchronous API gateway and microservice ingress layer handling routing, rate limiting, and auth.","required":true,"acceptable_evidence":["Technical keywords: API Gateway, FastAPI, async/await, rate limiting, Uvicorn, horizontal scaling.","Explains routing client traffic through an API gateway with SSL termination, JWT authentication, and distributed rate limiting.","Utilizes asynchronous FastAPI services to handle high-concurrency requests and real-time streaming without thread exhaustion."]},{"id":"KP2","description":"Builds high-performance retrieval and knowledge indexing infrastructure (hybrid search, dense indexing, reranking).","required":true,"acceptable_evidence":["Technical keywords: Docling parser, Milvus HNSW indexing, BM25 semantic hybrid search, cross-encoder reranking, Neo4j.","Explains parsing multimodal enterprise documents with Docling into semantically coherent chunks.","Indexes embeddings in Milvus with HNSW, executes hybrid dense/sparse search, and reranks top results with cross-encoders."]},{"id":"KP3","description":"Orchestrates stateful agent workflows using LangGraph with tool nodes, cyclic reasoning, and HITL checkpointing.","required":true,"acceptable_evidence":["Technical keywords: LangGraph, state graphs, tool calling nodes, HITL checkpointing, cyclic reasoning loops.","Designs agent workflows as stateful graphs supporting autonomous tool execution, reflection, and error recovery.","Implements human-in-the-loop checkpointing allowing human operators to review and approve sensitive agent decisions."]},{"id":"KP4","description":"Implements a multi-tiered caching and persistence strategy across Redis, PostgreSQL, and DynamoDB.","required":true,"acceptable_evidence":["Technical keywords: Redis semantic cache, Redis session store (TTL=86400), PostgreSQL audit history, pgvector.","Details caching frequent LLM responses in Redis to slash latency and costs, backed by a 24-hour sliding session TTL.","Persists durable audit logs, conversation threads, and billing metrics in PostgreSQL with full ACID integrity."]},{"id":"KP5","description":"Enforces strict input/output guardrails, Pydantic schema validation, and security controls.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, NeMo Guardrails, PII redaction, prompt injection defense, JWT/OAuth2.","Validates all user inputs and agent outputs against strict Pydantic schemas to prevent malformed payloads.","Applies safety guardrails to detect prompt injections, redact PII, and prevent toxic or ungrounded model outputs."]},{"id":"KP6","description":"Establishes end-to-end observability, distributed tracing, and automated regression evaluation (LangSmith, RAGAS, Prometheus).","required":false,"acceptable_evidence":["Technical keywords: LangSmith tracing, RAGAS metrics (faithfulness, relevancy), Prometheus, Grafana, MLflow.","Instruments distributed trace spans across every tool call, retrieval query, and LLM generation in LangSmith.","Integrates automated RAGAS evaluation into CI/CD pipelines and monitors latency and token metrics in Prometheus/Grafana."]}],"critical_failures":["Omits caching, rate limiting, and cost controls, leaving the system vulnerable to runaway API costs and service outages.","Treats LLM outputs as unmonitored black boxes without distributed tracing, schema validation, or automated evaluation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you balance engineering complexity, model performance, and user experience when building end-to-end ML systems for real-world applications?', '{"key_points":[{"id":"KP1","description":"Model latency vs accuracy trade-offs and selecting appropriate model tiers.","required":true,"acceptable_evidence":["Technical keywords: p95 latency, SLA, ONNX Runtime, quantization, XGBoost baseline vs LLM.","Explains benchmarking simple models (e.g. XGBoost, distilled transformers) against complex deep learning/LLM models to satisfy strict p95 inference latency SLAs.","Discusses evaluating model performance gains against computational cost and memory footprint."]},{"id":"KP2","description":"Perceived latency reduction using streaming and asynchronous response patterns.","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events (SSE), FastAPI async streaming, StreamingResponse, optimistic UI.","Explains using FastAPI async generators and SSE to stream tokens to frontend clients, reducing Time-To-First-Token (TTFT).","Describes decoupling heavy batch/offline tasks using Celery or background tasks while returning immediate acknowledgment."]},{"id":"KP3","description":"Semantic caching and precomputation to bypass repetitive model execution.","required":true,"acceptable_evidence":["Technical keywords: Redis, semantic caching, Milvus similarity search, TTL, feature store.","Explains caching frequent queries or embedding lookups in Redis with TTLs or using Milvus vector similarity thresholds.","Discusses precomputing static batch inferences and storing them in Redis or a feature store to optimize user response times."]},{"id":"KP4","description":"Graceful degradation, fallback heuristics, and production observability.","required":true,"acceptable_evidence":["Technical keywords: circuit breaker, fallback heuristic, Prometheus, Grafana, Evidently drift detection.","Explains implementing circuit breakers that route traffic to rule-based or lighter cached models if the primary model errors or exceeds latency budgets.","Describes monitoring operational latency and data drift with Prometheus, Grafana, and Evidently to trigger alerts."]}],"critical_failures":["Prioritizes marginal model accuracy improvements without considering p95/p99 inference latency or user SLA constraints.","Suggests synchronous blocking calls to large models in frontend-facing endpoints without streaming or background task processing.","Omits caching or fallback mechanisms when inference engines experience degraded performance or rate limits."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you design and implement REST APIs using FastAPI, including authentication mechanisms such as JWT and OAuth?', '{"key_points":[{"id":"KP1","description":"Modular routing and declarative data validation using APIRouter and Pydantic.","required":true,"acceptable_evidence":["Technical keywords: APIRouter, Pydantic BaseModel, Field, response_model, OpenAPI, HTTP status codes.","Explains structuring routes hierarchically using APIRouter with strict Pydantic schemas for request validation and response filtering.","Describes automatic OpenAPI documentation generation and explicit HTTP status codes (200, 201, 400, 401, 422)."]},{"id":"KP2","description":"OAuth2 password bearer flow and secure JWT token lifecycle.","required":true,"acceptable_evidence":["Technical keywords: OAuth2PasswordBearer, PyJWT, HS256/RS256, access token, refresh token, token expiry.","Explains using OAuth2PasswordBearer to extract Bearer tokens from the Authorization header and validating signatures using HS256/RS256.","Describes managing token expiration (exp claim) and issuing refresh tokens for extended user sessions."]},{"id":"KP3","description":"Dependency injection for user identification and role-based access control.","required":true,"acceptable_evidence":["Technical keywords: Depends, get_current_user, HTTPException, status.HTTP_401_UNAUTHORIZED, security scopes.","Explains defining reusable security dependencies using Depends(get_current_user) to decode claims and fetch user records.","Describes enforcing role-based permissions or scopes directly in dependency functions."]},{"id":"KP4","description":"Asynchronous concurrency and non-blocking I/O in route handlers.","required":true,"acceptable_evidence":["Technical keywords: async def, await, asyncio, httpx.AsyncClient, threadpool execution.","Explains using async def with await for I/O-bound operations (database queries, external API calls) to keep the event loop unblocked.","Contrasts async def with def (which FastAPI runs in an external threadpool) for CPU-bound tasks."]},{"id":"KP5","description":"Middleware, rate limiting, and production operational hardening.","required":true,"acceptable_evidence":["Technical keywords: CORSMiddleware, slowapi, Redis rate limiter, Uvicorn, health checks /healthz.","Explains attaching CORSMiddleware and rate limiting middleware (slowapi or Redis-backed sliding window) to prevent API abuse.","Describes running under Uvicorn with multiple workers behind an API gateway or reverse proxy."]}],"critical_failures":["Stores unhashed passwords or puts sensitive secrets in JWT payload without signature verification.","Uses blocking synchronous I/O operations directly inside async def endpoints, stalling FastAPI\'s event loop.","Omits Pydantic schema validation or relies on raw untyped dictionary parsing for incoming requests."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How do you design and implement a text-to-SQL system, including handling metadata, validation, and execution?', '{"key_points":[{"id":"KP1","description":"Dynamic schema introspection and metadata pruning for prompt injection.","required":true,"acceptable_evidence":["Technical keywords: information_schema, SQLAlchemy inspect, foreign keys, DDL, metadata filtering, Milvus.","Explains extracting table names, column types, and foreign key relationships using SQLAlchemy inspection or database catalogs.","Describes pruning irrelevant tables using vector similarity search in Milvus or keyword filtering to fit within LLM token limits."]},{"id":"KP2","description":"Few-shot contextual prompting and SQL generation.","required":true,"acceptable_evidence":["Technical keywords: few-shot examples, dialect specification, LangChain, LangGraph, prompt engineering.","Explains supplying schema DDL, dialect constraints (PostgreSQL/MySQL), and relevant few-shot natural-language-to-SQL pairs in the prompt.","Describes instructing the model to generate read-only SELECT queries with explicit LIMIT clauses."]},{"id":"KP3","description":"Syntax validation and Abstract Syntax Tree (AST) parsing.","required":true,"acceptable_evidence":["Technical keywords: sqlparse, SQLGlot, AST validation, read-only verification, statement blacklist.","Explains parsing the LLM-generated query into an AST using sqlparse or SQLGlot to verify syntactic correctness before execution.","Describes strictly enforcing that the query contains only SELECT statements and rejecting DROP, DELETE, INSERT, UPDATE, or ALTER commands."]},{"id":"KP4","description":"Secure execution sandbox and query guardrails.","required":true,"acceptable_evidence":["Technical keywords: read-only user, statement_timeout, EXPLAIN cost threshold, connection pool.","Explains executing queries under a dedicated database user with read-only privileges and strict statement timeouts (e.g. 5 seconds).","Describes running an EXPLAIN query first to verify plan cost does not exceed resource limits before actual execution."]},{"id":"KP5","description":"Self-correction loop and iterative error recovery.","required":true,"acceptable_evidence":["Technical keywords: LangGraph reflection, retry loop, error traceback feedback, SQL execution error.","Explains capturing database runtime error messages and feeding the SQL string and error traceback back to the LLM in a LangGraph loop for auto-correction.","Describes limiting retries to 2-3 iterations to avoid infinite execution cycles."]}],"critical_failures":["Executes generated raw SQL queries against production databases with write permissions or without read-only restrictions.","Directly concatenates LLM output into database drivers without AST parsing, validation, or statement timeouts.","Injects full monolithic database schemas into prompts without column/table filtering, exceeding token limits."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you design and validate unit tests for backend services, and what scenarios do you typically cover?', '{"key_points":[{"id":"KP1","description":"Test framework architecture, fixtures, and asynchronous runner setup.","required":true,"acceptable_evidence":["Technical keywords: pytest, pytest-asyncio, TestClient, conftest.py, fixture scoping, coverage.py.","Explains configuring pytest with conftest.py fixtures for dependency injection and FastAPI TestClient instantiation.","Describes managing fixture scopes (function, module, session) and using pytest-asyncio for testing async endpoints."]},{"id":"KP2","description":"Database isolation and state reset strategies.","required":true,"acceptable_evidence":["Technical keywords: SQLite in-memory, PostgreSQL test container, testcontainers, transaction rollback, Alembic.","Explains isolating test databases using transactional rollbacks after each test or spinning up lightweight test containers.","Describes applying Alembic migrations to test schemas to ensure schema parity with production."]},{"id":"KP3","description":"Mocking external service dependencies and network I/O.","required":true,"acceptable_evidence":["Technical keywords: unittest.mock.patch, AsyncMock, MagicMock, respx, mocking Redis / Milvus.","Explains mocking third-party REST APIs using respx or patch to prevent network calls during test execution.","Describes mocking Redis caches, Milvus vector databases, or LLM providers using AsyncMock."]},{"id":"KP4","description":"Comprehensive test scenario taxonomy across happy paths and error states.","required":true,"acceptable_evidence":["Technical keywords: @pytest.mark.parametrize, HTTP 422, HTTP 401/403, HTTP 404, boundary testing.","Explains covering happy path success (200/201), client validation errors (422), resource not found (404), and unauthorized access (401).","Describes using @pytest.mark.parametrize to test boundary conditions, malformed payloads, and edge cases."]},{"id":"KP5","description":"CI/CD integration, coverage enforcement, and automated quality gates.","required":true,"acceptable_evidence":["Technical keywords: GitHub Actions, pre-commit, coverage threshold (e.g. 80%), ruff linting.","Explains integrating pytest runs into GitHub Actions CI pipelines with minimum code coverage thresholds.","Describes running linters and formatters alongside unit tests as mandatory pull request approval criteria."]}],"critical_failures":["Relies on live third-party APIs or live production databases during unit test runs rather than mocks or isolated test fixtures.","Asserts only on HTTP 200 status codes without verifying response body schemas, error states, or database persistence.","Fails to use AsyncMock or pytest-asyncio when testing asynchronous FastAPI routes and coroutines."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you design scalable, distributed systems for handling large volumes of structured and unstructured data?', '{"key_points":[{"id":"KP1","description":"Polyglot storage architecture for structured, unstructured, and vector data.","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, Milvus, AWS S3, MinIO, Parquet, HNSW indexing.","Explains separating storage layers: relational databases (PostgreSQL) for transactional metadata, object storage (S3) for raw files/blobs, and vector databases (Milvus) for embeddings.","Describes columnar formats like Parquet/Delta Lake for analytical query efficiency."]},{"id":"KP2","description":"Asynchronous ingestion and distributed event streaming.","required":true,"acceptable_evidence":["Technical keywords: Apache Kafka, AWS SQS, Celery, distributed queues, backpressure.","Explains decoupling ingestion from processing using Kafka or SQS to handle traffic spikes and buffer high-volume workloads.","Describes worker pools consuming messages asynchronously with backpressure management."]},{"id":"KP3","description":"Distributed compute engine optimization and data partitioning.","required":true,"acceptable_evidence":["Technical keywords: PySpark, Adaptive Query Execution (AQE), broadcast joins, partition pruning.","Explains leveraging PySpark for batch and streaming transformations with AQE enabled to dynamically adjust shuffle partitions.","Describes broadcast joins for small dimension tables and salting techniques to alleviate data skew."]},{"id":"KP4","description":"Horizontal scaling, caching, and resilient fault tolerance.","required":true,"acceptable_evidence":["Technical keywords: Kubernetes EKS, HPA, Redis caching, read replicas, circuit breaker.","Explains autoscaling stateless worker nodes via Kubernetes Horizontal Pod Autoscaler (HPA).","Describes using read replicas in PostgreSQL, Redis caching for hot entities, and circuit breakers to isolate component failures."]}],"critical_failures":["Stores unstructured high-dimensional embeddings or large blobs directly in relational database tables without dedicated vector/object stores.","Processes high-volume data streams through synchronous REST calls without decoupling via message queues or distributed compute.","Ignores data skew and partitioning keys in distributed data processing engines like Spark."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure data consistency and synchronization in distributed systems with separate read and write databases?', '{"key_points":[{"id":"KP1","description":"Command Query Responsibility Segregation (CQRS) and dual-datastore design.","required":true,"acceptable_evidence":["Technical keywords: CQRS, write primary PostgreSQL, read replica, Elasticsearch / Redis read store.","Explains separating write operations (optimized for relational integrity on primary PostgreSQL) from read queries (optimized for low-latency queries on Redis/Elasticsearch/read replicas).","Describes acknowledging eventual consistency trade-offs between write and read datastores."]},{"id":"KP2","description":"Change Data Capture (CDC) and event-driven data synchronization.","required":true,"acceptable_evidence":["Technical keywords: Debezium, Apache Kafka, Write-Ahead Log (WAL), transactional outbox pattern.","Explains streaming database updates from the PostgreSQL WAL using Debezium and Kafka to synchronize read models asynchronously.","Describes using the transactional outbox pattern to guarantee that business state updates and event publishing happen atomically."]},{"id":"KP3","description":"Cache invalidation and handling replication lag for read-your-own-writes consistency.","required":true,"acceptable_evidence":["Technical keywords: Redis cache eviction, TTL, read-your-own-writes, version tracking, monotonic reads.","Explains invalidating or updating Redis cache entries upon primary database writes.","Describes routing immediate post-write queries to the write primary or using version timestamps to prevent users from reading stale data."]},{"id":"KP4","description":"Idempotent consumer processing and conflict reconciliation.","required":true,"acceptable_evidence":["Technical keywords: idempotency key, message deduplication, dead-letter queue, 2PC vs eventual consistency.","Explains using idempotency keys and deduplication stores to prevent double-processing during event replays.","Discusses why two-phase commit (2PC) hurts availability in distributed systems and favors eventual consistency with automated reconciliation."]}],"critical_failures":["Assumes immediate strict ACID consistency across distributed read and write databases without accounting for replication lag.","Updates read replicas or search indexes via non-transactional dual-writes in application code without CDC or outbox pattern.","Fails to implement idempotency keys, leading to duplicate writes or corrupted state during message re-delivery."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle user authentication and identification in your FastAPI backend?', '{"key_points":[{"id":"KP1","description":"OAuth2 password bearer and JSON Web Token (JWT) architecture.","required":true,"acceptable_evidence":["Technical keywords: OAuth2PasswordBearer, PyJWT, HS256/RS256, access token, sub claim, exp claim.","Explains configuring OAuth2PasswordBearer(tokenUrl=\'token\') to extract Bearer tokens from the HTTP Authorization header.","Describes encoding and decoding JWT claims containing user identification (`sub` claim) with explicit expiration (`exp`)."]},{"id":"KP2","description":"Dependency injection for current user extraction and token verification.","required":true,"acceptable_evidence":["Technical keywords: Depends, get_current_user, HTTPException, status.HTTP_401_UNAUTHORIZED.","Explains creating a reusable `get_current_user` dependency that decodes the JWT, validates signature and expiration, and raises 401 on failure.","Describes querying the PostgreSQL database or Redis session store using the extracted user ID to populate the current user object."]},{"id":"KP3","description":"Role-based access control (RBAC) and permission enforcement.","required":true,"acceptable_evidence":["Technical keywords: RBAC, SecurityScopes, User Pydantic model, role validation, HTTP 403 Forbidden.","Explains attaching role verification (e.g. admin vs standard user) into FastAPI dependencies or decorators.","Describes returning HTTP 403 Forbidden when an identified user lacks required operational permissions."]},{"id":"KP4","description":"Token revocation, refresh tokens, and secure credential handling.","required":true,"acceptable_evidence":["Technical keywords: Redis token blacklist, refresh token rotation, passlib bcrypt, secret key env vars.","Explains hashing passwords using bcrypt (passlib) before persistence and loading JWT secret keys strictly from environment variables.","Describes storing revoked tokens or session blacklists in Redis with TTL matching token expiration."]}],"critical_failures":["Performs user authentication by passing plain credentials or user IDs directly in URL query parameters.","Validates JWT tokens without verifying the digital signature, secret key, or expiration timestamp.","Hardcodes JWT signing secrets in source code instead of loading from secure environment variables."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you implement authentication and caching in your backend services?', '{"key_points":[{"id":"KP1","description":"Stateless token-based authentication and request authorization.","required":true,"acceptable_evidence":["Technical keywords: JWT, OAuth2PasswordBearer, PyJWT, FastAPI Depends, Bearer token.","Explains using JWTs with RS256/HS256 for stateless authentication, validated at the API Gateway or FastAPI route dependencies.","Describes extracting user identity and permissions from token claims without querying the primary database on every request."]},{"id":"KP2","description":"Distributed caching architecture using Redis and cache-aside pattern.","required":true,"acceptable_evidence":["Technical keywords: Redis, cache-aside, TTL, key namespacing, orjson / json serialization.","Explains implementing the cache-aside pattern where the service checks Redis first and falls back to PostgreSQL on cache miss.","Describes setting strict TTLs (Time-To-Live) and structured key namespaces (e.g., `user:profile:{user_id}`)."]},{"id":"KP3","description":"Cache invalidation strategies and stampede prevention.","required":true,"acceptable_evidence":["Technical keywords: cache eviction, write-through, mutex lock, cache stampede, dogpiling.","Explains evicting or updating specific Redis keys immediately upon state-changing mutations (POST/PUT/DELETE).","Describes mitigating cache stampedes using distributed locks or probabilistic early expiration."]},{"id":"KP4","description":"Security considerations for cached authenticated responses and token blacklists.","required":true,"acceptable_evidence":["Technical keywords: Redis token revocation, PII protection, Redis TLS, authentication token blacklist.","Explains using Redis to store revoked JWT IDs (jti) for instant logout and token revocation.","Describes avoiding caching unencrypted PII or sensitive session tokens in shared cache layers without TLS and ACL controls."]}],"critical_failures":["Caches sensitive unencrypted tokens or unmasked PII data in public or unauthenticated cache instances.","Implements caching without TTLs or invalidation strategies, causing stale data to persist indefinitely across updates.","Confuses client-side HTTP caching (Cache-Control headers) with server-side distributed caching (Redis)."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How do you implement robust error handling in Python when making API calls within a loop?', '{"key_points":[{"id":"KP1","description":"Granular exception hierarchy handling and status code inspection.","required":true,"acceptable_evidence":["Technical keywords: httpx.HTTPStatusError, httpx.RequestError, requests.exceptions, try/except, status code discrimination.","Explains catching specific network exceptions (connection errors, timeouts) separately from HTTP status errors.","Describes discriminating between recoverable server errors (5xx, 429) and non-recoverable client errors (400, 401, 404)."]},{"id":"KP2","description":"Exponential backoff with jitter and automated retry mechanisms.","required":true,"acceptable_evidence":["Technical keywords: tenacity, exponential backoff, jitter, max_retries, urllib3 Retry.","Explains using libraries like `tenacity` or custom retry loops with exponential backoff and randomized jitter to prevent thundering herd.","Describes respecting the `Retry-After` HTTP header when receiving 429 Too Many Requests."]},{"id":"KP3","description":"Rate limiting, throttling, and concurrency bounds.","required":true,"acceptable_evidence":["Technical keywords: asyncio.Semaphore, aiolimiter, token bucket, time.sleep.","Explains constraining loop request rates using asyncio.Semaphore or aiolimiter to adhere to provider rate limits.","Describes structuring loops to avoid burst exhaustion of API quotas."]},{"id":"KP4","description":"Partial failure containment, dead-letter collection, and structured logging.","required":true,"acceptable_evidence":["Technical keywords: dead-letter list, structlog, continue on error, partial success aggregation.","Explains isolating loop iterations with try/except so that a single failed record does not crash the entire loop.","Describes appending failed items to a dead-letter queue or list with error metadata for post-run analysis."]}],"critical_failures":["Uses a bare `except:` or `except Exception:` that catches system signals (KeyboardInterrupt/SystemExit) and suppresses all error context.","Retries indefinitely on permanent 4xx client errors (such as 400 Bad Request or 401 Unauthorized) instead of failing fast.","Crashes the entire loop on a single failed record without recording partial successes or collecting failed items."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you monitor model performance in production, and what tools and metrics do you rely on?', '{"key_points":[{"id":"KP1","description":"System and infrastructure operational metrics.","required":true,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, p95/p99 latency, RPS throughput, GPU/CPU utilization, error rates.","Explains instrumenting inference servers with Prometheus exporters to track request latency percentiles (p50, p95, p99), error rates, and hardware utilization.","Describes visualizing operational health and SLAs on Grafana dashboards."]},{"id":"KP2","description":"Data drift and concept drift detection.","required":true,"acceptable_evidence":["Technical keywords: Evidently AI, Kolmogorov-Smirnov test, Population Stability Index (PSI), Wasserstein distance, feature drift.","Explains comparing production input feature distributions against baseline training distributions using Evidently AI.","Describes using statistical tests (KS-test for continuous features, PSI for categorical distributions) to flag significant shifts."]},{"id":"KP3","description":"Task-specific ML evaluation metrics and delayed ground-truth feedback.","required":true,"acceptable_evidence":["Technical keywords: MLflow, AUC-ROC, PR-AUC, F1-score, delayed ground truth, feedback loop.","Explains tracking actual classification performance (AUC-ROC, precision-recall) once delayed ground truth labels arrive.","Describes logging evaluation metrics to MLflow model registry for performance comparison across model versions."]},{"id":"KP4","description":"LLM application observability and RAG-specific evaluation.","required":true,"acceptable_evidence":["Technical keywords: LangSmith, OpenTelemetry, RAGAS metrics, faithfulness, context_precision, answer_relevancy.","Explains tracing full LLM call chains and token usage with LangSmith or OpenTelemetry.","Describes computing automated RAGAS metrics to measure hallucination rates (faithfulness) and retrieval relevance."]},{"id":"KP5","description":"Automated alerting, incident response, and continuous retraining triggers.","required":true,"acceptable_evidence":["Technical keywords: Alertmanager, PagerDuty, fallback heuristic, DVC, automated retraining pipeline.","Explains configuring Prometheus Alertmanager and PagerDuty to notify on drift or latency anomalies.","Describes triggering automated DVC/Airflow retraining pipelines or falling back to safe heuristic rules when metrics breach acceptable thresholds."]}],"critical_failures":["Tracks only infrastructure metrics (CPU/RAM) while completely ignoring model data drift and output quality degradation.","Assumes ground truth labels are instantaneously available in real-time production without designing delayed feedback mechanisms.","Fails to set alert thresholds for prediction distribution shifts, allowing silent model degradation to persist unnoticed."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you perform external API calls in React, and how do you handle errors during these requests?', '{"key_points":[{"id":"KP1","description":"Lifecycle data fetching and request cancellation using AbortController.","required":true,"acceptable_evidence":["Technical keywords: useEffect, fetch / axios, AbortController, cleanup function, race conditions.","Explains invoking asynchronous API requests inside useEffect and returning an AbortController abort cleanup to cancel in-flight requests on component unmount.","Describes preventing race conditions when query dependencies change rapidly."]},{"id":"KP2","description":"State management for loading, error, and response payloads.","required":true,"acceptable_evidence":["Technical keywords: useState, isLoading, isError, data, error state, RTK Query.","Explains tracking discrete states for loading spinners, error messages, and fetched data using useState or RTK Query hooks (useQuery).","Describes resetting error states prior to dispatching new network requests."]},{"id":"KP3","description":"Granular HTTP response handling and status code parsing.","required":true,"acceptable_evidence":["Technical keywords: response.ok, HTTP 4xx/5xx, try/catch, toast notification, user-friendly error message.","Explains checking `response.ok` when using standard `fetch()` because non-2xx responses do not automatically reject the promise.","Describes parsing JSON error responses from backend endpoints and displaying user-friendly toast or banner notifications."]},{"id":"KP4","description":"React Error Boundaries and user-driven retry mechanisms.","required":true,"acceptable_evidence":["Technical keywords: ErrorBoundary, componentDidCatch, fallback UI, refetch handler.","Explains wrapping component trees in Error Boundaries to catch unhandled rendering exceptions caused by malformed API data.","Describes providing an interactive \'Retry\' button that re-triggers the data fetching function."]}],"critical_failures":["Forgets cleanup with AbortController in useEffect, leading to memory leaks and state updates on unmounted components.","Assumes fetch() rejects promises on 4xx/5xx HTTP status codes without inspecting `response.ok`.","Hardcodes API endpoints in component render logic instead of using centralized API client modules or environment variables."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you transition from experimentation to pilot and then to production while ensuring scalability and reliability?', '{"key_points":[{"id":"KP1","description":"Experimentation governance, artifact versioning, and offline benchmarking.","required":true,"acceptable_evidence":["Technical keywords: MLflow experiment tracking, DVC data versioning, RAGAS offline evaluation, baseline benchmarks.","Explains tracking hyperparameters, model artifacts, and evaluation metrics in MLflow while versioning dataset snapshots with DVC.","Describes establishing deterministic offline benchmark datasets to quantify quality before promoting models."]},{"id":"KP2","description":"Pilot deployment strategies using shadow traffic and canary releases.","required":true,"acceptable_evidence":["Technical keywords: shadow deployment, canary release, feature flags, A/B testing, user feedback loop.","Explains running shadow deployments where live requests are mirrored to the new model without serving responses to users, validating latency and accuracy.","Describes rolling out canary traffic (e.g. 5% to 100%) guarded by automated error rate gates."]},{"id":"KP3","description":"Containerization, infrastructure orchestration, and autoscaling.","required":true,"acceptable_evidence":["Technical keywords: Docker, Kubernetes EKS, HPA, FastAPI async workers, resource limits.","Explains packaging model inference into optimized Docker containers deployed on EKS with Horizontal Pod Autoscaler (HPA) driven by queue depth or CPU/GPU utilization.","Describes configuring memory requests/limits to avoid out-of-memory (OOM) evictions."]},{"id":"KP4","description":"Reliability guardrails, circuit breakers, and human-in-the-loop escalation.","required":true,"acceptable_evidence":["Technical keywords: circuit breaker, fallback model, rate limiting, LangGraph HITL checkpointing, guardrails.","Explains implementing circuit breakers that divert traffic to cached responses or rule-based heuristics if the inference engine degrades.","Describes routing low-confidence predictions to human-in-the-loop (HITL) review."]},{"id":"KP5","description":"Continuous production observability, drift monitoring, and automated alerts.","required":true,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, Evidently AI, LangSmith tracing, PagerDuty alerting.","Explains tracking production latency percentiles, error rates, and feature drift with Prometheus, Grafana, and Evidently.","Describes using LangSmith to trace multi-step LLM chains and alert on anomalous latency or hallucination spikes."]}],"critical_failures":["Deploys models directly from Jupyter notebooks to production without modular refactoring, containerization, or API contracts.","Skips shadow or canary evaluation, exposing all production traffic to an unvetted model immediately.","Omits automated monitoring and fallback plans, leaving no remediation if the pilot model crashes or hallucinates."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you address scalability challenges when data volume and variety increase significantly in production systems?', '{"key_points":[{"id":"KP1","description":"Distributed compute scaling and shuffle optimization with Spark.","required":true,"acceptable_evidence":["Technical keywords: PySpark, Adaptive Query Execution (AQE), dynamic partition pruning, broadcast joins, salting.","Explains leveraging PySpark with AQE enabled to automatically coalesce shuffle partitions and optimize skew joins.","Describes mitigating severe data skew using key salting to distribute load evenly across worker executors."]},{"id":"KP2","description":"Polyglot storage tiering for diverse data structures.","required":true,"acceptable_evidence":["Technical keywords: Delta Lake, Parquet, PostgreSQL, Milvus, S3 hot/warm/cold tiers.","Explains storing massive unstructured and semi-structured datasets in Parquet/Delta Lake on S3, transactional entities in PostgreSQL, and vector embeddings in Milvus.","Describes lifecycle tiering to archive older partitions to cost-effective cold storage."]},{"id":"KP3","description":"Flexible schema evolution and polymorphic data validation.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, Avro / Protobuf schema registry, PostgreSQL JSONB, GIN indexing.","Explains using Pydantic models and schema registries to validate incoming data structures while allowing controlled backward-compatible evolution.","Describes utilizing PostgreSQL JSONB with GIN indexing for polymorphic attribute storage without brittle schema migrations."]},{"id":"KP4","description":"Asynchronous streaming ingestion and backpressure management.","required":true,"acceptable_evidence":["Technical keywords: Apache Kafka, AWS SQS, backpressure, consumer autoscaling, dead-letter queue.","Explains buffering high-volume ingress using Kafka or SQS to absorb ingestion spikes and prevent service crashes.","Describes autoscaling consumer workers based on queue lag and routing corrupt records to dead-letter queues."]}],"critical_failures":["Relies on monolithic vertical scaling of single-instance relational databases to handle massive vector and document growth.","Uses unpartitioned row-oriented storage (e.g. raw JSON files or unindexed tables) for high-volume analytical workloads.","Ignores data skew, leading to executor out-of-memory (OOM) failures in distributed processing jobs."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you approach building scalable AI solutions for workflows such as contract lifecycle management or procurement processes?', '{"key_points":[{"id":"KP1","description":"Document parsing, OCR, and layout-aware structural chunking.","required":true,"acceptable_evidence":["Technical keywords: Docling, OCR, layout-aware PDF parsing, table extraction, header-based chunking.","Explains parsing complex scanned PDF contracts and procurement RFP documents using Docling to preserve table structures and section hierarchies.","Describes chunking text along legal clause and section boundaries rather than arbitrary token lengths."]},{"id":"KP2","description":"Hybrid retrieval and cross-encoder reranking for legal clauses.","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW indexing, BGE/MiniLM embeddings, BM25 keyword search, reciprocal rank fusion (RRF), cross-encoder reranker.","Explains combining dense semantic search in Milvus with sparse BM25 search to accurately locate exact clause identifiers, dates, and indemnification terminology.","Describes re-scoring top candidate clauses using a cross-encoder reranker before feeding them into the LLM context."]},{"id":"KP3","description":"Structured extraction, compliance verification, and Pydantic validation.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, instructor, entity extraction, compliance validation, confidence scoring.","Explains enforcing strictly typed Pydantic models for extracted fields (effective dates, termination clauses, liability caps).","Describes validating extracted values against standard procurement policy guidelines with confidence scoring."]},{"id":"KP4","description":"Human-in-the-loop (HITL) checkpoints, audit trails, and state persistence.","required":true,"acceptable_evidence":["Technical keywords: LangGraph HITL checkpointing, PostgreSQL state persistence, audit trail, review escalation.","Explains configuring LangGraph state machines that interrupt execution and require human legal approval when extraction confidence falls below a set threshold.","Describes logging every extraction decision, prompt, and human amendment in PostgreSQL for compliance auditing."]}],"critical_failures":["Sends raw scanned contract PDFs directly into LLM prompts without layout-aware parsing or chunking, exceeding token limits.","Executes automated legal approvals or contract modifications without confidence thresholds or human-in-the-loop validation.","Relies exclusively on naive semantic search without BM25 keyword matching for exact legal clauses, numbers, and dates."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you approach migrating a proof-of-concept AI system into a production-ready architecture with different backend and frontend technologies?', '{"key_points":[{"id":"KP1","description":"Decoupling monolithic prototype scripts into formal API contracts.","required":true,"acceptable_evidence":["Technical keywords: FastAPI APIRouter, OpenAPI specification, Pydantic schemas, contract-first design.","Explains extracting core inference logic from Streamlit/Jupyter prototypes into modular FastAPI services defined by Pydantic request/response schemas.","Describes publishing OpenAPI specifications to establish clean boundaries between backend engineers and frontend teams."]},{"id":"KP2","description":"Asynchronous response streaming and frontend state integration.","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events (SSE), FastAPI async streaming, React, RTK Query, optimistic UI.","Explains replacing synchronous blocking HTTP calls with SSE streaming endpoints in FastAPI, consumed by React frontend components.","Describes managing asynchronous data streams and loading states using RTK Query or custom hooks."]},{"id":"KP3","description":"Containerized model serving, orchestration, and worker queues.","required":true,"acceptable_evidence":["Technical keywords: Docker, Triton / vLLM, Kubernetes EKS, Celery, Redis task queue.","Explains packaging inference workloads in GPU-optimized Docker containers managed on EKS or dedicated serving engines like vLLM/Triton.","Describes offloading heavy document processing tasks to asynchronous Celery workers backed by Redis."]},{"id":"KP4","description":"Security, observability, and CI/CD automation.","required":true,"acceptable_evidence":["Technical keywords: JWT OAuth2, LangSmith tracing, Prometheus metrics, GitHub Actions CI/CD.","Explains replacing prototype hardcoded keys with JWT-based OAuth2 authentication and environment secrets.","Describes adding LangSmith and Prometheus instrumentation, and establishing automated test and deployment pipelines via GitHub Actions."]}],"critical_failures":["Directly ports prototype scripts (e.g., Streamlit / Gradio / raw notebook) into production without decoupling API contracts and state.","Uses synchronous blocking requests from frontend to LLM endpoints without streaming or background task polling.","Hardcodes credentials, model weights, and configurations directly inside frontend or backend source code."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you collaborate with another founding engineer to define core system architecture and divide responsibilities effectively?', '{"key_points":[{"id":"KP1","description":"Interface contract definition and architectural boundary separation.","required":true,"acceptable_evidence":["Technical keywords: API contract-first design, OpenAPI/Swagger, Pydantic DTO models, modular monolith.","Explains agreeing on interface boundaries and data contracts (OpenAPI/Pydantic schemas) upfront before writing backend and frontend implementations.","Describes starting with a well-structured modular monolith rather than prematurely distributed microservices."]},{"id":"KP2","description":"Clear domain ownership and vertical slice decomposition.","required":true,"acceptable_evidence":["Technical keywords: domain ownership, frontend/backend separation, data/ML vs platform infrastructure, end-to-end vertical slicing.","Explains dividing responsibilities by vertical functional domains (e.g., core API/data pipelines vs frontend UX/client integrations) to minimize merge friction.","Describes ensuring each engineer owns end-to-end delivery of their designated subsystems."]},{"id":"KP3","description":"Architecture Decision Records (ADRs) and structured technical debates.","required":true,"acceptable_evidence":["Technical keywords: Architecture Decision Records (ADRs), RFC process, trade-off analysis, technical debt tracking.","Explains documenting major architectural choices, evaluated alternatives, and trade-offs using lightweight ADRs in the repository.","Describes using ADRs to maintain technical alignment and prevent recurring debates on past decisions."]},{"id":"KP4","description":"Shared engineering standards and automated continuous integration.","required":true,"acceptable_evidence":["Technical keywords: pre-commit hooks, ruff, pytest, GitHub Actions, branch protection.","Explains standardizing code quality with pre-commit hooks, ruff linting, and mandatory pytest suites in GitHub Actions.","Describes enforcing small, frequent pull requests and pair-reviewing critical architectural components."]}],"critical_failures":["Begins coding without agreed-upon API specifications or data contracts, resulting in integration mismatches.","Operates in silos without shared Architectural Decision Records (ADRs) or technical reviews, leading to conflicting architecture choices.","Lacks automated testing and CI/CD gates, causing merge conflicts and broken shared environments."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a Python solution to process data from an Excel file and enrich it using external API calls?', '{"key_points":[{"id":"KP1","description":"Memory-efficient Excel parsing and row batching.","required":true,"acceptable_evidence":["Technical keywords: pandas read_excel, openpyxl, chunksize, generator, memory efficiency.","Explains using pandas or openpyxl read-only mode to iterate over Excel rows in chunks/generators to prevent high memory consumption.","Describes extracting and validating required columns prior to initiating enrichment calls."]},{"id":"KP2","description":"Asynchronous concurrent API enrichment with rate limiting.","required":true,"acceptable_evidence":["Technical keywords: httpx.AsyncClient, asyncio.gather, asyncio.Semaphore, aiolimiter, concurrency control.","Explains making non-blocking HTTP requests using httpx.AsyncClient and asyncio.gather to enrich rows concurrently.","Describes throttling concurrency with asyncio.Semaphore or aiolimiter to adhere to external API rate limits."]},{"id":"KP3","description":"Resilient error handling, retries, and dead-letter tracking.","required":true,"acceptable_evidence":["Technical keywords: tenacity, exponential backoff, status 429 Retry-After, dead-letter list, structlog.","Explains wrapping API calls in tenacity retry logic with exponential backoff for transient 5xx/429 errors.","Describes recording failed rows into a dead-letter log or CSV without crashing the remaining pipeline."]},{"id":"KP4","description":"Data validation, checkpointing, and formatted output writing.","required":true,"acceptable_evidence":["Technical keywords: Pydantic validation, incremental checkpointing, openpyxl writer, Parquet/Excel export.","Explains validating enriched responses against Pydantic models before updating records.","Describes saving periodic checkpoint files so processing can resume from the last successful row after unexpected interruptions."]}],"critical_failures":["Makes sequential, blocking synchronous HTTP calls inside a loop over thousands of rows, causing unacceptable execution times.","Crashes the entire batch pipeline on a single malformed row or failed API call without partial saving or error recording.","Loads massive multi-gigabyte Excel files entirely into memory without chunking or memory profiling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a common schema and response normalization layer to standardize heterogeneous API responses?', '{"key_points":[{"id":"KP1","description":"Canonical schema definition using Pydantic.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModel, Field, canonical schema, type validation, root_validator.","Explains defining a single unified canonical Pydantic model with strict field types, descriptions, and standard naming conventions.","Describes using Pydantic field validators to enforce consistent data types across heterogeneous sources."]},{"id":"KP2","description":"Adapter/Transformer pattern for provider-specific normalization.","required":true,"acceptable_evidence":["Technical keywords: Adapter pattern, transformer function, mapping dictionary, factory pattern.","Explains implementing distinct adapter functions or classes for each external API that map vendor-specific fields to canonical schema attributes.","Describes using a factory pattern to dispatch responses to the appropriate adapter based on source identifiers."]},{"id":"KP3","description":"Handling missing attributes, optional defaults, and metadata preservation.","required":true,"acceptable_evidence":["Technical keywords: Optional types, default values, raw metadata dict, extra=\'ignore\', schema evolution.","Explains handling nullable or absent provider fields using Optional types and sensible defaults.","Describes preserving the unmapped raw payload in a `raw_metadata` dictionary field for debugging and backward compatibility."]},{"id":"KP4","description":"High-performance serialization and transformation error auditing.","required":true,"acceptable_evidence":["Technical keywords: orjson, structlog, transformation error logging, dead-letter quarantine.","Explains using high-performance JSON libraries like orjson to optimize serialization speed.","Describes logging mapping failures with structured logs (structlog) and isolating non-conforming responses into a quarantine queue."]}],"critical_failures":["Performs ad-hoc manual dictionary key lookups with nested `.get()` calls scattered throughout application logic instead of centralized adapters.","Fails to validate normalized data types, allowing downstream consumers to crash on null or unexpected types.","Discards unmapped upstream fields completely without preserving raw responses or recording unmapped attributes."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a scalable and fault-tolerant message processing system using queues like SQS?', '{"key_points":[{"id":"KP1","description":"SQS queue configuration, message visibility, and long polling.","required":true,"acceptable_evidence":["Technical keywords: AWS SQS, VisibilityTimeout, Long Polling (WaitTimeSeconds), FIFO vs Standard queue.","Explains configuring appropriate VisibilityTimeout greater than expected worker processing time to prevent premature duplicate processing.","Describes enabling Long Polling (WaitTimeSeconds=20) to reduce empty receives and reduce AWS API costs."]},{"id":"KP2","description":"Worker pool scaling, concurrency, and backpressure management.","required":true,"acceptable_evidence":["Technical keywords: Kubernetes KEDA, Celery / asyncio consumers, ApproximateNumberOfMessages, backpressure.","Explains scaling consumer worker pods dynamically using KEDA based on queue depth metrics (ApproximateNumberOfMessagesVisible).","Describes controlling worker concurrency so downstream databases are not overwhelmed."]},{"id":"KP3","description":"Idempotent processing and deduplication strategies.","required":true,"acceptable_evidence":["Technical keywords: idempotency key, Redis deduplication cache, transactional outbox, message deduplication ID.","Explains generating deterministic idempotency keys per message and verifying them in Redis or a database unique index before execution.","Describes utilizing SQS FIFO MessageDeduplicationId where strict ordering and deduplication within a 5-minute window are required."]},{"id":"KP4","description":"Dead-Letter Queue (DLQ) configuration and poison pill isolation.","required":true,"acceptable_evidence":["Technical keywords: Dead-Letter Queue (DLQ), maxReceiveCount, redrive policy, CloudWatch alarm.","Explains attaching a redrive policy with a maxReceiveCount (e.g. 3-5) to automatically divert unprocessable messages to a DLQ.","Describes setting CloudWatch alarms on DLQ depth and building inspection/replay utilities."]}],"critical_failures":["Sets visibility timeout lower than actual worker processing time, causing redundant concurrent executions of the same message.","Omits idempotency handling, causing duplicate processing and database corruption when messages are re-delivered.","Lacks Dead-Letter Queues (DLQ), allowing poison pill messages to loop indefinitely and block queue consumption."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a scalable system for automating healthcare revenue cycle processes using generative AI?', '{"key_points":[{"id":"KP1","description":"HIPAA compliance, PHI de-identification, and clinical document ingestion.","required":true,"acceptable_evidence":["Technical keywords: HIPAA compliance, PHI redaction / de-identification, Docling / AWS Textract, SOC2.","Explains scrubbing Protected Health Information (PHI) before routing requests to generative models, adhering to HIPAA and BAA agreements.","Describes parsing complex multi-page medical claims, EHR records, and explanation of benefits (EOB) using layout-aware tools like Docling."]},{"id":"KP2","description":"Clinical coding extraction and hybrid policy retrieval.","required":true,"acceptable_evidence":["Technical keywords: ICD-10, CPT codes, Milvus hybrid search, BGE embeddings, BM25, payer billing rules.","Explains extracting and validating standardized medical billing codes (ICD-10-CM, CPT, HCPCS) using structured Pydantic schemas.","Describes querying insurance payer policy manuals using Milvus hybrid search (dense + BM25) to evaluate coverage criteria."]},{"id":"KP3","description":"Workflow orchestration and automated denial appeal generation.","required":true,"acceptable_evidence":["Technical keywords: LangGraph workflow, claim denial appeal, deterministic rules engine, prompt guardrails.","Explains using LangGraph to orchestrate multi-step claims analysis: reason code diagnosis, evidence gathering from clinical notes, and drafting appeal letters.","Describes enforcing deterministic rule-based checks before generating appeals to avoid invalid submissions."]},{"id":"KP4","description":"Human-in-the-loop (HITL) review, audit logging, and accuracy monitoring.","required":true,"acceptable_evidence":["Technical keywords: LangGraph HITL checkpointing, medical coder sign-off, audit trail, PostgreSQL, RAGAS faithfulness.","Explains halting autonomous submission and routing appeals to certified medical coders via LangGraph HITL checkpoints.","Describes maintaining immutable audit logs in PostgreSQL and monitoring generation faithfulness with RAGAS."]}],"critical_failures":["Sends unredacted Protected Health Information (PHI) to third-party public LLM endpoints without HIPAA Business Associate Agreements (BAA) or sanitization.","Directly submits generated clinical billing claims or appeal letters to payers without confidence validation or human review.","Omits deterministic rule checking for standard ICD-10/CPT coding rules, relying purely on stochastic generative model outputs."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a shared backend system for both mobile and web applications?', '{"key_points":[{"id":"KP1","description":"API Gateway and Backend-for-Frontend (BFF) architectural patterns.","required":true,"acceptable_evidence":["Technical keywords: Backend-for-Frontend (BFF), API Gateway, FastAPI APIRouter, route versioning (/v1/, /v2/).","Explains implementing an API Gateway or dedicated BFF layers to cater to disparate client form factors while sharing core business logic.","Describes strict route versioning (/v1/, /v2/) to support legacy mobile app versions alongside continuous web updates."]},{"id":"KP2","description":"Payload optimization, field filtering, and network efficiency.","required":true,"acceptable_evidence":["Technical keywords: pagination, field masking / sparse fieldsets, gzip/brotli compression, image CDN resizing.","Explains minimizing payload sizes for mobile devices on high-latency cellular networks via cursor-based pagination and field filtering.","Describes offloading static assets and resized responsive images to CDN edge caches."]},{"id":"KP3","description":"Unified authentication and multi-device session management.","required":true,"acceptable_evidence":["Technical keywords: JWT OAuth2, refresh token rotation, Firebase Cloud Messaging (FCM), Redis session tracking.","Explains using JWTs with refresh token rotation to maintain persistent mobile logins while securing web sessions.","Describes managing push notification tokens (FCM/APNs) and active multi-device sessions in Redis."]},{"id":"KP4","description":"Offline data synchronization and idempotent operations.","required":true,"acceptable_evidence":["Technical keywords: delta synchronization, timestamp / version vectors, idempotency keys, conflict resolution.","Explains designing delta sync endpoints that return only records updated since a given client timestamp.","Describes requiring idempotency keys on mutating endpoints to handle erratic mobile network retries safely."]}],"critical_failures":["Forces mobile clients to download huge, unpaginated payloads designed for desktop web clients, wasting bandwidth and battery.","Implements separate, duplicated business logic codebases for mobile and web backends rather than a shared service layer or BFF.","Omits API versioning (/v1/, /v2/), causing mobile apps that have not updated to break when backend schemas change."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a system to answer questions from both unstructured documents and structured databases?', '{"key_points":[{"id":"KP1","description":"Query intent classification and dynamic multi-pipeline routing.","required":true,"acceptable_evidence":["Technical keywords: LangGraph router, query classification, intent detection, Pydantic routing schema.","Explains using an LLM router or fast classifier to analyze the incoming query and determine whether it requires SQL, vector retrieval, or a hybrid combination.","Describes outputting structured route decisions using Pydantic schemas."]},{"id":"KP2","description":"Structured retrieval pipeline via Text-to-SQL.","required":true,"acceptable_evidence":["Technical keywords: schema introspection, few-shot SQL prompting, sqlparse AST validation, read-only PostgreSQL.","Explains injecting relevant table schemas and few-shot examples into the prompt to generate SQL queries.","Describes parsing SQL with sqlparse to enforce read-only execution against PostgreSQL primary/replicas with strict timeouts."]},{"id":"KP3","description":"Unstructured retrieval pipeline via hybrid RAG.","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW indexing, BGE/MiniLM embeddings, BM25 hybrid search, cross-encoder reranker, Docling.","Explains parsing and chunking unstructured documents with Docling and indexing into Milvus with HNSW.","Describes executing hybrid dense + BM25 keyword search followed by cross-encoder reranking to fetch relevant document contexts."]},{"id":"KP4","description":"Context fusion, answer synthesis, and provenance citation.","required":true,"acceptable_evidence":["Technical keywords: answer synthesis, citation attribution, faithfulness validation, RAGAS metrics.","Explains feeding both structured SQL query results and unstructured document chunks into a final synthesis prompt.","Describes attributing specific facts to source documents or database tables and evaluating answer faithfulness with RAGAS."]}],"critical_failures":["Attempts to vectorize relational database tables as unstructured text chunks instead of querying them with SQL.","Executes unvalidated LLM-generated SQL queries on production databases without read-only constraints or AST parsing.","Lacks a router or orchestrator, sending every query blindly to both pipelines without evaluating relevance or fusing responses."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How would you design and architect a scalable AI-driven operating system for home health, home care, and hospice agencies?', '{"key_points":[{"id":"KP1","description":"Multimodal ingestion and clinical encounter documentation.","required":true,"acceptable_evidence":["Technical keywords: speech-to-text, OASIS home health assessments, Docling clinical notes parsing, HIPAA PHI encryption.","Explains capturing audio encounter recordings and converting to text, extracting clinical OASIS and hospice assessment forms using layout-aware parsing.","Describes ensuring end-to-end encryption and HIPAA compliance for all transmitted and stored PHI."]},{"id":"KP2","description":"Agentic clinical documentation, ICD-10 coding, and visit note generation.","required":true,"acceptable_evidence":["Technical keywords: LangGraph agentic workflow, Pydantic clinical summary schema, ICD-10 medical coding, prompt guardrails.","Explains using LangGraph to orchestrate visit note generation from encounter transcripts into standardized SOAP format with ICD-10 coding.","Describes validating generated clinical summaries against strict Pydantic schemas before persistence."]},{"id":"KP3","description":"Geospatial caregiver scheduling and care plan matching.","required":true,"acceptable_evidence":["Technical keywords: PostGIS, geospatial routing, caregiver matching, linear programming / constraint solver, real-time dispatch.","Explains optimizing mobile caregiver travel schedules and route sequences using PostGIS and constraint solvers.","Describes matching caregiver certifications (RN, LPN, CNA) against patient acuity and payer authorized care plans."]},{"id":"KP4","description":"Offline-first mobile synchronization for field clinicians.","required":true,"acceptable_evidence":["Technical keywords: SQLite local mobile cache, delta sync, Redis Pub/Sub, optimistic updates, offline visit documentation.","Explains enabling field clinicians to document visits offline in SQLite and synchronizing via delta sync when cellular connection resumes.","Describes conflict resolution strategies using timestamp vectors or clinician-precedence rules."]},{"id":"KP5","description":"Human-in-the-loop (HITL) compliance, EHR integration, and audit logging.","required":true,"acceptable_evidence":["Technical keywords: HITL approval, FHIR / HL7 integration, HIPAA audit logging, Prometheus / Grafana.","Explains mandating clinician sign-off on AI-generated visit notes before transmitting to EHR systems (Epic, PointClickCare) via FHIR/HL7 APIs.","Describes maintaining immutable audit logs in PostgreSQL and monitoring system latency with Prometheus."]}],"critical_failures":["Automatically submits AI-generated clinical documentation to billing or EMR systems without nurse/clinician sign-off.","Ignores HIPAA regulations by transmitting unencrypted PHI across non-compliant endpoints or external models without BAAs.","Fails to support offline-first capabilities for field nurses and caregivers visiting areas without cellular connectivity."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design the system to be schema-agnostic and adaptable to changes in database structure?', '{"key_points":[{"id":"KP1","description":"Dynamic metadata introspection and catalog caching.","required":true,"acceptable_evidence":["Technical keywords: SQLAlchemy inspection, information_schema, Redis schema cache, TTL cache invalidation.","Explains querying database system catalogs (information_schema or SQLAlchemy Inspector) dynamically to discover current tables, columns, and foreign keys.","Describes caching schema metadata in Redis with a TTL or invalidating the cache upon DDL migration events to avoid repetitive introspection overhead."]},{"id":"KP2","description":"Semi-structured storage patterns and JSON document abstractions.","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL JSONB, GIN indexing, document store, flexible attribute mapping.","Explains storing variable or evolving domain attributes in PostgreSQL JSONB columns indexed with GIN to decouple code from schema changes.","Describes using key-value or document-oriented schemas for non-static attributes."]},{"id":"KP3","description":"Dynamic prompt injection and semantic column retrieval for LLM systems.","required":true,"acceptable_evidence":["Technical keywords: dynamic schema serialization, vector search over column metadata, Milvus, few-shot prompt updates.","Explains serializing current database schemas dynamically into prompts rather than hardcoding column names in templates.","Describes embedding column and table descriptions into Milvus to retrieve only schema subsets relevant to the user\'s natural language query."]},{"id":"KP4","description":"Schema evolution governance and automated contract testing.","required":true,"acceptable_evidence":["Technical keywords: Alembic migrations, Pydantic dynamic model generation, contract testing, backward compatibility.","Explains managing schema transitions with Alembic migrations and generating Pydantic validation models dynamically.","Describes running contract tests in CI pipelines to detect breaking schema changes before deploying service updates."]}],"critical_failures":["Hardcodes fixed table and column names in prompt templates or core application logic, breaking upon schema alterations.","Queries information_schema dynamically on every incoming request without caching, introducing severe database latency.","Omits validation or fallback mechanisms when unexpected columns or data types appear in query responses."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you implement a response builder that cleans, deduplicates, and aggregates results from multiple APIs?', '{"key_points":[{"id":"KP1","description":"Asynchronous concurrent API dispatch and timeout management.","required":true,"acceptable_evidence":["Technical keywords: asyncio.gather, httpx.AsyncClient, asyncio.wait_for, partial failure handling.","Explains invoking external upstream APIs concurrently using httpx.AsyncClient with asyncio.gather(return_exceptions=True).","Describes setting strict timeouts per endpoint and gracefully proceeding with partial results if one API times out."]},{"id":"KP2","description":"Data cleaning, field normalization, and Pydantic validation.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, field normalization, null handling, ISO 8601 timestamps, regex cleaning.","Explains transforming disparate external response payloads into a standardized intermediate Pydantic schema.","Describes stripping leading/trailing whitespace, normalizing date formats to ISO 8601, and substituting safe defaults for null values."]},{"id":"KP3","description":"Deduplication algorithms and entity resolution.","required":true,"acceptable_evidence":["Technical keywords: hash-based deduplication, exact ID match, fuzzy matching (rapidfuzz/Levenshtein), entity resolution.","Explains deduplicating identical entities using deterministic hash sets based on unique identifiers or normalized names.","Describes applying fuzzy string matching (rapidfuzz) to detect near-duplicate records from different vendors."]},{"id":"KP4","description":"Result aggregation, score normalization, and ranked output formatting.","required":true,"acceptable_evidence":["Technical keywords: reciprocal rank fusion (RRF), score normalization, min-max scaling, sorting.","Explains normalizing disparate ranking scores across providers using min-max scaling or reciprocal rank fusion (RRF).","Describes assembling the final aggregated payload sorted by unified relevance or recency."]}],"critical_failures":["Calls external APIs sequentially in a synchronous loop, multiplying latency across providers.","Drops all aggregated results if a single external API returns an error or times out, failing to return partial results.","Performs deduplication purely by object reference or naive string matching without normalizing keys or handling fuzzy duplicates."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you manage frontend state and data flow in a React-based application using tools like Redux for a search-driven interface?', '{"key_points":[{"id":"KP1","description":"Global client state architecture with Redux Toolkit (RTK).","required":true,"acceptable_evidence":["Technical keywords: configureStore, createSlice, search query state, active filters, pagination state.","Explains organizing user-driven UI state (applied facet filters, search keyword, sorting order, pagination) in Redux Toolkit slices.","Describes keeping the store normalized to prevent deeply nested mutation bugs."]},{"id":"KP2","description":"Server state caching and automated fetching with RTK Query.","required":true,"acceptable_evidence":["Technical keywords: RTK Query, createApi, fetchBaseQuery, cache invalidation, tags.","Explains delegating search API requests, caching, and background re-fetching to RTK Query hooks.","Describes automatic cache invalidation and query deduplication without writing manual reducer boilerplate."]},{"id":"KP3","description":"Search input debouncing and race condition prevention.","required":true,"acceptable_evidence":["Technical keywords: debounce (e.g. 300ms), useCallback, useMemo, AbortController, race conditions.","Explains debouncing search input keystrokes using a custom hook or lodash.debounce before dispatching API requests.","Describes canceling previous in-flight requests or discarding outdated search responses to avoid stale race conditions."]},{"id":"KP4","description":"Optimistic UI updates, skeleton loaders, and local vs global state separation.","required":true,"acceptable_evidence":["Technical keywords: useState for local transient state, useSelector, skeleton loaders, optimistic UI.","Explains keeping transient input keystrokes in local component `useState` and only syncing to Redux on debounced commit.","Describes rendering skeleton loaders and cached results while background queries fetch updated listings."]}],"critical_failures":["Puts high-frequency transient search input state into global Redux store on every keystroke without debouncing, causing excessive re-renders.","Does not cancel previous in-flight search requests when the user types new queries, causing race conditions and out-of-order results.","Manages API server caching manually in Redux reducers instead of utilizing specialized cache solutions like RTK Query."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you prepare for a system design exercise involving end-to-end ML architecture in a production setting?', '{"key_points":[{"id":"KP1","description":"Requirements clarification, business KPIs, and latency SLA definitions.","required":true,"acceptable_evidence":["Technical keywords: functional vs non-functional requirements, p95/p99 latency SLA, QPS throughput, offline vs real-time inference.","Explains clarifying whether the system requires low-latency real-time online inference (<100ms) or batch asynchronous processing.","Describes defining throughput targets (QPS), availability (99.9%), and business KPIs (conversion, fraud detection precision)."]},{"id":"KP2","description":"Data ingestion pipelines, feature engineering, and feature stores.","required":true,"acceptable_evidence":["Technical keywords: feature store (Feast), Apache Kafka, PySpark, DVC data versioning, training-serving skew.","Explains architecting dual feature pipelines (batch via Spark, real-time streaming via Kafka) synchronized through a feature store like Feast.","Describes mitigating training-serving feature skew by sharing feature transformation logic across training and serving."]},{"id":"KP3","description":"Model training, registry, and low-latency inference serving.","required":true,"acceptable_evidence":["Technical keywords: MLflow model registry, Triton Inference Server / vLLM, FastAPI, Redis feature cache.","Explains managing model artifacts and lineage in MLflow and deploying serving containers using Triton, vLLM, or FastAPI.","Describes fetching precomputed entity features from low-latency Redis caches during real-time scoring."]},{"id":"KP4","description":"Deployment strategy, observability, drift detection, and automated feedback loops.","required":true,"acceptable_evidence":["Technical keywords: canary / shadow deployment, Prometheus, Grafana, Evidently drift detection, LangSmith.","Explains validating new models via shadow traffic or canary rollouts before switching live traffic.","Describes continuous monitoring of latency, prediction drift, and input feature distributions with Prometheus and Evidently."]}],"critical_failures":["Jumps straight into model architecture or hyperparameter tuning without clarifying system requirements, latency budgets, or data volume.","Ignores production inference constraints, proposing massive batch architectures for low-latency online serving.","Omits continuous monitoring, drift detection, and retraining pipelines from the end-to-end design."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you prevent SQL injection in an application, and what role do techniques like parameterized queries or stored procedures play?', '{"key_points":[{"id":"KP1","description":"Root causes and exploitation mechanisms of SQL injection (SQLi).","required":true,"acceptable_evidence":["Technical keywords: untrusted input concatenation, SQL syntax manipulation, boolean injection (1=1), comment truncation (--).","Explains how concatenating unsanitized user inputs into raw SQL query strings alters the database query parser\'s intent.","Describes common attack payloads that bypass authentication or leak table contents."]},{"id":"KP2","description":"Parameterized queries, prepared statements, and AST query plan separation.","required":true,"acceptable_evidence":["Technical keywords: parameterized queries, prepared statements, SQLAlchemy bind parameters, database query plan.","Explains how parameterized queries send SQL structure and parameters separately to the database engine.","Describes how the database pre-compiles the execution plan so user inputs are treated strictly as data values, neutralizing injection attempts."]},{"id":"KP3","description":"ORMs and the conditional safety of stored procedures.","required":true,"acceptable_evidence":["Technical keywords: SQLAlchemy ORM, raw SQL execution pitfalls, parameterized stored procedures, dynamic SQL in procedures.","Explains that ORMs like SQLAlchemy automatically parameterize queries, but warns against calling raw query strings or unescaped clauses.","Clarifies that stored procedures prevent SQLi ONLY if they use parameters, and explains that dynamic SQL inside procedures (`EXECUTE IMMEDIATE`) remains vulnerable."]},{"id":"KP4","description":"Defense-in-depth security controls and least privilege permissions.","required":true,"acceptable_evidence":["Technical keywords: Pydantic input validation, least privilege database role, Web Application Firewall (WAF), sqlparse.","Explains enforcing strict type validation and regex checks via Pydantic schemas before queries are built.","Describes restricting database user accounts to minimum necessary privileges (e.g., read-only users without DROP/ALTER privileges)."]}],"critical_failures":["Claims that client-side input validation or string escaping/sanitization alone is sufficient to eliminate SQL injection without parameterized queries.","Believes stored procedures are inherently safe even when they concatenate dynamic SQL strings internally.","Uses raw string formatting (f-strings or % interpolation) to construct database queries in backend endpoints."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you recover from a particular state, and what would you do if you were running parallel tasks·would you continue the process or restart? Walk me through that process.', '{"key_points":[{"id":"KP1","description":"State persistence and checkpointing architectures.","required":true,"acceptable_evidence":["Technical keywords: LangGraph checkpointer, PostgreSQL / Redis state persistence, thread_id, checkpoint snapshots.","Explains recording task states and intermediate execution snapshots in a durable checkpointer (e.g. LangGraph with PostgreSQL/Redis).","Describes using thread IDs and snapshot versions to resume execution from the exact point of interruption."]},{"id":"KP2","description":"Parallel task error isolation and fault classification.","required":true,"acceptable_evidence":["Technical keywords: asyncio.gather return_exceptions=True, partial failure, transient vs deterministic failure.","Explains executing parallel tasks with isolated exception handling so one failed branch does not terminate running sibling coroutines.","Describes classifying failures into transient (network blip, rate limit) versus permanent/fatal (data corruption, schema violation)."]},{"id":"KP3","description":"Decision framework: continuing, retrying, or restarting.","required":true,"acceptable_evidence":["Technical keywords: idempotent retries, compensating transaction (Saga pattern), resuming from checkpoint, fail-fast.","Explains continuing independent parallel branches while selectively retrying the failed task with exponential backoff.","Describes triggering compensating rollback transactions (Saga pattern) or restarting only if an essential shared dependency fails."]},{"id":"KP4","description":"State reconciliation, dead-letter routing, and human-in-the-loop escalation.","required":true,"acceptable_evidence":["Technical keywords: dead-letter queue, LangGraph HITL checkpointing, state reconciliation, structured audit log.","Explains diverting unrecoverable branch failures to a dead-letter queue or quarantine state while letting valid branches complete.","Describes routing ambiguous states to human review via HITL checkpoints before resuming execution."]}],"critical_failures":["Blindly restarts an entire multi-task batch from scratch on any single task failure, wasting compute and duplicating successfully executed operations.","Continues pipeline execution silently when a critical dependency fails without isolating downstream dependencies or recording state.","Fails to maintain persistent checkpoints, making state recovery after crashes or network drops impossible."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you redesign or improve this system today given the rapid evolution of AI tools and technologies?', '{"key_points":[{"id":"KP1","description":"Upgrading linear chains to cyclic agentic graphs with state machines.","required":true,"acceptable_evidence":["Technical keywords: LangGraph, cyclic state machines, conditional routing, human-in-the-loop (HITL) checkpoints.","Explains transitioning brittle linear execution chains to stateful LangGraph agentic workflows with conditional branching.","Describes inserting human-in-the-loop verification checkpoints for high-stakes decisions."]},{"id":"KP2","description":"Modernizing document ingestion and hybrid retrieval.","required":true,"acceptable_evidence":["Technical keywords: Docling multimodal parsing, Milvus HNSW indexing, BM25 hybrid search, cross-encoder reranker.","Explains replacing primitive text splitters with layout-aware document parsers like Docling to retain table and header structures.","Describes combining dense embeddings with sparse BM25 and cross-encoder reranking to drastically improve retrieval precision."]},{"id":"KP3","description":"Implementing continuous automated evaluation and tracing.","required":true,"acceptable_evidence":["Technical keywords: LangSmith, RAGAS metrics (faithfulness, answer_relevancy, context_precision), continuous benchmarking.","Explains replacing anecdotal qualitative prompt testing with systematic automated evaluation using RAGAS and golden test datasets.","Describes instrumenting all production LLM calls with LangSmith for token cost tracking and latency observability."]},{"id":"KP4","description":"Serving optimization, structured outputs, and semantic caching.","required":true,"acceptable_evidence":["Technical keywords: vLLM / Triton, Pydantic structured outputs, instructor, Redis semantic caching.","Explains adopting high-throughput serving runtimes like vLLM with PagedAttention and enforcing strict JSON outputs using Pydantic schemas.","Describes deploying Redis semantic caching to bypass LLM inference for duplicate or similar prompts."]}],"critical_failures":["Suggests simply swapping in a newer model checkpoint without addressing systemic bottlenecks like retrieval quality, caching, or orchestration.","Proposes unconstrained autonomous agents without deterministic state machine guards, HITL controls, or structured schemas.","Ignores production latency, token costs, and automated evaluation metrics when proposing architectural upgrades."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you test an API endpoint that accepts a user ID and returns user data, and how would you categorize your test cases?', '{"key_points":[{"id":"KP1","description":"Test environment architecture and dependency isolation.","required":true,"acceptable_evidence":["Technical keywords: pytest, FastAPI TestClient, httpx, test fixture, mock database.","Explains configuring pytest with FastAPI TestClient and isolated database fixtures or mocked repositories.","Describes ensuring test runs are isolated and repeatable without impacting production databases."]},{"id":"KP2","description":"Positive happy path test categorization.","required":true,"acceptable_evidence":["Technical keywords: valid user ID, HTTP 200 OK, Pydantic response schema, expected payload validation.","Explains asserting HTTP 200 OK status for existing valid user IDs.","Describes validating response payload against the expected Pydantic user schema and verifying accurate field values."]},{"id":"KP3","description":"Negative, boundary, and input validation test categorization.","required":true,"acceptable_evidence":["Technical keywords: HTTP 404 Not Found, HTTP 422 Unprocessable Entity, malformed UUID / integer, non-existent user.","Explains asserting HTTP 404 Not Found when querying IDs that do not exist in the database.","Describes testing malformed or invalid ID types (e.g. negative integers, invalid UUID strings) to verify HTTP 422 validation errors."]},{"id":"KP4","description":"Security, authentication, and authorization test categorization.","required":true,"acceptable_evidence":["Technical keywords: HTTP 401 Unauthorized, HTTP 403 Forbidden, expired JWT, IDOR (Insecure Direct Object Reference).","Explains testing missing, expired, or invalid Bearer JWT tokens to ensure HTTP 401 responses.","Describes testing cross-user authorization boundaries (IDOR prevention) where User A attempts to view User B\'s private data, returning HTTP 403 Forbidden."]}],"critical_failures":["Tests only the happy path (valid user ID returns 200) while omitting 404, 422, and unauthorized 401/403 scenarios.","Hardcodes dependencies on live production user databases instead of using test fixtures or mocked repositories.","Ignores Pydantic schema validation of the response body, checking only HTTP status codes."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you test the functional behavior of an API covering CRUD operations and schema validation?', '{"key_points":[{"id":"KP1","description":"End-to-end CRUD lifecycle test design.","required":true,"acceptable_evidence":["Technical keywords: pytest, TestClient, POST create (201), GET read (200), PUT/PATCH update (200), DELETE delete (204).","Explains creating an end-to-end lifecycle test sequence: creating a record, verifying its retrieval, updating attributes, and deleting it.","Describes asserting that subsequent GET requests for the deleted record return HTTP 404 Not Found."]},{"id":"KP2","description":"Request and response schema validation.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModel, HTTP 422 validation error, response_model conformance, field constraints.","Explains asserting that invalid request payloads (wrong types, missing required fields) trigger HTTP 422 Unprocessable Entity.","Describes verifying that response payloads strictly conform to declared Pydantic response models."]},{"id":"KP3","description":"Test fixture isolation, transactional rollback, and database hygiene.","required":true,"acceptable_evidence":["Technical keywords: conftest.py, fixture teardown, SQLite in-memory / test PostgreSQL, transaction rollback.","Explains using pytest fixtures with database transaction rollbacks after each test to maintain clean, isolated state.","Describes preventing state leakage across tests that could cause flaky test execution."]},{"id":"KP4","description":"Boundary conditions, uniqueness constraints, and error scenarios.","required":true,"acceptable_evidence":["Technical keywords: @pytest.mark.parametrize, HTTP 409 Conflict, duplicate key, foreign key violation, boundary values.","Explains testing database constraint violations, such as creating duplicate unique resources (HTTP 409 Conflict).","Describes parametrizing test inputs across edge values (empty strings, extreme integer limits, null values)."]}],"critical_failures":["Allows tests to share state across test runs without teardown or transaction rollback, causing test interdependence and flaky runs.","Tests CRUD operations in isolation without verifying that a DELETE actually prevents subsequent GET requests.","Omits validation error tests for malformed payloads, testing only valid data schemas."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you validate API behavior for different input types, required vs optional fields, and error handling for invalid requests?', '{"key_points":[{"id":"KP1","description":"Pydantic schema definitions for type constraints and field requirements.","required":true,"acceptable_evidence":["Technical keywords: Pydantic BaseModel, Field, Optional, None defaults, strict typing, validator.","Explains defining schemas where required fields have no defaults (`Field(...)`) and optional fields use `Optional[T] = None`.","Describes configuring field constraints such as min_length, max_length, ge, le, and custom field validators."]},{"id":"KP2","description":"Parametrized testing across valid and invalid input combinations.","required":true,"acceptable_evidence":["Technical keywords: @pytest.mark.parametrize, boundary testing, type coercion, missing required fields.","Explains using `@pytest.mark.parametrize` to systematically test combinations of present and omitted optional fields.","Describes sending invalid data types (e.g., strings for integer fields) to verify robust validation enforcement."]},{"id":"KP3","description":"Validation error response structure and HTTP status verification.","required":true,"acceptable_evidence":["Technical keywords: HTTP 422 Unprocessable Entity, detail error list, loc path, msg error message.","Explains inspecting FastAPI\'s default 422 JSON response to verify the `loc` points to the exact invalid field and `msg` provides clear diagnostic feedback.","Describes overriding default exception handlers when custom standardized error envelopes are required."]},{"id":"KP4","description":"Security testing for extra unexpected fields and malicious inputs.","required":true,"acceptable_evidence":["Technical keywords: extra=\'forbid\' vs extra=\'ignore\', oversized payloads, malformed JSON, injection strings.","Explains configuring Pydantic\'s model configuration (`extra=\'forbid\'`) to reject unrecognized input fields that could indicate injection attempts.","Describes verifying that malformed JSON syntax triggers HTTP 400 Bad Request rather than uncaught 500 server crashes."]}],"critical_failures":["Relies on manual if/else checks inside route handlers instead of declarative Pydantic schemas and type annotations.","Accepts arbitrary extra fields without configuring Pydantic schema behavior or validating against unexpected input structures.","Fails to verify that invalid inputs yield appropriate 422/400 status codes with informative error payloads."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'If you were to rebuild the system from scratch, how would you approach evaluation and system design differently?', '{"key_points":[{"id":"KP1","description":"Evaluation-driven development (EDD) and golden benchmark construction.","required":true,"acceptable_evidence":["Technical keywords: RAGAS metrics, faithfulness, answer_relevancy, context_precision, golden evaluation dataset, LangSmith.","Explains establishing a curated ground-truth test suite and automated evaluation metrics (faithfulness, relevancy) before writing pipeline code.","Describes running regression evaluation in CI to prevent performance degradation across model iterations."]},{"id":"KP2","description":"Modular agentic architecture with explicit state machines.","required":true,"acceptable_evidence":["Technical keywords: LangGraph, cyclic state graph, conditional routing, human-in-the-loop (HITL) checkpoints.","Explains replacing brittle monolithic scripts with modular LangGraph state machines featuring explicit transitions and recovery paths.","Describes adding HITL checkpoints for ambiguous or high-risk decision points."]},{"id":"KP3","description":"Polyglot storage tiers and advanced hybrid retrieval.","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW indexing, BM25 hybrid search, cross-encoder reranker, PostgreSQL, Redis caching.","Explains adopting hybrid dense-sparse search in Milvus with cross-encoder reranking from the start rather than naive vector search.","Describes separating transactional history (PostgreSQL) and session caching (Redis) cleanly."]},{"id":"KP4","description":"Production guardrails, cost management, and continuous observability.","required":true,"acceptable_evidence":["Technical keywords: semantic cache, token budgeting, Prometheus, Grafana, OpenTelemetry, guardrails.","Explains implementing semantic caching in Redis to reduce redundant LLM calls and enforcing token budget limits per user.","Describes instrumenting complete OpenTelemetry traces and Prometheus metrics from inception."]}],"critical_failures":["Proposes rebuilding the system based purely on intuition without establishing automated quantitative evaluation metrics or golden benchmarks.","Couples business logic, LLM calls, and UI components into a monolithic script without clear architectural boundaries.","Ignores production guardrails, token cost governance, and latency constraints in the redesigned architecture."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'In a client-facing role, how would you gather requirements and translate them into technical architecture and solutions?', '{"key_points":[{"id":"KP1","description":"Stakeholder discovery, problem framing, and SLA definition.","required":true,"acceptable_evidence":["Technical keywords: functional vs non-functional requirements, SLA/SLO expectations, business KPIs, user journeys.","Explains conducting structured discovery interviews with client stakeholders to distinguish true business requirements from assumed technical implementations.","Describes establishing quantifiable non-functional constraints (latency budgets, availability, data volume, concurrency)."]},{"id":"KP2","description":"Data landscape assessment, security, and regulatory compliance.","required":true,"acceptable_evidence":["Technical keywords: data schema audit, API availability, compliance (HIPAA/GDPR/SOC2), data sovereignty.","Explains analyzing client data sources, quality, integration access, and volume/velocity characteristics.","Describes mapping security and regulatory constraints (HIPAA PHI handling, encryption in transit and at rest, SOC2 controls)."]},{"id":"KP3","description":"Architectural translation and Architecture Decision Records (ADRs).","required":true,"acceptable_evidence":["Technical keywords: Architecture Decision Records (ADRs), C4 architecture diagrams, API contracts, tech stack selection.","Explains translating high-level requirements into formal system architecture diagrams (C4 model) and tech stack specifications.","Describes drafting ADRs that document evaluated alternatives and rationale for chosen technologies."]},{"id":"KP4","description":"Iterative prototyping, MVP scope definition, and client feedback loops.","required":true,"acceptable_evidence":["Technical keywords: Proof of Concept (PoC), Minimum Viable Product (MVP), agile milestones, demo cadence.","Explains scoping a tight MVP that de-risks the highest technical uncertainties early.","Describes establishing a recurring bi-weekly demonstration cadence with client stakeholders for continuous feedback alignment."]},{"id":"KP5","description":"Scope governance, technical risk management, and client sign-off.","required":true,"acceptable_evidence":["Technical keywords: scope creep management, technical risk matrix, trade-off matrix, change request process.","Explains communicating technical trade-offs (e.g. speed to delivery vs architectural completeness) in clear business terms.","Describes managing scope changes through formal change requests and maintaining mutual client sign-off gates."]}],"critical_failures":["Commits to technical solutions and delivery timelines before clarifying data access, volume, latency requirements, or compliance constraints.","Presents complex engineering jargon to business stakeholders instead of translating technical trade-offs into business value and risk impacts.","Fails to document requirements in formal ADRs or contracts, resulting in unmanaged scope creep and misaligned client expectations."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What are common Spark performance tuning techniques you have applied in practice?', '{"key_points":[{"id":"KP1","description":"Adaptive Query Execution (AQE) and dynamic shuffle tuning.","required":true,"acceptable_evidence":["Technical keywords: PySpark, Adaptive Query Execution (AQE), spark.sql.adaptive.enabled, dynamic partition coalescing, adaptive skew join.","Explains enabling AQE to dynamically coalesce small shuffle partitions, convert sort-merge joins to broadcast joins at runtime, and optimize skew joins.","Describes configuring `spark.sql.adaptive.coalescePartitions.enabled` to eliminate excess shuffle tasks."]},{"id":"KP2","description":"Join optimization and broadcast join strategies.","required":true,"acceptable_evidence":["Technical keywords: broadcast join, broadcast(), spark.sql.autoBroadcastJoinThreshold, sort-merge join shuffle reduction.","Explains broadcasting small lookup tables across executors using `broadcast(df)` to avoid heavy network shuffle hash joins.","Describes tuning `spark.sql.autoBroadcastJoinThreshold` appropriately according to available driver/executor memory."]},{"id":"KP3","description":"Partitioning management and data skew mitigation.","required":true,"acceptable_evidence":["Technical keywords: repartition vs coalesce, salting skewed keys, partitionBy on write, columnar Parquet pruning.","Explains using `coalesce` to decrease partitions without a full shuffle and `repartition` for balanced redistribution.","Describes salting skewed join keys with random integer suffixes to prevent straggler tasks and executor OOM crashes."]}],"critical_failures":["Confuses `repartition` (full network shuffle) with `coalesce` (combines partitions without full shuffle when decreasing partition count).","Uses broadcast joins on massive tables exceeding driver/executor memory limits, causing Out-Of-Memory (OOM) crashes."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'HARD', 'SPECIFIC', 120, 'What are common web security vulnerabilities such as SQL injection, XML injection, and JavaScript injection, and how do you mitigate them?', '{"key_points":[{"id":"KP1","description":"SQL injection (SQLi) mechanisms and defenses.","required":true,"acceptable_evidence":["Technical keywords: parameterized queries, prepared statements, SQLAlchemy ORM, principle of least privilege.","Explains that SQLi occurs when untrusted input alters query logic, and that parameterized queries/prepared statements completely separate code from data.","Describes configuring database roles with minimum required permissions to limit breach blast radius."]},{"id":"KP2","description":"XML External Entity (XXE) and XML injection mitigations.","required":true,"acceptable_evidence":["Technical keywords: XML External Entity (XXE), defusedxml, disable DTD processing (Document Type Definition), external entity resolution.","Explains how XXE attacks exploit external entity parsing to access internal files, perform SSRF, or trigger denial of service.","Describes using hardened parsers like `defusedxml` and explicitly disabling DTD processing and external entity resolution in XML parsers."]},{"id":"KP3","description":"Cross-Site Scripting (XSS / JavaScript injection) prevention.","required":true,"acceptable_evidence":["Technical keywords: stored/reflected/DOM XSS, Content Security Policy (CSP), HTML entity escaping, React JSX automatic escaping.","Explains how malicious script injection steals session cookies or compromises client sessions.","Describes mitigating XSS via automatic JSX contextual escaping, strict Content Security Policy (CSP) headers, and avoiding raw HTML injection (`dangerouslySetInnerHTML`)."]},{"id":"KP4","description":"Input sanitization and schema validation boundaries.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schema validation, bleach library, DOMPurify, Content-Type enforcement.","Explains enforcing strict typing and input schemas at the API boundary using Pydantic.","Describes sanitizing rich-text user markup using trusted libraries like DOMPurify or bleach."]},{"id":"KP5","description":"Defense-in-depth security infrastructure and HTTP headers.","required":true,"acceptable_evidence":["Technical keywords: Web Application Firewall (WAF), HttpOnly, Secure, SameSite cookie flags, CORS configuration.","Explains deploying a Web Application Firewall (WAF) to filter common web exploit patterns at ingress.","Describes setting `HttpOnly`, `Secure`, and `SameSite` flags on authentication cookies to neutralize token theft via XSS."]}],"critical_failures":["Suggests regex string replacement as the primary defense against SQL injection or XSS instead of parameterized queries and context-aware escaping.","Parses untrusted XML with default standard library parsers without disabling external entities (XXE vulnerability).","Uses `dangerouslySetInnerHTML` in React with unescaped, unvalidated user input."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are the advantages of using GraphQL over REST APIs, and in what scenarios would you prefer one over the other?', '{"key_points":[{"id":"KP1","description":"Core advantages of GraphQL: declarative fetching and elimination of over/under-fetching.","required":true,"acceptable_evidence":["Technical keywords: over-fetching, under-fetching, single endpoint (/graphql), declarative query, schema introspection.","Explains how clients specify the exact shape of required data, preventing waste of bandwidth from over-fetching unneeded fields.","Describes consolidating multiple related resource fetches into a single network round-trip."]},{"id":"KP2","description":"Strengths of REST: native HTTP caching, simplicity, and established conventions.","required":true,"acceptable_evidence":["Technical keywords: HTTP caching, Cache-Control, standard HTTP status codes, CDN caching, idempotent methods.","Explains that REST leverages standard HTTP caching mechanisms (ETags, Cache-Control, CDN edge caching) natively based on URLs.","Describes REST\'s widespread tooling maturity, simplicity for standard CRUD, and intuitive HTTP status code error semantics."]},{"id":"KP3","description":"Decision criteria and architectural trade-offs.","required":true,"acceptable_evidence":["Technical keywords: DataLoader (N+1 query problem), query complexity limits, mobile client bandwidth, microservice integration.","Explains choosing GraphQL for complex frontend dashboards or bandwidth-constrained mobile apps with deeply nested relations.","Describes choosing REST for public third-party APIs, simple CRUD microservices, large file streaming, or when fine-grained HTTP CDN caching is critical."]}],"critical_failures":["Claims GraphQL completely eliminates backend database queries or N+1 problems without mentioning dataloaders or batching.","Claims GraphQL has identical out-of-the-box HTTP caching behavior as REST without acknowledging that POST requests bypass standard HTTP CDN caches."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What are the consequences of latency and incorrect interpretation of policy documents in a healthcare insurance context?', '{"key_points":[{"id":"KP1","description":"Clinical, regulatory, and financial consequences of incorrect policy interpretation.","required":true,"acceptable_evidence":["Technical keywords: wrongful claim denial, care delay, CMS regulatory audits, compliance penalties, provider friction, appeal overhead.","Explains that hallucinated or misapplied insurance policy criteria leads to wrongful denial of essential medical treatments, risking patient health outcomes.","Describes financial liabilities including expensive manual appeal re-adjudication and severe regulatory penalties from governing bodies (CMS/state regulators)."]},{"id":"KP2","description":"Impact of processing latency on healthcare workflows and hospital operations.","required":true,"acceptable_evidence":["Technical keywords: prior authorization turnaround time, discharge delays, emergency room bottlenecks, SLA breach.","Explains how latency in prior authorization decisions causes hospital bed gridlock, delayed discharges, and patient dissatisfaction.","Describes violating contractual and regulatory turnaround time SLAs when decision systems experience excessive processing delays."]},{"id":"KP3","description":"Architectural mitigation via strict guardrails, citation verification, and human escalation.","required":true,"acceptable_evidence":["Technical keywords: RAGAS faithfulness threshold, Milvus hybrid search, HITL clinical review, audit trail, NeMo Guardrails.","Explains requiring strict citation attribution and faithfulness thresholds before presenting policy decisions to users.","Describes routing any low-confidence policy interpretations or adverse coverage determinations to licensed clinical reviewers via HITL workflows."]}],"critical_failures":["Minimizes the severity of incorrect interpretations as simple text typos rather than legal, financial, and clinical compliance violations.","Suggests autonomous real-time claim denials based entirely on raw LLM outputs without human-in-the-loop escalation paths."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What are the databases you work with? Are you familiar with the Medallion Architecture, and can you explain that to me?', '{"key_points":[{"id":"KP1","description":"Polyglot persistence across operational, vector, and caching datastores.","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, Milvus, Redis, DynamoDB, MongoDB, appropriate engine selection.","Explains hands-on experience selecting database engines: relational databases (PostgreSQL) for transactional integrity, vector databases (Milvus) for embedding similarity search, and in-memory stores (Redis) for low-latency session caching.","Discusses tailoring datastore choices to access patterns and consistency requirements."]},{"id":"KP2","description":"Medallion Architecture layers: Bronze, Silver, and Gold.","required":true,"acceptable_evidence":["Technical keywords: Medallion Architecture, Bronze raw ingested layer, Silver cleaned/enriched layer, Gold aggregated business layer.","Explains Bronze as the raw, append-only landing zone preserving original source format and full history.","Explains Silver as the cleaned, deduplicated, and conformed layer with standardized schemas, and Gold as business-aggregated data marts optimized for reporting and analytics."]},{"id":"KP3","description":"Underlying storage formats and data engineering advantages.","required":true,"acceptable_evidence":["Technical keywords: Delta Lake / Databricks, Apache Spark, ACID transactions on object storage, schema enforcement, time travel.","Explains how Delta Lake/Parquet provides ACID transactions, time travel, and schema enforcement over cloud object storage.","Describes how Medallion Architecture guarantees data quality progression and allows re-processing downstream layers from raw Bronze data."]}],"critical_failures":["Confuses Medallion Architecture with relational normalization (1NF, 2NF, 3NF) or dimensional modeling (star schema).","Claims Bronze layer should contain curated aggregations or skips raw data storage entirely, preventing reprocessing."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What are the differences between serverless and server-based architectures, and when would you choose each?', '{"key_points":[{"id":"KP1","description":"Execution model, lifecycle, and resource scaling.","required":true,"acceptable_evidence":["Technical keywords: AWS Lambda vs Amazon EC2 / EKS, event-driven compute, scale-to-zero, provisioned capacity.","Explains that serverless executes ephemeral, event-driven functions that automatically scale down to zero when idle.","Contrasts with server-based architectures that maintain persistent, provisioned virtual machines or Kubernetes pods running continuously."]},{"id":"KP2","description":"Latency profile, cold starts, and connection persistence.","required":true,"acceptable_evidence":["Technical keywords: cold start latency, RDS Proxy connection pooling, WebSockets, persistent TCP connections.","Explains that serverless functions incur cold start latency during container initialization, whereas long-running servers provide predictable warm response times.","Describes connection pooling challenges in serverless (requiring RDS Proxy) versus native connection pools in server-based architectures."]},{"id":"KP3","description":"Cost economics across sporadic vs sustained workloads.","required":true,"acceptable_evidence":["Technical keywords: pay-per-execution / request duration, fixed hourly instance cost, idle resource waste, cost inflection point.","Explains that serverless is cost-efficient for intermittent, unpredictable, or low-frequency traffic because idle time costs nothing.","Describes that server-based architectures are substantially cheaper for continuous, predictable high-throughput traffic once past the cost inflection point."]},{"id":"KP4","description":"Operational maintenance and development velocity.","required":true,"acceptable_evidence":["Technical keywords: OS patching, infrastructure management, Kubernetes manifests, Serverless Framework / AWS SAM.","Explains that serverless offloads OS patching, runtime updates, and cluster management to the cloud provider.","Contrasts with server-based architectures that require infrastructure maintenance, container orchestration, and autoscaling policy configuration."]},{"id":"KP5","description":"Workload fit and selection criteria.","required":true,"acceptable_evidence":["Technical keywords: background event processing, GPU deep learning serving (vLLM/Triton), long-running tasks, execution timeout.","Explains selecting serverless for webhook handlers, asynchronous SQS event consumers, and low-traffic APIs.","Describes selecting server-based (EKS/EC2) for GPU-intensive ML inference, streaming architectures, or jobs exceeding serverless execution timeouts."]}],"critical_failures":["Recommends serverless functions with short timeouts for long-running GPU deep learning model training or heavy continuous streaming.","Ignores cold start latency considerations when designing real-time, low-latency API endpoints on serverless platforms.","Suggests server-based architectures provide automatic scale-to-zero without explicit autoscaling configurations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What are the differences between using Context API and Redux for state management, and when would you choose one over the other?', '{"key_points":[{"id":"KP1","description":"Re-rendering mechanisms and performance characteristics.","required":true,"acceptable_evidence":["Technical keywords: React Context API, useContext, Redux Toolkit (RTK), useSelector, component re-render.","Explains that any update to Context value triggers re-renders across all consumer components using `useContext`, lacking built-in selector subscriptions.","Contrasts with Redux where components subscribing via `useSelector` re-render only when the selected slice value changes."]},{"id":"KP2","description":"Architecture, middleware, and developer tooling.","required":true,"acceptable_evidence":["Technical keywords: Redux DevTools, time-travel debugging, middleware, centralized store vs Provider tree.","Explains Redux\'s strict unidirectional data flow, centralized immutable store, middleware pipeline, and time-travel debugging via Redux DevTools.","Contrasts with Context API which requires no external libraries and relies on React\'s native component tree."]},{"id":"KP3","description":"Asynchronous data fetching and side effect management.","required":true,"acceptable_evidence":["Technical keywords: RTK Query, createAsyncThunk, side effect handling, manual useEffect fetching.","Explains that Redux Toolkit provides integrated solutions for server state caching and async queries via RTK Query.","Contrasts with Context API which has no built-in async data fetching or cache invalidation logic, requiring custom hooks and reducers."]},{"id":"KP4","description":"Selection guidelines and practical use cases.","required":true,"acceptable_evidence":["Technical keywords: low-frequency global state (theme, auth, locale), high-frequency complex state, boilerplate trade-off.","Explains choosing Context API for low-frequency global state such as theme toggles, authenticated user identity, or UI locale.","Describes choosing Redux for complex applications with frequently mutating data, intricate entity relationships, or collaborative multi-user editing."]}],"critical_failures":["Uses React Context for rapidly changing state (e.g. text inputs or frequent animations), causing massive unnecessary component re-renders.","Recommends Redux for simple, static state (like dark mode toggle) without justifying the boilerplate overhead over Context.","Assumes Context API is an asynchronous data-fetching and caching framework comparable to RTK Query or React Query."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'What are the key differences between NumPy arrays and Python lists in terms of memory and performance?', '{"key_points":[{"id":"KP1","description":"Memory layout, contiguous allocation, and memory footprint.","required":true,"acceptable_evidence":["Technical keywords: contiguous memory block, C-style array, pointers to PyObject, memory overhead, cache locality.","Explains that NumPy arrays store homogeneous data in contiguous memory blocks with zero pointer indirection, achieving superior CPU cache locality.","Contrasts with Python lists which store arrays of pointers pointing to separate heap-allocated PyObject wrappers, incurring significant memory overhead per item."]},{"id":"KP2","description":"Vectorization, SIMD parallelism, and execution performance.","required":true,"acceptable_evidence":["Technical keywords: vectorization, SIMD instructions, avoiding Python interpreter loop overhead, universal functions (ufuncs).","Explains that NumPy executes vectorized computations at compiled C-speed using processor SIMD instructions, bypassing the Python bytecode interpreter loop.","Contrasts with Python lists which require iterating through elements via the interpreter with type checking at every step."]},{"id":"KP3","description":"Type homogeneity vs heterogeneity and mutability semantics.","required":true,"acceptable_evidence":["Technical keywords: dtype homogeneity, fixed size vs dynamic resizing, type coercion, PyObject* pointers.","Explains that NumPy arrays require fixed homogeneous data types (dtype) and have fixed size buffers.","Contrasts with Python lists which are dynamically resizable and support arbitrary heterogeneous element types."]}],"critical_failures":["Claims Python lists store primitive values directly in contiguous memory rather than pointers to heap-allocated PyObject wrappers.","Suggests writing explicit Python for loops over NumPy arrays is faster than vectorized NumPy ufuncs or operations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between directly calling APIs versus using a tool abstraction layer?', '{"key_points":[{"id":"KP1","description":"Coupling, vendor flexibility, and standardization.","required":true,"acceptable_evidence":["Technical keywords: Model Context Protocol (MCP), tool abstraction layer, vendor lock-in, loose coupling, interface contract.","Explains that direct API calls create tight coupling to vendor-specific endpoints and response structures, creating migration friction.","Describes how a tool abstraction layer (e.g. MCP tools or LangChain BaseTool) standardizes interfaces across disparate services."]},{"id":"KP2","description":"Agent tool calling, parameter validation, and prompt integration.","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, function calling, schema generation, argument validation, error transformation.","Explains that tool abstraction layers automatically generate JSON schema definitions for LLM function calling and validate parameters with Pydantic.","Describes how abstraction layers transform low-level runtime errors into clear, LLM-digestible feedback messages for self-correction."]},{"id":"KP3","description":"Centralization of cross-cutting concerns (auth, retries, rate limiting).","required":true,"acceptable_evidence":["Technical keywords: centralized rate limiting, tenacity retry policy, OAuth token injection, audit logging, circuit breaker.","Explains embedding authentication token refresh, rate limiting, and exponential retries centrally within the tool layer.","Contrasts with direct calls where cross-cutting concerns must be duplicated across every callsite."]},{"id":"KP4","description":"Overhead, debugging ergonomics, and architectural trade-offs.","required":true,"acceptable_evidence":["Technical keywords: indirection latency, stack trace complexity, premature abstraction, rapid prototyping.","Explains that abstraction layers introduce maintenance overhead, stack trace depth, and potential latency for simple integrations.","Describes favoring direct calls for quick prototypes or trivial single-use scripts, while mandating tool abstractions for production multi-agent systems."]}],"critical_failures":["Hardcodes direct vendor-specific API calls throughout agentic prompt routines without schema validation or interface abstractions.","Introduces overly complex multi-tiered abstraction layers for trivial one-off integrations where direct calls are cleaner and faster.","Omits centralized error handling, authentication injection, and rate limiting from tool abstraction layers."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between sequential and parallel API calls when processing large datasets?', '{"key_points":[{"id":"KP1","description":"Throughput and latency trade-offs between sequential and parallel execution","required":true,"acceptable_evidence":["Technical keywords: latency, throughput, asyncio.gather, httpx AsyncClient, wall-clock time.","Explains that sequential API calls result in O(N * T) total execution time with low memory usage, whereas parallel/concurrent calls dramatically reduce wall-clock time by overlapping I/O wait times.","Contrasts predictable execution order and simple error recovery in sequential loops against out-of-order responses and non-deterministic failures in concurrent pipelines."]},{"id":"KP2","description":"Concurrency control and downstream rate limiting","required":true,"acceptable_evidence":["Technical keywords: asyncio.Semaphore, HTTP 429, token bucket, leaky bucket, exponential backoff, jitter.","Explains using an asyncio.Semaphore to bound concurrent in-flight requests, preventing socket exhaustion and avoiding HTTP 429 (Too Many Requests) rate limit errors.","Describes backoff strategies like exponential backoff with jitter when encountering rate limits or downstream server throttling."]},{"id":"KP3","description":"Resource consumption, connection pooling, and backpressure","required":true,"acceptable_evidence":["Technical keywords: connection pooling, httpx Limits, file descriptors, memory backpressure, socket exhaustion.","Explains how unbounded parallel calls can exhaust system file descriptors, connection pools, and client-side RAM by buffering too many payloads simultaneously.","Describes configuring connection pool limits (e.g. max_connections, max_keepalive_connections) and applying stream processing or batch chunking to maintain backpressure."]},{"id":"KP4","description":"Failure isolation, partial failures, and idempotency","required":false,"acceptable_evidence":["Technical keywords: partial failure, return_exceptions, dead-letter queue, idempotency, retry policy.","Discusses handling partial batch failures using return_exceptions=True in asyncio.gather or routing failed items to a dead-letter queue (DLQ).","Emphasizes the necessity of idempotent API endpoints so that retried requests do not create duplicate state or side effects."]}],"critical_failures":["Confuses asynchronous I/O event-loop concurrency (asyncio) with multi-process CPU parallelism.","Fails to address rate limiting or downstream server throttling (HTTP 429) when discussing parallel API execution."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What are your key strengths as an engineer when solving complex problems, particularly in terms of scalability, modularity, and system design?', '{"key_points":[{"id":"KP1","description":"Scalable architectural design and horizontal partitioning","required":true,"acceptable_evidence":["Technical keywords: horizontal scaling, Kubernetes HPA, Redis caching, read replicas, database sharding.","Articulates designing stateless microservices deployed on Kubernetes (EKS) with Horizontal Pod Autoscaling (HPA) to handle traffic bursts.","Describes using Redis distributed caching for hot state and database read replicas to eliminate database bottlenecks under high read volume."]},{"id":"KP2","description":"Modularity, clear interface contracts, and loose coupling","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, dependency injection, LangGraph nodes, interface segregation, loose coupling.","Explains establishing strict schema boundaries using Pydantic models and REST/gRPC contracts between microservices.","Demonstrates decomposing monolithic logic into isolated, independently testable units, such as decoupled LangGraph workflow nodes."]},{"id":"KP3","description":"Resilience, fault isolation, and graceful degradation","required":true,"acceptable_evidence":["Technical keywords: circuit breaker, dead-letter queue, SQS, fallback mechanism, graceful degradation.","Explains implementing circuit breakers and asynchronous message queues (SQS) to decouple latency-sensitive APIs from slow downstream dependencies.","Describes graceful degradation patterns, such as serving cached results or fallback responses when vector DBs or external LLMs fail."]},{"id":"KP4","description":"Observability-driven debugging and performance profiling","required":false,"acceptable_evidence":["Technical keywords: OpenTelemetry, Prometheus, Grafana, LangSmith, distributed tracing, P95/P99 latency.","References using distributed tracing (OpenTelemetry, LangSmith) to identify microservice latency bottlenecks across async boundaries.","Describes monitoring operational SLIs/SLOs (tail latencies P95/P99, error rates) to guide architectural refactoring."]}],"critical_failures":["Gives generic behavioral statements without citing concrete architectural patterns or technologies.","Fails to explain how modularity or loose coupling is enforced in code or system design."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What challenges arise when building scalable AI platforms for large datasets, and how do you address performance, reliability, and data integrity?', '{"key_points":[{"id":"KP1","description":"High-throughput data ingestion and distributed processing bottlenecks","required":true,"acceptable_evidence":["Technical keywords: Apache Spark, batch embedding, Milvus ingestion, rate limiting, SQS worker pool.","Discusses handling ingestion bottlenecks across large corpora using distributed data processing (PySpark AQE) and asynchronous worker pools.","Addresses LLM embedding rate limits and network latency through batched asynchronous requests and worker queue leveling."]},{"id":"KP2","description":"Vector database scalability, indexing, and memory saturation","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, M, ef_construction, collection partitioning, MMAP.","Explains scaling vector search over millions of vectors using Milvus HNSW indexing with tuned M and ef_construction parameters.","Describes mitigating RAM saturation using Milvus MMAP disk-backed storage and partitioning collections by date or tenant."]},{"id":"KP3","description":"Data integrity, deduplication, and schema validation","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, SHA-256 deduplication, DVC versioning, schema validation.","Explains enforcing strict schema validation using Pydantic models at API boundaries and data ingestion pipelines.","Describes preventing knowledge contamination through SHA-256 content hashing deduplication and data version control with DVC."]},{"id":"KP4","description":"Reliability, fault tolerance, and queue-based decoupling","required":true,"acceptable_evidence":["Technical keywords: AWS SQS, dead-letter queue, circuit breaker, exponential backoff, retry policy.","Explains decoupling heavy AI processing jobs from user-facing APIs via SQS queues with dead-letter queues (DLQs) for failed items.","Discusses circuit breaker patterns and exponential backoff retry mechanisms against third-party AI provider outages."]},{"id":"KP5","description":"Continuous observability, drift detection, and evaluation","required":false,"acceptable_evidence":["Technical keywords: Evidently AI, Prometheus, Grafana, LangSmith, data drift, feature drift.","Discusses tracking operational metrics (P95/P99 latency, throughput, error rates) in Prometheus and Grafana.","Describes monitoring feature and prediction drift using Evidently AI and tracking execution traces via LangSmith."]}],"critical_failures":["Ignores vector database indexing and memory constraints when scaling AI platforms to large datasets.","Fails to provide mechanisms for data validation, deduplication, or error recovery in distributed pipelines."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What does good backend performance mean to you, and how do you balance developer productivity with runtime efficiency?', '{"key_points":[{"id":"KP1","description":"Quantifiable performance metrics focusing on tail latency and resource efficiency","required":true,"acceptable_evidence":["Technical keywords: P95/P99 latency, throughput, RPS, SLA, SLO, connection pool utilization.","Defines backend performance using service level objectives (SLOs): P95/P99 tail latencies, error budgets, and maximum requests per second under peak load.","Explains why tail latencies (P99) reflect user experience much more accurately than simple average response times."]},{"id":"KP2","description":"Balancing productivity and efficiency with modern Python frameworks","required":true,"acceptable_evidence":["Technical keywords: FastAPI, asyncio, Pydantic v2, Rust core, non-blocking I/O.","Explains selecting FastAPI and async Python to achieve high developer velocity while maintaining excellent runtime throughput for I/O-bound microservices.","Mentions Pydantic v2\'s compiled Rust core providing sub-millisecond serialization without sacrificing Python readability."]},{"id":"KP3","description":"Targeted optimization: caching, indexing, and eliminating I/O bottlenecks","required":true,"acceptable_evidence":["Technical keywords: Redis TTL, PostgreSQL indexing, EXPLAIN ANALYZE, N+1 query.","Advocates for optimizing high-impact bottlenecks first: adding Redis caching with TTLs and resolving N+1 database queries.","Uses PostgreSQL EXPLAIN ANALYZE to identify sequential scans and optimize query plans rather than rewriting application code prematurely."]},{"id":"KP4","description":"Data-driven profiling over premature optimization","required":false,"acceptable_evidence":["Technical keywords: cProfile, py-spy, APM, OpenTelemetry, flame graphs.","Emphasizes profiling applications with tools like cProfile, py-spy, or APM traces before refactoring.","Explains keeping code maintainable and idiomatic until profiling demonstrates a specific CPU or memory hotspot."]}],"critical_failures":["Evaluates performance purely using average/mean latency without acknowledging tail latency (P95/P99).","Recommends premature optimization or language rewrites without profiling bottlenecks or optimizing database queries."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What factors do you consider when designing AI systems for production, especially in terms of scalability and efficiency?', '{"key_points":[{"id":"KP1","description":"Inference latency optimization, streaming, and model quantization","required":true,"acceptable_evidence":["Technical keywords: quantization, INT8, FP16, bitsandbytes, GPTQ, TTFT, Server-Sent Events.","Explains reducing inference latency and VRAM usage via INT8/FP16 post-training quantization (GPTQ, bitsandbytes).","Describes streaming responses via FastAPI Server-Sent Events (SSE) to optimize perceived latency and Time-to-First-Token (TTFT)."]},{"id":"KP2","description":"Vector search efficiency, indexing, and semantic caching","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, M, ef, Redis semantic cache, similarity threshold.","Describes configuring Milvus HNSW indexing parameters (M, ef) to balance recall against sub-20ms search latency.","Explains using Redis for semantic prompt/response caching to completely bypass model inference for frequent or identical queries."]},{"id":"KP3","description":"Horizontal scalability and infrastructure resource allocation","required":true,"acceptable_evidence":["Technical keywords: Kubernetes HPA, EKS, GPU utilization, TorchServe sidecar, autoscaling.","Explains decoupling stateless API services from model serving backends (e.g. TorchServe / Triton) on Kubernetes.","Describes autoscaling pods using Kubernetes HPA based on custom metrics like GPU memory saturation or queue length."]},{"id":"KP4","description":"Cost governance, token budgeting, and model routing","required":false,"acceptable_evidence":["Technical keywords: token budget, cost per query, model routing, small language models, SLM.","Discusses routing queries dynamically between smaller, low-cost models and large foundational LLMs based on query complexity.","Explains setting token budget limits per user session to avoid runaway cloud expenditure."]}],"critical_failures":["Fails to address model inference resource constraints (GPU memory, VRAM) or inference latency bottlenecks.","Omits caching or quantization techniques when discussing AI system efficiency."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What feedback was received from previous interview rounds, and how can it be used to improve performance in future interviews?', '{"key_points":[{"id":"KP1","description":"Technical depth and concrete architectural grounding","required":true,"acceptable_evidence":["Technical keywords: Milvus HNSW, Redis TTL, PostgreSQL indexing, concrete parameters, production trade-offs.","Identifies feedback recommending deeper specificity: replacing generic diagrams with concrete technologies (Milvus, Redis, PostgreSQL).","Provides exact operational parameters (e.g. HNSW M/ef parameters, cache eviction strategies) rather than abstract concepts."]},{"id":"KP2","description":"Structured communication and explicit trade-off articulation","required":true,"acceptable_evidence":["Technical keywords: trade-off analysis, failure modes, SLA, latency vs recall, consistency vs availability.","Explains adopting a structured framework: clarifying requirements, presenting high-level architecture, deep-diving bottlenecks, and handling edge cases.","Explicitly evaluates trade-offs (e.g., memory overhead vs search latency in HNSW, or eventual consistency in Redis caches)."]},{"id":"KP3","description":"Proactive failure mode analysis and observability","required":true,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, circuit breaker, dead-letter queue, chaos testing.","Incorporate feedback by proactively discussing system failure modes, fallback mechanisms, and circuit breakers.","Describes defining observability metrics (P95/P99 latency, error rates) and health checks from the outset of system design."]}],"critical_failures":["Provides superficial personal feedback without technical reflection or architectural improvements.","Fails to demonstrate actionable methods for articulating engineering trade-offs or technical depth."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What guardrails did you implement to prevent unsafe SQL operations, and how effective were they?', '{"key_points":[{"id":"KP1","description":"Database-level privilege isolation and query execution limits","required":true,"acceptable_evidence":["Technical keywords: read-only role, GRANT SELECT, statement_timeout, schema isolation, least privilege.","Explains enforcing the principle of least privilege using dedicated read-only PostgreSQL database users restricted to SELECT permissions.","Sets PostgreSQL statement_timeout (e.g., 5000ms) to automatically kill runaway queries or Cartesian joins."]},{"id":"KP2","description":"Deterministic AST parsing and query validation","required":true,"acceptable_evidence":["Technical keywords: SQLGlot, AST parsing, sqlfluff, DDL, DML, DROP, DELETE, UPDATE.","Explains parsing LLM-generated SQL into an Abstract Syntax Tree (AST) using SQLGlot to inspect statement types.","Deterministically blocks any destructive DDL/DML statements (DROP, TRUNCATE, DELETE, ALTER, INSERT, UPDATE) before execution."]},{"id":"KP3","description":"Human-in-the-loop (HITL) escalation via LangGraph checkpoints","required":true,"acceptable_evidence":["Technical keywords: LangGraph, HITL, human-in-the-loop, interrupt, checkpoint, approval workflow.","Describes using LangGraph interrupt points to pause workflow execution when ambiguous or high-risk queries are generated.","Requires explicit administrative or human-in-the-loop approval before executing queries flagged as sensitive."]},{"id":"KP4","description":"Audit logging, monitoring, and efficacy measurement","required":false,"acceptable_evidence":["Technical keywords: audit trail, PostgreSQL audit log, false positives, injection escapes, zero-injection.","Maintains a complete audit trail of user prompts, generated SQL, AST parse verdicts, and execution outcomes.","Measures effectiveness through zero unauthorized data modifications and low false-positive query rejection rates."]}],"critical_failures":["Relies entirely on LLM system prompt instructions without deterministic software or database-level guardrails.","Fails to implement read-only database user credentials or AST parsing to block destructive SQL statements."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What improvements would you make to align this prototype with real-world API design practices?', '{"key_points":[{"id":"KP1","description":"Strict schema validation and API versioning","required":true,"acceptable_evidence":["Technical keywords: Pydantic v2, OpenAPI, URI versioning, /api/v1, schema contract.","Explains defining strict request and response schemas using Pydantic v2 models, preventing malformed payload processing.","Describes introducing URI path versioning (e.g., /api/v1/) to enable backward-compatible schema evolutions."]},{"id":"KP2","description":"Standardized authentication, authorization, and security","required":true,"acceptable_evidence":["Technical keywords: JWT, OAuth2, RBAC, HTTPS, CORS middleware, rate limiting.","Explains securing endpoints using OAuth2 password bearer tokens and JWT validation with Role-Based Access Control (RBAC).","Describes configuring CORS middleware and ensuring sensitive internal stack traces are sanitized from production error responses."]},{"id":"KP3","description":"Rate limiting, idempotency, and error standardization","required":true,"acceptable_evidence":["Technical keywords: Redis token bucket, Idempotency-Key, RFC 7807, HTTP status codes, 422 Unprocessable Entity.","Describes implementing Redis-backed token bucket rate limiting to prevent API abuse.","Advocates supporting Idempotency-Key headers for mutation endpoints and returning standardized RFC 7807 error responses."]},{"id":"KP4","description":"Production health checks and distributed observability","required":false,"acceptable_evidence":["Technical keywords: /healthz, /readyz, Prometheus, OpenTelemetry, correlation ID, structured logging.","Describes adding Kubernetes liveness (/healthz) and readiness (/readyz) probes to verify downstream database connectivity.","Explains injecting correlation IDs into headers and structured JSON logs for distributed request tracing across services."]}],"critical_failures":["Omits input validation (e.g., accepts unstructured dictionaries without Pydantic schemas) and lacks API versioning.","Fails to address authentication, authorization, or rate limiting in production API design."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What interests or motivations would drive you to join a startup environment compared to a more established company?', '{"key_points":[{"id":"KP1","description":"End-to-end architectural ownership and broad technical scope","required":true,"acceptable_evidence":["Technical keywords: end-to-end ownership, full lifecycle, FastAPI, Milvus, Kubernetes, cross-functional.","Emphasizes the desire to own the complete system lifecycle from data ingestion and model serving to frontend integration and cloud deployment.","Contrasts full architectural ownership in startups against narrow, siloed roles in large enterprises."]},{"id":"KP2","description":"Fast decision velocity and rapid feedback cycles","required":true,"acceptable_evidence":["Technical keywords: iteration speed, rapid feedback loop, CI/CD, A/B testing, user feedback.","Explains how short iteration cycles and continuous deployment allow rapid prototyping and immediate user feedback.","Contrasts lean decision-making in startups with lengthy bureaucratic approval processes in mature corporations."]},{"id":"KP3","description":"Pragmatic problem solving and navigating ambiguity","required":true,"acceptable_evidence":["Technical keywords: technical debt, pragmatic engineering, MVP, zero-to-one, resource constraints.","Discusses thriving in ambiguous environments where engineers must balance speed-to-market with sound architectural foundations.","Explains making pragmatic trade-offs between technical debt and product velocity during 0-to-1 build phases."]}],"critical_failures":["Focuses exclusively on financial perks or equity speculation without discussing technical ownership or engineering challenges.","Fails to acknowledge the trade-offs of resource constraints, ambiguity, and rapid pivots in startup environments."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is HNSW indexing, and how does it improve vector search performance?', '{"key_points":[{"id":"KP1","description":"Hierarchical multi-layer graph architecture","required":true,"acceptable_evidence":["Technical keywords: Hierarchical Navigable Small World, multi-layer graph, skip-list, coarse routing, fine search.","Explains that HNSW organizes vector embeddings into a multi-layered graph hierarchy inspired by probabilistic skip-lists.","Describes how top layers contain sparser graphs with long-range links for rapid coarse routing, while bottom layers contain dense local graphs for fine-grained nearest neighbor search."]},{"id":"KP2","description":"Logarithmic search complexity and greedy search routing","required":true,"acceptable_evidence":["Technical keywords: O(log N), approximate nearest neighbor, ANN, greedy search, entry point.","Explains that HNSW achieves O(log N) approximate nearest neighbor (ANN) search complexity compared to O(N) brute-force flat search.","Details the search mechanism: greedy routing at upper layers until a local minimum is reached, which serves as the entry point for the layer below."]},{"id":"KP3","description":"Key indexing and search hyperparameters (M, ef_construction, ef)","required":true,"acceptable_evidence":["Technical keywords: Milvus, M, ef_construction, ef, efSearch, recall vs latency.","Defines Milvus HNSW parameters: M is the maximum number of bidirectional connections per node, and ef_construction controls search scope during graph construction.","Explains that query-time parameter ef (or efSearch) controls the beam search size, allowing dynamic adjustment between higher recall and lower query latency."]},{"id":"KP4","description":"Performance trade-offs and memory utilization compared to IVF-PQ","required":false,"acceptable_evidence":["Technical keywords: IVF-PQ, Flat, recall, memory footprint, MMAP disk-backed.","Contrasts HNSW against IVF-PQ: HNSW offers superior recall (>98%) and lower latency at the expense of substantial memory overhead for storing graph edges.","Mentions using Milvus MMAP disk-backed storage to mitigate RAM saturation while preserving fast graph traversal."]}],"critical_failures":["Confuses HNSW graph structure with tree-based (KD-tree) or inverted file clustering (IVF) index methods.","Fails to explain the role of hyper-parameters M or ef in controlling the recall-versus-latency trade-off."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What is micro-frontend architecture, and how do you design and integrate multiple micro-frontends in a single application?', '{"key_points":[{"id":"KP1","description":"Architectural principles and Host/Shell vs Remote container separation","required":true,"acceptable_evidence":["Technical keywords: micro-frontend, Shell, Host application, Remote container, independent deployment.","Explains decomposing monolithic frontends into independent, domain-driven micro-apps developed and deployed by separate teams.","Describes a Shell/Host application that handles top-level routing, shared authentication, and dynamic container loading of Remote micro-frontends."]},{"id":"KP2","description":"Runtime integration via Webpack 5 Module Federation","required":true,"acceptable_evidence":["Technical keywords: Webpack 5, Module Federation, remoteEntry.js, shared dependencies, singleton.","Explains using Webpack 5 Module Federation to dynamically load remote JavaScript bundles (remoteEntry.js) at runtime without rebuilding the host.","Details configuring shared dependencies (e.g. React, ReactDOM) as singletons to prevent loading duplicate runtime libraries in the browser."]},{"id":"KP3","description":"Cross-micro-frontend communication and state sharing","required":true,"acceptable_evidence":["Technical keywords: CustomEvent, EventBus, window.postMessage, decoupled communication, publish-subscribe.","Describes decoupled communication mechanisms: utilizing custom DOM CustomEvents, an EventBus, or window.postMessage.","Warns against coupling micro-frontends through monolithic shared state stores (e.g. single shared Redux store), preserving team autonomy."]},{"id":"KP4","description":"Styling isolation and DOM sandboxing","required":true,"acceptable_evidence":["Technical keywords: CSS Modules, Shadow DOM, Tailwind prefix, iframe, style leakage.","Explains preventing CSS leakage and global namespace collisions using CSS Modules, scoped Tailwind CSS prefixes, or Web Components Shadow DOM.","Discusses using iframes when strict security sandboxing is required for third-party or untrusted micro-frontends."]},{"id":"KP5","description":"Resilience, error boundaries, and independent CI/CD","required":false,"acceptable_evidence":["Technical keywords: Error Boundary, fallback UI, independent CI/CD, canary deployment.","Explains wrapping remote components in React Error Boundaries to display fallback UI if a remote service fails or times out.","Highlights independent CI/CD deployment pipelines per remote, enabling canary releases without global application redeployments."]}],"critical_failures":["Suggests compiling all micro-frontends together into a single build-time npm bundle rather than dynamic runtime integration.","Fails to address CSS style encapsulation or cross-application communication decoupling, causing global namespace collisions."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What is model quantization, and how does it improve model efficiency and latency?', '{"key_points":[{"id":"KP1","description":"Precision reduction principles and numerical representation","required":true,"acceptable_evidence":["Technical keywords: FP32, FP16, INT8, INT4, FP8, scale factor, zero-point.","Explains mapping high-precision 32-bit or 16-bit floating point weights and activations to lower bit-width integers (INT8, INT4, FP8).","Describes the mathematical conversion using scaling factors and zero-point offsets to represent weight tensors in compact formats."]},{"id":"KP2","description":"Memory footprint and GPU VRAM reduction","required":true,"acceptable_evidence":["Technical keywords: VRAM, memory footprint, 4x reduction, 70B model, single GPU.","Explains that INT8 quantization reduces model memory footprint by ~2x compared to FP16 (and 4x compared to FP32), while INT4 achieves ~4x reduction over FP16.","Demonstrates how this enables serving large models (e.g., 70B parameter models) on fewer or smaller GPUs (e.g., fitting within 48GB/80GB VRAM)."]},{"id":"KP3","description":"Latency reduction and memory bandwidth bottleneck mitigation","required":true,"acceptable_evidence":["Technical keywords: memory-bandwidth bound, autoregressive decoding, INT8 Tensor Cores, inference latency.","Explains that autoregressive LLM token generation is predominantly memory-bandwidth bound (reading weights from GPU HBM into cache for every token).","Shows that transferring smaller quantized weights across the memory bus significantly reduces per-token decoding latency and leverages specialized INT8/INT4 Tensor Cores."]},{"id":"KP4","description":"Quantization techniques and accuracy trade-offs","required":false,"acceptable_evidence":["Technical keywords: PTQ, QAT, GPTQ, bitsandbytes, AWQ, calibration dataset, perplexity.","Distinguishes Post-Training Quantization (PTQ using GPTQ, AWQ, or bitsandbytes) using calibration sets from Quantization-Aware Training (QAT).","Discusses evaluating accuracy degradation and perplexity increases against task-specific validation metrics."]}],"critical_failures":["Confuses model quantization (precision reduction) with pruning (zeroing out weights) or knowledge distillation.","Claims quantization speeds up compute without acknowledging GPU memory bandwidth as the primary bottleneck in autoregressive token generation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is the difference between an API gateway and a load balancer?', '{"key_points":[{"id":"KP1","description":"Operating layers (OSI model) and core architectural focus","required":true,"acceptable_evidence":["Technical keywords: Layer 4, Layer 7, OSI model, transport layer, application layer, reverse proxy.","Explains that load balancers operate at Layer 4 (TCP/UDP, e.g. AWS NLB) or Layer 7 (HTTP, e.g. AWS ALB) focusing on distributing traffic across compute instances based on health checks.","States that API gateways operate strictly at Layer 7 as an intelligent application reverse proxy providing high-level API management."]},{"id":"KP2","description":"Feature set differences: API management vs traffic distribution","required":true,"acceptable_evidence":["Technical keywords: JWT validation, rate limiting, request transformation, OpenAPI, routing, SSL termination.","Identifies API gateway specific features: authentication (OAuth2/JWT), token bucket rate limiting, request/response transformation, API versioning, and policy enforcement.","Identifies load balancer features: SSL termination, high-throughput packet routing, session persistence, and instance health probing."]},{"id":"KP3","description":"Architectural coexistence in production systems","required":true,"acceptable_evidence":["Technical keywords: AWS API Gateway, EKS ingress, ALB, layered architecture, microservices.","Explains how both technologies work together: an external load balancer receives internet traffic and routes it to an API gateway cluster, which validates requests and forwards them to internal service pods.","Cites production deployments combining AWS API Gateway with Kubernetes Ingress controllers (ALB) on EKS."]}],"critical_failures":["Claims that API gateways and load balancers are interchangeable or identical in functionality.","Fails to identify Layer 7 API policy enforcement (authentication, rate limiting, transformation) as the distinguishing factor of an API gateway."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is the purpose of indexing in databases, and how does it improve query performance?', '{"key_points":[{"id":"KP1","description":"Mechanism: eliminating sequential table scans via auxiliary data structures","required":true,"acceptable_evidence":["Technical keywords: sequential scan, full table scan, B-tree, O(log N), pointer, index lookup.","Explains that indexes create auxiliary data structures holding sorted column keys and row pointers (TIDs), transforming O(N) full table scans into O(log N) tree traversals.","Describes how the database engine can seek directly to matching rows rather than reading every data block from disk."]},{"id":"KP2","description":"Specific index types and specialized use cases","required":true,"acceptable_evidence":["Technical keywords: B-tree, GIN, BRIN, JSONB, composite index, partial index.","Details specific index types: B-tree for standard equality/range queries, GIN (Generalized Inverted Index) for PostgreSQL JSONB arrays and full-text search, and BRIN for append-only time-series tables.","Mentions composite indexes for multi-column filtering and partial indexes for sparse condition queries."]},{"id":"KP3","description":"Query plan verification and column selectivity","required":true,"acceptable_evidence":["Technical keywords: EXPLAIN ANALYZE, cardinality, selectivity, query planner, index scan.","Explains validating index effectiveness using EXPLAIN ANALYZE to verify index scan vs seq scan in PostgreSQL.","Discusses how column cardinality affects selectivity: high-cardinality columns benefit significantly, whereas low-cardinality columns may still default to sequential scans."]},{"id":"KP4","description":"Write amplification and maintenance trade-offs","required":false,"acceptable_evidence":["Technical keywords: write amplification, INSERT overhead, UPDATE penalty, disk storage, index bloat.","Explains the trade-off: every index improves read performance but introduces write amplification, slowing down INSERT, UPDATE, and DELETE operations.","Discusses the disk space overhead of storing index pages and the need to monitor index bloat."]}],"critical_failures":["Claims database indexes improve write (INSERT/UPDATE) performance.","Fails to explain the underlying data structure mechanism (e.g. B-tree logarithmic search) or omits write overhead trade-offs."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your approach to moving a model from development to production and maintaining its performance over time?', '{"key_points":[{"id":"KP1","description":"Experiment tracking, model registry, and containerized packaging","required":true,"acceptable_evidence":["Technical keywords: MLflow, model registry, DVC, Docker, artifacts, versioning.","Explains logging hyperparameters, metrics, and model artifacts using MLflow and versioning training data with DVC.","Describes promoting models through MLflow Model Registry stages (Staging -> Production) and packaging models into reproducible Docker containers."]},{"id":"KP2","description":"Deployment strategies and serving infrastructure","required":true,"acceptable_evidence":["Technical keywords: blue-green deployment, canary release, Kubernetes, FastAPI, TorchServe.","Explains deploying containerized inference services on Kubernetes (EKS) using Canary or Blue-Green deployment strategies.","Validates latency and error rate metrics on a small traffic percentage before routing 100% of production traffic."]},{"id":"KP3","description":"Continuous production monitoring and drift detection","required":true,"acceptable_evidence":["Technical keywords: Evidently AI, Prometheus, Grafana, data drift, concept drift, feature drift.","Describes tracking operational metrics (latency, RPS, error rates) in Prometheus and Grafana.","Explains monitoring statistical feature drift and prediction drift against training baselines using Evidently AI."]},{"id":"KP4","description":"Automated retraining triggers and feedback loops","required":false,"acceptable_evidence":["Technical keywords: Prefect, Airflow, automated retraining, ground truth collection, CI/CD pipeline.","Describes triggering automated retraining pipelines via Prefect or Airflow when drift alerts or performance degradation thresholds are reached.","Explains collecting ground-truth labels and maintaining automated regression test suites before updating production weights."]}],"critical_failures":["Describes manual model deployment (e.g., copying pickle files directly to a virtual machine) without versioning or registry controls.","Fails to implement ongoing production monitoring for data or concept drift."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is your experience with Python, and how have you used it in AI/ML or backend development?', '{"key_points":[{"id":"KP1","description":"Asynchronous backend development and high-throughput microservices","required":true,"acceptable_evidence":["Technical keywords: FastAPI, asyncio, httpx, asyncpg, event loop, non-blocking I/O.","Explains building asynchronous web services using FastAPI and asyncio for non-blocking I/O operations.","Mentions integrating async database drivers (asyncpg) and HTTP clients (httpx.AsyncClient) to achieve high concurrent throughput."]},{"id":"KP2","description":"AI/ML engineering and agentic pipeline orchestration","required":true,"acceptable_evidence":["Technical keywords: LangGraph, LangChain, PyTorch, XGBoost, Milvus SDK, embeddings.","Describes developing stateful multi-agent workflows using LangGraph and LangChain.","Details integrating PyTorch/XGBoost models and interacting with vector databases using the Milvus Python SDK."]},{"id":"KP3","description":"Data processing, strict typing, and validation","required":true,"acceptable_evidence":["Technical keywords: Pydantic v2, PySpark, pandas, type hints, mypy.","Explains utilizing Pydantic v2 for strict schema definition, serialization, and runtime input validation.","Discusses manipulating large datasets with PySpark or pandas and enforcing code quality with Python type hints and mypy."]},{"id":"KP4","description":"Testing, profiling, and code performance optimization","required":false,"acceptable_evidence":["Technical keywords: pytest, cProfile, py-spy, test coverage, mocking.","Describes writing automated unit and integration tests using pytest and httpx TestClient.","Mentions profiling memory and CPU bottlenecks using cProfile or py-spy."]}],"critical_failures":["Fails to cite modern Python ecosystem libraries used in real systems (mentions only basic syntax like lists and loops).","Confuses Python\'s Global Interpreter Lock (GIL) and asyncio event-loop concurrency with true multi-process parallelism."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your experience with backend development, including building APIs and integrating databases with ML systems?', '{"key_points":[{"id":"KP1","description":"High-performance API development and schema contracts","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Pydantic v2, RESTful, dependency injection, OpenAPI.","Explains designing RESTful APIs using FastAPI with asynchronous route handlers and dependency injection for auth/database sessions.","Emphasizes strict request and response schema contracts using Pydantic v2."]},{"id":"KP2","description":"Heterogeneous database integration (Relational, Vector, Graph)","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, asyncpg, Milvus, Neo4j, connection pooling.","Describes integrating PostgreSQL with asyncpg connection pooling for transactional metadata and conversation history.","Details connecting Milvus for dense vector search and Neo4j for knowledge graph entity retrieval."]},{"id":"KP3","description":"Distributed caching and low-latency state management","required":true,"acceptable_evidence":["Technical keywords: Redis, TTL, session store, query caching, cache invalidation.","Explains using Redis for session caching, rate limiting, and prompt/response caching with configured TTLs.","Discusses reducing database and LLM compute load by serving cached state."]},{"id":"KP4","description":"Asynchronous task decoupling for compute-heavy ML workloads","required":false,"acceptable_evidence":["Technical keywords: AWS SQS, Celery, background tasks, non-blocking, worker pool.","Explains decoupling long-running ML feature computation or heavy inference jobs from HTTP request cycles via SQS queues or Celery workers.","Returns 202 Accepted with polling/webhook mechanisms to maintain low HTTP latency."]}],"critical_failures":["Runs heavy, long-running ML model inference synchronously inside the web request loop without timeouts or queue decoupling.","Fails to implement database connection pooling or caching, causing database connection exhaustion under load."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your experience with backend services and how do they integrate with ML/AI models?', '{"key_points":[{"id":"KP1","description":"Decoupled architecture: API orchestration vs dedicated model serving","required":true,"acceptable_evidence":["Technical keywords: FastAPI, TorchServe, Triton, gRPC, microservices, separation of concerns.","Explains decoupling the backend orchestration service (FastAPI) from specialized model serving engines (TorchServe / Triton).","Highlights that model serving requires specialized GPU resources and dynamic batching, which should be isolated from web API pods."]},{"id":"KP2","description":"Low-latency inter-service communication protocols","required":true,"acceptable_evidence":["Technical keywords: gRPC, HTTP/2, Protobuf, serialization, keep-alive.","Describes using gRPC or persistent HTTP/2 connections between FastAPI and inference engines to minimize serialization overhead.","Contrasts high-speed binary Protobuf serialization with standard JSON overhead for heavy tensor data."]},{"id":"KP3","description":"Real-time streaming and async response delivery","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events, SSE, WebSockets, StreamingResponse, TTFT.","Explains implementing Server-Sent Events (SSE) or WebSockets in FastAPI to stream LLM tokens to the client in real time.","Discusses how streaming drastically reduces Time-to-First-Token (TTFT) and improves user experience."]},{"id":"KP4","description":"Resilience, timeout boundaries, and circuit breaking","required":false,"acceptable_evidence":["Technical keywords: circuit breaker, timeout, fallback response, exponential backoff, retry.","Describes establishing strict timeout boundaries and circuit breakers on inference calls to prevent thread pool exhaustion.","Implements fallback responses or cached outputs when downstream AI model services degrade or time out."]}],"critical_failures":["Suggests embedding heavy deep learning models directly inside web server processes without resource isolation or GPU memory controls.","Omits token streaming or timeout handling when discussing integration with high-latency LLM models."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your experience with frontend and backend integration, and how have you used React and FastAPI in your projects?', '{"key_points":[{"id":"KP1","description":"Asynchronous streaming protocols (SSE / WebSockets)","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events, SSE, EventSource, fetch streaming, StreamingResponse, React state.","Explains integrating React with FastAPI StreamingResponse using the EventSource API or the ReadableStream fetch API.","Describes consuming incoming token chunks in React to incrementally update state and render streaming text in real time."]},{"id":"KP2","description":"API schema alignment, OpenAPI, and type synchronization","required":true,"acceptable_evidence":["Technical keywords: OpenAPI, Pydantic v2, TypeScript, openapi-typescript, schema generation.","Explains utilizing FastAPI\'s auto-generated OpenAPI JSON specification to generate TypeScript interfaces for the React frontend.","Highlights how Pydantic models on the backend synchronize with frontend TypeScript types to prevent runtime contract mismatches."]},{"id":"KP3","description":"Authentication state, token propagation, and CORS","required":true,"acceptable_evidence":["Technical keywords: JWT, HTTP-only cookies, Authorization header, CORS middleware, Bearer token.","Describes passing JWT bearer tokens via HTTP headers or secure HTTP-only cookies from React to FastAPI.","Details configuring CORSMiddleware in FastAPI with explicit allowed origins, methods, and credentials."]},{"id":"KP4","description":"UI state management, error boundaries, and optimistic updates","required":false,"acceptable_evidence":["Technical keywords: React Query, TanStack Query, Error Boundary, optimistic update, loading state.","Explains using TanStack Query (React Query) for server-state caching, automatic refetching, and error handling.","Describes handling 4xx/5xx API errors gracefully using React Error Boundaries and contextual toast alerts."]}],"critical_failures":["Fails to explain how real-time streaming (SSE / EventSource) is handled between FastAPI and React.","Ignores authentication propagation or CORS security configuration in the integration architecture."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is your process for using tools like Postman to validate APIs and debug request-response cycles?', '{"key_points":[{"id":"KP1","description":"Environment management and dynamic authentication automation","required":true,"acceptable_evidence":["Technical keywords: environment variables, pre-request scripts, JWT, Bearer token, pm.environment.set.","Explains organizing endpoints into modular collections and configuring environment variables for dev, staging, and production URLs.","Describes using pre-request scripts to automatically obtain JWT bearer tokens and inject them into request Authorization headers."]},{"id":"KP2","description":"Automated assertion testing and JSON schema validation","required":true,"acceptable_evidence":["Technical keywords: pm.test, pm.expect, status 200, JSON schema, Pydantic validation.","Details writing automated JavaScript test scripts using pm.test and pm.expect to assert HTTP response status codes (200, 201, 422).","Explains asserting response payload structures against JSON schemas generated from Pydantic backend models."]},{"id":"KP3","description":"Debugging edge cases and analyzing request-response diagnostics","required":true,"acceptable_evidence":["Technical keywords: response headers, latency, 422 Unprocessable Entity, Postman Console, network diagnostics.","Explains inspecting HTTP headers, response times, and status codes in the Postman Console to diagnose edge cases.","Describes debugging FastAPI 422 validation errors by analyzing the detailed loc and msg payload error structures."]}],"critical_failures":["Treats Postman solely as a manual UI click-through tool without mentioning environment variables or automated test scripts.","Fails to explain validating status codes, response headers, or JSON schema payloads."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What kinds of issues arise in dynamically typed languages, and how can they impact performance and reliability?', '{"key_points":[{"id":"KP1","description":"Runtime reliability hazards and delayed error detection","required":true,"acceptable_evidence":["Technical keywords: TypeError, AttributeError, NoneType, runtime exceptions, compile-time checks.","Explains that dynamic typing defers type checking to runtime, allowing fatal bugs (e.g. AttributeError, TypeError) to reach production without compiler warnings.","Discusses edge cases where unexpected None values or missing dictionary keys trigger runtime application crashes."]},{"id":"KP2","description":"Performance penalties: dynamic dispatch and object boxing","required":true,"acceptable_evidence":["Technical keywords: dynamic dispatch, boxing, unboxing, PyObject, interpreter overhead, CPU cache.","Details runtime performance overhead: every variable operation requires dynamic type inspection and method lookup in __dict__.","Explains that generic boxed objects (e.g. PyObject pointers) degrade CPU cache locality compared to packed native primitive arrays in compiled languages."]},{"id":"KP3","description":"Refactoring complexity and maintainability challenges","required":true,"acceptable_evidence":["Technical keywords: refactoring, IDE support, technical debt, code readability, contract drift.","Discusses how the absence of static type signatures makes large-scale refactoring error-prone across distributed services.","Explains that developers must inspect runtime data structures manually, slowing onboarding and increasing cognitive load."]},{"id":"KP4","description":"Modern mitigation techniques in Python","required":false,"acceptable_evidence":["Technical keywords: type hints, mypy, pyright, Pydantic v2, runtime validation.","Describes introducing static type hints and running CI type checkers (mypy, pyright) to catch type mismatches before deployment.","Mentions enforcing strict runtime validation contracts at API boundaries using Pydantic v2."]}],"critical_failures":["Claims dynamic typing carries no runtime performance penalty or that runtime errors are caught without testing/static analysis.","Fails to identify practical mitigation tools in Python such as Pydantic validation or static type checkers (mypy)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What role did API Gateway play in your system, and why did you choose it over alternatives like AI Gateway?', '{"key_points":[{"id":"KP1","description":"Edge infrastructure responsibilities and unified traffic entry","required":true,"acceptable_evidence":["Technical keywords: AWS API Gateway, SSL termination, AWS WAF, CORS, reverse proxy.","Explains using API Gateway as the centralized edge entry point for all client requests, handling SSL termination and CORS policies.","Describes integrating AWS WAF at the gateway level to defend against DDoS attacks, SQL injection, and malicious bot traffic."]},{"id":"KP2","description":"Authentication, authorization, and tenant rate limiting","required":true,"acceptable_evidence":["Technical keywords: JWT authorizer, Cognito, OAuth2, token bucket, throttling, 429.","Explains using API Gateway Lambda/JWT authorizers to authenticate tokens before requests enter internal VPC microservices.","Describes configuring usage plans and token-bucket throttling per API key or tenant to prevent service starvation."]},{"id":"KP3","description":"Architectural rationale vs specialized AI Gateway","required":true,"acceptable_evidence":["Technical keywords: AI Gateway, LiteLLM, Portkey, VPC integration, enterprise compliance, separation of concerns.","Explains choosing a traditional API Gateway (AWS API Gateway) for its mature VPC networking, IAM integration, and enterprise compliance.","Notes that LLM-specific features (prompt routing, fallback, token tracking) were decoupled into internal FastAPI middleware/LangGraph nodes rather than relying on an external third-party AI proxy."]},{"id":"KP4","description":"Separation of concerns between edge routing and AI application logic","required":false,"acceptable_evidence":["Technical keywords: vendor lock-in, decoupling, observability, microservices.","Emphasizes avoiding vendor lock-in to nascent AI gateway startups by keeping standard edge policies at the API Gateway level.","Maintains a clean architectural separation between network edge security and domain-specific LLM orchestration."]}],"critical_failures":["Confuses standard Layer 7 infrastructure edge capabilities (auth, WAF, rate limiting) with AI application logic.","Fails to explain the architectural trade-offs between an infrastructure API Gateway and an AI proxy (e.g., VPC security vs model routing)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What role does Python play in your system, and why did you choose FastAPI for microservices?', '{"key_points":[{"id":"KP1","description":"Python as the foundational ecosystem for AI/ML engineering","required":true,"acceptable_evidence":["Technical keywords: PyTorch, LangGraph, Milvus SDK, PySpark, native integration.","Explains that Python provides native interoperability with core AI and data engineering libraries (LangGraph, PyTorch, Milvus, PySpark).","Highlights eliminating inter-process serialization overhead by keeping orchestration and AI tool execution in a single language ecosystem."]},{"id":"KP2","description":"FastAPI asynchronous concurrency for I/O-bound operations","required":true,"acceptable_evidence":["Technical keywords: FastAPI, asyncio, Starlette, Uvicorn, non-blocking I/O, event loop.","Explains choosing FastAPI due to native asyncio support on Uvicorn, handling thousands of concurrent I/O connections efficiently.","Describes how non-blocking coroutines allow overlapping vector searches, database reads, and external LLM calls without thread pool exhaustion."]},{"id":"KP3","description":"High-performance data validation via Pydantic v2","required":true,"acceptable_evidence":["Technical keywords: Pydantic v2, Rust core, serialization, OpenAPI, Swagger.","Highlights Pydantic v2\'s Rust-compiled core, delivering sub-millisecond JSON parsing and schema validation.","Mentions automatic generation of OpenAPI/Swagger interactive documentation directly from Python type annotations."]},{"id":"KP4","description":"Developer velocity and lightweight footprint vs heavy frameworks","required":false,"acceptable_evidence":["Technical keywords: Django, Flask, dependency injection, container footprint, microservices.","Contrasts FastAPI\'s lightweight dependency injection and minimal memory footprint against monolithic frameworks like Django.","Emphasizes fast container startup times and rapid development velocity for microservices."]}],"critical_failures":["Claims FastAPI uses OS multi-threading for CPU-bound tasks instead of explaining its asynchronous non-blocking event-loop architecture.","Omits Pydantic schema validation or native async support as primary reasons for choosing FastAPI."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What strategies did you use to ensure data validation and consistent model performance in production systems?', '{"key_points":[{"id":"KP1","description":"Ingestion schema enforcement and input validation","required":true,"acceptable_evidence":["Technical keywords: Pydantic v2, schema validation, 422 Unprocessable Entity, type constraints, boundary checks.","Explains enforcing strict Pydantic v2 schemas at the API boundary, validating data types, string formats, and numerical bounds.","Rejects malformed inputs with descriptive 422 status codes before data reaches downstream inference pipelines."]},{"id":"KP2","description":"Data and feature drift monitoring","required":true,"acceptable_evidence":["Technical keywords: Evidently AI, Kolmogorov-Smirnov test, Wasserstein distance, feature drift, baseline distribution.","Describes monitoring production inference payloads against baseline training distributions using Evidently AI.","Explains using statistical metrics (KS-test, Wasserstein distance) to detect covariate shift and feature drift in real time."]},{"id":"KP3","description":"Automated model evaluation and output quality metrics","required":true,"acceptable_evidence":["Technical keywords: RAGAS, faithfulness, context precision, answer relevancy, golden dataset.","Explains evaluating production model outputs using RAGAS metrics (faithfulness, context precision, answer relevancy) or precision/recall benchmarks.","Maintains versioned golden test sets to evaluate model responses continuously against ground truth."]},{"id":"KP4","description":"Deployment validation gates and automated canary rollbacks","required":false,"acceptable_evidence":["Technical keywords: canary release, MLflow registry, Prometheus alerts, automated rollback.","Describes gating production deployments through MLflow staging tests and canary deployments.","Configures Prometheus alerts to trigger automated rollbacks if latency or drift metrics violate predefined thresholds."]}],"critical_failures":["Relies exclusively on manual spot-checking without automated schema validation or drift monitoring frameworks.","Fails to distinguish between input validation (schemas/types) and post-deployment model performance/drift monitoring."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What strategies did you use to reduce latency in your application, and how did you measure it?', '{"key_points":[{"id":"KP1","description":"Multi-tier caching to eliminate redundant computations","required":true,"acceptable_evidence":["Technical keywords: Redis, TTL, semantic cache, prompt caching, cache hit rate.","Explains deploying Redis caching with TTLs for frequent user queries and session states, avoiding repeated database and LLM calls.","Describes using semantic vector caching to serve instant responses for semantically identical questions."]},{"id":"KP2","description":"Vector search index optimization and partition filtering","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, M, ef, partition key, sub-20ms.","Details tuning Milvus HNSW indexing parameters: reducing ef search beam size to achieve sub-20ms vector retrieval while preserving high recall.","Utilizes partition keys (e.g. tenant or date) to filter search spaces and eliminate full-collection traversals."]},{"id":"KP3","description":"Asynchronous streaming and connection pooling","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events, SSE, TTFT, asyncpg, connection pooling, httpx AsyncClient.","Implements FastAPI Server-Sent Events (SSE) streaming to drastically minimize Time-to-First-Token (TTFT) perceived by users.","Configures persistent connection pools (asyncpg for PostgreSQL, httpx.AsyncClient for external APIs) to eliminate TCP handshake latency."]},{"id":"KP4","description":"Granular latency measurement and distributed tracing","required":false,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, P95, P99, LangSmith, OpenTelemetry, span latency.","Measures latency using P50, P95, and P99 percentiles in Prometheus and Grafana dashboards rather than deceptive averages.","Uses LangSmith or OpenTelemetry distributed tracing to break down per-span execution times across retrieval, reranking, and generation."]}],"critical_failures":["Measures latency solely via average/mean values without tracking tail latency (P95/P99) or span breakdowns.","Fails to provide concrete latency reduction mechanisms (omits caching, vector indexing, or connection pooling)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What strategies do you use to handle API failures in React applications, including error handling and recovery mechanisms?', '{"key_points":[{"id":"KP1","description":"React Error Boundaries for component crash isolation","required":true,"acceptable_evidence":["Technical keywords: Error Boundary, componentDidCatch, getDerivedStateFromError, fallback UI.","Explains wrapping UI component hierarchies with React Error Boundaries to catch unhandled rendering exceptions triggered by bad API responses.","Renders graceful localized fallback UI rather than letting the entire application crash to a blank white screen."]},{"id":"KP2","description":"Automated retry with exponential backoff and jitter","required":true,"acceptable_evidence":["Technical keywords: TanStack Query, React Query, exponential backoff, jitter, Axios interceptor, 5xx errors.","Describes using TanStack Query (React Query) or Axios interceptors to automatically retry failed idempotent requests on 5xx or network errors.","Applies exponential backoff with jitter to prevent retry storms from overwhelming struggling backend servers."]},{"id":"KP3","description":"In-flight request cancellation via AbortController","required":true,"acceptable_evidence":["Technical keywords: AbortController, signal, cleanup function, useEffect, race conditions, memory leaks.","Explains utilizing AbortController in useEffect cleanup functions to cancel pending API requests when components unmount.","Prevents race conditions, stale state updates, and memory leaks caused by responses resolving after navigation."]},{"id":"KP4","description":"User feedback, optimistic UI rollback, and state persistence","required":false,"acceptable_evidence":["Technical keywords: optimistic update, rollback, toast notification, localStorage, offline state.","Describes rolling back optimistic UI updates if the mutating API request fails.","Provides actionable user feedback via contextual toast notifications and manual retry buttons, preserving draft form inputs in state."]}],"critical_failures":["Uses empty catch blocks or unhandled promises that fail silently without notifying users or rendering fallback UI.","Fails to cancel in-flight requests using AbortController, causing race conditions or memory leaks upon component unmount."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What strategies would you use to reduce latency for APIs that process large volumes of data?', '{"key_points":[{"id":"KP1","description":"Cursor-based pagination vs offset pagination","required":true,"acceptable_evidence":["Technical keywords: cursor pagination, keyset pagination, OFFSET, indexed column, bounded payload.","Explains implementing cursor/keyset pagination (e.g. WHERE id > cursor LIMIT 50) instead of SQL OFFSET.","Highlights that cursor pagination avoids O(N) database row scanning on deep pages and keeps API response payloads bounded and fast."]},{"id":"KP2","description":"Streaming responses and chunked transfer encoding","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, Chunked Transfer Encoding, generators, FastAPI, memory backpressure.","Describes using FastAPI StreamingResponse with Python generators to stream data rows as they are fetched.","Avoids buffering massive multi-gigabyte payloads in backend memory, drastically reducing Time-to-First-Byte (TTFB)."]},{"id":"KP3","description":"Asynchronous job decoupling for heavy batch workloads","required":true,"acceptable_evidence":["Technical keywords: AWS SQS, Celery, 202 Accepted, worker pool, webhook, polling.","Explains converting large batch processing requests into asynchronous jobs: immediately returning HTTP 202 Accepted with a task ID.","Processes the heavy data transformation in background worker pools (SQS/Celery), notifying clients via webhooks or polling."]},{"id":"KP4","description":"Payload compression, connection pooling, and query optimization","required":false,"acceptable_evidence":["Technical keywords: Gzip, Brotli, asyncpg, EXPLAIN ANALYZE, projection, Redis.","Enables Gzip/Brotli compression middleware to reduce wire data transfer sizes over the network.","Applies database projection (selecting only required columns), connection pooling with asyncpg, and Redis caching for aggregate calculations."]}],"critical_failures":["Advocates loading entire massive datasets into application memory synchronously before returning a single giant JSON response.","Suggests using SQL OFFSET pagination for large tables without addressing the O(N) scan degradation of deep offsets."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What strategies would you use to reduce latency in a high-response-time system?', '{"key_points":[{"id":"KP1","description":"Distributed tracing and empirical bottleneck identification","required":true,"acceptable_evidence":["Technical keywords: OpenTelemetry, LangSmith, APM, span latency, flame graph, P99.","Advocates starting with distributed tracing (OpenTelemetry, LangSmith) to dissect per-service span latencies before optimizing.","Isolates whether the bottleneck originates from database locks, external API calls, serialization overhead, or CPU compute."]},{"id":"KP2","description":"Multi-tier caching architecture (in-memory and distributed)","required":true,"acceptable_evidence":["Technical keywords: Redis, TTL, LRU cache, semantic cache, cache hit ratio.","Implements distributed caching with Redis for database queries, session contexts, and vector search results with appropriate TTLs.","Uses local in-memory LRU caches for static configuration data to eliminate network round-trips."]},{"id":"KP3","description":"Database query optimization and connection pooling","required":true,"acceptable_evidence":["Technical keywords: EXPLAIN ANALYZE, B-tree index, GIN index, asyncpg, connection pooling, read replica.","Profiles slow queries using PostgreSQL EXPLAIN ANALYZE to eliminate sequential table scans by adding targeted B-tree or GIN indexes.","Configures connection pooling with asyncpg and directs read-heavy traffic to PostgreSQL read replicas."]},{"id":"KP4","description":"Asynchronous task offloading and concurrency optimization","required":false,"acceptable_evidence":["Technical keywords: asyncio.gather, SQS, background workers, non-blocking I/O.","Offloads non-critical writes, logging, and notifications to asynchronous message queues (SQS) outside the critical response path.","Executes independent I/O calls concurrently using asyncio.gather to overlap waiting times."]}],"critical_failures":["Prescribes optimizations blindly without profiling or identifying the root cause of the latency bottleneck.","Overlooks database indexing and caching, proposing only vertical server hardware scaling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What strategies would you use to scale the system as the user base and number of agencies grow rapidly?', '{"key_points":[{"id":"KP1","description":"Multi-tenant data isolation and partitioning strategies","required":true,"acceptable_evidence":["Technical keywords: multi-tenancy, Row-Level Security, RLS, tenant_id, schema-per-tenant, PostgreSQL.","Explains enforcing multi-tenant data isolation using PostgreSQL Row-Level Security (RLS) or tenant-partitioned schemas.","Ensures all queries index on agency_id to prevent cross-tenant data leakage and guarantee fast query execution."]},{"id":"KP2","description":"Stateless horizontal scaling and container orchestration","required":true,"acceptable_evidence":["Technical keywords: Kubernetes HPA, EKS, stateless microservices, pod autoscaling.","Maintains completely stateless FastAPI microservices containerized on AWS EKS.","Configures Kubernetes Horizontal Pod Autoscaler (HPA) to scale pods dynamically based on CPU, memory, and incoming request metrics."]},{"id":"KP3","description":"Distributed caching and database read replication","required":true,"acceptable_evidence":["Technical keywords: Redis cluster, read replicas, connection pooling, PgBouncer.","Deploys a Redis cluster to cache agency configurations, user permissions, and frequent query outputs.","Adds PostgreSQL read replicas behind PgBouncer connection poolers to scale read throughput independently of writes."]},{"id":"KP4","description":"Tenant rate limiting and noisy neighbor isolation","required":false,"acceptable_evidence":["Technical keywords: noisy neighbor, token bucket, rate limiting, API Gateway, fair-share.","Implements per-agency token bucket rate limiting at the API Gateway to prevent a single high-volume agency from starving system resources.","Establishes fair-share resource quotas and isolated queue partitions for high-throughput tenants."]}],"critical_failures":["Fails to address multi-tenant data isolation or noisy-neighbor issues as agency volume grows.","Proposes vertical scaling (upgrading server size) as the primary scaling solution instead of horizontal distribution."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What system-level metrics did you track, such as latency, throughput, and cost per query?', '{"key_points":[{"id":"KP1","description":"Latency percentile distributions across service layers","required":true,"acceptable_evidence":["Technical keywords: P50, P95, P99 latency, TTFT, Prometheus, Grafana, tail latency.","Tracks P50, P95, and P99 tail latency percentiles across API endpoints, vector database retrieval, and model inference.","Monitors Time-to-First-Token (TTFT) and token generation speed (tokens/sec) for streaming endpoints."]},{"id":"KP2","description":"System throughput and error budget tracking","required":true,"acceptable_evidence":["Technical keywords: RPS, requests per second, error rate, 4xx, 5xx, SLA, SLO.","Monitors request throughput (RPS), concurrent active connections, and HTTP error distributions (4xx client vs 5xx server errors).","Maintains SLA/SLO dashboards in Grafana to track error budget consumption under peak loads."]},{"id":"KP3","description":"Hardware and infrastructure resource saturation","required":true,"acceptable_evidence":["Technical keywords: CPU utilization, GPU memory, VRAM, connection pool, disk I/O.","Tracks container CPU and RAM usage alongside GPU memory (VRAM) utilization on inference nodes.","Monitors database connection pool saturation (asyncpg/PgBouncer) and vector database disk/memory metrics in Milvus."]},{"id":"KP4","description":"Economic governance: token accounting and cost per query","required":false,"acceptable_evidence":["Technical keywords: cost per query, prompt tokens, completion tokens, LangSmith, token budget.","Tracks prompt and completion token counts per request using LangSmith or API gateway logs.","Calculates real-time cost per query across model tiers to optimize financial expenditure and enforce user token quotas."]}],"critical_failures":["Focuses solely on average latency while failing to track tail latency (P95/P99) or error rate metrics.","Omits AI-specific economic metrics such as token consumption and cost per query."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What types of enterprise data did you ingest into the system, and how did you preprocess documents such as PDFs, manuals, APIs, and knowledge sources?', '{"key_points":[{"id":"KP1","description":"Heterogeneous enterprise data source ingestion","required":true,"acceptable_evidence":["Technical keywords: PDF manuals, OpenAPI JSON, Confluence, Markdown, knowledge base, unstructured data.","Describes ingesting diverse enterprise sources: multi-column PDF technical manuals, internal knowledge bases, API specifications (OpenAPI/JSON), and customer support logs.","Addresses handling both unstructured text and semi-structured schema documentation."]},{"id":"KP2","description":"Advanced document layout parsing with Docling","required":true,"acceptable_evidence":["Technical keywords: Docling, OCR, table extraction, multi-column layout, bounding boxes.","Explains using Docling to parse complex enterprise PDFs, preserving hierarchical document layouts and reading order.","Extracts embedded tables into clean Markdown/JSON representations and applies OCR to parse scanned diagrams and figures."]},{"id":"KP3","description":"Chunking strategies with context-preserving overlap","required":true,"acceptable_evidence":["Technical keywords: recursive character splitter, semantic chunking, chunk overlap, sentence boundary.","Applies recursive character text splitting or semantic chunking respecting natural sentence and section boundaries.","Maintains a 10-20% chunk overlap (e.g. 512-token chunks with 50-token overlap) to prevent losing context across chunk splits."]},{"id":"KP4","description":"Metadata enrichment and vector embedding indexing","required":false,"acceptable_evidence":["Technical keywords: metadata filtering, Milvus, BGE embeddings, source attribution, doc_id.","Enriches chunks with rich metadata attributes: document title, section header, page number, author, and updated timestamp.","Generates dense vector embeddings using BGE models and indexes them into Milvus with HNSW for hybrid metadata filtering."]}],"critical_failures":["Uses naive fixed-character chunking that splits tables and sentences arbitrarily without overlap.","Fails to address parsing complex PDF structures (tables, multi-column layouts) or extracting metadata."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What was the request volume of the system, and how did you design the backend to handle scalability and reliability requirements?', '{"key_points":[{"id":"KP1","description":"Quantifying request volume and production traffic patterns","required":true,"acceptable_evidence":["Technical keywords: RPS, QPS, burst traffic, 500 RPS, peak volume, throughput.","Quantifies system volume with concrete metrics: handling baseline traffic of 200-500 RPS with peak spikes up to 2,000 RPS.","Distinguishes between read-heavy query endpoints and asynchronous data processing workflows."]},{"id":"KP2","description":"Stateless FastAPI microservices on Kubernetes (EKS)","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Kubernetes HPA, EKS, stateless pods, autoscaling.","Designs stateless FastAPI microservices containerized on AWS EKS.","Configures Horizontal Pod Autoscalers (HPA) to scale pod replicas based on CPU utilization and incoming HTTP request volume."]},{"id":"KP3","description":"Distributed caching layer to absorb high read loads","required":true,"acceptable_evidence":["Technical keywords: Redis, cache hit ratio, TTL, query cache, session store.","Places a Redis distributed caching cluster in front of databases to absorb frequent reads and user session lookups.","Achieves high cache hit rates (>70%), drastically reducing load on PostgreSQL and vector database backends."]},{"id":"KP4","description":"Queue-based load leveling and asynchronous decoupling","required":true,"acceptable_evidence":["Technical keywords: AWS SQS, dead-letter queue, Celery, load leveling, backpressure.","Uses AWS SQS message queues to buffer heavy write spikes and asynchronous AI processing tasks.","Prevents cascading backend outages through queue-based load leveling and dead-letter queues (DLQs) for failed message processing."]},{"id":"KP5","description":"Database scalability, connection pooling, and high availability","required":false,"acceptable_evidence":["Technical keywords: PostgreSQL read replicas, asyncpg, PgBouncer, Multi-AZ failover.","Deploys PostgreSQL read replicas to offload read-heavy dashboard and reporting queries from the primary write instance.","Manages database connections using PgBouncer and asyncpg connection pooling, backed by Multi-AZ automated failover."]}],"critical_failures":["Fails to quantify traffic volume (RPS/QPS) or provide architectural mechanisms to handle traffic spikes.","Designs a tightly-coupled, synchronous architecture that lacks queue buffering or caching under high request volume."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What were the key factors that caused the dashboard performance issue in production but not in lower environments?', '{"key_points":[{"id":"KP1","description":"Data volume divergence and missing database indexes","required":true,"acceptable_evidence":["Technical keywords: data volume disparity, sequential scan, EXPLAIN ANALYZE, B-tree index, missing index.","Explains that staging environments held only hundreds of rows where sequential table scans took sub-10ms, masking missing indexes.","In production, millions of rows caused PostgreSQL to execute full table scans, driving CPU utilization to 100% and timing out queries."]},{"id":"KP2","description":"ORM N+1 query anti-pattern under large datasets","required":true,"acceptable_evidence":["Technical keywords: N+1 queries, ORM, eager loading, select_related, round-trips.","Identifies an N+1 query problem in the backend ORM: fetching a parent dashboard record triggered individual separate queries for each related child entity.","Shows that while N+1 executed unnoticed with 5 test items in staging, it triggered tens of thousands of database round-trips in production."]},{"id":"KP3","description":"Unbounded API payloads and missing pagination","required":true,"acceptable_evidence":["Technical keywords: unpaginated, payload size, cursor pagination, network serialization, memory spike.","Explains that the dashboard API endpoint lacked server-side pagination, attempting to serialize and transmit hundreds of thousands of historical records at once.","Details how this caused massive JSON serialization latency, network transfer delays, and client-side memory spikes in production."]},{"id":"KP4","description":"Frontend DOM over-rendering and lack of virtualization","required":false,"acceptable_evidence":["Technical keywords: DOM nodes, virtualization, react-window, main thread blocking, browser freeze.","Explains that React attempted to render thousands of table rows and chart SVG elements simultaneously in the browser DOM.","Resolves the issue by implementing virtualized windowing (react-window) and enforcing backend pagination."]}],"critical_failures":["Attributes production performance degradation entirely to server hardware differences without examining query execution or data volume.","Fails to identify database query bottlenecks (missing indexes or N+1 queries) or unpaginated API payloads."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What were the main technical challenges in your project, and how did you address issues like large corpus handling and latency?', '{"key_points":[{"id":"KP1","description":"Large corpus vector search scalability and memory management","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, MMAP, collection partition, RAM saturation, M, ef_construction.","Describes scaling search over millions of chunks using Milvus HNSW indexing with tuned M and ef_construction parameters.","Mitigates RAM saturation by leveraging Milvus MMAP disk-backed storage and partitioning collections by domain and date."]},{"id":"KP2","description":"Two-stage retrieval and reranking latency budget","required":true,"acceptable_evidence":["Technical keywords: hybrid search, BM25, dense embeddings, cross-encoder, reranking, top-k.","Combines sparse BM25 keyword matching with dense vector retrieval using Reciprocal Rank Fusion (RRF) for high recall.","Enforces a strict latency budget by running heavy cross-encoder rerankers only on the top-30 retrieved candidates rather than the entire corpus."]},{"id":"KP3","description":"Document parsing complexity and semantic chunking","required":true,"acceptable_evidence":["Technical keywords: Docling, PDF tables, semantic chunking, chunk overlap, context fragmentation.","Overcomes fragmented document extraction by using Docling to parse multi-column PDFs, extracting structured tables as Markdown.","Applies semantic chunking with 15% overlap to preserve context across boundaries and avoid fragmented answers."]},{"id":"KP4","description":"Mitigating generation latency via streaming responses","required":true,"acceptable_evidence":["Technical keywords: Server-Sent Events, SSE, TTFT, Time-to-First-Token, FastAPI StreamingResponse.","Mitigates LLM generation wait times by implementing FastAPI Server-Sent Events (SSE) token streaming.","Reduces perceived latency by delivering initial tokens (TTFT) in under 400ms while completion generation continues."]},{"id":"KP5","description":"Caching layer to eliminate repeated pipeline invocations","required":false,"acceptable_evidence":["Technical keywords: Redis, semantic caching, TTL, cache hit rate.","Deploys a Redis caching layer for prompt/response pairs and session history.","Completely bypasses vector retrieval and LLM inference for repeated questions, returning responses in under 15ms."]}],"critical_failures":["Suggests brute-force Flat vector search or running cross-encoder rerankers across an entire corpus without two-stage retrieval.","Fails to explain how retrieval latency was decoupled from LLM generation latency."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Which React hooks have you used, and how do they help in managing state, side effects, and performance optimization?', '{"key_points":[{"id":"KP1","description":"State management hooks (useState and useReducer)","required":true,"acceptable_evidence":["Technical keywords: useState, useReducer, immutable state, state updater function, complex state.","Explains useState for managing local primitive and object state with functional state updaters.","Describes using useReducer for managing complex, interdependent state transitions predictably via dispatch actions."]},{"id":"KP2","description":"Side effects and lifecycle cleanup (useEffect)","required":true,"acceptable_evidence":["Technical keywords: useEffect, dependency array, cleanup function, AbortController, subscriptions.","Explains useEffect for handling API data fetching, subscriptions, and DOM event listeners.","Highlights the critical role of dependency arrays and cleanup functions (e.g. canceling fetch requests via AbortController) to prevent memory leaks."]},{"id":"KP3","description":"Performance optimization hooks (useMemo and useCallback)","required":true,"acceptable_evidence":["Technical keywords: useMemo, useCallback, referential equality, re-renders, memoized computation.","Explains using useMemo to cache computationally heavy calculations between re-renders based on dependency changes.","Details using useCallback to preserve referential equality of callback functions passed to memoized child components (React.memo)."]},{"id":"KP4","description":"Persistent references without re-renders (useRef)","required":false,"acceptable_evidence":["Technical keywords: useRef, mutable reference, DOM element, timer ID, re-render avoidance.","Describes useRef for holding mutable values (e.g. timer IDs, previous state) that persist across renders without triggering a re-render.","Explains referencing underlying DOM elements directly for imperative operations like scrolling or input focus."]}],"critical_failures":["Fails to distinguish between useMemo (caching values) and useCallback (caching function definitions).","Omits cleanup functions in useEffect when dealing with event listeners, timers, or network requests."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Which specific PostGres indexing schema configuration did you use to handle this nested state updates for your multi-turn conversations?', '{"key_points":[{"id":"KP1","description":"Schema structure with JSONB column for conversation checkpoints","required":true,"acceptable_evidence":["Technical keywords: JSONB, conversations table, session_id, checkpoint_id, LangGraph PostgresSaver.","Explains designing a conversations table storing session identifiers, checkpoint IDs, and multi-turn state inside a PostgreSQL JSONB column.","Highlights how JSONB allows storing arbitrary nested message structures and tool call states without requiring relational schema migrations."]},{"id":"KP2","description":"GIN indexing using jsonb_path_ops for nested path queries","required":true,"acceptable_evidence":["Technical keywords: GIN index, jsonb_path_ops, CREATE INDEX, nested state, @> containment operator.","Specifies creating a GIN index on the state column using jsonb_path_ops: CREATE INDEX idx_conv_state ON conversations USING GIN (state jsonb_path_ops);","Explains that jsonb_path_ops creates significantly smaller and faster indexes than default GIN by hashing full key-value paths for containment queries (@>)."]},{"id":"KP3","description":"Composite B-Tree index for chronological session retrieval","required":true,"acceptable_evidence":["Technical keywords: composite B-Tree, (session_id, checkpoint_id DESC), (session_id, created_at DESC), index scan.","Defines a composite B-tree index on (session_id, checkpoint_id DESC) or (session_id, created_at DESC).","Explains that this allows instantaneous seeking to the latest conversation turn for an active session without scanning unrelated turns."]},{"id":"KP4","description":"Fine-grained updates via jsonb_set and optimistic locking","required":false,"acceptable_evidence":["Technical keywords: jsonb_set, optimistic concurrency, version check, in-place update.","Describes updating specific nested properties using the jsonb_set function rather than overwriting the entire conversation document.","Mentions implementing optimistic concurrency control with version numbers to prevent race conditions during concurrent turn updates."]}],"critical_failures":["Suggests storing conversation state as plain unstructured TEXT or BLOB columns without JSONB support.","Fails to specify GIN indexing for JSONB paths or composite B-tree indexing on (session_id, checkpoint_id) for turn lookups."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why are you interested in working in a startup environment, and how does it compare to your experience in larger organizations?', '{"key_points":[{"id":"KP1","description":"Broad architectural ownership and cross-functional impact","required":true,"acceptable_evidence":["Technical keywords: end-to-end ownership, architectural impact, cross-functional, full stack, microservices.","Explains seeking broad engineering ownership across the entire stack—from vector search and AI agent orchestration to API deployment and UI integration.","Contrasts this with large organizations where responsibilities are often fragmented across specialized, siloed component teams."]},{"id":"KP2","description":"Rapid execution velocity and immediate user feedback loops","required":true,"acceptable_evidence":["Technical keywords: iteration velocity, fast feedback loops, CI/CD, production deployment, agile.","Highlights thriving in environments with fast decision-making and continuous deployment, shipping features directly to end-users.","Contrasts rapid startup iteration with multi-month consensus building, steering committees, and lengthy corporate release cycles."]},{"id":"KP3","description":"Navigating ambiguity and making pragmatic technical trade-offs","required":true,"acceptable_evidence":["Technical keywords: ambiguity, pragmatic trade-offs, technical debt, 0 to 1, resource constraints.","Emphasizes comfort with ambiguity, fast-changing requirements, and lean resource constraints.","Discusses balancing pragmatic speed-to-market with sound architectural foundations to avoid crippling technical debt."]}],"critical_failures":["Fails to articulate clear technical differences in engineering lifecycle, ownership, or decision velocity between startups and enterprises.","Provides generic cultural platitudes without acknowledging the trade-offs of ambiguity and resource constraints."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why would you choose FastAPI for building backend services in an AI-driven application?', '{"key_points":[{"id":"KP1","description":"Native asynchronous concurrency for I/O-bound AI workloads","required":true,"acceptable_evidence":["Technical keywords: FastAPI, asyncio, non-blocking I/O, Starlette, Uvicorn, event loop.","Explains that AI applications spend substantial time waiting on network I/O (vector database searches, external LLM generation, embedding models).","Highlights FastAPI\'s native asyncio foundation on Uvicorn, enabling thousands of concurrent requests to be handled without thread pool starvation."]},{"id":"KP2","description":"Native streaming response capabilities for real-time token delivery","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, Server-Sent Events, SSE, TTFT, async generators.","Details built-in support for asynchronous generator streaming via FastAPI StreamingResponse and Server-Sent Events (SSE).","Explains how streaming tokens in real time dramatically lowers Time-to-First-Token (TTFT) for user-facing AI assistants."]},{"id":"KP3","description":"Strict type validation and rapid serialization via Pydantic v2","required":true,"acceptable_evidence":["Technical keywords: Pydantic v2, Rust core, schema validation, OpenAPI, Swagger documentation.","Leverages Pydantic v2\'s Rust-compiled core for sub-millisecond serialization and validation of complex nested JSON payloads.","Benefits from automatic, interactive OpenAPI/Swagger documentation generated directly from Python type annotations."]},{"id":"KP4","description":"Ecosystem interoperability and clean dependency injection","required":false,"acceptable_evidence":["Technical keywords: LangGraph, dependency injection, Milvus SDK, PyTorch, modular architecture.","Emphasizes direct Python interoperability with leading AI frameworks (LangGraph, Milvus, PyTorch) without cross-language serialization layers.","Utilizes FastAPI\'s dependency injection system for modular management of database connection pools, security authorizers, and rate limiters."]}],"critical_failures":["Claims FastAPI natively parallelizes CPU-bound model training rather than explaining its asynchronous non-blocking I/O event loop.","Omits Pydantic data validation or streaming response capabilities when discussing AI backend requirements."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why would you use FastAPI alongside TorchServe, and what responsibilities does each handle in a production system?', '{"key_points":[{"id":"KP1","description":"Architectural separation of concerns: API Gateway vs Model Server","required":true,"acceptable_evidence":["Technical keywords: separation of concerns, FastAPI, TorchServe, microservices, resource isolation.","Explains separating client-facing API management and business orchestration (FastAPI) from specialized model execution (TorchServe).","Highlights that this avoids coupling GPU-intensive model weights directly inside the web server process."]},{"id":"KP2","description":"FastAPI core responsibilities in the architecture","required":true,"acceptable_evidence":["Technical keywords: authentication, JWT, Pydantic validation, RAG orchestration, rate limiting, SSE streaming.","Defines FastAPI duties: client authentication (OAuth2/JWT), request schema validation via Pydantic, business logic, RAG retrieval orchestration, and client SSE streaming.","Protects internal inference backends from malformed or unauthorized requests."]},{"id":"KP3","description":"TorchServe core responsibilities in the architecture","required":true,"acceptable_evidence":["Technical keywords: GPU memory, VRAM, dynamic batching, .mar files, model versioning, multi-worker.","Defines TorchServe duties: loading PyTorch model archives (.mar), managing GPU VRAM allocation, and executing dynamic request batching to maximize hardware throughput.","Handles multi-model management and independent worker process scaling."]},{"id":"KP4","description":"Resilience, independent scaling, and fault tolerance","required":false,"acceptable_evidence":["Technical keywords: independent autoscaling, Kubernetes, GPU nodes, CPU nodes, crash isolation.","Explains that FastAPI can scale horizontally on inexpensive CPU-only Kubernetes nodes, while TorchServe scales independently on GPU instances.","Prevents GPU out-of-memory (OOM) crashes in TorchServe from taking down client-facing web API endpoints."]}],"critical_failures":["Confuses the roles of FastAPI and TorchServe (e.g. claims TorchServe handles client auth or FastAPI manages GPU tensor batching).","Suggests embedding heavy PyTorch model weights directly inside FastAPI web server worker processes for production serving."]}', 1),
('TECHNICAL', 'Software Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe a production issue where the user interface experienced performance degradation, including the root cause and how you resolved it?', '{"key_points":[{"id":"KP1","description":"Production symptoms, performance metrics, and detection","required":true,"acceptable_evidence":["Technical keywords: Interaction to Next Paint, INP, UI freeze, main thread blocking, APM, telemetry.","Identifies symptoms: noticeable UI stutter, high Interaction to Next Paint (INP) latency, and unresponsive browser tabs during high-volume data display.","Describes detecting the issue via frontend APM monitoring, user telemetry, and browser performance profiling."]},{"id":"KP2","description":"Root cause diagnosis via profiling: excessive DOM nodes and unpaginated payloads","required":true,"acceptable_evidence":["Technical keywords: Chrome DevTools, Performance tab, DOM nodes, unpaginated API, un-virtualized list.","Diagnoses root cause using Chrome DevTools Performance profiler: thousands of un-virtualized DOM elements were being rendered simultaneously from an unpaginated API response.","Explains that massive layout recalculations and garbage collection cycles completely blocked the browser\'s main thread."]},{"id":"KP3","description":"Technical remediation: window virtualization and server-side pagination","required":true,"acceptable_evidence":["Technical keywords: react-window, @tanstack/react-virtual, virtualization, server-side pagination, cursor.","Implements DOM window virtualization using react-window or @tanstack/react-virtual, rendering only items currently inside the visible viewport.","Enforces server-side cursor pagination in the backend API to strictly bound the payload size returned per request."]},{"id":"KP4","description":"Debouncing state updates and establishing regression guardrails","required":false,"acceptable_evidence":["Technical keywords: debouncing, throttling, requestAnimationFrame, synthetic monitoring, Core Web Vitals.","Debounces or throttles rapid incoming WebSocket/SSE state updates using requestAnimationFrame to prevent re-render thrashing.","Adds automated synthetic Core Web Vitals testing in CI/CD pipelines to prevent future performance regressions."]}],"critical_failures":["Fails to identify the root cause of UI blocking (e.g., main thread blocking from excessive DOM nodes or un-throttled state updates).","Proposes superficial fixes like \'clearing browser cache\' without addressing structural issues like virtualization or pagination."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you would implement concurrency using asyncio or similar techniques for parallel API calls?', '{"key_points":[{"id":"KP1","description":"Asynchronous dispatch using asyncio.gather or TaskGroup with httpx","required":true,"acceptable_evidence":["Technical keywords: asyncio.gather, asyncio.TaskGroup, httpx.AsyncClient, coroutines, non-blocking.","Explains dispatching concurrent HTTP requests across an async event loop using asyncio.gather or asyncio.TaskGroup with httpx.AsyncClient.","Describes how coroutines yield control during I/O wait times, allowing parallel execution without thread overhead."]},{"id":"KP2","description":"Concurrency throttling using asyncio.Semaphore","required":true,"acceptable_evidence":["Technical keywords: asyncio.Semaphore, concurrency limit, rate limiting, socket exhaustion, HTTP 429.","Explains wrapping coroutine calls inside an asyncio.Semaphore(limit) context manager to restrict concurrent in-flight requests.","Prevents overwhelming downstream services, exhausting operating system file descriptors, or triggering HTTP 429 errors."]},{"id":"KP3","description":"Resilient error handling and partial failure isolation","required":true,"acceptable_evidence":["Technical keywords: return_exceptions=True, isinstance, Exception, partial failure, retry logic.","Details setting return_exceptions=True in asyncio.gather so that a single failed request does not abort the remaining concurrent tasks.","Explains inspecting results with isinstance(res, Exception) to log errors or dispatch failed tasks to a retry queue."]},{"id":"KP4","description":"Connection pooling and HTTP client lifecycle management","required":false,"acceptable_evidence":["Technical keywords: httpx.Limits, connection pool, keep-alive, async context manager.","Manages a single shared httpx.AsyncClient instance inside an async context manager rather than creating a new client per request.","Configures httpx.Limits with max_connections and max_keepalive_connections to optimize TCP socket reuse."]}],"critical_failures":["Uses synchronous blocking HTTP libraries (e.g. requests.get) inside async coroutines, blocking the entire event loop.","Executes unbounded concurrent calls with asyncio.gather without semaphore limits, causing socket exhaustion and downstream failures."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain your experience with FastAPI in exposing ML or AI services and how you handled performance and scalability?', '{"key_points":[{"id":"KP1","description":"Asynchronous endpoint design for I/O-bound AI services","required":true,"acceptable_evidence":["Technical keywords: FastAPI, async/await, Uvicorn, non-blocking I/O, vector search.","Explains implementing asynchronous route handlers using async/await for I/O-bound calls to vector databases, Redis, and external LLMs.","Ensures that Uvicorn\'s event loop remains unblocked to service incoming requests with minimal queueing delay."]},{"id":"KP2","description":"Decoupling compute-heavy ML execution from the event loop","required":true,"acceptable_evidence":["Technical keywords: run_in_executor, background tasks, Celery, SQS, CPU-bound, event loop blocking.","Explains that CPU/GPU-intensive inference blocks the asyncio event loop if run directly inside an async route.","Describes offloading CPU-bound tasks using asyncio.get_event_loop().run_in_executor(thread_pool) or asynchronous worker queues (Celery/SQS)."]},{"id":"KP3","description":"Real-time streaming and Pydantic v2 serialization performance","required":true,"acceptable_evidence":["Technical keywords: StreamingResponse, Server-Sent Events, SSE, Pydantic v2, Rust core.","Implements FastAPI StreamingResponse with Server-Sent Events (SSE) to deliver streaming LLM responses with minimal TTFT.","Leverages Pydantic v2\'s compiled Rust core for sub-millisecond serialization and input validation of complex AI prompts."]},{"id":"KP4","description":"Horizontal scaling, containerization, and production observability","required":false,"acceptable_evidence":["Technical keywords: Kubernetes HPA, Docker, EKS, Prometheus, Grafana, P95 latency.","Packages FastAPI services into Docker containers deployed on AWS EKS with Kubernetes Horizontal Pod Autoscaler (HPA).","Monitors production performance using Prometheus and Grafana dashboards tracking RPS, P95/P99 latencies, and error rates."]}],"critical_failures":["Executes heavy synchronous CPU/GPU model inference directly in the async main thread, blocking Uvicorn from processing concurrent requests.","Fails to incorporate connection pooling, streaming, or autoscaling when discussing production scalability."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you construct and use labeled datasets or ground truth data to evaluate your model performance?', '{"key_points":[{"id":"KP1","description":"Golden dataset curation from real-world enterprise queries and edge cases","required":true,"acceptable_evidence":["Technical keywords: golden dataset, domain experts, historical logs, edge cases, ground truth.","Explains curating high-quality evaluation sets from historical user queries, enterprise documentation, and domain expert verification.","Ensures intentional representation of complex queries, out-of-domain prompts, and difficult edge cases."]},{"id":"KP2","description":"Synthetic test generation and human-in-the-loop validation","required":true,"acceptable_evidence":["Technical keywords: synthetic data, Ragas, LLM-as-a-judge, Cohen\'s Kappa, inter-annotator agreement.","Combines LLM-generated synthetic question-context pairs with human-in-the-loop expert review to scale dataset coverage.","Measures inter-annotator agreement (e.g. Cohen\'s Kappa) to validate labeling consistency across domain reviewers."]},{"id":"KP3","description":"Component-level ground truth evaluation metrics","required":true,"acceptable_evidence":["Technical keywords: Hit Rate@K, MRR@K, faithfulness, context precision, answer relevancy, RAGAS.","Evaluates retrieval performance against annotated relevant documents using Hit Rate@K and Mean Reciprocal Rank (MRR@K).","Evaluates generation quality using RAGAS metrics: measuring faithfulness against ground-truth context and answer relevancy."]},{"id":"KP4","description":"Dataset versioning and automated CI/CD regression testing","required":false,"acceptable_evidence":["Technical keywords: DVC, MLflow, CI/CD, regression testing, test stratification.","Versions evaluation datasets using DVC or MLflow to ensure benchmark reproducibility across model iterations.","Integrates the golden dataset into automated CI/CD testing pipelines to catch quality regressions before deploying model or prompt changes."]}],"critical_failures":["Relies entirely on ad-hoc manual testing without a structured, versioned golden evaluation dataset.","Fails to apply quantitative metrics (e.g. Hit Rate, MRR, Faithfulness) to evaluate model performance against ground truth."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How did you design and implement end-to-end AI assistant systems, and what architectural decisions did you make for scalability and performance?', '{"key_points":[{"id":"KP1","description":"Stateful agent workflow orchestration and checkpointing","required":true,"acceptable_evidence":["Technical keywords: LangGraph, PostgresSaver, checkpointing, state graph, conditional edges.","Architects agent workflows using LangGraph state graphs with conditional routing between intent classification, retrieval, tool execution, and response synthesis.","Implements persistent conversation checkpointing using PostgresSaver to maintain multi-turn context and enable human-in-the-loop interrupts."]},{"id":"KP2","description":"Hybrid retrieval and vector database indexing","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, BM25, hybrid search, Reciprocal Rank Fusion, cross-encoder reranking.","Integrates Milvus with HNSW indexing (tuned M and ef parameters) for sub-25ms approximate nearest neighbor search.","Combines dense semantic embeddings with sparse BM25 keyword matching via Reciprocal Rank Fusion (RRF) and top-k cross-encoder reranking."]},{"id":"KP3","description":"Low-latency streaming API layer","required":true,"acceptable_evidence":["Technical keywords: FastAPI, Server-Sent Events, SSE, TTFT, StreamingResponse, non-blocking.","Builds an asynchronous FastAPI backend utilizing Server-Sent Events (SSE) to stream generated tokens to the client in real time.","Reduces Time-to-First-Token (TTFT) to under 400ms, maintaining high user responsiveness during complex reasoning."]},{"id":"KP4","description":"Multi-tier caching and state persistence","required":true,"acceptable_evidence":["Technical keywords: Redis, TTL, semantic cache, PostgreSQL, connection pooling.","Deploys Redis for user session caching, rate limiting, and semantic query caching to bypass LLM calls for repeated prompts.","Uses PostgreSQL with asyncpg connection pooling for persistent conversation logs and audit trails."]},{"id":"KP5","description":"Infrastructure scalability, security, and observability","required":false,"acceptable_evidence":["Technical keywords: Kubernetes HPA, EKS, OAuth2, JWT, LangSmith, Prometheus, Grafana.","Deploys containerized microservices on AWS EKS with Kubernetes Horizontal Pod Autoscaling (HPA) and OAuth2/JWT security.","Monitors production performance, latency percentiles, and token costs using LangSmith distributed tracing and Prometheus/Grafana."]}],"critical_failures":["Presents a simplistic, monolithic script or single prompt call without workflow state management, vector indexing, or architectural decoupling.","Fails to address latency optimization, response streaming, or caching for production-grade user interaction."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How did you design and use a golden dataset and offline A/B testing to measure system performance?', '{"key_points":[{"id":"KP1","description":"Curation and schema design of a representative golden dataset with verified ground truth answers and diverse edge cases","required":true,"acceptable_evidence":["Technical keywords: golden dataset, ground truth, question-answer pairs, edge cases, domain coverage, reference context.","Explains assembling 500-1000 domain-specific customer call queries with verified expert answers and document context citations.","Describes stratifying queries across standard FAQs, ambiguous queries, adversarial inputs, and multi-turn conversational edge cases."]},{"id":"KP2","description":"Offline automated evaluation framework utilizing RAGAS metrics to score candidate systems against the golden set","required":true,"acceptable_evidence":["Technical keywords: RAGAS, faithfulness, answer_relevancy, context_precision, context_recall, LLM judge.","Explains running offline batch evaluation scoring faithfulness (factual consistency against context) and context_precision via cross-encoder/LLM judges.","Details computing baseline scores across retrieval configurations (e.g., dense MiniLM vs hybrid BM25+BGE) prior to deployment."]},{"id":"KP3","description":"Offline A/B testing methodology comparing pipeline configurations on matched splits with statistical rigor","required":true,"acceptable_evidence":["Technical keywords: offline A/B testing, traffic replay, paired t-test, statistical significance, latency histogram, P95/P99.","Explains replaying golden benchmark queries across Model Version A (baseline) and Model Version B (experimental prompt/retrieval).","Describes comparing evaluation metrics, error rates, and response time histograms to establish statistically significant improvements."]},{"id":"KP4","description":"Continuous golden set maintenance, drift handling, and governance feedback loops","required":false,"acceptable_evidence":["Technical keywords: active learning, hard negative mining, dataset drift, human-in-the-loop, MLflow, LangSmith.","Explains incorporating low-confidence production logs and user downvotes into the golden dataset for ongoing regression prevention."]}],"critical_failures":["Confuses offline A/B evaluation on a curated golden dataset with live production canary traffic routing.","Fails to specify concrete evaluation metrics such as RAGAS faithfulness, context precision, or latency distributions.","Claims golden dataset evaluation was performed without defining reference ground truth answers or context validation mechanisms."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you determine which data should be indexed to optimize both cost and latency?', '{"key_points":[{"id":"KP1","description":"Query pattern analysis and access frequency profiling to identify hot vs cold data pathways","required":true,"acceptable_evidence":["Technical keywords: access patterns, query frequency, high-cardinality, hot storage, cold storage, cache hit ratio.","Explains analyzing database and search access logs to isolate high-frequency filters (e.g., tenant_id, date, status, customer_id).","Differentiates between latency-critical real-time queries and analytical/reporting queries that can tolerate scanning."]},{"id":"KP2","description":"Selective indexing in vector stores (Milvus) balancing memory footprint and recall latency","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, IVF_FLAT, efConstruction, M parameter, vector dimensions, RAM overhead.","Explains indexing only high-semantic-value chunk embeddings (e.g., policy docs, customer resolutions) rather than raw logs or noisy system tokens.","Details tuning HNSW parameters (M=16, efConstruction=200) vs IVF_PQ to balance index build cost, RAM saturation, and sub-50ms search latency."]},{"id":"KP3","description":"Relational and structured metadata indexing strategies in PostgreSQL to minimize write overhead","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, B-tree, GIN index, JSONB, composite index, partial index, write amplification.","Explains using partial indexes (`WHERE active = true`) and composite indexes on `(user_id, created_at DESC)` instead of blanket indexing all columns.","Discusses trade-offs of index storage bloat, WAL generation overhead, and degraded write/insert throughput."]},{"id":"KP4","description":"Cost-benefit quantification and automated index pruning lifecycle","required":false,"acceptable_evidence":["Technical keywords: pg_stat_user_indexes, index pruning, vector compaction, TTL eviction, AWS S3 tiering.","Describes monitoring unused indexes with database metrics and tiering aged vectors to cold S3 storage to manage indexing expense."]}],"critical_failures":["Recommends indexing every field and embedding every raw text segment without considering RAM/disk cost or write penalties.","Fails to distinguish between vector indexing (e.g., HNSW in Milvus) and structured database indexing (e.g., B-tree/GIN in Postgres).","Does not mention the latency versus storage cost trade-offs inherent in index maintenance."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you evaluate the performance of your AI system, and which metrics did you use to measure quality and reliability?', '{"key_points":[{"id":"KP1","description":"Multi-dimensional quality evaluation using automated RAGAS metrics and LLM-as-a-judge","required":true,"acceptable_evidence":["Technical keywords: RAGAS, faithfulness, context_precision, answer_relevancy, context_recall, hallucination rate.","Explains measuring faithfulness to ensure LLM outputs do not hallucinate beyond retrieved Milvus documents.","Details quantifying context_precision and context_recall to assess retriever performance and reranker efficacy."]},{"id":"KP2","description":"Operational and system reliability metrics tracked in production telemetry","required":true,"acceptable_evidence":["Technical keywords: P95/P99 latency, Prometheus, TTFT (time-to-first-token), throughput, error rate, token consumption.","Explains tracking latency histograms (sub-2s target), token burn rates across LLM invocations, and 4xx/5xx API failure spikes.","Details monitoring LangSmith execution traces for tool call failures, rate limit retries, and checkpointer latency."]},{"id":"KP3","description":"Safety, guardrails, and model drift evaluation","required":true,"acceptable_evidence":["Technical keywords: guardrails, toxicity detection, PII masking, Evidently AI, drift detection, NeMo Guardrails.","Describes implementing input/output guardrails to filter prompt injections, sensitive customer PII, and unsafe completions.","Explains detecting embedding drift or input query distribution shifts using Evidently AI or Kolmogorov-Smirnov tests."]},{"id":"KP4","description":"Human-in-the-loop (HITL) validation and customer operational feedback loops","required":false,"acceptable_evidence":["Technical keywords: HITL, thumbs up/down, CSAT, LangGraph review node, ticket deflection rate.","Details correlating human agent ratings and resolution times with automated RAGAS scores to calibrate threshold cutoffs."]}],"critical_failures":["Relying solely on standard classification metrics (accuracy, F1) for generative RAG and multi-agent systems without RAGAS or hallucination metrics.","Failing to separate retrieval quality (precision/recall) from generation quality (faithfulness/relevancy).","Omitting operational reliability metrics like P95/P99 latency, streaming TTFT, or system error rates."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you identify UI and performance bottlenecks, and which tools did you use for analysis?', '{"key_points":[{"id":"KP1","description":"Frontend performance profiling and render optimization tooling","required":true,"acceptable_evidence":["Technical keywords: React Profiler, Chrome DevTools, Lighthouse, Core Web Vitals, re-renders, flame graph.","Explains using React Profiler to pinpoint unnecessary component re-renders and costly commit phases.","Describes analyzing Chrome DevTools Performance tab flame graphs to identify long tasks blocking the main event thread."]},{"id":"KP2","description":"Network and payload analysis for frontend-to-backend communication","required":true,"acceptable_evidence":["Technical keywords: Network tab, waterfall, payload size, SSE (Server-Sent Events), WebSocket, chunked transfer.","Explains identifying large JSON response payloads, uncompressed asset bundles, and blocking REST waterfalls.","Describes transitioning from monolithic blocking REST endpoints to async streaming (FastAPI StreamingResponse) to minimize TTFB."]},{"id":"KP3","description":"Targeted remediation techniques for UI bottlenecks","required":true,"acceptable_evidence":["Technical keywords: React.memo, useMemo, useCallback, virtualization, react-window, code splitting, lazy loading.","Details virtualizing large lists/tables of customer records using react-window to maintain 60 FPS scrolling.","Explains eliminating excessive state updates and memoizing heavy compute callbacks."]},{"id":"KP4","description":"Real User Monitoring (RUM) and synthetic performance monitoring","required":false,"acceptable_evidence":["Technical keywords: Sentry, Datadog RUM, LCP, FID, CLS, INP.","Describes monitoring field Core Web Vitals (INP, LCP) and frontend crash/error telemetry with Sentry or Datadog."]}],"critical_failures":["Suggesting backend optimizations (like SQL indexing) when asked specifically about UI rendering and client performance analysis.","Failing to name standard profiling tools like React Profiler, Chrome DevTools, or Lighthouse.","Unable to explain how re-rendering causes UI freezes or how virtualization resolves data-heavy rendering issues."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How did you measure and optimize latency in your system, and what techniques did you apply to improve response time?', '{"key_points":[{"id":"KP1","description":"Comprehensive latency profiling across pipeline stages with distributed tracing","required":true,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, OpenTelemetry, LangSmith, P95/P99 latency, TTFT, span tracing.","Explains breaking down end-to-end response time into API gateway overhead, vector search, reranking, and LLM inference generation.","Details identifying the P95/P99 tail latency culprits using distributed trace spans in LangSmith or OpenTelemetry."]},{"id":"KP2","description":"Streaming responses and asynchronous I/O execution to slash perceived user latency","required":true,"acceptable_evidence":["Technical keywords: FastAPI, async streaming, StreamingResponse, Server-Sent Events (SSE), asyncio.gather, TTFT.","Explains implementing token streaming via FastAPI `StreamingResponse` to deliver sub-500ms time-to-first-token (TTFT).","Describes parallelizing independent calls (e.g., BM25 keyword search, vector similarity search, user profile fetch) using `asyncio.gather`."]},{"id":"KP3","description":"Multi-tier caching strategies for session state and repeated retrieval results","required":true,"acceptable_evidence":["Technical keywords: Redis, semantic cache, TTL, query embedding cache, prompt caching.","Details caching precomputed document embeddings and frequent query results in Redis with deterministic TTLs.","Explains leveraging prompt caching or exact-match query caches to bypass expensive LLM inference cycles entirely."]},{"id":"KP4","description":"Retrieval and vector search parameter optimization","required":true,"acceptable_evidence":["Technical keywords: Milvus, HNSW, efSearch, cross-encoder top_k, quantization.","Explains tuning Milvus `efSearch` to achieve sub-30ms retrieval and pruning candidate pools to top 15 chunks before reranking.","Describes using lightweight bi-encoder embeddings (BGE-small/MiniLM) and quantized models for rapid initial candidate filtering."]},{"id":"KP5","description":"Infrastructure and concurrency scaling","required":false,"acceptable_evidence":["Technical keywords: connection pooling, Gunicorn/Uvicorn workers, EKS horizontal pod autoscaling, keep-alive.","Discusses managing persistent HTTP connection pools (httpx.AsyncClient) and database connection pools (asyncpg) to eliminate handshake overhead."]}],"critical_failures":["Focuses solely on model size reduction without addressing vector retrieval, database queries, network round trips, or streaming.","Fails to distinguish between overall completion latency and Time to First Token (TTFT).","Proposes caching without specifying cache invalidation, key structure, or eviction strategies (e.g., Redis TTL)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How did you measure camera startup latency and performance metrics such as FPS and latency using tools like logcat and systrace?', '{"key_points":[{"id":"KP1","description":"Defining granular camera startup latency phases and instrumentation markers.","required":true,"acceptable_evidence":["Technical keywords: camera cold start, warm start, launch-to-first-frame, CameraDevice.openCamera, onOpened callback, first frame buffer arrival.","Breaks down startup latency into distinct phases: process fork, camera service connection, HAL device open, stream configuration, and first frame surface render.","Explains instrumenting custom `Trace.beginSection()` and `Trace.endSection()` tags across lifecycle milestones."]},{"id":"KP2","description":"Measuring and analyzing execution timelines with systrace and Perfetto.","required":true,"acceptable_evidence":["Technical keywords: systrace, Perfetto, atrace, CPU scheduling slices, choregrapher frame drops, VSYNC synchronization.","Details analyzing Systrace HTML/Perfetto trace captures to identify main thread stalls, Binder IPC blocking during camera service connect, and surfaceflinger buffer drops.","Explains correlating CPU core frequency scaling and thread preemption with latency spikes."]},{"id":"KP3","description":"Automated logcat parsing and continuous performance benchmarking.","required":true,"acceptable_evidence":["Technical keywords: logcat timestamps, CameraManager log tags, automated test harness, FPS calculation, frame interval delta ($1/\\\\Delta t$).","Describes scripting automated logcat collectors measuring millisecond deltas between intent launch and `CameraX / Camera2` first frame received.","Details calculating running FPS and frame delivery jitter by analyzing frame callback timestamps over continuous capture intervals."]}],"critical_failures":["Measures camera startup solely using manual stopwatch or user-perceived estimates without tool-based instrumentation.","Fails to distinguish between camera open latency and first frame surface presentation latency.","Cannot explain how to read or interpret systrace/Perfetto timeline slices for identifying main thread blocking."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you use CameraX and system clock-based instrumentation to track and analyze camera performance in your test applications?', '{"key_points":[{"id":"KP1","description":"CameraX lifecycle-aware architecture and use case pipeline configuration.","required":true,"acceptable_evidence":["Technical keywords: CameraX, ProcessCameraProvider, Preview, ImageAnalysis, ImageCapture, LifecycleOwner, ExecutorService.","Explains binding CameraX use cases (`Preview`, `ImageAnalysis`) to activity lifecycles and configuring background worker executors to avoid UI thread blocking.","Details setting target resolutions and aspect ratios to match ISP sensor capabilities for optimal throughput."]},{"id":"KP2","description":"High-resolution system clock instrumentation for frame timing and latency measurement.","required":true,"acceptable_evidence":["Technical keywords: SystemClock.elapsedRealtimeNanos(), System.nanoTime(), monotonic clock, imageProxy.getImageInfo().getTimestamp(), frame duration.","Explains using monotonic clocks (`SystemClock.elapsedRealtimeNanos()`) rather than wall clock time to avoid NTP jumps during benchmarks.","Details computing end-to-end frame latency by comparing sensor hardware timestamps from `ImageInfo` with analyzer completion timestamps."]},{"id":"KP3","description":"Buffer queue management, frame drop detection, and analyzer performance tuning.","required":true,"acceptable_evidence":["Technical keywords: ImageProxy, close() lifecycle, STRATEGY_KEEP_ONLY_LATEST, backpressure handling, buffer starvation.","Describes managing CameraX backpressure using `ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST` to drop outdated frames when analysis takes longer than the frame interval.","Explains rigorously calling `imageProxy.close()` to return buffers to the camera driver pool, preventing memory leaks and camera stalls."]}],"critical_failures":["Uses wall-clock time (`System.currentTimeMillis()`) instead of monotonic system clocks for nanosecond performance measurements.","Fails to close `ImageProxy` objects in the analysis pipeline, causing immediate buffer starvation and pipeline freezing.","Runs heavy image analysis directly on the main UI thread, destroying preview framerates."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you use profiling tools to analyze CPU and GPU performance, and what bottlenecks did you identify during video editing workflows?', '{"key_points":[{"id":"KP1","description":"System profiling tools and methodology across CPU and GPU pipelines.","required":true,"acceptable_evidence":["Technical keywords: Android Studio Profiler, Perfetto, Snapdragon Profiler, NVIDIA Nsight, CPU flame graphs, GPU rendering pipeline, memory allocation tracker.","Explains deploying CPU profilers and GPU trace analyzers to record thread execution times, CPU frequency scaling, and GPU shader occupancy during video timeline scrubbing.","Details capturing flame graphs to pinpoint exact methods consuming excessive CPU cycles during frame decoding and composition."]},{"id":"KP2","description":"Identification of critical video processing bottlenecks.","required":true,"acceptable_evidence":["Technical keywords: CPU-to-GPU memory transfer, redundant texture uploads, software vs hardware decoding (MediaCodec), OpenGL/Vulkan shader complexity, GC pauses.","Identifies high latency caused by copying raw frame bytes over system bus rather than utilizing hardware zero-copy EGLImage / Surface textures.","Highlights bottlenecks caused by software decoders failing to maintain real-time playback rates, and memory thrashing leading to frequent garbage collection pauses."]},{"id":"KP3","description":"Architectural remediations and verified performance gains.","required":true,"acceptable_evidence":["Technical keywords: MediaCodec hardware acceleration, GPU surface rendering, texture caching, worker thread offloading, dropped frame reduction.","Explains migrating frame decoding to hardware-accelerated MediaCodec rendering directly to a GPU SurfaceTexture.","Details implementing frame LRU caching in GPU memory and decoupling timeline UI rendering from audio-video playback threads to achieve steady 60 FPS."]}],"critical_failures":["Cannot name standard CPU/GPU profiling tools (Perfetto, Android Studio Profiler, GPU frame analyzers).","Fails to identify bus transfer overhead (CPU memory to GPU VRAM) or software decoding as primary video pipeline bottlenecks.","Proposes decoding video frames on the UI thread without hardware acceleration or asynchronous pipeline stages."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you use tools like React Profiler to diagnose and optimize rendering performance issues?', '{"key_points":[{"id":"KP1","description":"Diagnostic workflow using React Profiler to capture render commits and identify waste","required":true,"acceptable_evidence":["Technical keywords: React Profiler, render duration, base duration, commit phase, flamegraph, ranked chart.","Explains recording interactions (e.g., filtering large ticket logs) to observe which components re-rendered and their execution times.","Describes inspecting \'Why did this render?\' annotations in React DevTools to pinpoint changing props, hooks, or state."]},{"id":"KP2","description":"Root-cause identification of unstable references and cascading child re-renders","required":true,"acceptable_evidence":["Technical keywords: referential instability, object literals, inline functions, context propagation, cascading renders.","Explains finding inline callbacks `() => handleClick()` or newly created object/array literals passed as props causing re-renders.","Details diagnosing large Context providers triggering updates across unmemoized consumer subtrees."]},{"id":"KP3","description":"Targeted optimization techniques including memoization and component restructuring","required":true,"acceptable_evidence":["Technical keywords: React.memo, useCallback, useMemo, custom comparison, component colocation.","Explains wrapping pure leaf components in `React.memo` and stabilizing props with `useCallback` and `useMemo`.","Describes lifting state down or splitting context into discrete providers (e.g., state vs dispatch) to isolate updates."]},{"id":"KP4","description":"Validation and benchmark comparison before vs after optimization","required":false,"acceptable_evidence":["Technical keywords: commit duration reduction, frame rate (60 FPS), interaction to next paint (INP).","Demonstrates verifying that commit phase duration dropped significantly (e.g., from 120ms to under 16ms) on subsequent profile recordings."]}],"critical_failures":["Claims React Profiler optimizes code automatically rather than being a diagnostic measurement tool.","Fails to explain the difference between render phase and commit phase or what causes component re-renders.","Advocates wrapping every single component indiscriminately in React.memo without diagnosing referential stability or profiling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach database scaling, and when do you choose horizontal scaling versus sharding?', '{"key_points":[{"id":"KP1","description":"Vertical scaling limits and the architectural rationale for horizontal scaling","required":true,"acceptable_evidence":["Technical keywords: vertical scaling, read replicas, replication lag, connection pooling, PgBouncer.","Explains scaling reads horizontally using read replicas in PostgreSQL while directing writes to a primary master node.","Discusses handling replication lag and offloading read-heavy queries like reporting or dashboard analytics."]},{"id":"KP2","description":"Definition and triggers for database sharding across independent nodes","required":true,"acceptable_evidence":["Technical keywords: sharding, horizontal partitioning, shard key, hash partitioning, range partitioning, multi-master.","Explains that sharding distributes both read and write workloads and data storage across multiple autonomous database instances.","Identifies triggers: primary write throughput saturation, storage limits exceeding single-node hardware, and extreme I/O IOPS bottlenecks."]},{"id":"KP3","description":"Shard key selection and mitigation of hotspot and cross-shard query challenges","required":true,"acceptable_evidence":["Technical keywords: shard key, consistent hashing, data skew, cross-shard joins, distributed transactions, 2PC.","Explains selecting a high-cardinality shard key (such as `tenant_id` or `user_id`) to evenly distribute data and avoid hot spots.","Details the severe trade-offs of sharding: loss of ACID foreign keys, complex cross-shard joins, scatter-gather query latency, and schema migrations."]},{"id":"KP4","description":"Comparative decision framework: Read Replicas vs Sharding vs NoSQL/Distributed SQL","required":true,"acceptable_evidence":["Technical keywords: CQRS, CockroachDB, Citus, DynamoDB, MongoDB, read-to-write ratio.","Provides clear decision rules: if read-heavy (90/10), scale horizontally with read replicas and caching (Redis); only shard or adopt distributed SQL (Citus) when write I/O saturates vertical limits."]}],"critical_failures":["Confuses standard read-replica horizontal scaling with database sharding (partitioning writes and data across nodes).","Fails to identify the complications introduced by sharding, such as cross-shard queries and loss of transactional integrity.","Claims sharding is the first step before trying read replication, caching, or query optimization."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you communicate complex AI system design decisions and trade-offs effectively to both technical and non-technical stakeholders?', '{"key_points":[{"id":"KP1","description":"Translating technical AI concepts into quantifiable business metrics for leadership and non-technical stakeholders","required":true,"acceptable_evidence":["Technical keywords: business ROI, cost per resolution, ticket deflection, CSAT, P95 SLA, token budget, failure risk.","Explains framing accuracy, latency, and hallucination trade-offs in terms of business impact, such as customer churn risk and support operational cost savings.","Details communicating AI system reliability using clear SLAs, risk boundaries, and user experience outcomes rather than raw loss curves."]},{"id":"KP2","description":"Rigorous technical documentation and architecture artifacts for engineering teams","required":true,"acceptable_evidence":["Technical keywords: C4 architecture diagrams, sequence diagrams, RFC/ADR (Architecture Decision Records), data flow, OpenAPI.","Describes using Architecture Decision Records (ADRs) to document why LangGraph was chosen over raw chains or why Milvus was selected over pgvector.","Details documenting component boundaries, fallback circuits, state transitions, and API contracts."]},{"id":"KP3","description":"Presenting trade-offs with explicit multi-variable decision matrices","required":true,"acceptable_evidence":["Technical keywords: decision matrix, cost vs latency vs accuracy, Pareto frontier, vendor lock-in, open-source vs proprietary.","Illustrates using comparative trade-off tables (e.g., fine-tuning vs RAG, Claude 3.5 Sonnet vs Llama-3-8B local inference).","Highlights presenting concrete trade-offs clearly: e.g., 200ms latency savings vs $0.03 higher inference cost per call."]},{"id":"KP4","description":"Live demonstration, interactive prototypes, and transparent evaluation dashboards","required":false,"acceptable_evidence":["Technical keywords: Grafana dashboard, LangSmith trace review, Streamlit prototype, RAGAS scorecard, guardrail demo.","Explains demonstrating failure edge cases side-by-side with guardrail interventions to build executive confidence."]}],"critical_failures":["Advocates using deep technical jargon (e.g., loss manifolds, HNSW graph construction) with business stakeholders.","Fails to provide structured communication artifacts such as Architecture Decision Records (ADRs) or trade-off matrices.","Does not connect AI engineering decisions to cost, risk, latency, or customer-facing reliability."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you evaluate and balance trade-offs between performance, cost, and model quality in production AI systems?', '{"key_points":[{"id":"KP1","description":"Defining the core trade-off trilemma: latency/throughput, dollar cost, and output quality","required":true,"acceptable_evidence":["Technical keywords: cost per token, TTFT, RAGAS faithfulness, throughput (RPS), accuracy vs latency vs cost trilemma.","Explains how maximizing model quality via large frontier models (e.g., GPT-4o, Claude 3.5 Sonnet) severely degrades latency and blows through token budgets.","Defines SLAs (e.g., P95 < 2.0s, faithfulness > 0.88, cost < $0.01 per query) to establish acceptable trade-off boundaries."]},{"id":"KP2","description":"Model tiering and intelligent query routing strategies","required":true,"acceptable_evidence":["Technical keywords: model cascading, semantic router, small language models (SLM), Llama 3 8B, GPT-4o mini, classification router.","Explains routing simple conversational queries and FAQ lookups to cheap, fast SLMs (e.g., Llama 3 8B / GPT-4o mini) while reserving frontier models for complex multi-step reasoning.","Details setting up fallback escalations if the small model\'s confidence score or output guardrail fails."]},{"id":"KP3","description":"Retrieval and context window optimization to slash cost and compute","required":true,"acceptable_evidence":["Technical keywords: context pruning, cross-encoder reranking, token budget, chunk size, BM25+dense hybrid, Milvus.","Explains filtering candidate chunks via cross-encoder reranker from top 50 down to the top 3-5 most relevant chunks to minimize context tokens sent to LLM.","Details caching repeated prompt prefixes and semantic embeddings in Redis to eliminate redundant vector searches and LLM calls."]},{"id":"KP4","description":"Continuous telemetry and cost-quality Pareto monitoring","required":true,"acceptable_evidence":["Technical keywords: LangSmith, Prometheus, Grafana, cost tracking, token counters, RAGAS evaluation, A/B testing.","Describes continuously plotting cost per request against RAGAS faithfulness and user acceptance rates to maintain optimal operating balance."]}],"critical_failures":["Recommends using the largest frontier model for every incoming query without routing, pruning, or cost awareness.","Fails to provide quantitative metrics for measuring cost (tokens/dollar), quality (faithfulness/accuracy), and performance (latency/TTFT).","Does not mention cascading, prompt pruning, caching, or semantic routing as optimization levers."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate and improve system performance without access to new data?', '{"key_points":[{"id":"KP1","description":"Algorithmic and architectural optimizations within the existing retrieval pipeline","required":true,"acceptable_evidence":["Technical keywords: hybrid search, BM25, Reciprocal Rank Fusion (RRF), cross-encoder reranking, chunking strategy.","Explains upgrading pure dense vector retrieval to hybrid search combining Milvus HNSW dense vectors with BM25 sparse keyword matching.","Describes adjusting chunking strategies (e.g., recursive character splitting with overlap, parent-document retrieval) on existing documents."]},{"id":"KP2","description":"Prompt engineering, structured reasoning, and output validation enhancements","required":true,"acceptable_evidence":["Technical keywords: Few-shot prompting, Chain-of-Thought (CoT), Pydantic structured outputs, system prompt optimization.","Explains improving generation faithfulness and relevance by incorporating few-shot in-context examples extracted from existing data.","Details enforcing strict JSON schemas via Pydantic and adding negative constraint prompting to eliminate hallucinations."]},{"id":"KP3","description":"Rigorous offline evaluation on existing historical logs via cross-validation and bootstrapping","required":true,"acceptable_evidence":["Technical keywords: k-fold cross-validation, bootstrapping, backtesting, RAGAS, historical query replay.","Explains replaying historical user query logs and computing RAGAS metrics (faithfulness, answer relevancy, context precision) across pipeline variations.","Describes using synthetic question generation from existing documents (e.g., using Ragas testset generator) to evaluate without external data."]},{"id":"KP4","description":"System-level latency, caching, and execution profiling optimizations","required":false,"acceptable_evidence":["Technical keywords: Redis caching, connection pooling, asyncio concurrency, query indexing, batching.","Details identifying bottleneck stages via LangSmith traces and implementing Redis caching and parallel retrieval without modifying the training dataset."]}],"critical_failures":["Claims it is impossible to improve or evaluate AI system performance without collecting more training data.","Fails to mention retrieval enhancements (hybrid search, reranking, chunking) or prompt optimization techniques.","Overlooks offline evaluation methods like historical log replaying, RAGAS scoring, or synthetic query generation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate model performance when labeled data is limited or unavailable?', '{"key_points":[{"id":"KP1","description":"LLM-as-a-judge automated evaluation framework using reference-free metrics","required":true,"acceptable_evidence":["Technical keywords: LLM-as-a-judge, RAGAS, faithfulness, answer_relevancy, reference-free evaluation, G-Eval.","Explains using RAGAS reference-free metrics that assess whether an answer is supported by retrieved context without needing ground truth answers.","Describes using strong frontier models (GPT-4o/Claude) with structured rubrics and calibration prompts to score candidate outputs."]},{"id":"KP2","description":"Synthetic benchmark dataset generation with verification filters","required":true,"acceptable_evidence":["Technical keywords: synthetic data generation, Ragas TestsetGenerator, evolution prompt, question-answer synthesis, Docling.","Explains generating diverse test query-context pairs programmatically from existing enterprise knowledge base documents.","Details filtering out low-quality synthetic samples using semantic consistency checks and automated question-answering verification."]},{"id":"KP3","description":"Unsupervised telemetry, consistency checks, and proxy performance signals","required":true,"acceptable_evidence":["Technical keywords: self-consistency, perplexity, confidence score, semantic similarity clustering, Evidently AI, embedding drift.","Explains evaluating model stability through temperature-sampling self-consistency (agreement across multiple generations).","Describes tracking proxy signals such as user thumbs up/down, ticket re-opening rates, and session completion rates in production."]},{"id":"KP4","description":"Human-in-the-loop (HITL) active learning and targeted spot-checking","required":false,"acceptable_evidence":["Technical keywords: active learning, uncertainty sampling, LangGraph HITL, SME validation.","Details routing high-uncertainty or flagged predictions to subject matter experts to bootstrap a small, high-leverage validation set."]}],"critical_failures":["Suggests standard supervised evaluation metrics like accuracy or ROC-AUC without addressing how labels are obtained.","Fails to describe LLM-as-a-judge or reference-free RAGAS metrics (faithfulness, answer relevancy).","Does not mention synthetic data generation, self-consistency checks, or human-in-the-loop sampling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you implement lazy loading and dynamic imports in React applications to improve performance?', '{"key_points":[{"id":"KP1","description":"Core mechanism using React.lazy and Suspense for component-level code splitting","required":true,"acceptable_evidence":["Technical keywords: React.lazy, Suspense, fallback, dynamic import, import(), bundle splitting.","Explains declaring dynamic component imports with `const HeavyModal = React.lazy(() => import(\'./HeavyModal\'))`.","Details wrapping lazily loaded components in `<Suspense fallback={<Spinner />}>` to render fallback UI during asynchronous chunk download."]},{"id":"KP2","description":"Route-based code splitting architecture","required":true,"acceptable_evidence":["Technical keywords: React Router, route-based splitting, webpack chunking, initial bundle size, Time to Interactive (TTI).","Explains splitting top-level application pages (e.g., Dashboard, Analytics, Settings) into independent bundle chunks.","Describes how this reduces initial JavaScript bundle size, improving First Contentful Paint (FCP) and Time to Interactive (TTI)."]},{"id":"KP3","description":"Chunk prefetching and network error boundary handling","required":true,"acceptable_evidence":["Technical keywords: ErrorBoundary, chunk load error, webpackPrefetch, hover prefetching, network retry.","Explains handling dynamic import network failures (e.g., stale deployment chunk hashes) using React Error Boundaries.","Describes optimizing perceived load time by prefetching bundles on link hover or using webpack magic comments (`/* webpackPrefetch: true */`)."]},{"id":"KP4","description":"Image and non-component asset lazy loading","required":false,"acceptable_evidence":["Technical keywords: loading=\'lazy\', IntersectionObserver, progressive image loading.","Discusses applying native browser `loading=\'lazy\'` attribute or IntersectionObserver for offscreen media assets."]}],"critical_failures":["Confuses component code splitting (React.lazy) with data pagination or infinite scrolling.","Fails to mention React.Suspense and its mandatory fallback prop when explaining React.lazy.","Neglects error handling for failed chunk downloads when new app versions invalidate old build hashes."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How does Adaptive Query Execution (AQE) work in Spark, and how does it optimize query performance?', '{"key_points":[{"id":"KP1","description":"Runtime re-optimization mechanism based on accurate shuffle stage runtime statistics","required":true,"acceptable_evidence":["Technical keywords: AQE, spark.sql.adaptive.enabled, runtime statistics, shuffle stage, query stages, Catalyst optimizer.","Explains that traditional Spark uses static Catalyst optimization, whereas AQE pauses between map and reduce shuffle stages to inspect actual partition data sizes.","Details re-optimizing the physical execution plan dynamically based on exact partition statistics produced at stage boundaries."]},{"id":"KP2","description":"Dynamic coalescing of post-shuffle partitions to prevent small-file overhead","required":true,"acceptable_evidence":["Technical keywords: dynamic partition coalescing, spark.sql.adaptive.coalescePartitions.enabled, shuffle partitions, small partitions.","Explains dynamically merging small, fragmented shuffle partitions into appropriately sized target partitions (default 64MB-128MB).","Describes how coalescing eliminates executor scheduling overhead and excessive small task generation without manual repartitioning."]},{"id":"KP3","description":"Dynamic conversion of Sort-Merge Joins into Broadcast Hash Joins","required":true,"acceptable_evidence":["Technical keywords: dynamically converting sort-merge join to broadcast join, autoBroadcastJoinThreshold, BroadcastHashJoin.","Explains that if filtering or aggregation reduces a table size below the broadcast threshold during execution, AQE switches a planned SortMergeJoin to a BroadcastHashJoin.","Describes how this conversion eliminates costly shuffle exchanges for the join stage entirely."]},{"id":"KP4","description":"Dynamic skew join handling and split optimization","required":true,"acceptable_evidence":["Technical keywords: skew join optimization, spark.sql.adaptive.skewJoin.enabled, skewed partition split, straggler tasks.","Explains detecting oversized partitions that exceed the median partition size by a configured factor.","Details splitting the skewed partition into smaller sub-partitions and duplicating corresponding join keys to balance executor workload and eliminate stragglers."]}],"critical_failures":["Claims AQE optimizes queries prior to execution (static optimization) rather than dynamically between shuffle stages at runtime.","Fails to mention at least two of the three primary AQE features: dynamic coalescing, broadcast join conversion, and skew join handling.","Confuses dynamic coalescing with static `df.coalesce()` or `df.repartition()` code calls."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How does Spark handle data skew, and what techniques can be used to mitigate skew-related performance issues?', '{"key_points":[{"id":"KP1","description":"Root cause of data skew and its operational symptoms in Spark clusters","required":true,"acceptable_evidence":["Technical keywords: data skew, straggler tasks, executor OOM, uneven distribution, shuffle spill to disk.","Explains that skew occurs when high-frequency join/grouping keys concentrate massive row volumes into a single executor partition.","Details symptoms: 99% of tasks finish in seconds while one straggler task runs for hours or crashes with OutOfMemoryError / disk spill."]},{"id":"KP2","description":"Salting technique to evenly distribute high-frequency keys across partitions","required":true,"acceptable_evidence":["Technical keywords: salting, random salt, composite key, explode, uniform distribution.","Explains appending a random integer suffix (e.g., `0` to `N-1`) to the skewed join key on the primary dataset.","Details replicating/exploding the matching keys in the secondary lookup dataset by the same factor `N` so join conditions align across distributed partitions."]},{"id":"KP3","description":"Adaptive Query Execution (AQE) automated skew join optimization","required":true,"acceptable_evidence":["Technical keywords: AQE skew join, spark.sql.adaptive.skewJoin.enabled, skewFactor, partition splitting.","Explains enabling `spark.sql.adaptive.skewJoin.enabled=true` to automatically detect skewed partitions at runtime shuffle boundaries.","Describes how AQE automatically splits oversized skewed partitions into multiple smaller sub-partitions without requiring manual code changes."]},{"id":"KP4","description":"Alternative mitigation strategies: Broadcast joins and custom repartitioning","required":true,"acceptable_evidence":["Technical keywords: broadcast join, broadcast hint, repartition by composite key, isolated skew processing.","Explains using `broadcast(small_df)` when one side of the join is small, bypassing shuffle partitioning completely.","Describes isolating skewed keys into a separate processing path and joining the un-skewed keys standardly before unioning."]}],"critical_failures":["Suggests simply increasing executor memory or cluster node count without resolving the partition key skew.","Fails to explain the salting mechanism (adding random salt to keys and exploding the lookup table).","Does not mention Spark 3.x AQE skew join optimization (`spark.sql.adaptive.skewJoin.enabled`)."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How does partitioning affect Spark performance, and how would you determine the optimal number of partitions?', '{"key_points":[{"id":"KP1","description":"Impact of under-partitioning and over-partitioning on cluster utilization and memory","required":true,"acceptable_evidence":["Technical keywords: under-partitioning, over-partitioning, executor core saturation, task scheduling overhead, shuffle spill.","Explains under-partitioning: too few partitions leads to idle CPU cores, massive partition sizes, executor OOM errors, and disk spilling.","Explains over-partitioning: too many tiny partitions causes driver bottleneck from scheduling millions of micro-tasks and small-file storage bloat."]},{"id":"KP2","description":"Target partition size heuristic and sizing calculations based on cluster capacity","required":true,"acceptable_evidence":["Technical keywords: target partition size (100MB-200MB), total executor cores, 2x to 4x core multiplier, spark.sql.shuffle.partitions.","Explains the target size rule of thumb: each partition should ideally be between 100MB and 200MB uncompressed in memory.","Details setting partition count as 2x to 4x the total available executor cores in the cluster to maintain balanced executor pipelining."]},{"id":"KP3","description":"Practical repartitioning strategies: repartition() vs coalesce() and composite keys","required":true,"acceptable_evidence":["Technical keywords: repartition(), coalesce(), full shuffle, narrow dependency, partitionBy.","Explains using `repartition(n)` (which triggers a full network shuffle) to increase partitions or redistribute data evenly on a high-cardinality key.","Contrasts with `coalesce(n)` which merges existing partitions via narrow dependencies without full shuffle when downsizing partition counts."]},{"id":"KP4","description":"Leveraging Spark Adaptive Query Execution (AQE) for automated partition tuning","required":false,"acceptable_evidence":["Technical keywords: spark.sql.adaptive.coalescePartitions.enabled, spark.sql.adaptive.advisoryPartitionSizeInBytes, AQE.","Describes configuring `spark.sql.adaptive.advisoryPartitionSizeInBytes=134217728` (128MB) so Spark dynamically coalesces post-shuffle stages."]}],"critical_failures":["Recommends keeping default `spark.sql.shuffle.partitions=200` regardless of data scale (e.g., for gigabytes vs terabytes).","Confuses `repartition()` (wide shuffle dependency) with `coalesce()` (narrow partition merging).","Fails to state the standard sizing heuristic (100MB-200MB per partition or 2-4x total cluster cores)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How have you contributed to ML platform architecture or infrastructure design, and what tools did you use for documentation and workflow design?', '{"key_points":[{"id":"KP1","description":"End-to-end ML platform architecture components and lifecycle stages","required":true,"acceptable_evidence":["Technical keywords: MLflow, DVC, feature store, model registry, FastAPI, Docker, Kubernetes/EKS, CI/CD pipeline.","Explains architecting decoupled pipelines: data versioning with DVC, training experiments and model artifacts registered in MLflow.","Details containerizing inference microservices with FastAPI and deploying onto Kubernetes (EKS) with horizontal autoscaling."]},{"id":"KP2","description":"Workflow orchestration and pipeline automation tooling","required":true,"acceptable_evidence":["Technical keywords: Prefect, Apache Airflow, DAG, scheduled retraining, event-driven orchestration, Slack alerts.","Explains designing automated DAGs for batch feature extraction, dataset validation, model retraining, and automated deployment.","Describes handling task dependencies, failure retries, and pipeline backfills in Prefect or Airflow."]},{"id":"KP3","description":"Production observability, drift monitoring, and feedback governance","required":true,"acceptable_evidence":["Technical keywords: Evidently AI, Prometheus, Grafana, drift detection, data quality checks, model cards.","Details integrating Evidently AI to monitor feature drift and prediction drift against the MLflow baseline.","Explains alerting on model performance drops and routing retraining triggers when drift exceeds thresholds."]},{"id":"KP4","description":"Architecture documentation and system design collaboration artifacts","required":true,"acceptable_evidence":["Technical keywords: C4 model, Architecture Decision Records (ADR), Miro, Lucidchart, OpenAPI specs, Notion.","Describes authoring Architecture Decision Records (ADRs) to justify tooling tradeoffs (e.g., MLflow vs Sagemaker).","Explains using C4 model diagrams and OpenAPI specifications to align data engineers, ML engineers, and backend teams."]}],"critical_failures":["Describes only training a standalone Jupyter notebook model without addressing platform infrastructure, registry, or orchestration.","Fails to mention workflow orchestration tools (Prefect, Airflow) or model lifecycle management (MLflow, DVC).","Omits documentation practices like ADRs or C4 architectural diagrams."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a REST API to handle large data payloads efficiently without overloading the system?', '{"key_points":[{"id":"KP1","description":"Streaming request and response processing to eliminate memory buffering","required":true,"acceptable_evidence":["Technical keywords: FastAPI, streaming request, chunked transfer encoding, StreamingResponse, generators, aiofiles.","Explains processing incoming payload streams in chunks using async generators rather than buffering entire gigabyte payloads in RAM.","Details returning large outputs via `StreamingResponse` with `Transfer-Encoding: chunked` or Server-Sent Events."]},{"id":"KP2","description":"Asynchronous ingestion via presigned URLs and object storage offloading","required":true,"acceptable_evidence":["Technical keywords: presigned S3 URL, AWS S3, async job queue, Celery, SQS, 202 Accepted, webhook.","Explains the claim-check pattern: client uploads large payload directly to S3 via presigned URL, bypassing API application servers.","Describes returning `202 Accepted` with a job ID and processing the file asynchronously via background workers (SQS/Celery)."]},{"id":"KP3","description":"Compression, pagination, and payload validation controls","required":true,"acceptable_evidence":["Technical keywords: Gzip/Brotli compression, cursor pagination, limit/offset, Content-Length limit, Pydantic.","Explains enforcing HTTP payload size limits (`413 Payload Too Large`) at the API Gateway / Nginx reverse proxy.","Details supporting client-side Gzip compression and implementing cursor-based pagination for large datasets to avoid deep-offset database scans."]},{"id":"KP4","description":"Rate limiting and backpressure protection","required":false,"acceptable_evidence":["Technical keywords: token bucket, slowapi, Redis rate limiting, circuit breaker, 429 Too Many Requests.","Describes applying concurrency limits and token bucket rate limits per tenant to prevent memory exhaustion under concurrent uploads."]}],"critical_failures":["Recommends reading entire large payloads into server RAM (`request.body()` in one buffer) without streaming or S3 offloading.","Fails to mention async job processing (202 Accepted) or presigned storage URLs for massive payloads.","Neglects API Gateway / reverse proxy size limits (413 Payload Too Large) and pagination mechanisms."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a system to handle multimodal data (text, images, audio) in a scalable architecture?', '{"key_points":[{"id":"KP1","description":"Decoupled ingestion and object storage architecture for diverse media formats","required":true,"acceptable_evidence":["Technical keywords: S3 object storage, presigned URLs, MIME type validation, metadata store, Docling, Whisper.","Explains storing raw media files (WAV audio, JPEG/PNG images, PDF docs) in object storage (S3) while recording structured metadata in PostgreSQL.","Details preprocessing pipelines: Whisper for audio transcription, Docling for PDF layout parsing, and OCR/Vision transformers for images."]},{"id":"KP2","description":"Multimodal embedding generation and unified vector search indexing","required":true,"acceptable_evidence":["Technical keywords: CLIP, ImageBind, Milvus, HNSW, vector dimension, cross-modal retrieval, multimodal embeddings.","Explains generating joint vector embeddings across modalities using CLIP or ImageBind so text and image queries project into a shared latent space.","Details indexing embeddings in Milvus with HNSW indexes and metadata filtering partitioned by modality type."]},{"id":"KP3","description":"Asynchronous event-driven processing pipelines and GPU worker decoupling","required":true,"acceptable_evidence":["Technical keywords: Apache Kafka, RabbitMQ, Celery, GPU worker pool, auto-scaling, batching.","Explains decoupling ingest from compute-heavy inference using Kafka or SQS queues to feed asynchronous GPU worker pools.","Describes dynamic batching of image/audio frames to maximize GPU tensor core utilization."]},{"id":"KP4","description":"Serving, fusion, and multimodal LLM generation","required":true,"acceptable_evidence":["Technical keywords: Multimodal LLM, GPT-4o, LLaVA, late fusion, early fusion, FastAPI async streaming.","Explains retrieving relevant cross-modal contexts and feeding structured text transcripts plus image bounding boxes into multimodal LLMs.","Details streaming generated responses to users via FastAPI SSE while tracking modal-specific latencies."]}],"critical_failures":["Suggests storing multi-megabyte binary images or audio blobs directly in SQL database tables instead of object storage (S3).","Fails to explain how multimodal data is converted into searchable representations (e.g., CLIP embeddings or Whisper transcripts).","Does not decouple heavy multimodal processing from the synchronous API ingest layer using async queues."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How would you design and implement a scalable UVM testbench architecture from scratch, including key components and their roles?', '{"key_points":[{"id":"KP1","description":"Hierarchical UVM component structure and phased testbench lifecycle.","required":true,"acceptable_evidence":["Technical keywords: uvm_test, uvm_env, uvm_agent, uvm_driver, uvm_monitor, uvm_sequencer, uvm_scoreboard, build_phase, connect_phase, run_phase.","Details the hierarchical organization: `uvm_test` encapsulates top `uvm_env`, which instantiates protocol agents, virtual sequencers, and scoreboards.","Explains execution phases: static component construction in `build_phase`, TLM port wiring in `connect_phase`, and time-consuming stimulus in `run_phase`."]},{"id":"KP2","description":"Agent architecture and stimulus generation with virtual sequencers.","required":true,"acceptable_evidence":["Technical keywords: active vs passive agent, virtual sequence, uvm_sequence, uvm_sequence_item, virtual sequencer, interface handle.","Explains structuring agents: active agents instantiate sequencer, driver, and monitor; passive agents instantiate only monitor for bus sniffing.","Details coordinating multi-interface protocol transactions using virtual sequences running on a central virtual sequencer."]},{"id":"KP3","description":"Scoreboarding, functional coverage, and configuration management.","required":true,"acceptable_evidence":["Technical keywords: uvm_config_db, uvm_analysis_port, TLM FIFO, coverage collector, golden predictor model.","Explains distributing virtual interfaces and configuration objects downward through the hierarchy using `uvm_config_db`.","Details broadcasting observed transactions via analysis ports to scoreboards for automated comparison against predictor outputs and coverage models."]}],"critical_failures":["Confuses software unit testing frameworks with hardware verification UVM component hierarchies.","Fails to describe the roles of driver (pin-level protocol toggling) versus monitor (passive transaction extraction) versus sequencer (stimulus arbitration).","Does not mention UVM phases (`build_phase`, `connect_phase`, `run_phase`) or configuration databases (`uvm_config_db`)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design and implement unit testing for an API-based backend system?', '{"key_points":[{"id":"KP1","description":"Test pyramid structure, isolation principles, and test framework tooling","required":true,"acceptable_evidence":["Technical keywords: pytest, pytest-asyncio, TestClient, FastAPI, isolation, test fixtures, coverage.","Explains using `pytest` and `httpx.AsyncClient` / FastAPI `TestClient` to execute isolated unit tests without spinning up a live network server.","Details scoping fixtures (`@pytest.fixture`) to set up clean state per test function."]},{"id":"KP2","description":"Mocking external dependencies, database layers, and third-party APIs","required":true,"acceptable_evidence":["Technical keywords: unittest.mock, AsyncMock, monkeypatch, dependency injection, FastAPI dependency_overrides.","Explains overriding FastAPI dependencies (`app.dependency_overrides[get_db] = get_test_db`) to inject in-memory databases or mocks.","Details mocking outbound LLM API calls and Milvus vector queries using `AsyncMock` to ensure deterministic, sub-second test execution."]},{"id":"KP3","description":"Validation testing for schemas, status codes, and error branches","required":true,"acceptable_evidence":["Technical keywords: Pydantic validation, 422 Unprocessable Entity, 401 Unauthorized, 403 Forbidden, 404 Not Found, 500 error handling.","Explains testing boundary edge cases: invalid payload types, missing required fields, SQL injection payloads, and expired JWT tokens.","Details asserting on exact error response schemas and HTTP status codes."]},{"id":"KP4","description":"CI/CD integration, coverage enforcement, and mutation testing","required":false,"acceptable_evidence":["Technical keywords: GitHub Actions, pytest-cov, coverage threshold (80%+), pre-commit hooks.","Describes running automated unit test suites in GitHub Actions CI pipelines with coverage thresholds preventing regressions."]}],"critical_failures":["Writes \'unit tests\' that make live HTTP calls to external third-party paid LLM APIs or production databases.","Fails to mention mocking techniques (`AsyncMock`, `dependency_overrides`) to isolate the code under test.","Tests only the happy path (200 OK) without asserting on schema validation errors, edge cases, or exception handling."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How would you design performance and load testing for an API, and what metrics would you monitor?', '{"key_points":[{"id":"KP1","description":"Load testing tool selection and realistic traffic simulation profiles","required":true,"acceptable_evidence":["Technical keywords: Locust, k6, JMeter, virtual users (VU), ramp-up, soak test, stress test, spike test.","Explains writing load scenarios in k6 or Locust simulating real user behavior (login, query submission, stream consumption).","Differentiates test profiles: ramp-up load testing, spike testing (sudden 10x traffic), and soak/endurance testing to detect memory leaks."]},{"id":"KP2","description":"Core latency and throughput metrics tracked at the API boundary","required":true,"acceptable_evidence":["Technical keywords: P50/P95/P99 latency, TTFT, RPS (requests per second), throughput, error rate (4xx/5xx).","Explains monitoring latency percentile distributions rather than arithmetic averages, targeting P95 < 2s and P99 < 3.5s.","Details tracking throughput saturation point where increased concurrent virtual users cause latency spikes and non-200 status codes."]},{"id":"KP3","description":"Infrastructure and resource utilization monitoring during load generation","required":true,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, CPU utilization, memory RSS, connection pool saturation, thread pool, network I/O.","Explains tracking container CPU and memory usage in Kubernetes pods to detect out-of-memory kills and GC pauses.","Details monitoring database connection pool exhaustion (e.g., asyncpg pool size) and Redis socket timeouts."]},{"id":"KP4","description":"Establishing performance baselines and regression gates in CI/CD","required":false,"acceptable_evidence":["Technical keywords: performance budget, threshold assertions, k6 thresholds, CI/CD regression gating.","Describes adding automated performance gates in deployment pipelines where PRs fail if P95 latency degrades by > 10%."]}],"critical_failures":["Relies exclusively on average latency instead of percentile distributions (P95/P99) to evaluate performance.","Tests only single-endpoint requests without modeling realistic user concurrency, think times, or mixed query distributions.","Fails to monitor infrastructure metrics (CPU, RAM, connection pools) alongside API response metrics."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you implement rate limiting and API security for AI applications serving multiple users?', '{"key_points":[{"id":"KP1","description":"Distributed rate limiting architectures using Redis algorithms","required":true,"acceptable_evidence":["Technical keywords: Redis, token bucket, sliding window counter, slowapi, 429 Too Many Requests, user_id/IP key.","Explains implementing sliding window or token bucket rate limiting in Redis keyed by authenticated `user_id` or tenant ID.","Details returning standard HTTP `429 Too Many Requests` headers with `Retry-After` when limits are breached."]},{"id":"KP2","description":"Token-aware rate limiting specifically designed for generative AI workloads","required":true,"acceptable_evidence":["Technical keywords: token budget, TPM (tokens per minute), RPM (requests per minute), tiktoken, streaming token counter.","Explains that request count alone is insufficient for LLMs because payload sizes vary wildly (e.g., 50 tokens vs 8,000 tokens).","Details tracking Tokens Per Minute (TPM) using pre-flight token estimation with `tiktoken` and post-generation adjustment."]},{"id":"KP3","description":"Authentication and authorization controls via JWT and OAuth2","required":true,"acceptable_evidence":["Technical keywords: JWT, OAuth2, Bearer token, RBAC, scopes, FastAPI Depends, secret rotation.","Explains validating signed JWT bearer tokens via FastAPI dependencies, checking cryptographic signatures and expiration (`exp`).","Details enforcing Role-Based Access Control (RBAC) scopes to restrict administrative tools or high-cost model tiers."]},{"id":"KP4","description":"AI-specific security controls and guardrail defenses","required":true,"acceptable_evidence":["Technical keywords: prompt injection defense, PII redaction, input validation, Pydantic, NeMo Guardrails, CORS.","Describes sanitizing user inputs against indirect prompt injections and system prompt override attempts.","Explains masking sensitive customer PII (credit cards, SSNs) before forwarding payloads to downstream LLMs or logging systems."]}],"critical_failures":["Suggests in-memory local dictionaries for rate limiting in multi-replica production environments without Redis.","Implements only request count rate limiting (RPM) while ignoring LLM token consumption limits (TPM).","Omits authentication verification (JWT/OAuth2) and fails to address prompt injection or PII exposure risks."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you incorporate continuous user feedback into the system to improve model performance and output quality over time?', '{"key_points":[{"id":"KP1","description":"Implicit and explicit feedback capture architecture at the API interface","required":true,"acceptable_evidence":["Technical keywords: explicit feedback (thumbs up/down, star ratings), implicit feedback (copy-to-clipboard, dwell time, regeneration), PostgreSQL.","Explains capturing explicit binary ratings (thumbs up/down) and text feedback tied directly to `message_id` and `trace_id`.","Details tracking implicit engagement signals: prompt regenerations, follow-up clarification queries, and agent response edits."]},{"id":"KP2","description":"Telemetry logging and trace correlation using LangSmith / OpenTelemetry","required":true,"acceptable_evidence":["Technical keywords: LangSmith, trace_id, run_id, metadata tagging, correlation, retrieval context logs.","Explains tagging feedback directly to execution traces in LangSmith, capturing exact prompt inputs, retrieved Milvus chunks, and model parameters.","Describes filtering traces with negative feedback to isolate retrieval failures vs generation hallucinations."]},{"id":"KP3","description":"Curating feedback into active learning datasets and hard-negative mining","required":true,"acceptable_evidence":["Technical keywords: active learning, hard-negative mining, golden dataset expansion, human-in-the-loop (HITL), DVC.","Explains extracting downvoted queries for domain expert review and labeling, converting failures into golden test set test cases.","Details updating embedding retrievers and cross-encoder rerankers using hard negative examples extracted from failed queries."]},{"id":"KP4","description":"Automated retraining triggers, fine-tuning, and offline regression verification","required":true,"acceptable_evidence":["Technical keywords: DPO (Direct Preference Optimization), RLHF, RAGAS regression benchmark, MLflow registry, Prefect workflow.","Explains compiling preference pairs (chosen vs rejected responses) for Direct Preference Optimization (DPO) or prompt refinement.","Details running automated RAGAS regression benchmarks in CI before deploying updated models or prompt versions."]}],"critical_failures":["Suggests retraining production LLMs continuously in real-time on live raw user input without validation or sanitization.","Fails to capture trace correlation (e.g., trace_id) between user feedback and the exact prompt/retrieval context.","Omits human-in-the-loop review or offline regression testing prior to updating production prompts or models."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How would you monitor production AI systems for latency, cost, failures, and quality degradation?', '{"key_points":[{"id":"KP1","description":"Latency and operational performance monitoring via Prometheus and Grafana","required":true,"acceptable_evidence":["Technical keywords: Prometheus, Grafana, /metrics endpoint, Histogram, P95/P99 latency, TTFT, throughput (RPS).","Explains instrumenting FastAPI with Prometheus metrics: `response_time_seconds` histogram and TTFT (time-to-first-token) gauge.","Details configuring Grafana dashboards and PagerDuty alert rules when P95 latency exceeds 2.0s."]},{"id":"KP2","description":"Granular cost and token consumption tracking","required":true,"acceptable_evidence":["Technical keywords: token counters, prompt_tokens, completion_tokens, cost per query, tenant attribution, LangSmith.","Explains logging prompt and completion tokens partitioned by model type, tenant ID, and endpoint route.","Details alerting on anomalous spending velocity or runaway recursive agent loops before budget exhaustion."]},{"id":"KP3","description":"Error tracking and distributed execution tracing for failure analysis","required":true,"acceptable_evidence":["Technical keywords: LangSmith, OpenTelemetry, Sentry, error rate counter, tool call failures, fallback circuit breaker.","Explains tracing multi-step agent graphs in LangSmith to pinpoint failing MCP tool calls, database timeouts, and rate limits.","Describes monitoring 4xx/5xx HTTP error spikes in Sentry with full stack traces and context payloads."]},{"id":"KP4","description":"Output quality evaluation and data/embedding drift detection","required":true,"acceptable_evidence":["Technical keywords: Evidently AI, RAGAS (faithfulness, relevancy), drift detection, LLM judge, semantic similarity.","Explains running periodic background RAGAS evaluation on sampled production queries to monitor faithfulness trends.","Details using Evidently AI to detect embedding drift, distribution shifts in user queries, and retrieval hit-rate degradation."]}],"critical_failures":["Monitors only standard server CPU/memory while ignoring AI-specific dimensions (tokens, RAGAS faithfulness, TTFT).","Lacks an execution tracing framework (like LangSmith or OpenTelemetry) to diagnose multi-step agent reasoning failures.","Fails to define concrete alert thresholds for cost surges, latency degradation, or quality drops."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you optimize data-heavy UI components to improve performance and user experience in large-scale applications?', '{"key_points":[{"id":"KP1","description":"DOM virtualization and windowing for high-volume tabular or list data","required":true,"acceptable_evidence":["Technical keywords: virtualization, react-window, react-virtualized, DOM node count, viewport rendering, 60 FPS.","Explains rendering only visible rows within the user viewport instead of mounting thousands of DOM nodes simultaneously.","Details calculating item offsets and dynamic row heights to keep DOM size small and scrolling smooth at 60 FPS."]},{"id":"KP2","description":"Data pagination, infinite scrolling, and chunked fetching strategies","required":true,"acceptable_evidence":["Technical keywords: cursor-based pagination, infinite query, TanStack Query (React Query), prefetching, caching.","Explains replacing massive full-dataset payloads with cursor-based pagination (e.g., 50 records per page).","Details caching and background refetching via TanStack Query to eliminate duplicate network calls."]},{"id":"KP3","description":"Debouncing, throttling, and offloading heavy compute from the main JavaScript thread","required":true,"acceptable_evidence":["Technical keywords: debounce, throttle, Web Workers, useDeferredValue, useTransition, search filtering.","Explains debouncing search inputs (300ms) to avoid re-filtering massive arrays on every keystroke.","Describes offloading heavy data sorting/transformations to Web Workers or using React 18 `useTransition` to keep inputs responsive."]},{"id":"KP4","description":"Component memoization and referential stability optimization","required":true,"acceptable_evidence":["Technical keywords: React.memo, useMemo, useCallback, shallow comparison, column renderers.","Explains memoizing row and cell renderer components with `React.memo` and caching computed values via `useMemo`.","Details stabilizing callback props with `useCallback` to prevent cascading re-renders across the table grid."]}],"critical_failures":["Recommends mounting tens of thousands of DOM elements directly into the browser without virtualization or pagination.","Fails to mention virtualization libraries (`react-window`, `react-virtualized`) for large datasets.","Ignores client-side main thread blocking during intensive data sorting, filtering, or search interactions."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you optimize performance when a backend API involves long-running database queries?', '{"key_points":[{"id":"KP1","description":"Query plan analysis, indexing, and relational schema optimization","required":true,"acceptable_evidence":["Technical keywords: EXPLAIN ANALYZE, Seq Scan, Index Scan, composite index, partial index, query rewrite.","Explains running `EXPLAIN (ANALYZE, BUFFERS)` in PostgreSQL to identify slow sequential scans, hash joins, or high disk reads.","Details creating composite indexes on `(tenant_id, created_at DESC)` and rewriting correlated subqueries into efficient JOINs."]},{"id":"KP2","description":"Decoupling long queries via asynchronous task execution and job queues","required":true,"acceptable_evidence":["Technical keywords: Celery, Redis queue, SQS, 202 Accepted, polling endpoint, WebSockets, background worker.","Explains avoiding HTTP request timeouts by converting synchronous requests into async background jobs.","Details returning `202 Accepted` with a `job_id`, delegating the heavy query to worker processes, and notifying the client via WebSocket or polling."]},{"id":"KP3","description":"Read/write separation and materialized views for precomputed aggregations","required":true,"acceptable_evidence":["Technical keywords: read replicas, materialized views, REFRESH MATERIALIZED VIEW CONCURRENTLY, CQRS.","Explains offloading analytical, long-running SELECT queries to read replicas using PgBouncer to preserve primary write capacity.","Describes maintaining materialized views refreshed periodically or using Redis to cache precomputed metric aggregations."]},{"id":"KP4","description":"Connection pool tuning and statement timeout protections","required":true,"acceptable_evidence":["Technical keywords: asyncpg, PgBouncer, statement_timeout, connection pool exhaustion, idle connections.","Explains configuring strict `statement_timeout` (e.g., 5000ms) to cancel runaway queries before they exhaust connection pools.","Details tuning async connection pool min/max sizes to avoid thread starvation."]}],"critical_failures":["Suggests letting HTTP requests block synchronously for minutes until the database query completes, risking gateway timeouts (504).","Fails to use database query diagnostics like `EXPLAIN ANALYZE` to pinpoint query bottlenecks.","Omits asynchronous background processing (202 Accepted + queue) for heavy analytical queries."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How would you optimize recursion-heavy logic in Python to avoid performance bottlenecks?', '{"key_points":[{"id":"KP1","description":"Eliminating redundant recursive subproblems using memoization and dynamic programming","required":true,"acceptable_evidence":["Technical keywords: functools.lru_cache, memoization, cache_clear, hashable arguments, O(2^N) to O(N).","Explains decorating recursive functions with `@functools.lru_cache(maxsize=128)` to cache previous computations.","Details how memoization drastically reduces time complexity from exponential to linear or polynomial for overlapping subproblems."]},{"id":"KP2","description":"Preventing stack overflow by converting recursion to iteration with an explicit stack","required":true,"acceptable_evidence":["Technical keywords: RecursionError, sys.getrecursionlimit, iterative conversion, explicit stack (list/deque), heap memory.","Explains that Python defaults to a recursion depth limit (1000) and does not support automatic Tail Call Optimization (TCO).","Details refactoring recursive algorithms to iterative loops using `collections.deque` or a Python `list` as an explicit stack on the heap."]},{"id":"KP3","description":"Memory and call frame overhead considerations in Python\'s execution model","required":true,"acceptable_evidence":["Technical keywords: call frame overhead, frame allocation, sys.setrecursionlimit, CPython stack, garbage collection.","Explains why simply increasing `sys.setrecursionlimit()` is dangerous and can lead to C-level segmentation faults.","Discusses the performance cost of Python frame creation compared to simple loop iterations and generator pipelines."]},{"id":"KP4","description":"Generator-based trampolining and tail-call emulation techniques","required":false,"acceptable_evidence":["Technical keywords: trampoline, generator yield, tail-call emulation.","Describes using trampolining with generators where recursive functions yield intermediate callables to a driver loop."]}],"critical_failures":["Suggests merely increasing `sys.setrecursionlimit()` as the production solution without addressing memory or stack overflow risks.","Fails to identify that Python does NOT have native Tail Call Optimization (TCO).","Does not mention memoization (`functools.lru_cache`) or iterative stack-based refactoring."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you optimize the getHits operation to avoid latency spikes when processing large volumes of data?', '{"key_points":[{"id":"KP1","description":"Data structure optimization using sliding window buckets instead of raw event storage","required":true,"acceptable_evidence":["Technical keywords: sliding window, circular buffer, fixed time buckets, granular buckets (seconds/minutes), O(1) complexity.","Explains replacing unbounded event timestamps with a fixed-size circular array or bucketed counters (e.g., 300 1-second buckets for 5 minutes).","Details aggregating hit counts per second so `getHits()` sums bucket counts in O(B) time rather than scanning millions of raw entries."]},{"id":"KP2","description":"Distributed in-memory caching and Redis data structures for high-throughput counting","required":true,"acceptable_evidence":["Technical keywords: Redis, ZREMRANGEBYSCORE, ZRANGEBYSCORE, Redis HyperLogLog, Hash buckets, atomic INCR.","Explains using Redis Sorted Sets (`ZADD`, `ZREMRANGEBYSCORE`) with timestamp scores or bucketed Redis Hashes with TTLs.","Details the latency penalty of large Sorted Sets under high load and transitioning to bucketed counters (`HINCRBY`) to avoid lock contention."]},{"id":"KP3","description":"Asynchronous write buffering and background aggregation to protect read latency","required":true,"acceptable_evidence":["Technical keywords: write-back buffer, batching, asyncio.Queue, atomic accumulator, pre-aggregation.","Explains buffering incoming hits in local memory and flushing aggregates in batch every 100ms to reduce database write operations.","Details keeping a pre-aggregated running sum updated asynchronously so `getHits` performs an instantaneous O(1) read."]},{"id":"KP4","description":"Concurrency safety, lock-free operations, and distributed coordination","required":false,"acceptable_evidence":["Technical keywords: lock contention, atomic operations, read-write lock, Redis cluster.","Describes using atomic operations or partitioned sharded counters to prevent lock contention across multiple application threads."]}],"critical_failures":["Proposes scanning an unindexed, unbounded database table or list of raw timestamps on every `getHits` invocation.","Fails to implement sliding window bucket aggregation or circular buffer data structures.","Does not address concurrency bottlenecks or memory consumption under high hit volume."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you optimize the tile-fetching process to reduce runtime, and how does asynchronous execution improve performance in this case?', '{"key_points":[{"id":"KP1","description":"Asynchronous concurrent I/O to eliminate sequential network blocking","required":true,"acceptable_evidence":["Technical keywords: asyncio, httpx.AsyncClient, asyncio.gather, concurrency, event loop, non-blocking I/O.","Explains that tile fetching is heavily I/O-bound (network latency per HTTP tile request).","Details replacing sequential requests with `asyncio.gather(*[fetch_tile(url) for url in tile_urls])` to download hundreds of tiles concurrently."]},{"id":"KP2","description":"Concurrency limiting and connection pooling to avoid resource exhaustion","required":true,"acceptable_evidence":["Technical keywords: asyncio.Semaphore, connection pool limits, TCP handshake, HTTP keep-alive, socket exhaustion.","Explains using `asyncio.Semaphore(50)` to restrict concurrent in-flight requests and prevent server rate limiting or local socket exhaustion.","Details reusing persistent HTTP connections via `httpx.AsyncClient(limits=limits)` with keep-alive to bypass TLS/TCP handshakes."]},{"id":"KP3","description":"Multi-tier caching strategy (in-memory LRU and distributed cache)","required":true,"acceptable_evidence":["Technical keywords: Redis, LRU cache, tile coordinate keys (z/x/y), CDN, cache hit ratio.","Explains caching pre-fetched tiles in Redis or local memory keyed by coordinate quadtree/slippy tile coordinates (`z/x/y`).","Describes checking cache first to satisfy requests in sub-milliseconds without triggering network fetches."]},{"id":"KP4","description":"Bounding box pruning and spatial prefetching strategies","required":false,"acceptable_evidence":["Technical keywords: spatial index, bounding box (BBox), quadtree, speculative prefetching.","Discusses computing viewport bounding boxes to fetch only visible tiles and speculatively prefetching adjacent border tiles."]}],"critical_failures":["Suggests synchronous multithreading or multiprocessing for purely network I/O-bound tasks without discussing async/event loop benefits.","Launches thousands of unbounded concurrent requests without Semaphore throttling or connection pooling, risking system crashes.","Fails to identify caching (Redis/LRU) based on spatial tile coordinate keys."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How would you store and manage conversation history in a chat system, and what are the trade-offs between SQL and NoSQL databases for this use case?', '{"key_points":[{"id":"KP1","description":"Differentiating ephemeral working session memory from persistent long-term conversation storage","required":true,"acceptable_evidence":["Technical keywords: working memory, ephemeral cache, Redis, persistent storage, PostgreSQL, LangGraph MemorySaver.","Explains storing active session turns in Redis with TTLs or LangGraph checkpointers for sub-5ms conversational latency.","Details archiving completed turns and session metadata asynchronously into durable persistent database storage."]},{"id":"KP2","description":"SQL database architecture: schema design, JSONB flexibility, and transactional ACID guarantees","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, JSONB, schema validation, foreign keys, ACID compliance, audit trails.","Explains modeling conversations in PostgreSQL: `conversations` table joined with `messages` table storing roles, timestamps, and JSONB tool calls.","Highlights SQL advantages: strong relational integrity, complex analytical querying, strict compliance/auditing, and typed schemas."]},{"id":"KP3","description":"NoSQL database architecture: document/key-value flexibility, horizontal write scaling, and partitioning","required":true,"acceptable_evidence":["Technical keywords: DynamoDB, MongoDB, Cassandra, partition key (session_id), sort key (timestamp), horizontal scaling.","Explains modeling chats in DynamoDB or MongoDB with `session_id` as partition key and message timestamp as sort key.","Highlights NoSQL trade-offs: massive horizontal write scalability and flexible payload schemas vs lack of cross-entity joins and eventual consistency."]},{"id":"KP4","description":"Context window pruning, token budget management, and long-term semantic retrieval","required":true,"acceptable_evidence":["Technical keywords: token budget, sliding window, summary memory, Milvus vector search, message trimming.","Explains that raw chat histories exceed LLM context windows; applies sliding window trimming (last K turns) plus recursive LLM summarization.","Details indexing past conversation insights into vector stores (Milvus) to recall relevant past interactions semantically."]}],"critical_failures":["Fails to distinguish between fast ephemeral working memory (Redis) and durable historical storage (PostgreSQL/NoSQL).","Does not address LLM token context limits, failing to explain sliding window trimming or summarization.","Presents a one-sided database comparison without discussing trade-offs (e.g., ACID vs horizontal write scaling)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you use techniques like debouncing, placeholders, or progressive rendering to improve perceived performance on the frontend?', '{"key_points":[{"id":"KP1","description":"Debouncing and throttling mechanisms for user interaction and network request management","required":true,"acceptable_evidence":["Technical keywords: debouncing, throttling, setTimeout, clearTimeout, search-as-you-type, network traffic reduction.","Explains debouncing input fields (e.g., 300ms delay) to reset timer on each keystroke and trigger API queries only after user pauses.","Contrasts debouncing with throttling (guaranteeing execution every N milliseconds) for continuous events like window scrolling or resizing."]},{"id":"KP2","description":"Skeleton screens, placeholders, and layout stability to reduce perceived load time","required":true,"acceptable_evidence":["Technical keywords: skeleton screens, shimmer effect, layout shift, Cumulative Layout Shift (CLS), visual hierarchy.","Explains displaying skeleton placeholders that mimic final content dimensions, eliminating jarring spinner overlays.","Details preventing layout shifts (improving Core Web Vitals CLS) by reserving layout space before media and data arrive."]},{"id":"KP3","description":"Progressive and streaming rendering techniques to provide instant feedback","required":true,"acceptable_evidence":["Technical keywords: progressive rendering, React Suspense, streaming SSR, Server-Sent Events, token streaming.","Explains streaming LLM tokens incrementally via SSE so users read answers immediately rather than waiting seconds for full responses.","Details progressive hydration and selective rendering using `<Suspense>` boundaries to prioritize critical above-the-fold UI elements."]},{"id":"KP4","description":"Optimistic UI updates to provide zero-latency user interactions","required":false,"acceptable_evidence":["Technical keywords: optimistic UI, rollback, cache mutation, TanStack Query.","Describes rendering user state changes instantly (e.g., submitting a comment or like) before receiving the server confirmation."]}],"critical_failures":["Confuses actual performance optimization (raw execution speed) with perceived performance (user psychological perception).","Unable to explain the technical implementation of debouncing (timer cancellation and reset).","Omits token streaming or skeleton placeholders when discussing perceived responsiveness in modern interactive apps."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would your architecture change if ticket data scaled from hundreds of GBs to multiple TBs?', '{"key_points":[{"id":"KP1","description":"Database tier evolution: from single-node relational DB to distributed storage and sharding","required":true,"acceptable_evidence":["Technical keywords: sharding, horizontal partitioning, table partitioning (pg_partman), distributed SQL, Citus, DynamoDB.","Explains replacing single PostgreSQL instances with time-based and tenant-based table partitioning (range partitioning on `created_at`).","Details transitioning high-volume write ingestion to distributed databases (Citus, CockroachDB, or DynamoDB) keyed by `tenant_id`."]},{"id":"KP2","description":"Tiered storage lifecycle: hot, warm, and cold data separation","required":true,"acceptable_evidence":["Technical keywords: tiered storage, AWS S3, Parquet, data lake, Athena, Snowflake, TTL archival.","Explains maintaining recent 30-day ticket data in fast SSD hot storage, moving warm data (1-12 months) to read-only replicas.","Details offloading historical multi-TB ticket logs to cold object storage (S3) formatted in columnar Parquet files for Athena/Spark analytics."]},{"id":"KP3","description":"Asynchronous ingestion and streaming pipeline decoupling","required":true,"acceptable_evidence":["Technical keywords: Apache Kafka, message buffering, backpressure, distributed consumers, Spark Structured Streaming.","Explains decoupling ticket submission from ingestion using Apache Kafka to absorb high-throughput ingestion spikes.","Describes running batch/stream workers to process and persist tickets without overwhelming primary database connections."]},{"id":"KP4","description":"Search and retrieval indexing scaling strategies","required":true,"acceptable_evidence":["Technical keywords: Elasticsearch/OpenSearch cluster, Milvus distributed cluster, index sharding, replica routing.","Explains scaling search systems from embedded or single-node vector stores to distributed Milvus clusters with independent query/data nodes."]}],"critical_failures":["Suggests simply increasing single-node PostgreSQL RAM and disk without architectural partitioning or storage tiering.","Fails to introduce cold archival storage (S3/Parquet) for multi-TB historical ticket data.","Neglects ingestion bottlenecks, failing to implement distributed message queues (Kafka) to handle write scale."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How would your architecture evolve as data scales from hundreds of GBs to TBs, including strategies for vector search, partitioning, and indexing?', '{"key_points":[{"id":"KP1","description":"Vector database scaling: transitioning to a distributed, decoupled vector cluster","required":true,"acceptable_evidence":["Technical keywords: Milvus distributed cluster, coordinator nodes, data nodes, query nodes, MinIO/S3 object storage, segment management.","Explains migrating from standalone Milvus/pgvector to a distributed Milvus cluster where query nodes and data nodes scale independently.","Details delegating vector persistence to cloud object storage (S3/MinIO) while caching active index segments in RAM."]},{"id":"KP2","description":"Vector indexing strategies under multi-TB memory constraints","required":true,"acceptable_evidence":["Technical keywords: HNSW vs IVF_PQ, product quantization, scalar quantization (SQ8), RAM footprint, recall vs latency.","Explains that unquantized HNSW requires massive RAM (tens of GBs per million vectors) which becomes cost-prohibitive at TB scale.","Details adopting scalar quantization (SQ8) or Product Quantization (IVF_PQ) and disk-backed graph indexes (DiskANN) to reduce memory by 75%+."]},{"id":"KP3","description":"Partitioning and tenant-based vector routing","required":true,"acceptable_evidence":["Technical keywords: partition keys, physical partition, metadata filtering, collection sharding, tenant isolation.","Explains sharding vector collections by physical partition keys (e.g., `tenant_id` or `year_month`).","Details routing queries to specific partition shards to prune vector search search-space from billions of vectors down to targeted subsets."]},{"id":"KP4","description":"Asynchronous batch indexing and hybrid search pipeline evolution","required":true,"acceptable_evidence":["Technical keywords: Kafka, Spark embedding generation, BM25 OpenSearch cluster, hybrid fusion, segment compaction.","Explains offloading embedding generation to distributed Spark/Ray worker pools feeding Kafka topics for asynchronous Milvus ingestion.","Details coupling distributed Milvus with an OpenSearch cluster for scalable hybrid lexical-semantic retrieval."]}],"critical_failures":["Recommends keeping pure in-memory uncompressed HNSW indexes for terabytes of vectors without calculating prohibitive RAM costs.","Fails to explain partitioning or collection sharding strategies to restrict search scope across large datasets.","Does not differentiate between standalone vector instances and distributed architectures with decoupled compute/storage nodes."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What approach did you use to implement persistent memory in your system, and how did combining vector search with a knowledge graph improve performance?', '{"key_points":[{"id":"KP1","description":"Tiered persistent memory architecture: separating conversational state from long-term memory","required":true,"acceptable_evidence":["Technical keywords: LangGraph MemorySaver, checkpointer, Redis session cache, Milvus, Neo4j, persistent state.","Explains managing short-term conversational session state using LangGraph checkpointers and Redis.","Details extracting episodic facts and user preferences into long-term durable stores (Milvus vector DB and Neo4j graph) across sessions."]},{"id":"KP2","description":"Combining vector search with knowledge graph traversal (GraphRAG)","required":true,"acceptable_evidence":["Technical keywords: GraphRAG, Neo4j, Milvus, hybrid retrieval, Cypher queries, entities, relationships, multi-hop reasoning.","Explains that vector search retrieves semantically similar unstructured text chunks but fails at multi-hop relational dependencies.","Details querying Neo4j knowledge graph for structured entity relationships (e.g., `User -[OWNS]-> Policy -[COVERS]-> Claim`) to provide exact relational context."]},{"id":"KP3","description":"Performance and accuracy improvements achieved by the hybrid architecture","required":true,"acceptable_evidence":["Technical keywords: RAGAS context_recall, hallucination reduction, disambiguation, structured context injection.","Explains how combining vector semantic hits with 1-to-2 hop knowledge graph subgraphs eliminates hallucinations regarding entity relations.","Details measurable gains in RAGAS context_precision and context_recall compared to vector-only baselines."]},{"id":"KP4","description":"Memory lifecycle management, pruning, and privacy governance","required":true,"acceptable_evidence":["Technical keywords: TTL, memory summarization, PII redaction, token budget, entity resolution.","Describes periodic memory consolidation: summarizing aged interactions and pruning outdated graph facts.","Explains enforcing tenant isolation and privacy controls (redacting PII before committing to persistent graph memory)."]}],"critical_failures":["Confuses short-term working context window with persistent long-term cross-session memory.","Cannot articulate the specific value of a Knowledge Graph over vector search (e.g., multi-hop reasoning, explicit relationships).","Fails to explain how retrieved vector chunks and knowledge graph subgraphs are combined into the prompt context."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What are the trade-offs between SQL and NoSQL databases in scalable AI systems, and how do you design read/write separation?', '{"key_points":[{"id":"KP1","description":"Core trade-off analysis: SQL relational integrity vs NoSQL horizontal scaling","required":true,"acceptable_evidence":["Technical keywords: PostgreSQL, DynamoDB, MongoDB, ACID transactions, eventual consistency, schema flexibility, horizontal vs vertical scaling.","Explains SQL strengths: strong ACID consistency, complex relational joins, structured schema validation, and auditability for financial/user billing.","Explains NoSQL strengths: effortless horizontal partitioning, high write throughput, and flexible JSON document schemas for varying model outputs."]},{"id":"KP2","description":"Read/write separation architecture using replicas and CQRS pattern","required":true,"acceptable_evidence":["Technical keywords: read replicas, primary/replica, CQRS (Command Query Responsibility Segregation), replication lag, write master.","Explains directing mutating operations (INSERT/UPDATE/DELETE) exclusively to primary master node while routing read queries to horizontally scaled read replicas.","Details the CQRS pattern: writing raw events to an operational store and projecting read-optimized views into fast caching/search stores."]},{"id":"KP3","description":"Mitigating replication lag and consistency anomalies in AI workflows","required":true,"acceptable_evidence":["Technical keywords: replication lag, read-your-own-writes consistency, sticky sessions, Redis cache invalidation.","Explains handling replication lag where an agent writes a message but an immediate read replica query returns stale state.","Details solutions: read-your-own-writes routing (reading from primary for 2 seconds post-write) or fetching immediate state from Redis."]},{"id":"KP4","description":"Connection routing and connection pooling infrastructure","required":false,"acceptable_evidence":["Technical keywords: PgBouncer, AWS Aurora read endpoint, proxy routing, connection pooling.","Describes using PgBouncer and cloud database cluster endpoints (writer vs reader endpoints) to automate traffic distribution."]}],"critical_failures":["Claims NoSQL is always better for scale without acknowledging loss of ACID transactions and relational joins.","Fails to explain the read-your-own-writes consistency hazard caused by replication lag in read-replica architectures.","Does not explain the mechanism of read/write separation (e.g., primary writer with read replica pool)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What considerations are important when designing scalable ML systems for high-volume environments such as manufacturing or sensor-based data streams?', '{"key_points":[{"id":"KP1","description":"High-throughput streaming ingestion and stream-processing architecture","required":true,"acceptable_evidence":["Technical keywords: Apache Kafka, MQTT, Spark Structured Streaming, Flink, backpressure, high-frequency time series.","Explains ingesting massive sensor telemetry (thousands of events/sec) via lightweight protocols (MQTT/Kafka).","Details windowed stream processing (tumbling/sliding windows) in Flink or Spark to compute moving averages and rolling variance."]},{"id":"KP2","description":"Low-latency inference strategies at the edge vs centralized cloud","required":true,"acceptable_evidence":["Technical keywords: edge computing, ONNX Runtime, TensorRT, model quantization (INT8), local inference, offline resilience.","Explains deploying quantized models (e.g., XGBoost, ONNX) directly onto edge gateways on the manufacturing floor for sub-10ms anomaly detection.","Details cloud vs edge trade-offs: edge guarantees operation during network outages, while cloud handles heavy retraining and aggregate analytics."]},{"id":"KP3","description":"Feature store and specialized time-series data storage","required":true,"acceptable_evidence":["Technical keywords: TimescaleDB, InfluxDB, Feast feature store, downsampling, cold tiering, Parquet/S3.","Explains persisting raw high-frequency sensor readings into time-series optimized databases (TimescaleDB) with automatic downsampling policies.","Describes synchronizing real-time features between edge cache and training feature stores to eliminate train-serve skew."]},{"id":"KP4","description":"Continuous monitoring for sensor degradation, noise, and data drift","required":true,"acceptable_evidence":["Technical keywords: Evidently AI, concept drift, sensor calibration drift, missing data imputation, anomaly detection.","Explains detecting sensor drift (physical hardware wear or fouling) using Kolmogorov-Smirnov tests and baseline distribution comparisons.","Details resilient handling of packet drops, out-of-order timestamps, and missing sensor values via forward-filling or imputation."]}],"critical_failures":["Proposes batch REST API polling over HTTP for millions of real-time industrial sensors instead of streaming protocols (Kafka/MQTT).","Fails to address network disconnection risks on factory floors, ignoring edge deployment or local inference resilience.","Neglects sensor drift and physical data corruption common in high-volume industrial environments."]}', 1),
('TECHNICAL', 'Software Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 90, 'What data augmentation techniques have you implemented for NLP tasks, and how did they impact model performance?', '{"key_points":[{"id":"KP1","description":"Lexical and rule-based text augmentation techniques.","required":true,"acceptable_evidence":["Technical keywords: synonym replacement, WordNet, word embedding similarity (Word2Vec, GloVe), random deletion, random swap, random insertion, EDA (Easy Data Augmentation).","Explains replacing non-stopword tokens with semantic synonyms using WordNet or cosine nearest neighbors in vector space to preserve sentence intent.","Details applying EDA techniques (controlled token insertion, swapping, deletion) while ensuring syntactic coherence is not destroyed."]},{"id":"KP2","description":"Model-based and generative augmentation methods.","required":true,"acceptable_evidence":["Technical keywords: back-translation, machine translation models (MarianMT), masked language model insertion (BERT), contextual paraphrasing, LLM synthetic generation.","Explains back-translation pipeline: translating source text into pivot languages (e.g., German, French) and back to English to generate fluent semantic paraphrases.","Details using masked language models (BERT/RoBERTa) to predict context-aware replacement tokens for masked spans."]},{"id":"KP3","description":"Empirical impact on generalization, overfitting, and validation guardrails.","required":true,"acceptable_evidence":["Technical keywords: out-of-distribution (OOD) generalization, cross-entropy loss, F1-score, label preservation, semantic drift, threshold filtering.","Explains quantitative improvements: reducing overfitting in low-resource data regimes, yielding +3-8% gains in macro F1-score on rare intent classes.","Details filtering augmented samples using embedding similarity thresholds or semantic consistency classifiers to prevent label noise."]}],"critical_failures":["Recommends aggressive random word replacement without semantic constraints, creating contradictory training labels.","Fails to mention back-translation or contextual language model augmentation.","Cannot explain how augmented data is validated to prevent semantic drift and degraded model accuracy."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is a broadcast join in Spark, and how does it improve performance compared to standard joins?', '{"key_points":[{"id":"KP1","description":"Mechanism of Broadcast Hash Join: copying the small dataset to all executor nodes","required":true,"acceptable_evidence":["Technical keywords: Broadcast Hash Join (BHJ), broadcast(), spark.sql.autoBroadcastJoinThreshold, driver memory, executor hash table.","Explains that the driver collects the small DataFrame and broadcasts an identical copy to the memory of all cluster executors.","Details building an in-memory hash table on each executor against which the local partitions of the large table are streamed and joined."]},{"id":"KP2","description":"Performance advantage: complete elimination of expensive network shuffle","required":true,"acceptable_evidence":["Technical keywords: shuffle elimination, Sort-Merge Join (SMJ), network I/O, disk spill, stage boundary, narrow dependency.","Explains that standard Sort-Merge Joins require hashing, sorting, and shuffling both datasets across the network to matching partitions.","Details how broadcast joins eliminate shuffle exchanges, disk serialization, and sorting overhead, turning wide dependencies into narrow operations."]},{"id":"KP3","description":"Threshold configurations, explicit hints, and Adaptive Query Execution (AQE)","required":true,"acceptable_evidence":["Technical keywords: autoBroadcastJoinThreshold (default 10MB), broadcast hint (broadcast(df)), AQE runtime conversion.","Explains automatic threshold configuration (`spark.sql.autoBroadcastJoinThreshold`) and programmatic hints (`F.broadcast(lookup_df)`).","Describes how Spark 3.x AQE automatically converts a planned SortMergeJoin to a BroadcastJoin if runtime filtering reduces table size below threshold."]},{"id":"KP4","description":"Limitations and failure modes (driver/executor OutOfMemory errors)","required":true,"acceptable_evidence":["Technical keywords: driver OOM, OutOfMemoryError, threshold limits, broadcast size limit.","Explains that broadcasting large datasets exceeds driver memory or executor RAM, causing fatal OutOfMemory crashes.","Highlights rule: only broadcast dimension/lookup tables that safely fit into memory (typically under a few hundred MBs)."]}],"critical_failures":["Claims broadcast join shuffles both tables across the network instead of sending the small table to executors to avoid shuffle.","Fails to identify driver or executor OutOfMemory (OOM) risk when broadcasting oversized datasets.","Does not contrast Broadcast Hash Join with Sort-Merge Join."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between dense models and mixture-of-experts models, and how do their architectures impact performance and efficiency?', '{"key_points":[{"id":"KP1","description":"Fundamental architectural distinction between dense computation and sparse routing.","required":true,"acceptable_evidence":["Technical keywords: dense model vs sparse Mixture-of-Experts (MoE), router/gating network, expert FFN layers, active parameters vs total parameters.","Explains that dense models activate 100% of parameters for every input token, whereas MoE models replace standard FFN layers with multiple expert sub-networks.","Details the role of the gating network computing softmax routing probabilities to select a sparse subset (e.g., top-1 or top-2 experts) per token."]},{"id":"KP2","description":"Computational efficiency, FLOPs, and inference latency trade-offs.","required":true,"acceptable_evidence":["Technical keywords: computational cost (FLOPs per token), throughput, pretraining efficiency, inference memory footprint (VRAM), expert parallelism.","Explains that MoE achieves the representational capacity of a large model with the compute cost (FLOPs) of a much smaller model during inference.","Highlights that while inference compute is low, the full parameter set must reside in GPU VRAM, increasing memory requirements compared to equivalent compute-size dense models."]},{"id":"KP3","description":"Training and deployment challenges: load balancing and routing routing stability.","required":true,"acceptable_evidence":["Technical keywords: auxiliary load balancing loss, expert collapse, routing overhead, batch size efficiency, all-to-all communication.","Describes the expert collapse problem (where router sends all tokens to the same 1-2 experts) and the auxiliary loss penalty used to enforce uniform load distribution.","Details communication overhead in distributed expert parallelism where token dispatch across GPUs introduces all-to-all network latency."]}],"critical_failures":["Claims MoE activates all experts simultaneously for every token (confusing sparse MoE with ensemble models).","Fails to distinguish between total model parameters in VRAM and active parameter count per forward pass.","Does not mention the router/gating mechanism or expert load balancing challenges."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is the difference between wrap_content and match_parent, and how do they impact layout performance?', '{"key_points":[{"id":"KP1","description":"Core layout measurement semantics of wrap_content versus match_parent.","required":true,"acceptable_evidence":["Technical keywords: wrap_content, match_parent (fill_parent), MeasureSpec (EXACTLY vs AT_MOST), View.onMeasure(), parent layout constraints.","Explains that `match_parent` instructs a view to expand to occupy all available space allocated by its parent (corresponding to `MeasureSpec.EXACTLY`).","Explains that `wrap_content` sizes the view to fit its internal content dimensions (corresponding to `MeasureSpec.AT_MOST`)."]},{"id":"KP2","description":"Impact on view measurement passes, hierarchy traversals, and double taxation.","required":true,"acceptable_evidence":["Technical keywords: layout measurement pass, double taxation, nested layout weights, onMeasure overhead, view hierarchy depth.","Explains that `wrap_content` frequently triggers multi-pass measurements (double taxation) because parents must measure children once, calculate bounds, and remeasure.","Highlights performance penalties when combining `wrap_content` with nested `LinearLayout` weights or complex `RelativeLayout` constraints."]},{"id":"KP3","description":"Optimization strategies and modern layout architectures.","required":true,"acceptable_evidence":["Technical keywords: ConstraintLayout, flat view hierarchy, 0dp (MATCH_CONSTRAINT), Systrace frame drops, 16ms frame budget (60 FPS).","Recommends replacing deeply nested layouts with a flat `ConstraintLayout` using `0dp` (`MATCH_CONSTRAINT`) to eliminate redundant measure passes.","Details monitoring layout inflation and measurement times with Systrace to guarantee frame rendering stays within 16ms."]}],"critical_failures":["Reverses the definitions of wrap_content and match_parent.","Cannot explain why wrap_content incurs greater measurement overhead than match_parent (double measurement / AT_MOST vs EXACTLY).","Fails to identify nested layout hierarchies or layout weights as causes of UI frame drops."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your experience with A/B testing in ML systems, and how did you measure model performance improvements?', '{"key_points":[{"id":"KP1","description":"A/B testing architecture and traffic splitting mechanism","required":true,"acceptable_evidence":["Technical keywords: traffic routing, canary deployment, API gateway split, feature flags, user_id hashing, Model A vs Model B.","Explains splitting production traffic deterministically (e.g., 90/10 or 50/50) based on consistent user_id hashing.","Details routing requests to Model A (baseline) and Model B (candidate) concurrently under identical real-world conditions."]},{"id":"KP2","description":"Dual evaluation metric framework: business KPIs vs offline technical metrics","required":true,"acceptable_evidence":["Technical keywords: conversion rate, ticket deflection, CSAT, RAGAS faithfulness, latency (P95), false positive rate, XGBoost AUC.","Explains evaluating business outcomes: e.g., fraud catch rate, reduction in customer support escalations, and conversion rates.","Couples business KPIs with technical performance: tracking latency degradation, token cost per query, and model prediction drift."]},{"id":"KP3","description":"Statistical significance testing and guardrail criteria for rollout decisions","required":true,"acceptable_evidence":["Technical keywords: p-value, statistical significance, sample size calculation, confidence interval, minimum detectable effect (MDE).","Explains running tests until reaching statistical significance (p < 0.05) with sufficient sample size to avoid false discovery.","Details establishing circuit breakers: automatically aborting the test if Model B error rates or P95 latency exceed predefined thresholds."]},{"id":"KP4","description":"Observability and experiment governance","required":false,"acceptable_evidence":["Technical keywords: MLflow experiments, Prometheus, Grafana dashboards, LangSmith traces.","Describes logging experiment tags in MLflow and monitoring live performance side-by-side on Grafana dashboards."]}],"critical_failures":["Confuses offline benchmark validation with live production A/B testing on real user traffic.","Fails to mention statistical significance testing or minimum sample size considerations.","Evaluates only model accuracy while ignoring system latency, error rate, or business KPI impact."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What lessons have you learned from managing low performance, and how would you apply them in future hiring decisions?', '{"key_points":[{"id":"KP1","description":"Early root-cause diagnosis separating skill gaps from motivation, clarity, or tooling friction","required":true,"acceptable_evidence":["Technical keywords: root-cause analysis, skill vs will, role clarity, feedback loop, technical friction, onboarding gaps.","Explains diagnosing whether low performance stems from ambiguous expectations, inadequate technical tooling/mentorship, or skill mismatches.","Details addressing issues early through frequent 1:1 check-ins and objective, documented feedback rather than delaying until annual reviews."]},{"id":"KP2","description":"Structured performance improvement plans (PIP) with concrete deliverables and measurable milestones","required":true,"acceptable_evidence":["Technical keywords: performance improvement plan (PIP), measurable milestones, SMART goals, objective rubric, paired programming.","Explains creating a 30/60-day plan with specific code quality, PR velocity, and ownership milestones.","Details providing focused support (e.g., senior engineer pairing, dedicated documentation) with explicit binary outcomes."]},{"id":"KP3","description":"Translating performance lessons into calibrated technical and behavioral hiring evaluations","required":true,"acceptable_evidence":["Technical keywords: structured hiring rubrics, practical work-sample tests, debugging exercises, ownership questions, behavioral signals.","Explains replacing generic algorithmic brainteasers with realistic coding/debugging tasks reflecting daily engineering reality.","Details evaluating problem-solving adaptability, responsiveness to feedback during interviews, and demonstrated technical ownership."]},{"id":"KP4","description":"Team morale protection and cultural integrity","required":false,"acceptable_evidence":["Technical keywords: team velocity, psychological safety, decisive management, respectful offboarding.","Discusses how protracted underperformance harms team morale and how transparent, decisive management preserves team trust."]}],"critical_failures":["Advocates immediate termination without investigating root causes, providing constructive feedback, or giving a clear turnaround plan.","Fails to connect performance management insights to actionable improvements in the hiring and interview process.","Focuses solely on blaming individuals without assessing onboarding, documentation, or engineering culture gaps."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What optimization techniques did you apply to reduce latency, and what performance improvements did you achieve?', '{"key_points":[{"id":"KP1","description":"Pipeline profiling and granular latency bottleneck identification","required":true,"acceptable_evidence":["Technical keywords: LangSmith traces, Prometheus, P95/P99 latency breakdown, TTFT, retrieval vs generation latency.","Explains breaking down baseline latency: e.g., 4.5s total time composed of 800ms retrieval, 400ms reranking, and 3.3s blocking LLM completion.","Details targeting the largest contributors to optimize end-to-end user perceived latency."]},{"id":"KP2","description":"Asynchronous streaming and concurrent I/O execution","required":true,"acceptable_evidence":["Technical keywords: FastAPI StreamingResponse, Server-Sent Events (SSE), asyncio.gather, TTFT reduction.","Explains implementing token streaming to reduce Time to First Token (TTFT) from 3.5s down to sub-400ms.","Details parallelizing independent operations (e.g., BM25 search, Milvus vector search, user profile lookup) via `asyncio.gather`."]},{"id":"KP3","description":"Multi-tier caching and retrieval index parameter tuning","required":true,"acceptable_evidence":["Technical keywords: Redis semantic cache, Milvus HNSW efSearch, cross-encoder pruning, prompt caching.","Explains caching frequent query answers in Redis to bypass retrieval and LLM generation entirely (sub-20ms responses).","Details tuning Milvus `efSearch` parameters and reducing candidate chunks passed to reranker from 50 to 15."]},{"id":"KP4","description":"Quantified latency reduction results and reliability impact","required":true,"acceptable_evidence":["Technical keywords: P95 latency drop (e.g., from 4.5s to 1.2s), TTFT drop (e.g., from 3s to 350ms), throughput increase.","Provides concrete quantitative before-and-after numbers demonstrating substantial latency improvements across percentiles."]}],"critical_failures":["Fails to provide quantitative latency improvements (before vs after metrics across P95 or TTFT).","Mentions only one vague optimization without a structured multi-layer approach (streaming, caching, retrieval tuning).","Ignores Time to First Token (TTFT) when discussing generative AI response latency."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What security measures did you implement for handling sensitive financial data, including SSO, RBAC, compliance, and API Gateway controls?', '{"key_points":[{"id":"KP1","description":"Single Sign-On (SSO) and robust authentication architecture","required":true,"acceptable_evidence":["Technical keywords: SAML 2.0, OIDC (OpenID Connect), OAuth2, Okta/Azure AD, JWT Bearer tokens, token expiration.","Explains integrating enterprise identity providers via OIDC/SAML for centralized employee authentication.","Details validating cryptographically signed JWT tokens with short lifetimes and automated public-key rotation."]},{"id":"KP2","description":"Fine-grained Role-Based Access Control (RBAC) and least privilege enforcement","required":true,"acceptable_evidence":["Technical keywords: RBAC, permission scopes, least privilege, FastAPI Depends, tenant isolation, claim validation.","Explains enforcing granular scopes (e.g., `finance:read`, `transactions:approve`) at the API route and controller level.","Details row-level security or tenant filtering ensuring financial analysts access only data for their authorized corporate entities."]},{"id":"KP3","description":"API Gateway security policies and perimeter defenses","required":true,"acceptable_evidence":["Technical keywords: API Gateway, rate limiting, WAF (Web Application Firewall), mTLS, IP allowlisting, DDoS protection.","Explains enforcing mutual TLS (mTLS) and TLS 1.3 encryption in transit between API Gateway and downstream microservices.","Details implementing rate limiting, payload inspection, and WAF rules to block OWASP Top 10 exploits and credential stuffing."]},{"id":"KP4","description":"Data protection at rest, compliance standards, and immutable auditing","required":true,"acceptable_evidence":["Technical keywords: AES-256 encryption at rest, AWS KMS, PII/PCI-DSS masking, immutable audit log, SOC 2, field-level encryption.","Explains encrypting databases and vector storage using AWS KMS customer-managed keys (AES-256).","Details masking sensitive financial identifiers (credit card numbers, bank routing info) and writing immutable audit logs to S3 with Object Lock."]}],"critical_failures":["Omits encryption standards (TLS in transit, AES-256 at rest) when handling financial data.","Fails to explain how RBAC or SSO integrates with the API backend authorization flow.","Does not mention compliance requirements (SOC 2, PCI-DSS) or audit logging for sensitive data access."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What strategies would you use to reduce latency in a multi-API aggregation system, and how would you decide between sequential and parallel execution?', '{"key_points":[{"id":"KP1","description":"Parallel asynchronous execution for independent upstream API dependencies","required":true,"acceptable_evidence":["Technical keywords: asyncio.gather, parallel execution, non-blocking I/O, httpx.AsyncClient, concurrent requests.","Explains executing all independent API calls concurrently so overall response time equals `max(latencies)` rather than `sum(latencies)`.","Details managing pooled asynchronous connections to minimize handshake latency across upstream services."]},{"id":"KP2","description":"Sequential execution decision criteria and dependency DAG modeling","required":true,"acceptable_evidence":["Technical keywords: data dependency, directed acyclic graph (DAG), prerequisite output, conditional branching.","Explains that sequential execution is strictly mandatory when Step B requires data produced by Step A (e.g., auth token fetch, user ID lookup).","Details modeling multi-API workflows as a DAG where independent branches execute in parallel and join at synchronization points."]},{"id":"KP3","description":"Resilience patterns: timeouts, fallbacks, and circuit breakers","required":true,"acceptable_evidence":["Technical keywords: asyncio.wait_for, timeout per call, circuit breaker, graceful degradation, fallback defaults.","Explains assigning strict SLA timeouts (e.g., 500ms) to non-critical upstream APIs to prevent stragglers from delaying the aggregated response.","Details tripping circuit breakers on failing upstream services and returning cached or default fallback data."]},{"id":"KP4","description":"Multi-tier caching and response streaming to clients","required":true,"acceptable_evidence":["Technical keywords: Redis cache, TTL, chunked response streaming, Server-Sent Events (SSE).","Explains caching frequent upstream responses in Redis with differential TTLs based on data volatility.","Describes streaming partial aggregated chunks to client UI as soon as individual APIs resolve."]}],"critical_failures":["Proposes running all API calls sequentially by default without analyzing data dependencies.","Fails to implement per-call timeouts or fallback mechanisms, allowing a single slow API to block the entire aggregation system.","Cannot articulate the mathematical latency difference between sequential (sum of latencies) and parallel (max latency) execution."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'What techniques can be used to improve Python execution performance, including concurrency and vectorization?', '{"key_points":[{"id":"KP1","description":"Vectorization using NumPy/Pandas to bypass Python interpreter loops with C-level SIMD operations","required":true,"acceptable_evidence":["Technical keywords: NumPy, vectorization, SIMD, C-speed, array broadcasting, eliminating for-loops.","Explains replacing slow Python `for` loops with vectorized array operations executed in contiguous C memory buffers.","Details performance gains (10x-100x speedup) achieved by leveraging CPU SIMD registers and avoiding dynamic Python object overhead."]},{"id":"KP2","description":"Concurrency models: asyncio vs multiprocessing vs multithreading under the GIL","required":true,"acceptable_evidence":["Technical keywords: GIL (Global Interpreter Lock), asyncio, multiprocessing, concurrent.futures, I/O-bound vs CPU-bound.","Explains using `asyncio` or `ThreadPoolExecutor` for I/O-bound tasks (API calls, DB queries) where GIL is released during I/O.","Explains using `multiprocessing` or `ProcessPoolExecutor` for CPU-bound computation to bypass the GIL across multiple CPU cores."]},{"id":"KP3","description":"Data structure optimization, generators, and memory locality","required":true,"acceptable_evidence":["Technical keywords: generators, yield, set lookups O(1), __slots__, deque, memory footprint.","Explains replacing list accumulators with generator iterators (`yield`) to maintain constant O(1) memory during stream processing.","Details using `set` / `dict` hash lookups instead of list scans and using `__slots__` to eliminate object `__dict__` overhead."]},{"id":"KP4","description":"Profiling and compiled extensions (Cython, PyPy, Numba)","required":false,"acceptable_evidence":["Technical keywords: cProfile, line_profiler, Numba JIT, Cython.","Describes profiling code bottlenecks with `cProfile` and compiling numerical hotspots with Numba `@jit` or Cython."]}],"critical_failures":["Recommends standard Python threading for CPU-heavy tasks without understanding the Global Interpreter Lock (GIL).","Suggests manual Python for-loops over arrays instead of vectorized NumPy operations for numeric computing.","Fails to distinguish between I/O-bound concurrency (asyncio) and CPU-bound parallelism (multiprocessing)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs do you consider when designing systems with limited scale requirements versus highly scalable architectures?', '{"key_points":[{"id":"KP1","description":"Engineering velocity and operational simplicity vs distributed complexity overhead","required":true,"acceptable_evidence":["Technical keywords: YAGNI, premature optimization, operational complexity, monolithic architecture vs microservices, maintenance cost.","Explains that low-scale systems benefit from monolithic deployments (FastAPI + SQLite/Postgres) with near-zero operational maintenance and fast feature iteration.","Details the massive overhead introduced by high-scale architectures: distributed tracing, service discovery, network serialization, and distributed state coordination."]},{"id":"KP2","description":"Infrastructure cost and resource utilization trade-offs","required":true,"acceptable_evidence":["Technical keywords: cloud spend, fixed cost vs variable cost, Kubernetes cluster overhead, managed services, over-provisioning.","Explains that hyper-scalable architectures (EKS, Kafka, distributed Milvus, multi-region DBs) carry high baseline cluster costs and administrative overhead.","Contrasts with modest architectures that run cost-effectively on single managed instances (e.g., AWS RDS + App Runner) for a fraction of the cost."]},{"id":"KP3","description":"Data storage and consistency design choices","required":true,"acceptable_evidence":["Technical keywords: ACID compliance, single primary DB, sharding, eventual consistency, distributed transactions.","Explains that low-scale architectures can rely on single-node ACID transactions, simple foreign keys, and instant consistency.","Details that high-scale architectures force trade-offs toward eventual consistency, CQRS, sharding, and complex distributed rollback logic."]},{"id":"KP4","description":"Modularity and future migration path without premature overengineering","required":true,"acceptable_evidence":["Technical keywords: modular monolith, clean architecture, interface abstraction, migration boundaries.","Describes designing with clear domain boundaries and interface abstractions so individual modules can be split into distributed microservices when load dictates."]}],"critical_failures":["Advocates implementing complex distributed architectures (Kafka, sharding, Kubernetes microservices) indiscriminately for simple, low-scale systems.","Fails to identify operational costs, cognitive load, and debugging friction as major disadvantages of distributed scale.","Does not explain how to design clean modular boundaries that allow future scaling without premature overengineering."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What was the latency of your system, and how did you balance response quality with performance?', '{"key_points":[{"id":"KP1","description":"Granular latency baseline metrics across percentiles and pipeline stages","required":true,"acceptable_evidence":["Technical keywords: P50/P95 latency, TTFT (time-to-first-token), end-to-end response time, retrieval latency, inference latency.","Provides concrete quantitative latency numbers: e.g., P50 of 1.2s, P95 of 2.1s, and streaming TTFT under 450ms.","Breaks down component latencies: Milvus vector search (30ms), reranking (120ms), and LLM token generation (1.5s)."]},{"id":"KP2","description":"Architectural balancing mechanisms: streaming and model tiering","required":true,"acceptable_evidence":["Technical keywords: token streaming, FastAPI StreamingResponse, model cascading, small vs large LLMs (GPT-4o vs 8B SLM).","Explains using streaming responses to make perceived latency sub-second while allowing complex answers to complete over several seconds.","Details routing simple queries to lightweight fast models and reserving heavier multi-turn models for complex issues."]},{"id":"KP3","description":"Retrieval optimization: candidate pruning and hybrid balance","required":true,"acceptable_evidence":["Technical keywords: top_k candidate cutoff, cross-encoder reranker, context pruning, RAGAS faithfulness.","Explains limiting retrieved context to top 3-5 chunks rather than 15+ to reduce LLM prompt processing time without sacrificing context recall.","Details tuning the reranker threshold to discard irrelevant chunks, preserving RAGAS faithfulness while cutting generation latency."]},{"id":"KP4","description":"Quality guardrails and SLA enforcement","required":false,"acceptable_evidence":["Technical keywords: SLA threshold, fallback prompt, timeout circuit breaker, cache hit ratio.","Describes falling back to concise predefined responses or cached answers if retrieval or LLM inference exceeds SLA limits."]}],"critical_failures":["Gives a single vague latency number without percentiles (P95/P99) or without breaking down TTFT vs total completion time.","Cannot explain any trade-off mechanisms used to balance model quality against execution speed.","Fails to mention response streaming or context chunk pruning as primary latency-reduction levers."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Where are the potential performance bottlenecks in a hit counter system under high throughput, and how would you optimize them?', '{"key_points":[{"id":"KP1","description":"Database write lock contention and row-level serialization bottlenecks","required":true,"acceptable_evidence":["Technical keywords: lock contention, row-level locks, serialized writes, transactional bottleneck, disk I/O.","Explains that updating a single relational database counter (`UPDATE counters SET count = count + 1`) serializes transactions under high concurrency.","Details how lock queues lead to connection pool exhaustion, timeout cascades, and system degradation under thousands of RPS."]},{"id":"KP2","description":"In-memory distributed caching with atomic increments and counter sharding","required":true,"acceptable_evidence":["Technical keywords: Redis, INCR / INCRBY, atomic operation, counter sharding, distributed counters, hash slots.","Explains offloading real-time increments to Redis in-memory storage using atomic `INCR` commands.","Details counter sharding: splitting a logical counter across N keys (`counter_1` ... `counter_N`) and summing them on read to eliminate Redis single-key lock contention."]},{"id":"KP3","description":"Client-side / application-tier write aggregation and asynchronous batching","required":true,"acceptable_evidence":["Technical keywords: write aggregation, local memory buffer, batch flushing, asyncio background task, message queue (Kafka).","Explains buffering hit counts in local server process memory (e.g., aggregating hits over 1-second intervals) before sending batch increments.","Details pushing aggregated counts through Kafka/SQS queues to asynchronously update persistent database storage."]},{"id":"KP4","description":"Network and API Gateway layer optimization","required":true,"acceptable_evidence":["Technical keywords: keep-alive connections, UDP / statsd, connection pooling, non-blocking async endpoints.","Explains using UDP/statsd or asynchronous non-blocking fire-and-forget endpoints to eliminate HTTP request-response overhead for hit logging."]}],"critical_failures":["Proposes updating a single SQL database row synchronously on every incoming hit under high throughput.","Fails to identify database row lock contention or single-key serialization as the primary bottleneck.","Does not mention in-memory counter aggregation, Redis atomic operations, or counter sharding."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose FastAPI for the backend, and what trade-offs exist compared to other frameworks?', '{"key_points":[{"id":"KP1","description":"Core advantages of FastAPI: native asynchronous concurrency and streaming support","required":true,"acceptable_evidence":["Technical keywords: async/await, asyncio, Starlette, Uvicorn, non-blocking I/O, StreamingResponse, SSE (Server-Sent Events).","Explains native asynchronous event loop support, essential for non-blocking I/O when integrating vector databases, external LLM APIs, and cache layers.","Details first-class support for `StreamingResponse` allowing real-time token streaming to frontend clients."]},{"id":"KP2","description":"Automatic data validation, serialization, and documentation with Pydantic","required":true,"acceptable_evidence":["Technical keywords: Pydantic schemas, type hints, automatic data validation, OpenAPI (Swagger), JSON Schema.","Explains Pydantic model integration that guarantees strict request/response type validation, automatic 422 error generation, and schema enforcement.","Details automatic generation of interactive OpenAPI Swagger UI documentation, accelerating frontend-backend contract integration."]},{"id":"KP3","description":"Architectural comparison and trade-offs against Flask and Django","required":true,"acceptable_evidence":["Technical keywords: Flask (WSGI vs ASGI, sync by default), Django (batteries-included, ORM, admin panel), framework trade-offs.","Contrasts with Flask: Flask is traditionally synchronous WSGI requiring extra extensions for validation/OpenAPI and lacks native high-concurrency async support.","Contrasts with Django: Django offers an all-in-one ecosystem (built-in ORM, admin interface, auth), but is heavyweight and overengineered for microservices and AI inference APIs."]},{"id":"KP4","description":"FastAPI limitations and engineering considerations","required":true,"acceptable_evidence":["Technical keywords: lack of built-in ORM, dependency injection learning curve, third-party async drivers (asyncpg), CPU-bound blocking.","Explains that FastAPI does not provide a built-in ORM or admin UI, requiring manual architectural choices (e.g., SQLAlchemy + Alembic).","Highlights that long-running synchronous CPU computations in async endpoints can accidentally block the main event loop if not run in thread pools."]}],"critical_failures":["Claims Flask has higher native asynchronous concurrency and automatic validation than FastAPI.","Fails to mention Pydantic validation or async streaming as key architectural reasons for choosing FastAPI.","Ignores FastAPI trade-offs, such as the lack of a built-in ORM/admin interface and the risk of blocking the async event loop with synchronous code."]}', 1);
